/* ==========================================================================
   Palette — one set of tokens, two themes
   --------------------------------------------------------------------------
   This app was written dark-first: ~830 of its surfaces, borders and dividers
   are literally `rgba(255,255,255,α)` — a white LIFT off a dark ground. That
   idiom is the whole reason a light theme is possible without rewriting every
   component: the colour is not "white", it is "whatever contrasts with the
   page", and there is exactly one of those per theme.

   So --tint is that colour, and every one of those literals now reads
   `rgba(var(--tint), α)`. In dark --tint IS white, which makes the conversion a
   byte-for-byte no-op — the dark theme cannot regress. In light it flips to a
   deep navy-black and the same alpha that was a subtle lift becomes a subtle
   press into the page, which is the correct translation of the idea.

   Hue colours (the orange, the gold, the greens and reds that mean something)
   are NOT tokenized. A figure that means money stays orange in both themes.
   ========================================================================== */
:root {
  color-scheme: dark;
  --font-body: 'IBM Plex Sans', system-ui, sans-serif;
  --font-display: 'Space Grotesk', system-ui, sans-serif;
  /* The rgb triple every soft surface in this file is written against. */
  --tint: 255, 255, 255;
  /* The ink, as a triple, for the ~130 places that set secondary text as the
     ink at an alpha. Same no-op trick as --tint: in dark it IS --text. */
  --ink-rgb: 238, 241, 246;
  --grey-1: 138, 150, 172;
  --grey-2: 190, 199, 212;
  --grey-3: 186, 195, 208;
  --grey-4: 192, 202, 216;
  --grey-5: 140, 150, 166;
  --grey-6: 226, 232, 242;
  --bg: #070a11;
  /* The two grounds under the page: a panel well and a raised card. */
  --bg-2: #0e1219;
  --bg-3: #171b23;
  --bg-elevated: rgba(29, 33, 42, 0.9);
  --bg-soft: rgba(var(--tint), 0.04);
  --line: rgba(var(--tint), 0.07);
  --text: #eef1f6;
  --foreground: var(--text);
  --muted: #99a2b2;
  --mute: var(--muted);
  /* The dimmer of the two secondary greys, used for captions and hints. */
  --muted-2: #6c7688;
  /* Ink that sits ON the accent. The accent doesn't change between themes, so
     neither does this. */
  --on-accent: #1a0a00;
  --accent: #ff7a21;
  --accent-2: #ff9d5c;
  --accent-end: #ff9d5c;
  --accent-paper: var(--accent);
  --accent-ink: #ff9d5c;
  --accent-gradient: linear-gradient(180deg, var(--accent), var(--accent-end));
  --ambient-glow: radial-gradient(circle at top, rgba(255, 122, 33, var(--glow-a, 0.22)), transparent 35%), radial-gradient(circle at 85% 20%, rgba(255, 209, 102, var(--glow-b, 0.14)), transparent 22%);
  --bg-gradient-canvas: radial-gradient(ellipse 90% 60% at 50% -15%, rgba(255, 122, 33, 0.22), transparent 60%), radial-gradient(ellipse 70% 50% at 90% 25%, rgba(56, 189, 248, 0.12), transparent 55%), radial-gradient(ellipse 60% 45% at 10% 85%, rgba(124, 58, 237, 0.10), transparent 50%), linear-gradient(180deg, #090c14 0%, #0d121d 45%, #05070d 100%);
  --bg-gradient-card: linear-gradient(180deg, rgba(26, 33, 48, 0.86) 0%, rgba(13, 17, 26, 0.95) 100%);
  --bg-gradient-sheen: linear-gradient(180deg, rgba(255, 255, 255, 0.14) 0%, rgba(255, 255, 255, 0.01) 100%);
  --bg-ambient-cone: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(255, 122, 33, 0.22) 0%, transparent 65%);
  --planning: #7c3aed;
  --planning-end: #4f169f;
  --planning-gradient: linear-gradient(180deg, #7c3aed 0%, #6320c9 55%, #4f169f 100%);
  --planning-glow: radial-gradient(135% 120% at 50% 118%, rgba(214, 176, 255, 0.42) 0%, rgba(168, 85, 247, 0.2) 42%, transparent 70%);
  --planning-shadow: 0 0 9px rgba(180, 120, 255, 0.6), 0 0 24px rgba(147, 51, 234, 0.42), 0 0 62px rgba(124, 40, 220, 0.3), 0 14px 46px -14px rgba(120, 40, 210, 0.5), inset 0 1px 0 rgba(233, 219, 255, 0.5), inset 0 -20px 38px -24px rgba(214, 186, 255, 0.5);
  --assistant-accent: linear-gradient(135deg, #7c3aed 0%, #ec4899 55%, #f59e0b 100%);
  --assistant-shadow: 0 4px 14px rgba(124, 58, 237, 0.32);
  --glow-a: 0.10;
  --glow-b: 0.06;
  --fresh: #3dd68c;
  --shade: 2, 4, 9;
  --good: #3dd68c;
  --warn: #fdb022;
  --bad: #fd8a7a;
  --info: #7aa2ff;
  --cap-open: #3dd68c;
  --cap-light: #a6e35b;
  --cap-busy: #fdb022;
  --cap-full: #fd853a;
  --cap-over: #f97066;
  --cap-unknown: #98a2b3;
  --gold-ink: #ffd166;
  --on-active: #fff;
  --nav-work: #ff7a21;
  --nav-intake: #53b1fd;
  --nav-team: #2ed3d3;
  --nav-money: #3dd68c;
  --nav-grow: #b692f6;
  --shadow-strong: rgba(2, 4, 9, 0.7);
  --shadow-soft: rgba(2, 4, 9, 0.45);
  --ground-1: #05070c;
  --ground-2: #0b0e15;
  --panel-rgb: 14, 18, 25;
  --chrome-rgb: 5, 7, 12;
  --chrome: rgba(5, 7, 12, 0.86);
  --chrome-soft: rgba(5, 7, 12, 0.76);
  --chrome-solid: rgba(5, 7, 12, 0.92);
  /* Theme compatibility aliases */
  --card-bg: var(--bg-2);
  --panel-bg: var(--bg-2);
  --border-subtle: var(--line);
  --text-muted: var(--muted);
  --text-primary: var(--text);
  --text-color: var(--text);
  --panel-subtle: rgba(var(--tint), 0.04);
  background: var(--bg);
  color: var(--text);
}

