}

.missed-card .missed-field small {
  font-size: 0.79rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

/* Status. The dot carries the state as well as the words, so it reads at a
   glance without depending on colour alone for the meaning. */
.missed-card .missed-status {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  margin-top: 0.2rem;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
}

.missed-card .missed-status div {
  display: grid;
  gap: 0.15rem;
}

.missed-card .missed-status strong {
