}

.missed-card .missed-status.is-live strong {
  color: var(--ink-lime-1);
}

.missed-card .missed-status.is-waiting .missed-dot {
  background: var(--ink-amber-3);
}

.missed-card .missed-status.is-error {
  border-color: var(--cedge-orange-9);
  background: rgba(255, 122, 33, 0.09);
}

.missed-card .missed-status.is-error .missed-dot {
  background: var(--ink-orange-1);
}

.missed-card .missed-status.is-error strong {
  color: var(--ink-orange-1);
}

.missed-card .missed-advanced {
  margin-top: 0.9rem;
}

.missed-card .missed-note {
  margin: 0.6rem 0 0;
  font-size: 0.81rem;
  line-height: 1.6;
  color: var(--mute-t50);
}

.missed-card .missed-note code {
  overflow-wrap: anywhere;
  font-size: 0.78rem;
}

/* The phone, same device as the arrival preview. */
.missed-card .missed-phone {
