/* ── Review requests ─────────────────────────────────────────────────────────
   Elevated card layout with segmented destination mode cards, live interactive
   smartphone preview, Google Business verification status, and policy trust badge. */
.review-card {
  padding: 1.25rem 1.35rem;
  border-radius: 20px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.03);
  backdrop-filter: blur(12px);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.review-card.is-paused .review-preview {
  opacity: 0.65;
}

.review-state-banner {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.85rem 1.05rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  margin-bottom: 1.35rem;
  transition: all 0.2s ease;
}

.review-state-banner.is-active {
  border-color: rgba(79, 211, 154, 0.35);
  background: rgba(79, 211, 154, 0.08);
}

.review-state-banner.is-paused {
  border-color: rgba(255, 122, 33, 0.3);
  background: rgba(255, 122, 33, 0.07);
}

.review-state-indicator {
  display: grid;
  place-items: center;
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 50%;
  background: rgba(var(--tint), 0.08);
  font-size: 1.1rem;
  flex-shrink: 0;
}

.review-state-text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.review-state-heading {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text);
}

.review-state-banner.is-active .review-state-heading {
  color: var(--good);
}

.review-state-banner.is-paused .review-state-heading {
  color: var(--warn);
}

.review-state-desc {
  font-size: 0.84rem;
  line-height: 1.5;
  color: var(--muted);
}

.review-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 1.6rem;
  align-items: start;
}

.review-section-header {
