  font-size: 0.86rem;
  line-height: 1.58;
}

.base-plan-checkout-affirmation {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-top: 1rem;
  color: var(--text);
  font-weight: 700;
  line-height: 1.48;
