}

.base-plan-checkout-actions {
  display: flex;
  align-items: center;
  gap: 0.85rem 1.15rem;
  flex-wrap: wrap;
}

.base-plan-checkout-actions>span {
  color: rgba(var(--ink-rgb), 0.7);
  font-size: 0.82rem;
  line-height: 1.45;
}

@media (max-width: 680px) {

  .plan-usage-plan-facts,
  .plan-usage-balance-grid,
  .plan-usage-limit-list {
    grid-template-columns: 1fr;
