  .plan-usage-limit-list>div:nth-child(odd) {
    margin-right: 0;
  }

  .base-plan-checkout-price {
    grid-template-columns: 1fr;
  }

  .base-plan-checkout-price>strong {
    text-align: left;
  }

  .base-plan-checkout-price>small {
    grid-column: auto;
  }
