  color: var(--gold-ink);
  background: rgba(255, 209, 102, 0.1);
  border: 1px solid var(--cedge-amber-7);
}

/* Screen-reader-only text (visually hidden, still announced). */
/* `text-transform: none` because these labels sit INSIDE styled things. The
   rail's "New" pill is uppercase, so the sentence explaining it inherited the
   uppercase too — and a screen reader handed a short run of capitals may spell
   it out rather than read it. Nothing here is ever seen, so nothing here should
   inherit how its container looks. */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
  text-transform: none;
  letter-spacing: normal;
}

/* Dashboard navigation skeleton (app/dashboard/loading.tsx) — shown instantly
   while the next page's data loads, so nav clicks never feel frozen. */
.skeleton-block {
  border-radius: 14px;
  background-color: rgba(var(--tint), 0.045);
  background-image: linear-gradient(100deg, transparent 20%, rgba(var(--tint), 0.06) 45%, rgba(var(--tint), 0.09) 55%, transparent 80%);
  background-size: 220% 100%;
  animation: skel-shimmer 1.5s ease-in-out infinite;
}

@keyframes skel-shimmer {
  from {
    background-position: 220% 0;
  }

  to {
    background-position: -120% 0;
  }
}

.dash-skel-hero {
  height: 116px;
  margin-bottom: 1.25rem;
}

.dash-skel-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.dash-skel-card {
  height: 148px;
}

.dash-skel-wide {
  height: 220px;
}

@media (max-width: 760px) {
  .dash-skel-grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-block {
    animation: none;
  }
}

