  transform: translateY(-1px);
  background: rgba(var(--tint), 0.12);
  border-color: var(--edge-t30);
  box-shadow: none;
}

.website-nav-signal {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
  flex: 0 0 auto;
}

.website-nav-signal i {
  width: 3px;
  height: 100%;
  border-radius: 1px;
  background: var(--good);
  transform-origin: bottom;
  animation: website-nav-bars 3.4s ease-in-out infinite;
}

.website-nav-signal i:nth-child(2) {
  animation-delay: 0.5s;
}

.website-nav-signal i:nth-child(3) {
  animation-delay: 1s;
}

@keyframes website-nav-bars {

  0%,
  100% {
    transform: scaleY(0.4);
  }

  50% {
    transform: scaleY(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .website-nav-signal i {
    animation: none;
    transform: scaleY(0.7);
  }

  .website-nav-badge.live:hover {
    transform: none;
  }
}

@media (max-width: 860px) {
  .website-nav-badge {
    order: -2;
  }
}

/* Shares the website badge's chip: same 12px radius, same translucent surface.
   State lives in the leading tile — whose GLYPH changes too (✓ / !), so it
   never depends on colour alone. */
.stripe-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 44px;
  padding: 0.35rem 0.8rem 0.35rem 0.4rem;
  border-radius: 12px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.07);
  color: var(--ink-neutral-4);
  /* No extra margin — .topbar-inner's gap already spaces the chips, and the
     row needs every pixel to stay on one line. */
  transition: border-color 0.15s ease, background 0.15s ease;
}

.stripe-status-pill:hover {
  border-color: var(--edge-t30);
  background: rgba(var(--tint), 0.12);
}

/* Top-bar pill: dimmed interior so it sits back into the bar instead of reading
   as a lit-up primary action on every single page. The coloured "$" tile still
   carries the state, and the outline keeps it a legible target. */
.stripe-status-pill.topbar-stripe {
  background: rgba(var(--tint), 0.025);
}

.stripe-status-pill.topbar-stripe:hover {
  background: rgba(var(--tint), 0.07);
}

.stripe-status-tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  /* A touch larger than the old tick — "$" is a narrower glyph and reads small
     at the same size. */
  font-size: 0.8rem;
  font-weight: 800;
  line-height: 1;
  background: rgba(var(--tint), 0.12);
  color: var(--ink-neutral-11);
  border-radius: 999px;
  flex-shrink: 0;
}

/* Connected uses the website badge's emerald, not the old lime, so the two
   chips stop showing slightly different greens side by side. */
.stripe-status-pill.connected {
  color: var(--good);
}

.stripe-status-pill.connected .stripe-status-tile {
  background: rgba(52, 211, 153, 0.2);
  color: var(--good);
}

.stripe-status-pill.warning {
  color: var(--ink-amber-3);
}

.stripe-status-pill.warning .stripe-status-tile {
  background: rgba(251, 191, 36, 0.2);
  color: var(--ink-amber-3);
}

/* The status is fetched client-side, so it's briefly unknown on every load —
   muted and blinking rather than flashing a wrong state. */
.stripe-status-pill.checking {
  color: #64748b;
}

.stripe-status-pill.checking .stripe-status-tile {
  background: rgba(var(--tint), 0.08);
  color: #64748b;
  animation: stripe-status-blink 1.6s ease-in-out infinite;
}

@keyframes stripe-status-blink {

  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.4;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stripe-status-pill.checking .stripe-status-tile {
    animation: none;
  }
}

@media (max-width: 860px) {
  .stripe-status-pill {
    margin-left: 0;
    order: -1;
  }
}

.page-shell {
  min-height: calc(100vh - 5.5rem);
  display: grid;
  place-items: center;
  padding: 2rem;
}

.wide-shell {
  min-height: calc(100vh - 5.5rem);
  padding: 2.5rem 2rem 4rem;
  max-width: 1100px;
  margin: 0 auto;
}

.marketing-shell {
  max-width: 1180px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.9fr);
  gap: 1.25rem;
  align-items: stretch;
}

.hero-card,
.hero-panel,
.panel,
.feature-card {
  background: var(--bg-gradient-card, var(--bg-elevated));
  border: 1px solid var(--line);
  border-radius: 24px;
  box-shadow: 0 18px 50px -12px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(var(--tint), 0.12);
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}

.hero-card,
.hero-copy,
.hero-panel,
.panel,
.feature-card {
  padding: 1.5rem;
}

.hero-copy {
  background:
    linear-gradient(145deg, rgba(255, 122, 33, 0.12), transparent 28%),
    var(--bg-elevated);
  border: 1px solid var(--line);
  border-radius: 32px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-size: 0.78rem;
  /* --gold-ink, not --accent-2: this is the gold being READ as words. On paper
     #ffd166 measures 1.44:1, which is not a quiet label, it is an absent one.
     --accent-2 stays as it is for gradients, washes and borders. */
  color: var(--gold-ink);
  font-weight: 700;
}

.workspace-eyebrow-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.account-tag {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--mute-t55);
  letter-spacing: 0.01em;
}

.account-created-note {
  margin: 0.6rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t45);
}

h1 {
  font-size: clamp(2.6rem, 5vw, 5rem);
  line-height: 0.98;
  margin: 0.35rem 0 0.85rem;
}

h2 {
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  line-height: 1.02;
  margin: 0.25rem 0 0;
}

h3 {
  font-size: 1.2rem;
  margin: 0;
}

p {
  line-height: 1.6;
  color: var(--muted);
}

.hero-text {
  max-width: 60ch;
  font-size: 1.05rem;
}

.actions {
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
  margin: 1.5rem 0 1.1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.82rem 1.1rem;
  border-radius: 999px;
  font-weight: 700;
  border: 1px solid transparent;
}

/* OUTLINE, not a slab. White on that orange gradient measured 3.12:1 at its
   dark end and 2.34:1 at its light one — the primary action in the app was the
   hardest thing in it to read, and worst exactly where the gradient was
   brightest.
   Hollow fixes it by inverting which part carries the colour: the ink and the
   ring are orange against the page's own ground, which is 7.2:1 on navy and
   5.6:1 on paper. --ink-orange-8 already flips per theme (#ff7a29 / #a54f1b),
   so neither needs its own rule.
   It stays unmistakably the primary action: nothing else on a screen wears a
   full-strength accent ring, and hover fills toward the old slab without ever
   putting white on top of it. */
.btn.primary {
  background: rgba(255, 122, 33, 0.1);
  border-color: var(--cedge-orange-2);
  color: var(--ink-orange-8);
}

.btn.primary:hover:not(:disabled) {
  background: rgba(255, 122, 33, 0.18);
  border-color: var(--cedge-orange-3);
}

.btn.secondary {
  border-color: var(--edge-t18);
  background: rgba(var(--tint), 0.04);
}

.btn.qb {
  background: #2CA01C;
  color: white;
}

.btn.fun {
  background: var(--assistant-accent, linear-gradient(135deg, #7c3aed 0%, #ec4899 55%, #f59e0b 100%));
  color: white;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: var(--assistant-shadow, 0 4px 14px rgba(124, 58, 237, 0.35));
}

.btn.fun:hover {
  transform: translateY(-2px) scale(1.03);
  box-shadow: var(--assistant-shadow, 0 6px 20px rgba(236, 72, 153, 0.45));
}

ul {
  padding-left: 1.2rem;
  color: var(--muted);
}

li+li {
  margin-top: 0.45rem;
}

.hero-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  background:
    radial-gradient(circle at top right, rgba(255, 209, 102, 0.18), transparent 30%),
    var(--bg-elevated);
}

.feature-card p,
.section-heading p {
  color: var(--muted);
}

.section-block {
  margin-top: 1.25rem;
  padding: 1.5rem;
  border-radius: 32px;
  border: 1px solid var(--edge-t08);
  background: rgba(var(--tint), 0.02);
}

.section-heading {
  max-width: 46rem;
}

/* Page titles inside a section heading are <h1> for semantics — every page needs
   exactly one, and these pages had none, so screen-reader users navigating by
   heading found no page name and the hierarchy started at h2. Visually they must
   stay section-sized: the global h1 is clamp(2.6rem, 5vw, 5rem) with an 11ch
   max-width, which would dwarf and wrap them. */
.section-heading h1 {
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  line-height: 1.02;
  margin: 0.25rem 0 0;
  max-width: none;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.4rem;
}

.feature-card p {
  margin-bottom: 0;
}

.proof-band {
  background:
    linear-gradient(145deg, rgba(var(--tint), 0.03), transparent 55%),
    rgba(var(--tint), 0.02);
}

/* ---------------------------------------------------------------- */
/* Homepage: ambient background glow                                 */
/* ---------------------------------------------------------------- */
.ambient-glow {
  position: fixed;
  z-index: -1;
  border-radius: 999px;
  filter: blur(90px);
  pointer-events: none;
  opacity: 0.55;
}

.ambient-glow-a {
  top: -10%;
  right: -8%;
  width: 42vw;
  height: 42vw;
  background: rgba(255, 122, 33, 0.22);
  animation: drift-a 22s ease-in-out infinite alternate;
}

.ambient-glow-b {
  bottom: 5%;
  left: -12%;
  width: 34vw;
  height: 34vw;
  background: rgba(255, 209, 102, 0.16);
  animation: drift-b 26s ease-in-out infinite alternate;
}

@keyframes drift-a {
  0% {
    transform: translate(0, 0) scale(1);
  }

  100% {
    transform: translate(-4%, 6%) scale(1.08);
  }
}

@keyframes drift-b {
  0% {
    transform: translate(0, 0) scale(1);
  }

  100% {
    transform: translate(5%, -5%) scale(1.05);
  }
}

/* ---------------------------------------------------------------- */
/* Homepage: hero flow strip + gradient headline                     */
/* ---------------------------------------------------------------- */
.hero-flow-strip {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.95rem;
  border-radius: 999px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  color: rgba(var(--ink-rgb), 0.68);
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.1rem;
}

.flow-strip-arrow {
  color: var(--mute-i32);
}

.flow-strip-highlight {
  color: var(--gold-ink);
}

/* Solid fallback first; the clipped gradient only applies where supported, so
   the headline is never invisible in browsers/modes where background-clip:text
   fails (e.g. Windows High Contrast / forced-colors). */
.gradient-text {
  color: var(--gold-ink);
}

@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .gradient-text {
    background: linear-gradient(90deg, var(--accent) 0%, var(--accent-2) 50%, var(--accent) 100%);
    background-size: 200% auto;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: gradient-shift 6s ease-in-out infinite;
  }

  /* background-position on background-clip:text has no compositable
     equivalent — every frame repaints the glyphs, forever, and there are
     several of these on the marketing page at once. The gradient itself is
     what carries the look; the drift across it is a bonus a tablet shouldn't
     pay for while it's trying to scroll. */
  @media (hover: none) and (pointer: coarse) {
    .gradient-text {
      animation: none;
      background-position: 50% center;
    }
  }
}

@media (forced-colors: active) {
  .gradient-text {
    forced-color-adjust: none;
    background: none;
    color: CanvasText;
    -webkit-text-fill-color: currentColor;
  }
}

@keyframes gradient-shift {

  0%,
  100% {
    background-position: 0% center;
  }

  50% {
    background-position: 100% center;
  }
}

.hero-trust-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem 1.4rem;
  margin: 1.3rem 0 0;
  padding: 0;
  list-style: none;
}

.hero-trust-row li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: rgba(var(--ink-rgb), 0.66);
  font-size: 0.85rem;
}

.hero-trust-row li+li {
  margin-top: 0;
}

.hero-trust-row svg {
  color: var(--gold-ink);
  flex-shrink: 0;
}

/* ---------------------------------------------------------------- */
/* Homepage: money-flow pipeline (hero panel)                        */
/* ---------------------------------------------------------------- */
.flow-panel {
  justify-content: center;
}

/* Homepage "quote to bank" flow band — the stepper as its own section beside
   its heading (the hero now carries the interactive dashboard panel instead). */
.flow-band-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(300px, 0.92fr);
  gap: 1.75rem;
  align-items: center;
}

.flow-band-grid .section-heading {
  margin: 0;
}

@media (max-width: 860px) {
  .flow-band-grid {
    grid-template-columns: 1fr;
  }
}

.flow-panel-eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--mute-i45);
  margin: 0 0 0.6rem;
}

.flow-pipeline {
  display: flex;
  flex-direction: column;
}

.flow-step {
  display: flex;
  gap: 1rem;
  padding-bottom: 1.7rem;
}

.flow-step:last-child {
  padding-bottom: 0;
}

.flow-step-node {
  position: relative;
  flex-shrink: 0;
}

.flow-step-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.05);
  color: var(--gold-ink);
  position: relative;
  z-index: 1;
}

.flow-step:not(:last-child) .flow-step-node::after {
  content: '';
  position: absolute;
  top: 44px;
  left: 21px;
  width: 2px;
  height: calc(100% - 18px);
  background-image: linear-gradient(180deg, rgba(255, 209, 102, 0.85) 0%, rgba(255, 209, 102, 0.85) 50%, transparent 50%, transparent 100%);
  background-size: 2px 16px;
  animation: flow-line-travel 0.8s linear infinite;
}

@keyframes flow-line-travel {
  0% {
    background-position-y: 0;
  }

  100% {
    background-position-y: 16px;
  }
}

.flow-step-copy {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding-top: 0.5rem;
}

.flow-step-copy strong {
  font-size: 1rem;
}

.flow-step-copy span {
  font-size: 0.83rem;
  color: var(--mute-i56);
}

.flow-step-final .flow-step-icon {
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  color: #101319;
  border-color: transparent;
  box-shadow: 0 0 22px rgba(255, 209, 102, 0.35);
}

.flow-step-final .flow-step-copy strong {
  font-size: 1.1rem;
}

/* ---------------------------------------------------------------- */
/* Homepage: website template showcase                               */
/* ---------------------------------------------------------------- */
.template-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
  margin-top: 1.5rem;
}

.template-card {
  display: flex;
  flex-direction: column;
  border-radius: 22px;
  border: 1px solid var(--line);
