.stripe-alert-wrap {
  max-width: 1100px;
  margin: 1.1rem auto 0;
  padding: 0 2rem;
}

/* Lit block: saturated fill, neon rim, bloom underneath. The glow is layered
   rather than one big shadow — a tight rim, a mid halo, and a wide pool cast
   downward — because a single blur that reaches this far just looks like fog. */
.stripe-alert-banner {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  gap: 0.95rem;
  /* It's a submit button — a form control inherits none of this by default. */
  width: 100%;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  padding: 1.05rem 1.25rem;
  border: 1px solid var(--cedge-orange-22);
  border-radius: 18px;
  color: #fff;
  text-decoration: none;
  background:
    radial-gradient(135% 120% at 50% 118%, rgba(255, 197, 140, 0.42) 0%, rgba(255, 145, 65, 0.17) 42%, transparent 70%),
    linear-gradient(180deg, #a53e0b 0%, #8d3308 55%, #772a06 100%);
  box-shadow:
    0 0 9px rgba(255, 163, 82, 0.64),
    0 0 24px rgba(255, 122, 33, 0.42),
    0 0 62px rgba(255, 100, 20, 0.29),
    0 14px 46px -14px rgba(255, 96, 18, 0.47),
    inset 0 1px 0 rgba(255, 232, 212, 0.51),
    inset 0 -20px 38px -24px rgba(255, 214, 170, 0.51);
  transition: box-shadow 0.18s ease, transform 0.18s ease;
}

/* Faint lattice so the fill has some texture instead of reading as flat paint.
   Two hatches rather than an image — no asset to ship. */
.stripe-alert-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(60deg, rgba(var(--tint), 0.05) 0 1px, transparent 1px 15px),
    repeating-linear-gradient(-60deg, rgba(var(--tint), 0.05) 0 1px, transparent 1px 15px);
}

.stripe-alert-banner:hover {
  transform: translateY(-1px);
  box-shadow:
    0 0 26px rgba(255, 143, 60, 0.6),
    0 0 72px rgba(255, 110, 25, 0.36),
    0 20px 60px -20px rgba(255, 90, 20, 0.68),
    inset 0 1px 0 rgba(255, 236, 219, 0.6),
    inset 0 -20px 38px -24px rgba(255, 222, 186, 0.6);
}

.stripe-alert-banner:focus-visible {
  outline: 2px solid #ffdcc4;
  outline-offset: 3px;
}

/* Waiting on Stripe for the onboarding link. Stays lit — dimming it here would
   read as "this failed" rather than "this is working". */
.stripe-alert-banner:disabled {
  cursor: progress;
}

.stripe-alert-banner:disabled:hover {
  transform: none;
}

.stripe-alert-icon {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 13px;
  border: 1px solid var(--cedge-orange-23);
  background: linear-gradient(180deg, rgba(var(--tint), 0.22), rgba(var(--tint), 0.08));
  box-shadow: inset 0 1px 0 rgba(var(--tint), 0.35), 0 2px 8px rgba(0, 0, 0, 0.25);
}

.stripe-alert-icon svg {
  width: 1.5rem;
  height: 1.5rem;
}

.stripe-alert-copy {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1 1 auto;
  min-width: 0;
}

.stripe-alert-copy strong {
  color: #fff;
  font-size: 1.02rem;
  letter-spacing: -0.01em;
}

.stripe-alert-copy span {
  color: var(--dim-grey-1-2);
  font-size: 0.85rem;
}

.stripe-alert-chevron {
  position: relative;
  flex: none;
  width: 1.3rem;
  height: 1.3rem;
  color: rgba(var(--tint), 0.8);
  transition: transform 0.18s ease;
}

.stripe-alert-banner:hover .stripe-alert-chevron {
  transform: translateX(3px);
}

@media (max-width: 640px) {
  .stripe-alert-wrap {
    padding: 0 1rem;
  }

  .stripe-alert-banner {
    padding: 0.9rem 1rem;
    gap: 0.75rem;
  }

  .stripe-alert-icon {
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 11px;
  }

  .stripe-alert-copy strong {
    font-size: 0.95rem;
  }
}

