/* Undo toast after a drop/reschedule. */
.schedule-undo-toast {
  position: fixed;
  left: 50%;
  bottom: 1.5rem;
  transform: translateX(-50%);
  z-index: 210;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: .65rem .7rem .65rem 1.1rem;
  border-radius: 999px;
  background: rgba(12, 20, 32, .97);
