  color: var(--text);
  font-size: .85rem;
  font-weight: 600;
  animation: schedule-undo-in .22s ease both;
}

@keyframes schedule-undo-in {
  from {
    opacity: 0;
    transform: translate(-50%, 10px);
  }

  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.schedule-undo-toast button {
  padding: .4rem 1.05rem;
  border-radius: 999px;
  border: 0;
  background: linear-gradient(180deg, #ff7a21, #ff9440);
  color: var(--on-accent);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
}

.schedule-undo-toast button:disabled {
  opacity: .6;
  cursor: default;
}

