.schedule-drop-custom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8rem;
  color: var(--ink-neutral-6);
  font-size: .82rem;
  font-weight: 600;
}

.schedule-drop-custom input {
  padding: .5rem .6rem;
  border-radius: 8px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), .05);
  color: var(--text);
  font: inherit;
}

.schedule-drop-actions {
  display: flex;
  justify-content: flex-end;
  gap: .6rem;
}

.calendar-day-number {
  font-size: .78rem;
  font-weight: 700;
  color: var(--mute-t60);
}

.calendar-day-jobs {
  display: flex;
  flex-direction: column;
  gap: .25rem;
}

.calendar-job-slot.empty {
  min-height: 24px;
}

.calendar-job-chip {
  display: flex;
  align-items: flex-start;
  gap: .3rem;
  width: 100%;
  padding: .2rem .4rem;
  border: 0;
  border-radius: 5px;
  background: rgba(var(--tint), .08);
  color: #fff;
  font: inherit;
  font-size: .7rem;
  line-height: 1.3;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  cursor: pointer;
}

/* Two-line chip: who and when on top, what it's worth underneath. */
.calendar-job-chip-lines {
  display: grid;
  gap: .1rem;
  min-width: 0;
  flex: 1;
}

.calendar-job-chip-main {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calendar-job-chip-main {
  font-weight: 650;
}

.calendar-job-chip-meta b {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto;
}

.calendar-job-chip-meta {
  display: flex;
  align-items: center;
  gap: .26rem;
  min-width: 0;
  font-size: .62rem;
  line-height: 1.25;
  opacity: .82;
  white-space: nowrap;
  overflow: hidden;
}

.calendar-job-chip-meta em {
  font-style: normal;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto;
}

.calendar-job-chip-meta>span {
  flex: 0 1 auto;
  overflow: hidden;
}

/* Dot separators, so the row reads as one line rather than three chips. */
.calendar-job-chip-meta>*+*::before {
  content: '·';
  margin-right: .26rem;
  opacity: .6;
}

.calendar-job-chip-city {
  font-size: .6rem;
  line-height: 1.2;
  opacity: .72;
  letter-spacing: .01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.calendar-job-chip-crew {
  flex: 0 0 auto;
  padding: 0 .24rem;
  border-radius: 3px;
  background: rgba(var(--tint), .16);
  font-weight: 800;
  letter-spacing: .02em;
}

.calendar-job-chip-crew::before {
  content: none !important;
}

.calendar-job-band-badge {
  flex: 0 0 auto;
  max-width: 46%;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: .12rem .34rem;
  border-radius: 999px;
  font-size: .56rem;
  font-weight: 900;
  letter-spacing: .03em;
  text-transform: uppercase;
}

.calendar-job-chip:hover {
  background: rgba(var(--tint), .16);
}

.calendar-job-chip.status-new_lead {
  background: rgba(255, 209, 102, .16);
  color: var(--gold-ink);
}

.calendar-job-chip.status-in_progress {
  background: rgba(255, 138, 61, .18);
  color: var(--ink-orange-2);
}

.calendar-job-chip.status-complete {
  background: rgba(120, 220, 150, .16);
  color: var(--ink-green-1);
}

/* Calendar chips are draggable (tap opens the job, drag moves it to a new date).
   touch-action:none keeps a touch-drag from scrolling the page instead. */
.calendar-job-chip {
  touch-action: none;
  cursor: grab;
  -webkit-user-select: none;
  user-select: none;
}

.calendar-job-chip:active {
  cursor: grabbing;
}

.calendar-job-chip.dragging {
  opacity: .4;
}

.calendar-year-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .75rem;
}

.calendar-year-card {
  min-width: 0;
  min-height: 150px;
  padding: .85rem;
  border: 1px solid var(--edge-t10);
  border-radius: 12px;
  background: rgba(var(--tint), .025);
}

.calendar-year-card-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: .75rem;
  margin-bottom: .7rem;
}

.calendar-year-card-header strong {
  color: var(--text);
  font-size: .95rem;
}

/* The month name is the way INTO a month and it measured 20px tall — the
   smallest target on the page, on the view whose whole job is picking a month. */
.calendar-year-month-link {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: .95rem;
  font-weight: 900;
  text-align: left;
  cursor: pointer;
}

.calendar-year-month-link:hover {
  color: var(--gold-ink);
  text-decoration: underline;
  text-underline-offset: 4px;
}

.calendar-year-card-header span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 24px;
  padding: 0 .45rem;
  border: 1px solid var(--cedge-amber-12);
  border-radius: 999px;
  background: rgba(255, 209, 102, .08);
  color: var(--gold-ink);
  font-size: .78rem;
  font-weight: 900;
}

/* A month with nothing in it is not news. Eleven gold "0 jobs" pills down a
   year of empty months made the quiet part the loudest thing on the screen. */
.calendar-year-card-header span[data-empty] {
  border-color: var(--edge-t10);
  background: rgba(var(--tint), 0.03);
  color: var(--mute-t45);
}

.calendar-year-jobs {
  display: grid;
  gap: .35rem;
}

.calendar-year-job {
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: .45rem;
  align-items: center;
  width: 100%;
  min-height: 44px;
  padding: .38rem .45rem;
  border: 1px solid var(--edge-t08);
  border-radius: 8px;
  background: rgba(var(--tint), .045);
  color: var(--text);
  font: inherit;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}

.calendar-year-job:hover {
  border-color: var(--cedge-orange-26);
  background: rgba(255, 138, 61, .11);
}

.calendar-year-job span {
  color: var(--mute-i55);
  font-size: .66rem;
  font-weight: 900;
  text-transform: uppercase;
}

.calendar-year-job strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: .78rem;
}

.calendar-year-job.status-new_lead {
  color: var(--gold-ink);
}

.calendar-year-job.status-in_progress {
  color: var(--ink-orange-4);
}

.calendar-year-job.status-complete {
  color: var(--ink-green-4);
}

.calendar-year-more,
.calendar-year-empty {
  margin: .45rem 0 0;
  color: var(--mute-i48);
  font-size: .76rem;
}

/* ---- Year: which twelve months, and how full each one is ------------------
   The toolbar above says "August 2026" — the month the arrows step, not what
   is on screen — so the one view that is not about a month was captioned with
   one. And each card carried a bare job count: three 40-hour jobs and three
   one-hour jobs both printed 3. */
.calendar-year-range {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.2rem 0.6rem;
  margin: 0 0 0.7rem;
}

.calendar-year-range strong {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 800;
}

.calendar-year-range span {
  color: var(--mute-t50);
  font-size: 0.78rem;
}

.calendar-year-load {
  margin: 0 0 0.6rem;
}

.calendar-year-load-bar {
  height: 6px;
  margin-bottom: 0.3rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.1);
  overflow: hidden;
}

.calendar-year-load-bar>span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
}

/* The same ramp Capacity uses, and the figure under it says the same thing in
   words — so a card still reads correctly with the color stripped out. */
.calendar-year-load[data-load='none'] .calendar-year-load-bar>span {
  background: var(--mute-i42);
}

.calendar-year-load[data-load='high'] .calendar-year-load-bar>span {
  background: var(--gold-ink);
}

.calendar-year-load[data-load='over'] .calendar-year-load-bar>span {
  background: #ff6b6b;
}

.calendar-year-load>p {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15rem 0.45rem;
  margin: 0;
  font-size: 0.74rem;
  color: var(--mute-i55);
}

.calendar-year-load>p b {
  color: var(--text);
  font-size: 0.86rem;
  font-weight: 850;
}

.calendar-year-load>p em {
  margin-left: auto;
  font-style: normal;
  font-weight: 800;
  color: var(--gold-ink);
}

.calendar-year-load[data-load='over']>p b {
  color: var(--ink-orange-2);
}

.calendar-year-unknown {
  margin: 0.25rem 0 0;
  color: var(--ink-amber-1);
  font-size: 0.7rem;
  font-weight: 700;
}

@media (max-width: 640px) {
  .calendar-grid {
    grid-template-columns: repeat(7, minmax(32px, 1fr));
  }

  .calendar-cell {
    min-height: 64px;
  }

  .calendar-job-chip {
    font-size: .62rem;
  }

  .calendar-year-grid {
    grid-template-columns: 1fr;
  }
}

/* THE TOOLBAR MEASURES ITSELF AGAINST THE COLUMN, NOT THE WINDOW.
   Every rule that used to compact this row was a @media query, written when the
   calendar WAS the page. It is a column in a three-column workbench now, so at
   1920 the window says "huge" and the calendar has 728px — which is how a
   toolbar built to fit ended up 85px tall at every width measured. A container
   query asks the only question that matters: how much room is there HERE.

   The wrapper exists because an element cannot query itself. It is deliberately
   the toolbar's own box and not the panel: `container-type` implies
   `contain: layout`, which makes the element a containing block for fixed
   descendants — on the panel that would re-anchor the job dialog and the drag
   ghost. The views menu is a portal to <body>, so it is outside this. */
.calendar-toolbar-wrap {
  container: caltoolbar / inline-size;
}

.calendar-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: .75rem;
  margin: 0 0 .75rem;
}

.calendar-hint {
  margin: 0;
  color: var(--mute-t50);
  font-size: .82rem;
}

/* The group is ringed in cool light; the segment you're on is filled with the
   brand orange. It used to be a flat white pill — the one bright white object
   on a near-black page, which read as a hole punched in the UI rather than as
   a selected state. Orange also keeps "selected" meaning the same thing here
   as it does on every other control in the dashboard. */
.calendar-view-toggle {
  display: inline-flex;
  padding: .2rem;
  border: 1px solid var(--cedge-sky-5);
  border-radius: 999px;
  background: rgba(58, 160, 255, .05);
  box-shadow: 0 0 14px rgba(58, 160, 255, .16), inset 0 0 12px rgba(58, 160, 255, .05);
}

.calendar-view-toggle button {
  border: 0;
  border-radius: 999px;
  padding: .35rem .65rem;
  background: transparent;
  color: var(--mute-t58);
  font: inherit;
  font-size: .75rem;
  font-weight: 800;
  cursor: pointer;
  transition: color .16s ease, box-shadow .16s ease;
}

.calendar-view-toggle button.active {
  background: linear-gradient(135deg, #ff5a1f 0%, #ff8a3d 100%);
  /* Dark ink, not white. White on this gradient is 2.3:1 at its light end —
     the same failure the primary button had, and --on-accent is the token the
     rest of the app already uses for text that has to sit ON the accent. */
  color: var(--on-accent);
  box-shadow: 0 0 0 1px rgba(255, 176, 120, .55), 0 0 14px rgba(255, 122, 33, .5);
}

.calendar-view-toggle button:not(.active):hover {
  color: #fff;
}

/* ---- View switcher (the dashboard calendar; the demo keeps the segmented
   toggle above). Five views won't fit in a segmented control without shrinking
   every label to an abbreviation, so this is one button that names the view
   you're in and opens a menu. Same blue ring + orange lit treatment. ---- */
/* .calendar-toolbar is flex with space-between, so this sits hard right — the
   top-right corner of the calendar. margin-left:auto keeps it there even when
   the month nav wraps to its own line. */
/* THE THREE YOU LIVE IN, ON THE SURFACE.
   Day, Week and Month are the zoom level and get switched constantly; they used
   to cost two clicks and a read — open the menu, find the row, press it. They
   are a segmented control now and the menu keeps the other four, which are
   destinations you pick occasionally rather than a zoom.

   Segmented, not three loose buttons: one shared border and hairline dividers
   say "these three are one choice, and it is the one you are in", which three
   separate pills do not. */
.calendar-view-menu {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-left: auto;
}

/* No inner padding, so the buttons themselves are the full height of the group
   and a 44px target is a 44px target. With 2px of padding the group measured
   33px and the pressable part of it 27px. */
.calendar-view-quick {
  display: inline-flex;
  align-items: stretch;
  border: 1px solid var(--cedge-sky-6);
  border-radius: 12px;
  background: rgba(58, 160, 255, 0.05);
}

.calendar-view-quick-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 44px;
  padding: 0 0.7rem;
  border: 1px solid transparent;
  border-radius: 11px;
  background: transparent;
  color: var(--mute-t62);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.15;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.14s ease, background 0.14s ease, border-color 0.14s ease;
}

.calendar-view-quick-btn svg {
  width: 0.95rem;
  height: 0.95rem;
  flex: none;
}

/* The divider is a sibling rule rather than a border on each button, so the
   pressed one can carry its own border without the line doubling beside it. */
.calendar-view-quick-btn+.calendar-view-quick-btn {
  box-shadow: inset 1px 0 0 var(--edge-t10);
}

.calendar-view-quick-btn.active+.calendar-view-quick-btn,
.calendar-view-quick-btn.active {
  box-shadow: none;
}

.calendar-view-quick-btn:hover {
  color: var(--text);
  background: rgba(var(--tint), 0.05);
}

.calendar-view-quick-btn.active {
  border-color: var(--cedge-orange-27);
  background: rgba(255, 122, 33, 0.12);
  color: var(--accent-ink);
}

.calendar-view-quick-btn:focus-visible {
  outline: 2px solid rgba(255, 176, 120, 0.8);
  outline-offset: 2px;
}

/* WHEN THE COLUMN GETS TIGHT, THE WORDS GO AND THE ICONS STAY.
   Measured against the toolbar's own width, so it fires on a 690px calendar
   inside an 1440px window — which the old `@media (max-width: 900px)` version
   never did, and that is the width where the row was breaking. Icons keep the
   three one press away rather than pushing them back into the menu.

   720px is the number because it is what the row needs with the labels on:
   nav 328 + views 246 + menu 109 + gaps 24 = 707. */
@container caltoolbar (max-width: 720px) {
  .calendar-view-quick-btn {
    padding: 0 0.62rem;
    font-size: 0;
    gap: 0;
  }

  .calendar-view-quick-btn svg {
    width: 1.15rem;
    height: 1.15rem;
  }
}

/* QUIETER THAN THE GROUP BESIDE IT, NOT LOUDER.
   This carried two glows — a blue outer and a blue inset — which made the way
   to the four views you rarely visit the brightest object in the row, beside a
   segmented control for the three you live in that has neither. Same border,
   same background, no glow: they read as one family of view controls. */
.calendar-view-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  min-height: 46px;
  padding: 0 0.7rem;
  border: 1px solid var(--cedge-sky-6);
  border-radius: 12px;
  background: rgba(58, 160, 255, 0.05);
  color: var(--text);
  font: inherit;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.calendar-view-trigger:hover,
.calendar-view-trigger.open {
  border-color: var(--cedge-orange-27);
  background: rgba(255, 122, 33, 0.08);
}

.calendar-view-trigger:focus-visible {
  outline: 2px solid rgba(255, 176, 120, 0.8);
  outline-offset: 2px;
}

.calendar-view-trigger-ic {
  width: 1.05rem;
  height: 1.05rem;
  flex: none;
  color: var(--accent);
}

.calendar-view-trigger-text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.15;
}

.calendar-view-trigger-text small {
  font-size: 0.6rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--mute-t60);
}

.calendar-view-trigger-text strong {
  font-size: 0.8rem;
  font-weight: 800;
}

.calendar-view-caret {
  width: 0.85rem;
  height: 0.85rem;
  flex: none;
  color: var(--mute-t50);
  transition: transform 0.16s ease;
}

.calendar-view-trigger.open .calendar-view-caret {
  transform: rotate(180deg);
}

/* THE MENU BUTTON'S WORDS GO FIRST, before the three views lose theirs.
   780 and not 560: the calendar column is 728px at 1920 in the three-column
   layout, and Day's nav is the widest of the three (a date, not a range), so
   that width has to be paid for out of something. Day / Week / Capacity are
   the control people press; this is the way to four views they visit
   occasionally, and it keeps its icon, its caret and its accessible name.

   BELOW THE BASE RULES ON PURPOSE. A container query carries no extra
   specificity, so written above them `display: flex` won on source order and
   this block measured as if it were not there. */
@container caltoolbar (max-width: 780px) {
  .calendar-view-trigger {
    padding: 0 0.55rem;
  }

  .calendar-view-trigger-text {
    display: none;
  }
}


.calendar-view-panel {
  padding: 0.35rem;
  border: 1px solid var(--edge-t12);
  border-radius: 14px;
  background: rgba(10, 20, 33, 0.97);
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
}

.calendar-view-option {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  width: 100%;
  min-height: 44px;
  padding: 0.5rem 0.55rem;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.calendar-view-option:hover {
  background: rgba(var(--tint), 0.06);
}

.calendar-view-option.active {
  background: rgba(255, 122, 33, 0.12);
  box-shadow: inset 0 0 0 1px rgba(255, 122, 33, 0.3);
}

.calendar-view-option-ic {
  width: 1.1rem;
  height: 1.1rem;
  flex: none;
  color: var(--mute-t55);
}

.calendar-view-option.active .calendar-view-option-ic {
  color: var(--accent);
}

.calendar-view-option-text {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
  flex: 1 1 auto;
}

.calendar-view-option-text strong {
  font-size: 0.82rem;
  font-weight: 800;
}

.calendar-view-option-text small {
  font-size: 0.7rem;
  color: var(--mute-t50);
}

.calendar-view-option-tick {
  flex: none;
  color: var(--accent);
  font-weight: 900;
  font-size: 0.8rem;
}

/* ---- Day columns, in the same menu -------------------------------------
   Saturday and Sunday used to be two chips in the toolbar. They are switches
   for what the grid draws, which is what this menu is for, and as chips they
   cost the row 224px in every month — see CalendarDayColumns for the whole
   argument. Separated by a rule and a heading so a checkbox is never mistaken
   for one of the views above it. */
.calendar-col-group {
  margin-top: 0.35rem;
  padding-top: 0.35rem;
  border-top: 1px solid var(--edge-t10);
}

.calendar-col-heading {
  margin: 0 0 0.15rem;
  padding: 0 0.55rem;
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--mute-t45);
}

/* Filled or empty, never colour alone: the state has to survive a monochrome
   screen and a red-green eye. */
.calendar-col-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.1rem;
  height: 1.1rem;
  flex: none;
  border: 1.5px solid var(--edge-t22);
  border-radius: 5px;
  color: var(--on-accent);
  font-size: 0.72rem;
  font-weight: 900;
  line-height: 1;
}

.calendar-col-box[data-on] {
  border-color: var(--cedge-orange-38);
  background: var(--accent);
}

/* Hidden AND holding work — the one state that is not a preference. Amber, and
   the same amber the toolbar's notice uses, so the two are obviously the same
   fact said in two places. */
.calendar-col-option[data-hiding] .calendar-col-box {
  border-color: var(--cedge-orange-54);
}

.calendar-col-option[data-hiding] .calendar-view-option-text small {
  color: var(--ink-amber-1);
}

/* ---- "3 jobs are booked on a day the calendar is not showing" -----------
   The same shape as .calendar-view-swapped above it, deliberately: both say
   what is missing from the grid and both carry the way to get it back. Amber
   rather than that one's dashed grey, because a view standing down at a narrow
   window is an explanation and work you cannot see is not. */
.calendar-hidden-days {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.15rem 0.45rem;
  margin: 0 0 0.55rem;
  padding: 0.45rem 0.7rem;
  border: 1px solid var(--cedge-orange-54);
  border-radius: 10px;
  background: rgba(255, 176, 32, 0.1);
  color: var(--ink-amber-1);
  font-size: 0.76rem;
  line-height: 1.45;
}

.calendar-hidden-days svg {
  width: 1rem;
  height: 1rem;
  flex: none;
}

.calendar-hidden-days>span {
  min-width: 0;
}

.calendar-hidden-days button {
  min-height: 44px;
  padding: 0 0.55rem;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 800;
  text-decoration: underline;
  white-space: nowrap;
  cursor: pointer;
}

.calendar-hidden-days button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

.calendar-view-empty {
  margin: 1.5rem 0;
  padding: 2rem 1rem;
  border: 1px dashed var(--edge-t12);
  border-radius: 14px;
  text-align: center;
  color: var(--mute-t50);
  font-size: 0.9rem;
}

/* ---- Agenda: the days that have work, and nothing else. Rows are wide, so
   everything the month cell had to ellipsis or drop into a tooltip fits. ---- */
/* ---- Job list: search and a status filter --------------------------------
   This is the one view you can look something UP in. Every other view is
   bounded by a day; this is the month — 124 rows on a real account — and it had
   no way to narrow it, so finding one customer meant scrolling past everybody
   else. Only rendered above six jobs: three rows do not need a search box, and
   offering one suggests you are missing something. */
.calendar-agenda-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin: 0.9rem 0 0;
}

.calendar-agenda-search {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  flex: 1 1 14rem;
  min-width: 0;
  min-height: 44px;
  padding: 0 0.75rem;
  border: 1px solid var(--edge-t14);
  border-radius: 999px;
  background: rgba(var(--tint), 0.03);
  color: var(--mute-t50);
}

.calendar-agenda-search svg {
  width: 1rem;
  height: 1rem;
  flex: none;
}

.calendar-agenda-search input {
  min-width: 0;
  flex: 1 1 auto;
  border: 0;
  background: none;
  color: var(--text);
  font: inherit;
  font-size: 0.86rem;
}

.calendar-agenda-search input::placeholder {
  color: var(--muted-2);
  opacity: 0.88;
}

.calendar-agenda-search input:focus {
  outline: none;
}

.calendar-agenda-search:focus-within {
  border-color: var(--cedge-orange-38);
}

.calendar-agenda-status select {
  min-height: 44px;
  padding: 0 0.7rem;
  border: 1px solid var(--edge-t14);
  border-radius: 999px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  font-size: 0.84rem;
  cursor: pointer;
}

.calendar-agenda-status select:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.calendar-agenda-count {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0 auto;
  color: var(--mute-t50);
  font-size: 0.78rem;
  font-variant-numeric: tabular-nums;
}

.calendar-agenda-count button {
  min-height: 44px;
  padding: 0 0.5rem;
  border: 0;
  background: none;
  color: var(--accent-ink);
  font: inherit;
  font-weight: 750;
  text-decoration: underline;
  cursor: pointer;
}

.calendar-agenda-count button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

.calendar-view-empty button {
  min-height: 44px;
  padding: 0 0.4rem;
  border: 0;
  background: none;
  color: var(--accent-ink);
  font: inherit;
  font-weight: 750;
  text-decoration: underline;
  cursor: pointer;
}

.calendar-agenda {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0.9rem 0 0;
  padding: 0;
  list-style: none;
}

.calendar-agenda-day {
  display: grid;
  grid-template-columns: 3.6rem minmax(0, 1fr);
  gap: 0.75rem;
  align-items: start;
  padding: 0.6rem;
  border: 1px solid var(--edge-t08);
  border-radius: 14px;
  background: rgba(var(--tint), 0.02);
}

.calendar-agenda-day.today {
  border-color: var(--cedge-orange-28);
  background: rgba(255, 138, 61, 0.05);
}

.calendar-agenda-date {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.1rem;
  padding-top: 0.35rem;
}

.calendar-agenda-date small {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mute-t45);
}

.calendar-agenda-date strong {
  font-size: 1.25rem;
  font-weight: 800;
  line-height: 1;
}

.calendar-agenda-day.today .calendar-agenda-date strong {
  color: var(--accent);
}

.calendar-agenda-flag {
  margin-top: 0.15rem;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ink-amber-1);
}

.calendar-agenda-jobs {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-width: 0;
}

.calendar-agenda-job {
  display: grid;
  grid-template-columns: 5.5rem minmax(0, 1.6fr) minmax(0, auto) minmax(0, auto) 2.6rem;
  gap: 0.7rem;
  align-items: center;
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--edge-t09);
  border-left-width: 3px;
  border-radius: 10px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.14s ease, background 0.14s ease;
}

.calendar-agenda-job:hover {
  border-color: var(--cedge-orange-29);
  background: rgba(255, 138, 61, 0.05);
}

.calendar-agenda-job:focus-visible {
  outline: 2px solid rgba(255, 176, 120, 0.75);
  outline-offset: 2px;
}

.calendar-agenda-when {
  font-size: 0.76rem;
  font-weight: 800;
  color: rgba(var(--tint), 0.72);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.calendar-agenda-who {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
}

.calendar-agenda-who strong {
  font-size: 0.86rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calendar-agenda-who small {
  font-size: 0.72rem;
  color: var(--mute-t50);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Grid items are min-width:auto, so a nowrap badge like "Invoice sent ·
   Awaiting payment" refuses to shrink and pushes the whole page sideways.
   min-width:0 lets the track win; the ellipsis is the safety valve. */
.calendar-agenda-job>* {
  min-width: 0;
}

.calendar-agenda-badge {
  justify-self: start;
  max-width: 100%;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  background: rgba(var(--tint), 0.08);
  color: rgba(var(--tint), 0.75);
}

.calendar-agenda-figures {
  display: flex;
  gap: 0.6rem;
  align-items: baseline;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.calendar-agenda-figures em {
  font-style: normal;
  font-weight: 800;
  font-size: 0.82rem;
}

.calendar-agenda-figures i {
  font-style: normal;
  font-size: 0.74rem;
  color: var(--mute-t50);
}

.calendar-agenda-crew {
  justify-self: end;
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--mute-t55);
  white-space: nowrap;
}

/* ---- Timeline: one bar per job across the month. The only view where a
   multi-day job reads as a single thing rather than as N separate chips. ---- */
.calendar-timeline-scroll {
  margin-top: 0.9rem;
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 138, 61, 0.38) transparent;
}

.calendar-timeline-scroll::-webkit-scrollbar {
  height: 10px;
}

.calendar-timeline-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.calendar-timeline-scroll::-webkit-scrollbar-thumb {
  background: rgba(255, 138, 61, 0.32);
  background-clip: content-box;
  border: 2px solid transparent;
  border-radius: 999px;
}

.calendar-timeline {
  display: grid;
  align-items: center;
  gap: 0.3rem 0;
  padding-bottom: 0.5rem;
}

.calendar-timeline-corner,
.calendar-timeline-head {
  position: sticky;
  top: 0;
  padding-bottom: 0.35rem;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mute-t42);
  text-align: center;
}

.calendar-timeline-corner {
  text-align: left;
  padding-left: 0.15rem;
}

.calendar-timeline-column {
  border-radius: 6px;
  pointer-events: none;
  /* The grid centres its items, which collapses an empty span to zero height.
     Stretch is what makes these full-height columns rather than nothing. */
  align-self: stretch;
}

.calendar-timeline-column.weekend {
  background: rgba(var(--tint), 0.055);
}

.calendar-timeline-column.today {
  background: rgba(255, 138, 61, 0.13);
  box-shadow: inset 0 0 0 1px rgba(255, 138, 61, 0.34);
}

.calendar-timeline-head.weekend {
  color: var(--mute-t22);
}

.calendar-timeline-head.today {
  color: var(--accent);
}

.calendar-timeline-name {
  padding-right: 0.6rem;
  font-size: 0.78rem;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 44px, not the 26px these measured. Thirteen of them are the entire content of
   this view, and a Gantt bar you cannot reliably hit is a chart you can only
   read. The rows grow with them, which a scrolling view can afford — and the
   labels the bars now carry needed the height anyway. */
.calendar-timeline-bar {
  display: flex;
  align-items: center;
  min-width: 0;
  height: 44px;
  padding: 0 0.5rem;
  border: 0;
  border-radius: 8px;
  background: rgba(var(--tint), 0.12);
  color: #fff;
  font: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  cursor: pointer;
  transition: filter 0.14s ease, box-shadow 0.14s ease;
}

/* THE BAR SAYS WHAT IT IS. It used to be a bare block below three days and a
   single line above — and with one-day jobs on the grid that made most of them
   unlabeled rectangles you had to hover one at a time. Three pieces, each
   appearing only once the bar is wide enough to hold it: the span always, the
   client from four days, the value from six. */
.calendar-timeline-bar-label {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  min-width: 0;
  overflow: hidden;
}

.calendar-timeline-bar-label b {
  flex: none;
  font-weight: 850;
}

/* The bar measures itself. A day count cannot: three days is 102px across a
   month and 286px across a week, and the same rule cannot be right for both. */
/* NAMED. An unnamed @container binds to the nearest ancestor container, which
   in a stylesheet this size is a promise about everything anyone adds later —
   and these two thresholds are about a Gantt bar, not about whatever else
   happens to be a container above one. */
.calendar-timeline-bar {
  container: timelinebar / inline-size;
}

@container timelinebar (max-width: 196px) {
  .calendar-timeline-bar-label em {
    display: none;
  }
}

@container timelinebar (max-width: 126px) {
  .calendar-timeline-bar-label i {
    display: none;
  }
}

.calendar-timeline-bar-label i,
.calendar-timeline-bar-label em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-style: normal;
  font-weight: 650;
  opacity: 0.85;
}

.calendar-timeline-bar span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Projects: month or week ---------------------------------------------
   31 columns plus a 180px name gutter is 986px, and the calendar column is
   728px at 1920 — so the month arrived pre-scrolled sideways with every bar too
   narrow to label. A week of the same grid gives each day ~78px. */
.calendar-timeline-zoom {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.6rem;
}

.calendar-timeline-zoom-btn {
  min-height: 44px;
  padding: 0 0.9rem;
  border: 1px solid var(--edge-t14);
  border-radius: 999px;
  background: rgba(var(--tint), 0.03);
  color: var(--mute-i62);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 750;
  cursor: pointer;
}

.calendar-timeline-zoom-btn:hover {
  border-color: var(--cedge-orange-38);
  color: var(--text);
}

.calendar-timeline-zoom-btn.active {
  border-color: var(--cedge-orange-27);
  background: rgba(255, 122, 33, 0.12);
  color: var(--accent-ink);
}

.calendar-timeline-zoom-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.calendar-timeline-zoom-note {
  margin-left: auto;
  color: var(--mute-t50);
  font-size: 0.76rem;
  font-weight: 700;
}

.calendar-timeline-bar:hover {
  filter: brightness(1.18);
  box-shadow: 0 0 0 1px rgba(var(--tint), 0.28);
}

.calendar-timeline-bar:focus-visible {
  outline: 2px solid rgba(255, 176, 120, 0.85);
  outline-offset: 2px;
}

@media (max-width: 720px) {

  /* The five-column job row stops fitting; drop to name + figures and let the
     rest wrap under it. */
  .calendar-agenda-job {
    grid-template-columns: 4.6rem minmax(0, 1fr);
    row-gap: 0.35rem;
  }

  .calendar-agenda-badge,
  .calendar-agenda-figures {
    grid-column: 2;
  }

  /* On its own row here, so it can wrap and keep the whole status rather than
     ellipsising to "Invoice sent · Awaiti…". */
  .calendar-agenda-badge {
    white-space: normal;
    overflow: visible;
  }

  .calendar-agenda-crew {
    display: none;
  }

  .calendar-view-trigger-text small {
    display: none;
  }
}

/* The crew button sits OVER the chip's top-right rather than beside it. In a
   117px month cell it was taking 20px of flow — nearly a third of what was
   left for text after padding — which is why the money was being cut off. It
   keeps its full tap target; only the name line reserves room for it. */
.calendar-job-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: .3rem;
}

.calendar-job-item .calendar-job-chip {
  flex: 1 1 auto;
  min-width: 0;
}

.calendar-job-item>.calendar-crew-toggle {
  position: absolute;
  right: 2px;
  top: 2px;
  z-index: 2;
}

.calendar-job-item>.calendar-crew-toggle+.calendar-job-chip .calendar-job-chip-main,
.calendar-job-item .calendar-job-chip .calendar-job-chip-main {
  padding-right: 1.25rem;
}

.calendar-band {
  position: relative;
  z-index: 1;
  min-height: 26px;
  padding: .16rem .22rem;
  border: 1px solid var(--edge-t08);
  background: rgba(var(--tint), .08);
  box-shadow: inset 0 0 0 1px rgba(var(--tint), .03);
}

.calendar-band .calendar-job-chip {
  padding-left: .22rem;
  background: transparent;
  color: inherit;
}

.calendar-band .calendar-job-chip:hover {
  background: transparent;
}

.calendar-band.status-new_lead {
  border-color: var(--rail-new);
  background: rgba(255, 209, 102, .2);
  color: var(--gold-ink);
}

.calendar-band.status-in_progress {
  border-color: var(--rail-progress);
  background: rgba(255, 138, 61, .23);
  color: var(--ink-orange-4);
}

.calendar-band.status-complete {
  border-color: var(--rail-complete);
  background: rgba(120, 220, 150, .18);
  color: var(--ink-green-1);
}

.calendar-band.calendar-band-color-0 {
  border-color: var(--rail-crew-0);
  background: rgba(255, 138, 61, .24);
  color: var(--ink-orange-4);
}

.calendar-band.calendar-band-color-1 {
  border-color: var(--rail-crew-1);
  background: rgba(61, 184, 255, .2);
  color: var(--ink-sky-3);
}

.calendar-band.calendar-band-color-2 {
  border-color: var(--rail-crew-2);
  background: rgba(120, 220, 150, .2);
  color: var(--ink-green-4);
}

.calendar-band.calendar-band-color-3 {
  border-color: var(--rail-crew-3);
  background: rgba(255, 209, 102, .2);
  color: var(--ink-amber-5);
}

.calendar-band.calendar-band-color-4 {
  border-color: var(--rail-crew-4);
  background: rgba(255, 112, 163, .2);
  color: var(--ink-pink-1);
}

.calendar-band.calendar-band-color-5 {
  border-color: var(--rail-crew-5);
  background: rgba(176, 141, 255, .2);
  color: var(--ink-violet-3);
}

.calendar-band-single {
  border-radius: 7px;
}

.calendar-band-start {
  margin-right: calc(-.4rem - 7px);
  border-right-color: transparent;
  border-radius: 7px 0 0 7px;
}

.calendar-band-middle {
  margin-right: calc(-.4rem - 7px);
  margin-left: calc(-.4rem - 7px);
  border-right-color: transparent;
  border-left-color: transparent;
  border-radius: 0;
}

.calendar-band-end {
  margin-left: calc(-.4rem - 7px);
  border-left-color: transparent;
  border-radius: 0 7px 7px 0;
}

.calendar-band-middle .calendar-job-chip,
.calendar-band-end .calendar-job-chip {
  color: transparent;
}

.calendar-band-middle .calendar-job-band-badge,
.calendar-band-end .calendar-job-band-badge {
  color: inherit;
}

.calendar-band-middle .calendar-job-chip::selection,
.calendar-band-end .calendar-job-chip::selection {
  color: transparent;
}

.calendar-crew-toggle {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 .3rem;
  border-radius: 999px;
  border: 1px dashed var(--edge-t30);
  background: rgba(var(--tint), .04);
  color: rgba(var(--tint), .65);
  font-size: .6rem;
  font-weight: 700;
  letter-spacing: .02em;
  cursor: pointer;
  line-height: 1;
  font-family: inherit;
}

.calendar-crew-toggle:hover {
  border-color: #ff8a3d;
  color: var(--ink-orange-2);
}

.calendar-crew-toggle.has-crew {
  border-style: solid;
  border-color: var(--cedge-green-8);
  background: rgba(120, 220, 150, .14);
  color: var(--ink-green-1);
}

/* Crew initials sit at 10px inside a green pill — the smallest coloured text on
   the page, so it gets the deepest value in the family rather than the shared one. */
:root[data-theme='light'] .calendar-crew-toggle.has-crew {
  border-color: #1f9d63;
  background: #e4f4ea;
  color: #0c5c34;
}

@media (max-width: 640px) {
  .calendar-crew-toggle {
    min-width: 16px;
    height: 16px;
    font-size: .55rem;
  }
}

.crew-assign-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background: rgba(5, 8, 15, .65);
}

.crew-assign-panel {
  width: 100%;
  max-width: 360px;
  max-height: min(80vh, 520px);
  overflow-y: auto;
  padding: 1.1rem 1.2rem 1.3rem;
  border: 1px solid var(--edge-t12);
  border-radius: 16px;
  background: #12161f;
  box-shadow: 0 20px 60px rgba(0, 0, 0, .5);
}

.schedule-job-actions-panel {
  max-width: 520px;
}

.crew-assign-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: .75rem;
  margin-bottom: .9rem;
}

.crew-assign-title {
  margin: 0;
  font-weight: 700;
  font-size: 1rem;
}

.crew-assign-sub {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: .35rem;
  margin: .2rem 0 0;
  color: var(--mute-t55);
  font-size: .8rem;
}

.crew-assign-close {
  flex: none;
  padding: .2rem .45rem;
  border: none;
  border-radius: 6px;
  background: none;
  color: var(--mute-t50);
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
}

.crew-assign-close:hover {
  color: #fff;
  background: rgba(var(--tint), .08);
}

.crew-assign-list {
  display: flex;
  flex-direction: column;
  gap: .4rem;
}

.crew-assign-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  width: 100%;
  padding: .55rem .7rem;
  border: 1px solid var(--edge-t10);
  border-radius: 10px;
  background: rgba(var(--tint), .02);
  color: #fff;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  transition: border-color .15s ease, background .15s ease;
}

.crew-assign-option:hover {
  border-color: var(--cedge-orange-30);
}

.crew-assign-option.assigned {
  border-color: var(--cedge-green-8);
  background: rgba(120, 220, 150, .08);
}

.crew-assign-option.pending {
  opacity: .6;
  cursor: wait;
}

.crew-assign-option-info {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .1rem;
}

.crew-assign-option-name {
  font-weight: 600;
  font-size: .88rem;
}

.crew-assign-option-role {
  color: var(--mute-t50);
  font-size: .75rem;
}

.crew-assign-check {
  flex: none;
  width: 20px;
  height: 20px;
  border: 1.5px solid var(--edge-t30);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .7rem;
  color: transparent;
}

.crew-assign-option.assigned .crew-assign-check {
  background: #78dc96;
  border-color: #78dc96;
  color: var(--bg-2);
}

