  text-transform: uppercase;
}

.week-glance-jobs {
  display: flex;
  flex-direction: column;
  gap: .4rem;
}

.week-glance-job {
  display: flex;
  flex-direction: column;
  gap: .1rem;
  padding: .35rem .45rem;
  border-radius: 7px;
  background: rgba(var(--tint), .06);
  color: #fff;
  text-decoration: none;
}

.week-glance-job:hover {
  background: rgba(var(--tint), .13);
}

/* The crew pill follows the name; it is not pushed to the far edge.
   space-between put the whole gap between the two, so in a narrow column — where
   a name like "Hannah Ostrowski" wraps to two lines — the pill ended up hard
   against the card's right border, vertically centred against the gap BETWEEN
   the two lines of the name. It read as belonging to nothing. flex-start on both
   axes keeps it beside the first line of the name it describes, and min-width on
   the name lets the name shrink and wrap rather than shoving the pill out. */
.week-glance-job-top {
  display: flex;
  align-items: flex-start;
  gap: .35rem;
}

.week-glance-job-top strong {
  min-width: 0;
}

.week-glance-job strong {
  font-size: .78rem;
  line-height: 1.25;
}

.week-glance-job span {
  font-size: .68rem;
  color: var(--mute-t55);
}

.week-glance-job .week-glance-crew {
  flex-shrink: 0;
  min-width: 1.35rem;
  padding: .12rem .28rem;
  border: 1px solid var(--cedge-green-14);
  border-radius: 999px;
  background: rgba(120, 220, 150, .14);
  color: var(--ink-green-1);
  font-size: .58rem;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  letter-spacing: .02em;
}

/* 9px initials on a green pill — the smallest text in the product, so the family
   ink is not deep enough for it and it takes the next value down. */
:root[data-theme='light'] .week-glance-job .week-glance-crew {
  border-color: #1f9d63;
  background: #e4f4ea;
  color: #0c5c34;
}

.week-glance-empty {
  margin: 0;
  font-size: .72rem;
  color: var(--mute-t35);
}

