  display: grid;
  place-items: center;
  border: 1px solid var(--edge-t16);
  background: linear-gradient(135deg, rgba(255, 138, 61, 0.28), rgba(120, 220, 150, 0.16));
  color: #fff;
  font-weight: 800;
  letter-spacing: 0.06em;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
}

.crew-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.crew-photo-form {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.crew-photo-button input {
  display: none;
}

/* Crew cards — stronger per-member differentiation and a compact action
   footer (removes the dead space the old descriptive row left behind). */
.crew-card {
  background: rgba(var(--tint), 0.055);
  border-color: var(--edge-t15);
}

.crew-card:hover {
  border-color: var(--cedge-orange-17);
  background: rgba(var(--tint), 0.08);
}

.crew-card-name {
  font-size: 1.18rem;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.01em;
}

.crew-card-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.2rem 0.6rem;
  margin-top: 0.3rem;
}

.crew-card-role {
  font-size: 0.9rem;
  font-weight: 800;
  color: var(--gold-ink);
  letter-spacing: 0.01em;
}

.crew-card-contact {
  font-size: 0.86rem;
  color: var(--mute-t62);
}

.crew-card-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.85rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--rule-t08);
}

/* Current-assignment chips: what each crew member is working on right now. */
.crew-card-jobs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.55rem;
}

.crew-job-chip {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 0.22rem 0.6rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-orange-37);
  background: rgba(255, 138, 61, 0.1);
  color: var(--accent-ink);
  font-size: 0.78rem;
  font-weight: 700;
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.crew-job-chip:hover,
.crew-job-chip:focus-visible {
  background: rgba(255, 138, 61, 0.2);
  border-color: var(--cedge-orange-27);
}

.crew-available-pill {
  display: inline-flex;
  align-items: center;
  padding: 0.22rem 0.6rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-green-19);
  background: rgba(120, 220, 150, 0.1);
  color: var(--ink-green-1);
  font-size: 0.78rem;
  font-weight: 800;
}

/* "Text crew when I add them" toggle in the schedule calendar crew popover, and
   the two-button save row in the schedule unscheduled-jobs crew picker. */
.schedule-crew-notify-toggle {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0.1rem 0 0.6rem;
  font-size: 0.82rem;
  color: rgba(var(--tint), 0.72);
  cursor: pointer;
}

.schedule-crew-notify-toggle input {
  accent-color: #19d6ae;
}

.schedule-crew-picker-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.6rem;
}

/* Account "Danger zone" — delete account */
.danger-zone {
  border-color: var(--cedge-red-8);
}

.danger-zone-eyebrow {
  color: var(--ink-red-3);
}

.delete-account-confirm {
  display: grid;
  gap: 0.5rem;
  max-width: 520px;
}

.delete-account-confirm label {
  font-size: 0.85rem;
  color: rgba(var(--tint), 0.72);
}

/* Avatar-as-uploader: click the "+" badge to add/replace a crew photo. The
   badge sits OUTSIDE the circle (which is overflow:hidden), so it lives as a
   sibling on the positioned label wrapper. */
.crew-photo-upload-form {
  display: inline-flex;
}

.crew-avatar-upload {
  position: relative;
  display: inline-block;
  cursor: pointer;
}

.crew-avatar-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
}

.crew-avatar-add {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #ff7a21;
  color: var(--on-accent);
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1;
  border: 2px solid #0d1826;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  transition: filter 0.12s ease, transform 0.12s ease;
}

.crew-avatar-add.pending {
  font-size: 0.8rem;
}

.crew-avatar-upload:hover .crew-avatar-add {
  filter: brightness(1.1);
  transform: scale(1.05);
}

/* Keyboard focus lands on the visually-hidden file input; surface it on the
   "+" badge so the avatar uploader is a visible focus target. */
.crew-avatar-upload:focus-within .crew-avatar-add {
  outline: 2px solid #fff;
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.6);
}

