  align-items: center;
  gap: 0.35rem;
  width: fit-content;
  max-width: 100%;
  padding: 0.3rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-green-20);
  background: rgba(57, 224, 122, .14);
  color: var(--ink-green-10) !important;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: .01em;
  text-decoration: none;
  transition: background .15s ease, border-color .15s ease;
}

.hero-phone-link:hover,
.hero-phone-link:focus-visible {
  background: rgba(57, 224, 122, .24);
  border-color: var(--cedge-green-21);
}

.hero-email-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  width: fit-content;
  max-width: 100%;
  padding: 0.3rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-amber-11);
  background: rgba(255, 209, 102, .12);
  color: var(--gold-ink) !important;
  font-size: 0.82rem !important;
  font-weight: 800 !important;
  letter-spacing: .01em;
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: background .15s ease, border-color .15s ease;
}

.hero-email-link:hover,
.hero-email-link:focus-visible {
