}

.blog-row {
  border-radius: 14px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
}

.blog-row.is-open {
  border-color: var(--edge-t26);
}

.blog-row-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.75rem 0.95rem;
}

.blog-row-title {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.blog-row-title strong {
  font-size: 0.95rem;
}

.blog-row-title:hover strong {
  color: var(--ink-lime-1);
}

.blog-row-meta {
  font-size: 0.76rem;
  color: var(--mute-t45);
}

/* Live / Scheduled / Draft. The shape carries the state as well as the word,
   so a list of ten posts is scannable without reading every row. */
.blog-status {
  flex: none;
  padding: 0.18rem 0.6rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: rgba(var(--tint), 0.1);
  color: var(--mute-t55);
}

.blog-status-live {
  background: rgba(22, 163, 74, 0.2);
  color: var(--ink-lime-1);
}

.blog-status-scheduled {
  background: rgba(255, 122, 33, 0.16);
  color: var(--ink-orange-1);
}

.blog-row-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0 0.95rem 0.95rem;
