}

.blog-publish-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.7rem;
}

.blog-cover {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin: 0.4rem 0;
}

.blog-cover img {
  width: min(180px, 40%);
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--edge-t12);
}

.blog-cover-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
  margin-top: 0.3rem;
}

.blog-cover-upload {
  display: inline-block;
  padding: 0.5rem 0.9rem;
