}

.blog-cover-upload input {
  display: none;
}

/* Stock photo picker. Portaled to <body> — a fixed overlay inside .panel gets
   trapped by that element's backdrop-filter on iPad and renders behind it. */
.stock-overlay {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.2rem;
  background: rgba(4, 8, 14, 0.72);
}

.stock-modal {
  display: flex;
  flex-direction: column;
  width: min(920px, 100%);
  max-height: min(80vh, 720px);
  border-radius: 16px;
  border: 1px solid var(--edge-t18);
  background: var(--panel, #0f1620);
  overflow: hidden;
}

.stock-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.1rem 0.8rem;
  border-bottom: 1px solid var(--rule-t10);
}

.stock-head small {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.stock-close {
  flex: none;
  padding: 0.3rem 0.55rem;
  border: 0;
  border-radius: 8px;
  background: rgba(var(--tint), 0.08);
  color: inherit;
  font-size: 0.95rem;
  cursor: pointer;
}

.stock-search {
  display: flex;
  gap: 0.5rem;
  padding: 0.8rem 1.1rem;
}

.stock-search input {
  flex: 1;
  min-height: 40px;
  padding: 0.45rem 0.75rem;
  border: 1px solid var(--edge-t18);
  border-radius: 8px;
  background: rgba(var(--tint), 0.06);
  color: var(--text);
}

.stock-body {
  flex: 1;
  overflow-y: auto;
  padding: 0 1.1rem 1.1rem;
}

.stock-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.7rem;
}

.stock-tile {
  display: block;
  padding: 0;
  border: 1px solid var(--edge-t12);
  border-radius: 10px;
  background: rgba(var(--tint), 0.04);
  overflow: hidden;
  cursor: pointer;
  text-align: left;
}

.stock-tile:hover {
  border-color: var(--ink-lime-1);
}

.stock-tile img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

/* Pexels asks for the photographer to be credited. */
.stock-tile span {
  display: block;
  padding: 0.35rem 0.5rem;
  font-size: 0.72rem;
  color: var(--mute-t45);
}

/* The reason there's no "text them" button, where somebody would look for it. */
.marketing-sms-note {
  margin: 1.2rem 0 0;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  background: rgba(var(--tint), 0.05);
  font-size: 0.8rem;
  line-height: 1.55;
  color: var(--mute-t55);
}

/* Selection board — owner side. */
.selection-board {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 0.6rem;
}

.selection-summary {
  display: flex;
  justify-content: space-between;
  gap: 0.8rem;
  flex-wrap: wrap;
  font-size: 0.85rem;
  color: var(--mute-t55);
}

.selection-summary .is-overdue {
  color: var(--ink-orange-1);
  font-weight: 600;
}

.selection-list {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.selection-card {
  padding: 0.85rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.selection-card.is-overdue {
  border-color: var(--ink-orange-1);
  background: rgba(255, 138, 61, 0.1);
}

.selection-card.is-decided {
  border-color: var(--ink-lime-1);
}

.selection-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.selection-allowance {
