}

.selection-template-list {
  list-style: none;
  padding: 0;
  margin: 0.7rem 0 0;
  display: grid;
  gap: 0.4rem;
}

.selection-template-list li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 0.7rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.05);
  font-size: 0.86rem;
}

.selection-template-list em {
  margin-left: 0.5rem;
  font-style: normal;
  font-size: 0.78rem;
  color: var(--mute-t45);
}

.selection-template-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.selection-template-actions .btn {
  padding: 0.3rem 0.65rem;
  font-size: 0.8rem;
}

.selection-template-empty {
  margin: 0.7rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t45);
}

.selection-template-save {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.7rem;
}

.selection-template-save input {
  flex: 1 1 12rem;
  min-height: 38px;
  padding: 0.4rem 0.7rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-size: 0.86rem;
  font-family: inherit;
}

.selection-template-note {
  margin: 0.6rem 0 0;
  font-size: 0.79rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

.selection-template-note.is-ok {
  color: var(--ink-lime-1);
}

.selection-template-note.is-bad {
  color: var(--ink-orange-1);
}

/* Intake tuning, moved here from the website builder. */
.intake-content {
  margin-top: 0.9rem;
}

.intake-content .intake-heading {
  margin-top: 1.3rem;
}

.intake-lede {
  margin: 0.3rem 0 0.8rem;
  font-size: 0.84rem;
  line-height: 1.55;
  color: var(--mute-t50);
}

.intake-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: 0.7rem;
}

.intake-exclusions {
  display: grid;
  gap: 0.4rem;
  margin-bottom: 0.5rem;
}

.intake-exclusion {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.intake-exclusion input {
  flex: 1;
  min-height: 38px;
  padding: 0.4rem 0.7rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-size: 0.88rem;
  font-family: inherit;
}

.intake-foot {
  display: flex;
  justify-content: flex-end;
  margin-top: 1rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--rule-t09);
  font-size: 0.78rem;
  color: var(--mute-t45);
}

.intake-save {
  min-height: 1.2em;
}

.intake-save-saved {
  color: var(--ink-lime-1);
}

.intake-save-error {
  color: var(--ink-orange-1);
}

/* The option's photo, on the OWNER's board too. Small — this is a list, and the
   picture is here so both sides recognise the same tile, not to be admired. */
.selection-option-photo {
  width: 2rem;
  height: 2rem;
  margin-right: 0.45rem;
  border-radius: 6px;
  object-fit: cover;
  vertical-align: middle;
}

.selection-move {
  display: inline-flex;
  gap: 0.15rem;
}

.selection-move form {
  display: inline;
}

.selection-move .icon-btn {
  padding: 0.1rem 0.35rem;
  font-size: 0.85rem;
  line-height: 1.2;
}

/* The homeowner's third option: ask, rather than confirm or say nothing. */
.client-selection-ask {
  margin-top: 0.7rem;
}

.client-selection-ask>summary {
  cursor: pointer;
  font-size: 0.85rem;
  color: var(--mute-t55);
}

.client-selection-ask>summary:hover {
  color: var(--text);
}

.client-selection-ask form {
  display: grid;
  gap: 0.4rem;
  margin-top: 0.5rem;
}

.client-selection-ask label {
  font-size: 0.82rem;
  color: var(--mute-t55);
}

.client-selection-ask textarea {
  padding: 0.55rem 0.7rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-family: inherit;
  font-size: 0.9rem;
  line-height: 1.5;
  resize: vertical;
}

.client-selection-ask .btn {
  justify-self: start;
}

.client-selection-asked {
  margin: 0.7rem 0 0;
  font-size: 0.85rem;
  color: var(--ink-lime-1);
}

/* The order sheet. Printing the job page gives the supplier the decisions and
   their product codes, and nothing else on the page. */
/* PRINT ISOLATION FOR THE SELECTION BOARD, and only for it.
   `body * { visibility: hidden }` was unscoped, so it applied to every page in
   the product. Anything else printed — a quote, a statement, a job record —
   came out as the right number of blank pages, because the rule that unhid
   `.selection-board` had nothing to unhide. :has() scopes it to a page that
   actually contains a board; a browser without :has() drops the whole rule and
   prints the page intact, which is the correct way to fail. */
@media print {
  body:has(.selection-board) * {
    visibility: hidden;
  }

  .selection-board,
  .selection-board * {
    visibility: visible;
  }

  .selection-board {
    position: absolute;
    inset: 0;
    color: #000;
  }

  .selection-send,
  .selection-templates,
  .selection-new-form,
  .selection-option-form,
  .selection-option-edit,
  .selection-move,
  .selection-chosen .btn,
  .selection-option-cost .icon-btn {
    display: none !important;
  }

  .selection-card {
    break-inside: avoid;
    border: 1px solid #ccc;
    margin-bottom: 0.5rem;
  }
}

/* Decisions made and then changed. In front of the contractor rather than
   buried: if the first colour is already on the wall, this is the record. */
.selection-history {
  list-style: none;
  padding: 0.5rem 0.7rem;
  margin: 0.6rem 0 0;
  border-left: 2px solid var(--rule-t20);
  border-radius: 0 8px 8px 0;
  background: rgba(var(--tint), 0.04);
  display: grid;
  gap: 0.25rem;
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--mute-t50);
}

/* Inline option edit. A disclosure so the option list still reads as a list. */
.selection-option-edit>summary {
  list-style: none;
  cursor: pointer;
  padding: 0 0.2rem;
  color: var(--mute-t45);
  font-size: 0.82rem;
}

.selection-option-edit>summary::-webkit-details-marker {
  display: none;
}

.selection-option-edit>summary:hover {
  color: var(--text);
}

.selection-option-edit form {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr 0.7fr auto;
  gap: 0.4rem;
  margin-top: 0.45rem;
}

@media (max-width: 640px) {
  .selection-option-edit form {
    grid-template-columns: 1fr;
  }
}

.selection-option-form {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr 0.7fr 1fr auto;
  gap: 0.4rem;
  margin-top: 0.7rem;
}

.selection-option-form input[type='file'] {
  font-size: 0.78rem;
}

.selection-new-form {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.selection-new-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 0.6rem;
}

@media (max-width: 640px) {
  .selection-option-form {
    grid-template-columns: 1fr;
  }
}

/* Selection board — homeowner side. Options as cards, because choosing a tap
   from a table of rows is not how anybody chooses a tap. */
.client-selection-list {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  margin-top: 0.6rem;
}

.client-selection {
  padding: 1rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.client-selection.is-overdue {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.client-selection-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.client-selection-allowance {
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.client-selection-desc {
  margin: 0.45rem 0 0;
  line-height: 1.55;
}

.client-selection-deadline {
  margin: 0.45rem 0 0;
  font-size: 0.85rem;
  color: var(--mute-t55);
}

/* Why they're being asked again. Without it, a homeowner who already answered
   assumes their answer was lost. */
.client-selection-reopened {
  margin: 0.6rem 0 0;
  padding: 0.6rem 0.8rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.06);
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--mute-t60);
}

.client-selection-chosen {
  margin-top: 0.7rem;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  background: rgba(var(--tint), 0.06);
}

.client-selection-ref {
  margin-left: 0.45rem;
  padding: 0.05rem 0.35rem;
  border-radius: 5px;
  background: rgba(var(--tint), 0.1);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.78rem;
}

.client-selection-meta {
  display: block;
  margin-top: 0.25rem;
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.client-selection-form {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-top: 0.8rem;
}

.client-selection-form label {
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.client-option-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: 0.6rem;
}

.client-option {
  display: flex;
  gap: 0.5rem;
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t18);
  background: rgba(var(--tint), 0.03);
  cursor: pointer;
}

.client-option.is-picked {
