  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t55);
}

.weather-risk-draft {
  margin-top: 0.7rem;
  padding: 0.6rem 0.75rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.06);
}

.weather-risk-draft p {
  margin: 0 0 0.5rem;
  font-size: 0.84rem;
  line-height: 1.5;
}

.weather-risk-foot {
  margin: 0.4rem 0 0;
  font-size: 0.79rem;
  color: var(--mute-t45);
}

/* Client portal — the homeowner's own way back in.
   Rendered on the CONTRACTOR's white site shell (SitePortalPage), not in the
   workspace, so these are literal light-page colours rather than the dashboard
   tint tokens — and the button takes the site's own accent. */
.portal-request-form {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-top: 1.4rem;
}

.portal-request-form label {
  font-size: 0.9rem;
  font-weight: 600;
  color: #10151f;
}

.portal-request-form input {
  width: 100%;
  padding: 0.85rem 0.95rem;
  border: 1px solid #d4dae4;
  border-radius: 12px;
  background: #fff;
  color: #10151f;
  font-size: 1rem;
  font-family: inherit;
}

.portal-request-form input::placeholder {
  color: #98a1b3;
}

.portal-request-form input:focus-visible {
  outline: none;
  border-color: var(--theme-accent, #2563eb);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theme-accent, #2563eb) 22%, transparent);
}

.portal-request-submit {
  margin-top: 0.35rem;
  padding: 0.9rem 1.1rem;
  border: 0;
  border-radius: 12px;
  background: var(--theme-accent, #2563eb);
  color: #fff;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
}

.portal-request-submit:hover:not(:disabled) {
  filter: brightness(1.06);
}

.portal-request-submit:disabled {
  opacity: 0.65;
  cursor: default;
}

.portal-request-done {
  margin-top: 1.4rem;
}

.portal-request-done p {
  margin: 0 0 0.5rem;
  font-size: 1rem;
  line-height: 1.6;
  color: #333c4c;
}

.portal-request-fine {
  margin: 0.55rem 0 0;
  font-size: 0.85rem;
  line-height: 1.55;
  color: #6b7686;
}

.portal-job-list {
  list-style: none;
  padding: 0;
  margin: 0.6rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.portal-job {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.8rem;
  flex-wrap: wrap;
  padding: 0.7rem 0.9rem;
  border-radius: 12px;
  background: rgba(var(--tint), 0.05);
}

.portal-job.status-complete {
  opacity: 0.9;
}

.portal-job-main {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1 1 16rem;
}

.portal-job-meta {
  font-size: 0.79rem;
  color: var(--mute-t50);
}

.portal-job-amount {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.portal-note,
.portal-foot {
  margin: 0.8rem 0 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

.portal-foot {
  text-align: center;
  padding-bottom: 2rem;
}

/* Warranty — owner side. Green only for cover that is genuinely live: this app
   uses green for money agreed, and "still in warranty" is the same kind of fact. */
.warranty-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 0.6rem;
}

.warranty-list {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.warranty-card {
  padding: 0.85rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.warranty-card.status-expiring {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.warranty-card.status-expired {
  opacity: 0.75;
}

.warranty-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.warranty-status {
  margin-left: 0.5rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t45);
}

.warranty-remaining {
  font-size: 0.83rem;
  color: var(--mute-t55);
}

.warranty-dates {
  margin: 0.4rem 0 0;
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
  color: var(--mute-t50);
}

.warranty-line {
  margin: 0.4rem 0 0;
  font-size: 0.85rem;
  line-height: 1.5;
}

.warranty-service {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-top: 0.7rem;
  padding: 0.5rem 0.7rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.06);
  font-size: 0.82rem;
}

.warranty-service.is-overdue {
  background: rgba(255, 179, 122, 0.16);
}

.warranty-service-form {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.warranty-claims {
  list-style: none;
  padding: 0;
  margin: 0.7rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.warranty-claim {
  padding: 0.55rem 0.7rem;
  border-radius: 10px;
  border-left: 3px solid var(--ink-amber-3);
  background: rgba(var(--tint), 0.05);
}

.warranty-claim p {
  margin: 0.25rem 0 0;
  font-size: 0.84rem;
  line-height: 1.45;
}

.warranty-claim-in,
.warranty-claim-out {
  margin-left: 0.5rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.warranty-claim-in {
  color: var(--ink-lime-1);
}

.warranty-claim-out {
  color: var(--mute-t45);
}

.warranty-form {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.warranty-form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  gap: 0.6rem;
}

/* Warranty — homeowner side. */
.client-warranty-list {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  margin-top: 0.6rem;
}

.client-warranty {
  padding: 1rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.client-warranty.status-expiring {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.client-warranty-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.client-warranty-status {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.client-warranty-dates {
  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t50);
  font-variant-numeric: tabular-nums;
}

.client-warranty-covers,
.client-warranty-excludes,
.client-warranty-maintenance {
  margin: 0.5rem 0 0;
  font-size: 0.88rem;
  line-height: 1.5;
}

.client-warranty-service,
.client-warranty-docs {
  margin: 0.5rem 0 0;
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.client-warranty-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.8rem;
}

.client-warranty-actions small {
  font-size: 0.76rem;
  color: var(--mute-t45);
  flex: 1 1 12rem;
}

.client-warranty-form {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-top: 0.8rem;
}

.client-warranty-form label {
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.client-warranty-done {
  margin: 0.7rem 0 0;
  font-size: 0.86rem;
  color: var(--ink-lime-1);
}

.client-warranty-error {
  margin: 0.6rem 0 0;
  font-size: 0.83rem;
  color: var(--ink-orange-1);
}

/* Change orders — owner side. */
.change-order-list {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  margin-top: 0.6rem;
}

.change-order {
  padding: 0.9rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.change-order.status-draft {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.09);
}

.change-order.status-approved {
  border-color: var(--ink-lime-1);
}

.change-order-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.change-order-status {
  margin-left: 0.5rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t45);
}

.change-order-amount {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* The crew member's own words. Quoted and set apart because this is the primary
   record of the condition found on site, not a field the office filled in. */
.change-order-note {
  margin: 0.6rem 0 0;
  padding: 0.55rem 0.8rem;
  border-left: 3px solid var(--rule-t25);
  font-style: italic;
  line-height: 1.5;
  color: rgba(var(--tint), 0.85);
}

.change-order-note cite {
  display: block;
  margin-top: 0.25rem;
  font-style: normal;
  font-size: 0.78rem;
  color: var(--mute-t45);
}

.change-order-photos,
.change-order-scope,
.change-order-signature {
  margin: 0.5rem 0 0;
  font-size: 0.83rem;
  color: var(--mute-t55);
}

.change-order-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.7rem;
}

.change-order-actions small {
  font-size: 0.76rem;
  color: var(--mute-t45);
  flex: 1 1 12rem;
}

.change-order-fields {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-top: 0.7rem;
}

.change-order-fields label {
  font-size: 0.76rem;
  color: var(--mute-t50);
  margin-top: 0.4rem;
}

.change-order-draft {
  margin-top: 0.7rem;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  border: 1px dashed var(--edge-t28);
}

.change-order-draft ul {
  list-style: none;
  padding: 0;
  margin: 0.5rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.change-order-draft li {
  display: flex;
  justify-content: space-between;
  gap: 0.6rem;
  font-size: 0.85rem;
}

.change-order-assumptions {
  margin: 0.6rem 0 0;
  font-size: 0.79rem;
  line-height: 1.45;
  color: var(--mute-t55);
}

.change-order-blockers {
  margin: 0.6rem 0 0;
  padding-left: 1.1rem;
  font-size: 0.8rem;
  color: var(--ink-amber-1, var(--mute-t55));
}

.change-order-message {
  margin: 0.6rem 0 0;
  font-size: 0.82rem;
  color: var(--ink-lime-1);
}

.change-order-message.is-error {
  color: var(--ink-orange-1);
}

/* Change orders — homeowner side. Approve and Decline are the SAME weight:
   a page that makes yes a primary button and no a grey link is a page designed
   to extract an answer, and the value of a written record is that it was free. */
.client-co-list {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  margin-top: 0.6rem;
}

.client-co {
  padding: 1rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.client-co.is-open {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.client-co-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.client-co-status {
  margin-left: 0.5rem;
  font-size: 0.74rem;
  color: var(--mute-t50);
}

.client-co-amount {
  font-weight: 700;
  font-size: 1.05rem;
  font-variant-numeric: tabular-nums;
}

.client-co-scope {
  margin: 0.55rem 0 0;
  line-height: 1.55;
}

.client-co-items {
  list-style: none;
  padding: 0;
  margin: 0.6rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.client-co-items li {
  display: flex;
  justify-content: space-between;
  gap: 0.6rem;
  font-size: 0.86rem;
  color: var(--mute-t55);
}

.client-co-photos,
.client-co-foot {
  margin: 0.6rem 0 0;
  font-size: 0.8rem;
  line-height: 1.45;
  color: var(--mute-t50);
}

.client-co-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.8rem;
}

.client-co-actions .btn {
  flex: 1 1 10rem;
}

.client-co-form {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-top: 0.8rem;
}

.client-co-form label {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.client-co-error {
  margin: 0.6rem 0 0;
  font-size: 0.83rem;
  color: var(--ink-orange-1);
}

/* Quote Guard. Nothing here blocks sending, so nothing here is styled like an
   error — a panel that looks like a failure gets closed instead of read. */
.quote-review {
  margin: 0.8rem 0;
  padding: 0.9rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.04);
}

.quote-review.is-stop {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.quote-review-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.quote-review-list {
  list-style: none;
  padding: 0;
  margin: 0.7rem 0 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.quote-review-item {
  padding: 0.6rem 0.75rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.05);
  border-left: 3px solid var(--rule-t20);
}

.quote-review-item.is-high {
  border-left-color: var(--ink-orange-1);
}

.quote-review-item.is-medium {
  border-left-color: var(--ink-amber-3);
}

.quote-review-item p {
  margin: 0.2rem 0 0;
  font-size: 0.83rem;
  line-height: 1.45;
  color: var(--mute-t55);
}

.quote-review-item-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.quote-review-source {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t45);
  white-space: nowrap;
}

.quote-review-foot {
  margin: 0.7rem 0 0;
  font-size: 0.78rem;
  color: var(--mute-t45);
}

/* Job costing. Amber rather than red throughout: these are things to look at,
   not errors — a duplicate flag that shouts turns into a flag nobody reads. */
.cost-item-duplicate {
  display: block;
  margin-top: 0.25rem;
  font-size: 0.76rem;
  line-height: 1.4;
  color: var(--ink-amber-1, var(--mute-t55));
}

.margin-alert {
  margin: 0.7rem 0 0;
  padding: 0.6rem 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.12);
  font-size: 0.82rem;
  line-height: 1.45;
}

.margin-alert.is-loss {
  border-color: var(--cedge-red-3);
  background: rgba(255, 101, 101, 0.12);
}

.margin-row.muted {
  color: var(--mute-t55);
  font-size: 0.85em;
}

.receipt-scan input[type='file'] {
  font-size: 0.85rem;
}

.field-hint.is-error {
  color: var(--ink-amber-1, var(--bad));
}

.review-policy-note {
  margin: 0.6rem 0 0;
  max-width: 44rem;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

/* The two review routes. Laid out as equal columns on purpose: the public route
   and the private one are offered to every customer at the same size, in the
   same order, whatever they rated. Steering an unhappy customer away from the
   public option is review gating even when the link is technically on the page. */
.review-routes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 0.7rem;
  margin-top: 1.4rem;
  max-width: 40rem;
}

.review-route {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  padding: 1rem 1.15rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  text-decoration: none;
  color: inherit;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
}

.review-route:hover {
  border-color: var(--edge-t30);
  background: rgba(var(--tint), 0.09);
  transform: translateY(-1px);
}

.review-route.is-public {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.12);
}

.review-route.is-public:hover {
  border-color: var(--ink-amber-4);
  background: rgba(255, 179, 122, 0.2);
}

.review-route-title {
  font-weight: 700;
  font-size: 1rem;
}

.review-route-note {
  font-size: 0.82rem;
  line-height: 1.4;
  color: var(--mute-t55);
}

@media (prefers-reduced-motion: reduce) {
  .review-route:hover {
    transform: none;
  }
}

.review-feedback-form {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  margin-top: 1.2rem;
  max-width: 440px;
}

.review-feedback-form textarea {
  width: 100%;
  padding: 0.9rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font: inherit;
  font-size: 1rem;
  resize: vertical;
}

/* ---------------------------------------------------------------------------
   REBOOK — win back past customers
   --------------------------------------------------------------------------- */
.rebook-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.rebook-bulk {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  margin: 1rem 0 0.4rem;
  padding: 0.8rem 1rem;
  border-radius: 12px;
  background: rgba(245, 158, 11, 0.08);
  border: 1px solid var(--cedge-orange-43);
  font-size: 0.9rem;
}

.rebook-list {
  display: flex;
  flex-direction: column;
}

.rebook-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--rule-t07);
}

.rebook-row:last-child {
  border-bottom: none;
}

.rebook-row-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.rebook-row-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.6rem;
}

.rebook-name {
  font-weight: 700;
  font-size: 0.98rem;
  color: var(--text);
  text-decoration: none;
}

.rebook-name:hover {
  text-decoration: underline;
}

.rebook-ago {
  font-size: 0.8rem;
  color: var(--ink-orange-1);
}

.rebook-row-meta {
  margin: 0;
  font-size: 0.83rem;
  color: var(--mute-t55);
}

.rebook-cant {
  font-size: 0.82rem;
  color: var(--mute-t45);
}

.rebook-bulk small {
  color: var(--mute-t55);
}

/* ── What they actually get, before anybody presses send ─────────────────────
   The page offered one button to every past customer and showed neither the
   message nor which way it leaves. They are two different messages with two
   different sets of rules. */
.rebook-preview-lead {
  margin: 0.35rem 0 0.9rem;
}

.rebook-preview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(20rem, 100%), 1fr));
  gap: 0.8rem;
}

.rebook-preview-card {
  display: grid;
  gap: 0.55rem;
  align-content: start;
  padding: 0.9rem 1rem;
  border: 1px solid var(--edge-t12);
  border-radius: 13px;
  background: rgba(var(--tint), 0.03);
}

.rebook-preview-card.is-blocked {
  border-color: var(--cedge-orange-43);
}

.rebook-preview-head {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.rebook-preview-head strong {
  font-size: 0.86rem;
  color: var(--mute-t55);
  font-weight: 650;
}

.rebook-preview-card>small {
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

.rebook-preview-block {
  color: var(--muted) !important;
}

/* The text, as a text. A monospace-ish block reads as "this is the literal
   string that goes out" in a way a paragraph of body copy does not. */
.rebook-sms-body {
  margin: 0;
  padding: 0.7rem 0.85rem;
  border-radius: 12px 12px 12px 3px;
  background: rgba(var(--tint), 0.06);
  font-size: 0.88rem;
  line-height: 1.55;
}

.rebook-email-body {
  display: grid;
  gap: 0.45rem;
  margin: 0;
}

.rebook-email-body>div {
  display: grid;
  gap: 0.1rem;
}

.rebook-email-body dt {
  font-size: 0.63rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--mute-t45);
}

.rebook-email-body dd {
  margin: 0;
  font-size: 0.86rem;
  line-height: 1.5;
}

/* The channel as its own thing, because it decides which message arrives. */
.rebook-channel-chip {
  flex: none;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.rebook-channel-chip.is-sms {
  border-color: var(--cedge-green-38);
  background: rgba(127, 224, 178, 0.12);
  color: var(--good);
}

.rebook-channel-chip.is-email {
  border-color: var(--cedge-amber-49);
  background: rgba(255, 209, 102, 0.12);
  color: var(--warn);
}

.rebook-channel-chip.is-none {
  border-color: var(--edge-t14);
  color: var(--mute-t45);
}

@media (max-width: 640px) {
  .rebook-row {
    flex-direction: column;
    align-items: stretch;
  }

  .rebook-row-actions .btn {
    width: 100%;
  }
}

/* ---------------------------------------------------------------------------
   PRICE BOOK — saved services
   --------------------------------------------------------------------------- */
/* A price book read as eleven identical full-width slabs: the price — the only
   thing anyone opens this page for — sat in a small chip beside the name, and the
   middle 40% of every row was empty. Cards put the money in display type, give
   each service its trade glyph, and let the list be scanned in two dimensions. */
.service-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(265px, 1fr));
  gap: 0.85rem;
  margin-top: 1.1rem;
}

.service-row {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 1rem 1.05rem 0.85rem;
  border-radius: 18px;
  border: 1px solid var(--edge-t10);
  background:
    linear-gradient(160deg, rgba(255, 122, 33, 0.07), transparent 46%),
    rgba(var(--tint), 0.03);
  overflow: hidden;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

/* A hairline of accent along the top edge, lit on hover — the same "neon edge"
   language as the Stripe banner, dialled right down so a grid of them is calm. */
.service-row::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255, 122, 33, 0.55), transparent);
  opacity: 0.35;
  transition: opacity 0.18s ease;
}

.service-row:hover {
  transform: translateY(-2px);
  border-color: var(--cedge-orange-29);
  box-shadow: 0 12px 30px -18px rgba(255, 122, 33, 0.7);
}

.service-row:hover::before {
  opacity: 1;
}

.service-row.is-archived {
  opacity: 0.55;
}

.service-row.is-archived::before {
  display: none;
}

/* Hero stats: how big the book is, what it averages, and how wide the spread is. */
.pricebook-stats {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  justify-content: center;
  min-width: 0;
}

.pricebook-range {
  border: 1px solid var(--edge-t10);
  border-radius: 22px;
  padding: 1rem 1.05rem;
  background: rgba(var(--tint), 0.03);
}

.pricebook-range-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.7rem;
}

.pricebook-range-head strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.pricebook-range-track {
  position: relative;
  height: 8px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.07);
}

.pricebook-range-fill {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(255, 122, 33, 0.35), var(--accent, #ff7a21));
}

/* Where the average sits between the cheapest and dearest job — a book bunched at
   one end reads very differently from one that spans a full range. */
.pricebook-range-marker {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  margin-left: -6px;
  border-radius: 50%;
  transform: translateY(-50%);
  background: #ffc08a;
  box-shadow: 0 0 10px rgba(255, 122, 33, 0.9), 0 0 0 3px rgba(var(--panel-rgb), 0.9);
}

.pricebook-range-ends {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: 0.5rem;
  font-size: 0.78rem;
  color: var(--mute-t55);
  font-variant-numeric: tabular-nums;
}

.service-row-top {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  min-width: 0;
}

.service-glyph {
  display: grid;
  place-items: center;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 14px;
  border: 1px solid var(--cedge-orange-44);
  background: linear-gradient(160deg, rgba(255, 122, 33, 0.22), rgba(255, 122, 33, 0.07));
  color: var(--ink-orange-1);
  flex-shrink: 0;
}

.service-glyph svg {
  width: 1.35rem;
  height: 1.35rem;
}

.service-row-main {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.service-name {
  font-size: 0.98rem;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.service-price {
  font-family: var(--font-display);
  font-size: 1.5rem;
  line-height: 1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  display: flex;
  align-items: baseline;
  gap: 0.22rem;
}

.service-price .service-price-unit {
  font-family: var(--font-body);
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--dim-orange-4-3);
  letter-spacing: 0.02em;
}

.service-desc {
  margin: 0;
  font-size: 0.83rem;
  line-height: 1.45;
  color: var(--mute-t58);
}

.service-row-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: auto;
  padding-top: 0.7rem;
  border-top: 1px solid var(--rule-t07);
}

.service-row-actions .btn {
  padding: 0.32rem 0.75rem;
  font-size: 0.8rem;
}

.service-row-actions .linklike {
  margin-left: auto;
}

/* Closed, the <details> is just its Edit button and sits inline with Archive.
   Open, it claims its own line so the form isn't squeezed beside two buttons. */
.service-edit {
  padding: 0;
}

.service-edit[open] {
  flex-basis: 100%;
  order: 9;
}

/* An edit form in a 265px column is unusable; give that card the whole row while
   it's open. Without :has() the form is merely narrow, never broken. */
.service-row:has(.service-edit[open]) {
  grid-column: 1 / -1;
}

.service-row:has(.service-edit[open]) .service-form-grid {
  grid-template-columns: 2fr 1fr 1fr;
}

.service-form {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  margin-top: 0.9rem;
}

/* A column flex container stretches its children, which turned Save into a
   full-width orange bar shouting across the card. */
.service-form>button[type='submit'] {
  align-self: flex-start;
}

.service-form-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 0.7rem;
}

/* Make it obvious the Edit button is a toggle that's currently on. */
.service-edit[open]>summary .btn {
  border-color: var(--cedge-orange-30);
  color: var(--ink-orange-3);
}

.quote-book-picker {
  min-height: 40px;
  border-radius: 9px;
  border: 1px solid var(--edge-t18);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  padding: 0 0.7rem;
  font: inherit;
  font-size: 0.9rem;
  cursor: pointer;
}

.quote-book-picker option {
  background: var(--bg-3);
  color: var(--text);
}

@media (max-width: 640px) {
  .service-form-grid {
    grid-template-columns: 1fr;
  }

  .service-row-actions {
    width: 100%;
    justify-content: space-between;
  }
}

.crew-field-linked {
  display: inline-flex;
  align-items: center;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-lime-1);
}

.crew-field-hint {
  font-size: 0.8rem;
  color: var(--mute-t50);
}

.auth-crew-link {
  margin-top: 0.5rem;
  text-align: center;
  font-size: 0.85rem;
}

.auth-crew-link a {
  color: #b45309;
  font-weight: 600;
}

/* ===========================================================================
   FIELD APP — crew's mobile view (standalone, no dashboard chrome)
   =========================================================================== */
.field-app {
  min-height: 100vh;
  background: var(--bg);
  color: var(--ink-neutral-1);
  font-family: var(--font-body, system-ui, sans-serif);
}

/* -- Crew login -- */
.field-login {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.field-login-card {
  width: 100%;
  max-width: 400px;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t10);
  border-radius: 18px;
  padding: 1.75rem 1.5rem;
}

.field-login-eyebrow {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-orange-5);
}

.field-login-card h1 {
  margin: 0.4rem 0 0.6rem;
  font-size: 1.7rem;
}

.field-login-lead {
  margin: 0 0 1.4rem;
  color: var(--mute-t60);
  line-height: 1.5;
}

.field-login-form {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.field-login-form label {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--mute-t55);
}

.field-login-form input {
  padding: 0.9rem 1rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font-size: 1.05rem;
}

.field-login-form .btn {
  margin-top: 0.3rem;
  padding: 0.95rem;
  font-size: 1.02rem;
}

.field-login-message {
  margin: 0.3rem 0 0;
  font-size: 0.9rem;
  color: var(--ink-orange-15);
  line-height: 1.45;
}

.field-login-foot {
  margin: 1.3rem 0 0;
  text-align: center;
  font-size: 0.85rem;
  color: var(--mute-t50);
}

.field-login-foot a {
  color: var(--ink-sky-1);
}

/* -- Header -- */
.field-header {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.9rem 1.1rem;
  background: rgba(6, 19, 31, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--rule-t08);
}

.field-header-id {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.field-brand {
  font-weight: 700;
  font-size: 1rem;
}

.field-header-brand-wrap {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.field-header-brand-wrap--sub {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.field-header-back-wrap {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  min-width: 0;
}

.field-header-logo {
  max-height: 34px;
  max-width: 80px;
  object-fit: contain;
  object-position: left center;
  flex-shrink: 0;
  border-radius: 4px;
}

.field-header-logo--compact {
  max-height: 26px;
  max-width: 60px;
}

.field-header-mark {
  width: 34px;
  height: 34px;
  border-radius: 7px;
  background: linear-gradient(135deg, #ea580c 0%, #c2410c 100%);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.88rem;
  letter-spacing: 0.04em;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(234, 88, 12, 0.3);
}

.field-header-mark--compact {
  width: 26px;
  height: 26px;
  border-radius: 5px;
  font-size: 0.74rem;
}

.field-header-lgq-badge {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.field-header-lgq-wordmark {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 0.82rem;
  letter-spacing: -0.01em;
  color: var(--text);
  white-space: nowrap;
}

.field-header-lgq-wordmark span {
  color: var(--accent);
}

.field-brand--compact {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 160px;
}

.field-crew {
  font-size: 0.8rem;
  color: var(--mute-t55);
}

.field-back {
  color: var(--ink-sky-1);
  font-weight: 600;
  text-decoration: none;
  font-size: 0.95rem;
}

.field-signout {
  background: none;
  border: 1px solid var(--edge-t16);
  color: rgba(var(--tint), 0.7);
  border-radius: 999px;
  padding: 0.4rem 0.85rem;
  font-size: 0.82rem;
  cursor: pointer;
}

/* Field Footer: Powered by Let's Get Quoted */
.field-footer {
  width: 100%;
  max-width: 640px;
  margin: 1.5rem auto 2.5rem;
  padding: 1.25rem 1.1rem 0;
  border-top: 1px solid var(--rule-t08);
  display: flex;
  align-items: center;
  justify-content: center;
}

.field-footer-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  color: var(--mute-t55);
  font-size: 0.76rem;
  text-decoration: none;
}

.field-footer-logo {
  opacity: 0.8;
  flex-shrink: 0;
}

.field-footer-text strong {
  color: var(--accent);
  font-weight: 700;
}

/* Field Choose Business Brand Monogram & Logo */
.field-choose-logo {
  max-height: 28px;
  max-width: 60px;
  object-fit: contain;
  flex-shrink: 0;
  border-radius: 4px;
}

.field-choose-monogram {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: linear-gradient(135deg, #ea580c 0%, #c2410c 100%);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.76rem;
  flex-shrink: 0;
}

/* -- My jobs -- */
.field-main {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.1rem 1.1rem 3rem;
}

/* -- Field PWA: notifications toggle -- */
.field-push {
  margin: 0 0 1.1rem;
}

.field-push-enable {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.6rem 1rem;
  border-radius: 999px;
  border: none;
  background: linear-gradient(135deg, #ff7a21, #ff9d4d);
  color: #1a0f04;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
}

.field-push-enable:disabled {
  opacity: 0.7;
  cursor: default;
}

.field-push-status {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.field-push-on {
  font-size: 0.85rem;
  color: var(--ink-green-6);
  font-weight: 600;
}

.field-push-link {
  background: none;
  border: none;
  color: var(--ink-neutral-8);
  text-decoration: underline;
  font-size: 0.82rem;
  cursor: pointer;
  padding: 0;
}

.field-push-note {
  font-size: 0.82rem;
  color: var(--ink-neutral-8);
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t08);
  border-radius: 12px;
  padding: 0.6rem 0.8rem;
}

.field-greeting {
  margin: 0.5rem 0 1.2rem;
  font-size: 1.5rem;
}

.field-empty {
  color: var(--mute-t60);
  line-height: 1.55;
  padding: 1.5rem 0;
}

.field-section {
  margin-bottom: 1.6rem;
}

.field-section-title {
  margin: 0 0 0.7rem;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--mute-t50);
}

.field-job-card {
  display: block;
  text-decoration: none;
  color: inherit;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t10);
  border-radius: 14px;
  padding: 1rem 1.1rem;
  margin-bottom: 0.7rem;
}

.field-job-card:active {
  background: rgba(var(--tint), 0.07);
}

.field-job-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.field-job-top strong {
  font-size: 1.08rem;
}

.field-job-when {
  margin: 0.3rem 0 0;
  font-size: 0.88rem;
  color: var(--ink-sky-1);
}

.field-job-addr {
  margin: 0.25rem 0 0;
  font-size: 0.86rem;
  color: var(--mute-t60);
}

.field-job-scope {
  margin: 0.45rem 0 0;
  font-size: 0.86rem;
  color: rgba(var(--tint), 0.7);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.field-status {
  flex-shrink: 0;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  white-space: nowrap;
}

/* -- Today's route (numbered stops) -- */
.field-route {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.field-route-stop {
  display: flex;
  align-items: stretch;
  gap: 0.7rem;
}

.field-route-num {
  flex-shrink: 0;
  width: 1.9rem;
  min-height: 1.9rem;
  border-radius: 999px;
  background: #f59e0b;
  color: var(--bg);
  font-weight: 800;
  font-size: 0.95rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 0.2rem;
}

.field-route-body {
  flex: 1;
  min-width: 0;
  display: block;
  text-decoration: none;
  color: inherit;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t10);
  border-radius: 14px;
  padding: 0.85rem 1rem;
}

.field-route-body:active {
  background: rgba(var(--tint), 0.07);
}

.field-route-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
}

.field-route-top strong {
  font-size: 1.05rem;
}

.field-route-time {
  font-size: 0.9rem;
  color: var(--ink-sky-1);
  font-weight: 600;
  white-space: nowrap;
}

.field-route-addr {
  margin: 0.3rem 0;
  font-size: 0.86rem;
  color: rgba(var(--tint), 0.7);
}

.field-route-addr.muted {
  color: var(--mute-t40);
}

.field-route-nav {
  flex-shrink: 0;
  width: 3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: rgba(56, 189, 248, 0.14);
  border: 1px solid var(--cedge-teal-8);
  text-decoration: none;
  font-size: 1.4rem;
}

.field-route-nav:active {
  background: rgba(56, 189, 248, 0.25);
}

.field-status-new_lead {
  background: rgba(56, 189, 248, 0.16);
  color: var(--ink-sky-1);
}

.field-status-in_progress {
  background: rgba(251, 191, 36, 0.16);
  color: var(--ink-amber-3);
}

.field-status-complete {
  background: rgba(163, 230, 53, 0.16);
  color: var(--ink-lime-1);
}

.field-status-archived {
  background: rgba(161, 161, 170, 0.16);
  color: var(--ink-neutral-7);
}

/* A stop that isn't a job — the dump, the supply house, fuel. Quieter than a  */
/* job card and visibly not tappable, because there is no job page behind it.  */
/* The number stays the same colour: it is stop 3 of 5 whatever kind it is,    */
/* and re-colouring it would break the one thing the column is for.            */
.field-route-stop.is-errand .field-route-body {
  background: rgba(var(--tint), 0.02);
  border-style: dashed;
  cursor: default;
}

.field-route-stop.is-errand .field-route-top strong {
  font-size: 0.98rem;
  font-weight: 700;
}

.field-status-errand {
  background: rgba(var(--tint), 0.09);
  color: rgba(var(--tint), 0.72);
}

.field-route-note {
  margin: 0.35rem 0 0;
  font-size: 0.84rem;
  color: rgba(var(--tint), 0.68);
  line-height: 1.45;
}

/* -- Job detail -- */
.field-detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
  margin-top: 0.4rem;
}

.field-detail-head h1 {
  margin: 0;
  font-size: 1.5rem;
}

.field-detail-ref {
  margin: 0.3rem 0 1.1rem;
  font-size: 0.9rem;
  color: var(--mute-t55);
}

.field-actions-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.field-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.7rem 1.1rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.06);
  border: 1px solid var(--edge-t14);
  color: var(--ink-neutral-1);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 600;
}

.field-chip:active {
  background: rgba(var(--tint), 0.12);
}

/* Time clock, field app. Big targets: this is tapped with a glove on, in
   daylight, standing on someone's roof. */
.field-clock {
  display: grid;
  gap: 0.75rem;
  margin-bottom: 1rem;
  padding: 0.9rem 1rem;
  border: 1px solid var(--edge-g30);
  border-radius: 14px;
  background: rgba(var(--tint), 0.04);
}

.field-clock.is-running {
  border-color: var(--cedge-green-24);
  background: rgba(72, 199, 142, 0.1);
}

.field-clock-state {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.field-clock-state strong {
  display: block;
  font-size: 1rem;
}

.field-clock-state span {
  display: block;
  margin-top: 0.1rem;
  font-size: 0.85rem;
  color: rgba(var(--tint), 0.72);
  line-height: 1.45;
}

/* A pulse, so a running shift reads as running from across a room. */
.field-clock-dot {
  flex: none;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  background: var(--good);
  box-shadow: 0 0 0 0 rgba(72, 199, 142, 0.7);
  animation: fieldClockPulse 2s ease-out infinite;
}

@keyframes fieldClockPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(72, 199, 142, 0.6);
  }

  70% {
    box-shadow: 0 0 0 0.6rem rgba(72, 199, 142, 0);
  }

  100% {
    box-shadow: 0 0 0 0 rgba(72, 199, 142, 0);
  }
}

.field-clock-form {
  display: grid;
  gap: 0.5rem;
}

.field-clock .btn {
  width: 100%;
  padding: 0.95rem 1rem;
  font-size: 1rem;
}

@media (prefers-reduced-motion: reduce) {
  .field-clock-dot {
    animation: none;
  }
}

.field-block {
  margin-top: 1.5rem;
}

.field-block-title {
  margin: 0 0 0.5rem;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--mute-t50);
}

.field-block p {
  margin: 0;
  line-height: 1.55;
}

.field-scope-body {
  white-space: pre-wrap;
  color: rgba(var(--tint), 0.85);
}

/* What the customer asked us to know. Tinted so it's findable at a glance on a
   phone in daylight — this is the block you check before you get out of the van. */
.field-block-note {
  padding: 0.8rem 0.9rem;
  border-radius: 12px;
  border: 1px solid var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.1);
}

.field-complete-note {
  color: var(--ink-lime-1);
  font-weight: 600;
}

.field-update-form {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.field-update-form textarea {
  width: 100%;
  padding: 0.85rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font-size: 1rem;
  font-family: inherit;
  resize: vertical;
}

.field-share {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  font-size: 0.9rem;
  color: rgba(var(--tint), 0.7);
}

.field-share input {
  width: 1.1rem;
  height: 1.1rem;
}

.field-flash {
  margin-bottom: 1rem;
  padding: 0.7rem 1rem;
  border-radius: 11px;
  font-size: 0.92rem;
  font-weight: 600;
  background: rgba(163, 230, 53, 0.12);
  border: 1px solid var(--cedge-green-7);
  color: var(--ink-lime-1);
}

.field-flash.is-error {
  background: rgba(255, 122, 33, 0.12);
  border-color: var(--cedge-orange-41);
  color: var(--ink-orange-1);
}

.field-log-summary {
  margin: 0 0 0.9rem;
  font-size: 0.88rem;
  color: rgba(var(--tint), 0.7);
}

.field-log-form {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-bottom: 1rem;
}

.field-log-row {
  display: flex;
  gap: 0.6rem;
}

.field-log-row label {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.field-log-row label.field-log-grow {
  flex: 2;
}

.field-log-row label span {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t50);
}

.field-log-form input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font-size: 1rem;
  font-family: inherit;
}

.field-log-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.2rem;
}

.field-log-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  padding: 0.55rem 0.8rem;
  border-radius: 9px;
  background: rgba(var(--tint), 0.03);
  border: 1px solid var(--edge-t08);
  font-size: 0.88rem;
}

.field-log-item span:last-child {
  color: var(--ink-lime-1);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* What the hours are worth. Not a field — the rate is the office's number —   */
/* but not a secret either: it's on My pay, and hours with no visible value    */
/* are hours nobody checks.                                                    */
.field-log-rate {
  margin: 0;
  font-size: 0.82rem;
  color: rgba(var(--tint), 0.65);
  line-height: 1.45;
}

/* -- Field: held on the phone ------------------------------------- */
/* Everything queued offline says so in the same voice, in the same    */
/* colour, whether it came from the clock, a note or a material. Blue  */
/* rather than green: this has NOT been saved yet, and dressing it as  */
/* success is how somebody drives away believing it went.              */
.field-queue-note {
  margin: 0.6rem 0 0;
  padding: 0.6rem 0.85rem;
  border-radius: 11px;
  background: rgba(56, 189, 248, 0.1);
  border: 1px solid var(--cedge-teal-8);
  color: var(--ink-sky-1);
  font-size: 0.86rem;
  font-weight: 600;
  line-height: 1.45;
}

/* -- Field: the offline fallback ---------------------------------- */
.field-offline-lead {
  margin: 0 0 1.2rem;
  font-size: 1rem;
  line-height: 1.55;
  color: rgba(var(--tint), 0.78);
}

.field-offline-list {
  margin: 0;
  padding-left: 1.1rem;
  display: grid;
  gap: 0.5rem;
  font-size: 0.92rem;
  line-height: 1.5;
  color: rgba(var(--tint), 0.75);
}

.field-offline-hint {
  margin: 1.1rem 0;
  font-size: 0.9rem;
  color: var(--mute-t55);
}

/* -- Field: choosing which business ------------------------------- */
/* Only ever seen by somebody on two rosters. Full-width targets       */
/* because it is the first thing they touch after a magic link, often  */
/* one-handed, and picking the wrong firm shows them a stranger's day. */
.field-choose-lead {
  margin: 0 0 1.3rem;
  font-size: 0.98rem;
  line-height: 1.55;
  color: rgba(var(--tint), 0.75);
}

.field-choose-list {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.field-choose-option {
  width: 100%;
  min-height: 3.4rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.9rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  color: inherit;
  font-family: inherit;
  font-size: 1.05rem;
  text-align: left;
  cursor: pointer;
}

.field-choose-option:active {
  background: rgba(var(--tint), 0.08);
}

.field-choose-option[aria-current] {
  border-color: var(--cedge-teal-8);
  background: rgba(56, 189, 248, 0.1);
}

.field-choose-name {
  font-weight: 700;
}

.field-choose-out {
  margin-top: 2rem;
}

.field-brand-switch {
  text-decoration: none;
  color: inherit;
}

/* -- Field: photo uploads ----------------------------------------- */
/* Each photo is its own row with its own progress and its own Retry,  */
/* because "3 photos failed" is not something anybody can act on and   */
/* "the second one failed, tap here" is.                               */
.field-photos {
  display: grid;
  gap: 0.5rem;
}

.field-photos-pick {
  display: grid;
  gap: 0.3rem;
}

.field-photos-pick>span {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t50);
}

.field-photos-hint {
  font-size: 0.8rem;
  color: var(--mute-t50);
  line-height: 1.45;
}

.field-photos-list {
  list-style: none;
  margin: 0.2rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.field-photo-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.7rem;
  border-radius: 11px;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t10);
}

.field-photo-item.is-failed {
  border-color: var(--cedge-orange-41);
  background: rgba(255, 122, 33, 0.09);
}

.field-photo-item.is-done {
  border-color: var(--cedge-green-7);
}

.field-photo-main {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 0.2rem;
}

.field-photo-main strong {
  font-size: 0.86rem;
  font-weight: 650;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.field-photo-main span {
  font-size: 0.78rem;
  color: rgba(var(--tint), 0.7);
  line-height: 1.4;
}

.field-photo-item.is-failed .field-photo-main span {
  color: var(--ink-orange-1);
}

.field-photo-bar {
  height: 4px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.12);
  overflow: hidden;
}

.field-photo-fill {
  height: 100%;
  background: var(--ink-sky-1);
  transition: width 0.2s ease;
}

.field-photo-retry,
.field-photo-drop {
  flex-shrink: 0;
  min-width: 2.75rem;
  min-height: 2.75rem;
  padding: 0 0.7rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.06);
  color: inherit;
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
}

.field-photo-retry {
  border-color: var(--cedge-orange-41);
  color: var(--ink-orange-1);
}

.field-feed {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.field-feed-item {
  background: rgba(var(--tint), 0.03);
  border: 1px solid var(--edge-t08);
  border-radius: 11px;
  padding: 0.75rem 0.9rem;
}

.field-feed-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
}

.field-feed-top strong {
  font-size: 0.92rem;
}

.field-feed-top span {
  font-size: 0.76rem;
  color: var(--mute-t45);
  white-space: nowrap;
}

.field-feed-item p {
  margin: 0.3rem 0 0;
  font-size: 0.9rem;
  color: rgba(var(--tint), 0.75);
  line-height: 1.5;
}

.field-main .btn {
  width: 100%;
}

.field-actions-row form {
  flex: 1;
  min-width: 140px;
}

/* -- Field: arrival ("on my way") --------------------------------- */
/* Tapped one-handed, in a van, in sunlight. Targets are large, the    */
/* customer's name outranks every control, and anything that says a    */
/* message did NOT send is the loudest thing on screen.                */

.arrival-sheet {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 0.3rem;
  padding: 0.95rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
}

/* Wrong-job protection: who is about to be texted, before any control. */
.arrival-confirm {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.8rem 0.9rem;
  border-radius: 12px;
  background: rgba(56, 189, 248, 0.09);
  border: 1px solid var(--cedge-teal-9);
}

.arrival-confirm-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--mute-t55);
}

.arrival-confirm strong {
  font-size: 1.15rem;
  line-height: 1.3;
}

.arrival-confirm span {
  font-size: 0.88rem;
  color: rgba(var(--tint), 0.72);
  line-height: 1.45;
}

.arrival-confirm .arrival-warn {
  color: var(--ink-amber-3);
}

.arrival-warn-box {
  margin: 0;
  padding: 0.7rem 0.85rem;
  border-radius: 11px;
  font-size: 0.88rem;
  line-height: 1.5;
  background: rgba(251, 191, 36, 0.1);
  border: 1px solid var(--cedge-amber-37);
  color: var(--ink-amber-3);
}

.arrival-field-label {
  margin: 0.2rem 0 -0.35rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--mute-t50);
}

.arrival-suggested {
  text-transform: none;
  letter-spacing: 0;
  color: var(--ink-sky-1);
  font-weight: 600;
}

.arrival-eta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(84px, 1fr));
  gap: 0.5rem;
}

.arrival-eta {
  padding: 0.85rem 0.4rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font-size: 0.95rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
}

.arrival-eta.is-on {
  background: rgba(56, 189, 248, 0.2);
  border-color: var(--cedge-teal-3);
  color: var(--ink-sky-1);
}

.arrival-custom {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.arrival-custom span {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-t50);
}

.arrival-custom input,
.arrival-message,
.arrival-outcome-form input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-1);
  font-size: 1rem;
  font-family: inherit;
}

.arrival-message {
  line-height: 1.5;
  resize: vertical;
}

.arrival-window {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.5;
}

.arrival-window strong {
  color: var(--ink-sky-1);
}

.arrival-window span {
  color: var(--mute-t55);
  font-size: 0.86rem;
}

.arrival-share {
  margin-top: 0.1rem;
}

.arrival-hint {
  margin: -0.3rem 0 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

.arrival-link-btn {
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: inherit;
  color: var(--ink-sky-1);
  text-decoration: underline;
  cursor: pointer;
}

.arrival-error {
  margin: 0;
  padding: 0.7rem 0.85rem;
  border-radius: 11px;
  font-size: 0.9rem;
  font-weight: 600;
  line-height: 1.5;
  background: rgba(255, 122, 33, 0.12);
  border: 1px solid var(--cedge-orange-41);
  color: var(--ink-orange-1);
}

.arrival-actions {
  margin-top: 0.2rem;
}

/* The trip already in flight. */
.arrival-live {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-bottom: 0.9rem;
  padding: 0.85rem 0.95rem;
  border-radius: 13px;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t12);
}

.arrival-live-top {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.arrival-live-top strong {
  font-size: 1.05rem;
  font-variant-numeric: tabular-nums;
}

.arrival-pill {
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(56, 189, 248, 0.16);
  color: var(--ink-sky-1);
}

.arrival-pill.is-late {
  background: rgba(251, 191, 36, 0.18);
  color: var(--ink-amber-3);
}

.arrival-pill.is-done {
  background: rgba(163, 230, 53, 0.16);
  color: var(--ink-lime-1);
}

.arrival-delivery {
  margin: 0;
  font-size: 0.86rem;
  line-height: 1.5;
  color: rgba(var(--tint), 0.72);
}

.arrival-delivery.is-bad {
  color: var(--ink-orange-1);
  font-weight: 600;
}

.arrival-note {
  margin: 0;
  padding: 0.6rem 0.75rem;
  border-radius: 10px;
  font-size: 0.9rem;
  line-height: 1.5;
  background: rgba(163, 230, 53, 0.1);
  border: 1px solid var(--cedge-green-25);
  color: var(--ink-lime-1);
}

/* The same panel on the owner's job screen. Only the heading differs — the
   sheet, the safeguards and the controls are the component's own. */
.arrival-card-title {
  margin: 0 0 0.9rem;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.workspace-section-card .arrival-sheet {
  background: transparent;
  border: 0;
  padding: 0;
  margin-top: 0;
}

.workspace-section-card .arrival-eta-grid {
  grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
}

/* "Leave by" on a route stop. Only rendered when it's imminent or missed, so
   it can afford to be loud. */
.field-route-leave {
  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--ink-sky-1);
}

.field-route-leave.is-overdue {
  color: var(--ink-orange-1);
}

/* The geofence prompt. Asks, never announces — see arrival-tracker. */
.arrival-geofence {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  margin: 0 0 1.2rem;
  padding: 1rem 1.05rem;
  border-radius: 14px;
  background: rgba(163, 230, 53, 0.09);
  border: 1px solid var(--cedge-green-7);
}

.arrival-geofence-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.arrival-geofence-copy strong {
  font-size: 1.05rem;
}

.arrival-geofence-copy span {
  font-size: 0.88rem;
  line-height: 1.5;
  color: rgba(var(--tint), 0.75);
}

.arrival-geofence-actions {
  display: flex;
  align-items: center;
  gap: 0.9rem;
}

.arrival-geofence-actions form {
  flex: 1;
}

.arrival-controls {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  margin-top: 0.9rem;
}

.arrival-secondary {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.arrival-outcome {
  flex: 1;
  min-width: 128px;
  padding: 0.65rem 0.7rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  color: rgba(var(--tint), 0.78);
  font-size: 0.86rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
}

.arrival-outcome-form {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

/* -- Field: Voice & Text Intake Tip ------------------------------ */
.field-textintake-tip {
  margin: 0 0 1.2rem;
  padding: 0.9rem 1.1rem;
  border: 1px solid var(--cedge-blue-24, rgba(59, 130, 246, 0.24));
  border-radius: 14px;
  background: rgba(59, 130, 246, 0.06);
  color: inherit;
}

.field-textintake-tip-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.35rem;
}

.field-textintake-tip-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #60a5fa;
}

.field-textintake-tip-sub {
  font-size: 0.74rem;
  color: rgba(var(--tint), 0.55);
}

.field-textintake-tip p {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: rgba(var(--tint), 0.85);
}

.field-textintake-tip a.field-textintake-phone {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  color: #93c5fd;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* -- Field: my pay ------------------------------------------------ */
/* The crew member's own hours and money. Reuses the field shell, so  */
/* only what is genuinely new to this screen lives here.              */

.field-paylink {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  margin: 0 0 1.4rem;
  padding: 0.95rem 1.1rem;
  border: 1px solid var(--cedge-green-26);
  border-radius: 14px;
  background: rgba(190, 242, 100, 0.07);
  color: inherit;
  text-decoration: none;
}

.field-paylink:active {
  background: rgba(190, 242, 100, 0.12);
}

.field-paylink strong {
  display: block;
  font-size: 1.02rem;
  margin-bottom: 0.15rem;
}

.field-paylink span {
  font-size: 0.84rem;
  color: rgba(var(--tint), 0.66);
  line-height: 1.45;
}

.field-paylink>span:last-child {
  font-size: 1.5rem;
  color: var(--mute-t40);
}

.mypay-standing {
  padding: 1.1rem 1.2rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.04);
  margin-bottom: 1rem;
}

/* The tone comes from the pay day, so an overdue period reads as overdue from  */
/* the home screen rather than looking like every other week.                   */
.mypay-standing.tone-ok {
  border-color: var(--cedge-green-27);
  background: rgba(72, 199, 142, 0.08);
}

.mypay-standing.tone-warn {
  border-color: var(--cedge-amber-38);
  background: rgba(251, 191, 36, 0.08);
}

.mypay-standing.tone-alert {
  border-color: var(--cedge-red-11);
  background: rgba(248, 113, 113, 0.1);
}

.mypay-stage {
  display: block;
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--mute-t50);
}

.mypay-amount {
  display: block;
  margin: 0.35rem 0 0;
  font-size: 1.75rem;
  font-variant-numeric: tabular-nums;
}

.mypay-detail {
  margin: 0.4rem 0 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: rgba(var(--tint), 0.82);
}

.mypay-rate {
  margin: 0.6rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t55);
  line-height: 1.45;
}

.mypay-live {
  margin: 0 0 1rem;
  padding: 0.7rem 0.9rem;
  border-radius: 11px;
  border: 1px solid var(--cedge-green-27);
  background: rgba(72, 199, 142, 0.09);
  font-size: 0.87rem;
  line-height: 1.5;
}

.mypay-flag {
  display: block;
  margin: 0 0 1.4rem;
  padding: 0.9rem 1.05rem;
  border-radius: 14px;
  border: 1px solid var(--cedge-amber-39);
  background: rgba(251, 191, 36, 0.09);
}

.mypay-flag strong {
  display: block;
  font-size: 0.95rem;
}

.mypay-flag p {
  margin: 0.35rem 0 0;
  font-size: 0.88rem;
  line-height: 1.5;
  color: rgba(var(--tint), 0.84);
}

.mypay-flag-list {
  margin: 0.6rem 0 0;
  padding-left: 1.05rem;
  display: grid;
  gap: 0.35rem;
}

.mypay-flag-list li {
  font-size: 0.84rem;
  line-height: 1.45;
  color: rgba(var(--tint), 0.72);
}

.mypay-entries,
.mypay-history {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.mypay-entry,
.mypay-history li {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.9rem;
  padding: 0.75rem 0.9rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t08);
  background: rgba(var(--tint), 0.03);
}

.mypay-entry-main strong,
.mypay-history strong {
  display: block;
  font-size: 0.92rem;
}

.mypay-entry-when,
.mypay-history li span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.mypay-entry-note {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.78rem;
  color: var(--dim-amber-2-2);
}

.mypay-entry-figures {
  text-align: right;
  white-space: nowrap;
}

.mypay-entry-figures strong {
  display: block;
  font-size: 0.92rem;
  font-variant-numeric: tabular-nums;
}

.mypay-entry-figures span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.8rem;
  color: var(--ink-lime-1);
  font-variant-numeric: tabular-nums;
}

.mypay-history-when {
  text-align: right;
  white-space: nowrap;
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.mypay-aside {
  margin: 0 0 0.6rem;
  font-size: 0.84rem;
  line-height: 1.5;
  color: var(--mute-t60);
}

.mypay-foot {
  margin: 1.6rem 0 0.9rem;
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--mute-t50);
}

.mypay-back {
  display: inline-block;
  font-size: 0.9rem;
  color: var(--ink-sky-1);
  text-decoration: none;
}

/* ================================================================ */
/* /features rebuild — bento command center + lifecycle pipeline.    */
/* All classes are .fx- prefixed so they never touch the existing    */
/* homepage feature classes.                                         */
/* ================================================================ */

/* ---- Hero ---------------------------------------------------------- */
.fx-hero {
  max-width: 62rem;
  padding: 1rem 0 0.5rem;
}

.fx-hero-title {
  max-width: 20ch;
}

.fx-hero-lede {
  max-width: 62ch;
  margin-top: 1rem;
  font-size: clamp(1rem, 1.4vw, 1.18rem);
  color: var(--muted);
}

.fx-stat-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin: 1.7rem 0 0.2rem;
  padding: 0;
}

.fx-stat {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 122px;
  margin: 0;
  padding: 0.7rem 1.05rem;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(var(--tint), 0.03);
}

.fx-stat dt {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.fx-stat dd {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--mute-g362);
}

.fx-stat--hot {
  border-color: var(--cedge-orange-16);
  background: rgba(255, 122, 33, 0.08);
}

.fx-stat--hot dt {
  color: var(--accent);
}

.fx-stat--good {
  border-color: var(--cedge-green-28);
  background: rgba(74, 222, 128, 0.08);
}

.fx-stat--good dt {
  color: var(--good);
}

/* ---- Shared section head ------------------------------------------ */
.fx-bento-section,
.fx-pipeline-section {
  margin-top: 3.4rem;
}

.fx-section-head {
  max-width: 48rem;
}

.fx-section-head h2 {
  margin-top: 0.45rem;
}

.fx-section-sub {
  margin: 0.8rem 0 0;
  max-width: 58ch;
  font-size: 1.02rem;
  color: var(--muted);
}

/* ---- Concept B: bento command center ------------------------------ */
.fx-bento {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: minmax(148px, auto);
  grid-auto-flow: dense;
  gap: 0.9rem;
  margin-top: 1.6rem;
}

.fx-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1.25rem;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(var(--tint), 0.05), rgba(var(--tint), 0.015));
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.fx-tile::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, var(--accent), var(--accent-2));
  opacity: 0.85;
}

.fx-tile:hover {
  transform: translateY(-4px);
  border-color: var(--cedge-orange-9);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.36);
}

.fx-tile--big {
  grid-column: span 2;
  grid-row: span 2;
}

.fx-tile--wide {
  grid-column: span 2;
}

.fx-tile-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 13px;
  border: 1px solid var(--cedge-orange-6);
  background: rgba(255, 122, 33, 0.1);
  color: var(--accent);
}

.fx-tile-ic svg {
  width: 1.4rem;
  height: 1.4rem;
}

.fx-tile-tag {
  align-self: flex-start;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold-ink);
}

.fx-tile-name {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--text);
}

.fx-tile-desc {
  margin: 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.fx-tile--big .fx-tile-ic {
  width: 3rem;
  height: 3rem;
  margin-bottom: auto;
}

.fx-tile--big .fx-tile-ic svg {
  width: 1.6rem;
  height: 1.6rem;
}

.fx-tile--big .fx-tile-name {
  font-size: 1.4rem;
}

.fx-tile--big .fx-tile-desc {
  font-size: 0.98rem;
}

/* ---- Screenshot-backed tiles (button) + click-to-enlarge lightbox ---- */
.fx-tile--shot {
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
  width: 100%;
  background-size: cover;
  background-position: center top;
  min-height: 208px;
  justify-content: flex-end;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

/* Readability veil over the photo — content sits above it. */
.fx-tile--shot::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(180deg, rgba(6, 19, 31, 0.28) 0%, rgba(6, 19, 31, 0.52) 42%, rgba(6, 19, 31, 0.93) 100%);
}

.fx-tile--shot>* {
  position: relative;
  z-index: 1;
}

.fx-tile--shot .fx-tile-ic {
  margin-bottom: auto;
  background: rgba(6, 19, 31, 0.55);
  border: 1px solid var(--edge-t14);
}

.fx-tile--shot:hover,
.fx-tile--shot:focus-visible {
  transform: translateY(-4px);
  border-color: var(--cedge-orange-5);
  box-shadow: 0 24px 50px -22px rgba(0, 0, 0, 0.7);
  outline: none;
}

.fx-tile-expand {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 1;
  display: inline-flex;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: var(--text);
  background: rgba(6, 19, 31, 0.6);
  border: 1px solid var(--edge-t18);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.fx-tile-expand svg {
  width: 1rem;
  height: 1rem;
}

.fx-tile--shot:hover .fx-tile-expand,
.fx-tile--shot:focus-visible .fx-tile-expand {
  opacity: 1;
}

.fx-lightbox {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(1rem, 4vw, 3rem);
  background: rgba(3, 10, 18, 0.86);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
  animation: fxFade 0.2s ease;
}

.fx-lightbox-inner {
  width: min(1120px, 100%);
  max-height: 92vh;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.fx-lightbox-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.fx-lightbox-tag {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold-ink);
}

.fx-lightbox-title {
  margin: 0.15rem 0 0;
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--text);
}

.fx-lightbox-close {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 999px;
  color: var(--text);
  background: rgba(var(--tint), 0.06);
  border: 1px solid var(--line);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.fx-lightbox-close:hover {
  background: rgba(255, 122, 33, 0.16);
  border-color: var(--cedge-orange-5);
}

.fx-lightbox-close svg {
  width: 1.2rem;
  height: 1.2rem;
}

.fx-lightbox-img {
  width: 100%;
  max-height: 72vh;
  object-fit: contain;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: var(--bg-2);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
}

.fx-lightbox-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem 1.5rem;
  flex-wrap: wrap;
}

.fx-lightbox-foot p {
  margin: 0;
  color: var(--muted);
  max-width: 62ch;
  font-size: 0.92rem;
}

@keyframes fxFade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fx-lightbox {
    animation: none;
  }

  .fx-tile--shot {
    transition: none;
  }

  .fx-tile--shot:hover,
  .fx-tile--shot:focus-visible {
    transform: none;
  }
}

/* ---- Concept A: the lifecycle pipeline ---------------------------- */
.fx-pipeline {
  position: relative;
  margin-top: 1.6rem;
}

.fx-spine {
  position: absolute;
  top: 1.5rem;
  bottom: 0;
  left: 50%;
  width: 3px;
  transform: translateX(-50%);
  pointer-events: none;
}

.fx-spine-track,
.fx-spine-fill {
  position: absolute;
  inset: 0;
  border-radius: 999px;
}

.fx-spine-track {
  background: linear-gradient(180deg, rgba(var(--tint), 0.14), rgba(var(--tint), 0.05));
}

.fx-spine-fill {
  transform-origin: top center;
  background: linear-gradient(180deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 14px rgba(255, 122, 33, 0.55);
}

.fx-stations {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2.4rem;
}

.fx-station {
  position: relative;
  margin: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  column-gap: 2rem;
  align-items: start;
}

.fx-station--left .fx-panel {
  grid-column: 1;
}

.fx-station--right .fx-panel {
  grid-column: 3;
}

.fx-node {
  position: relative;
  z-index: 1;
  grid-column: 2;
  grid-row: 1;
  width: 3.2rem;
  height: 3.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--bg);
  border: 1px solid var(--line);
}

.fx-node-ring {
  position: absolute;
  inset: -3px;
  border-radius: 999px;
  border: 2px solid var(--cedge-orange-45);
  transition: border-color 0.4s ease, box-shadow 0.4s ease;
}

.fx-node-num {
  font-size: 1rem;
  font-weight: 800;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  transition: color 0.4s ease;
}

.fx-station.is-visible .fx-node-num {
  color: var(--accent);
}

.fx-station.is-visible .fx-node-ring {
  border-color: var(--cedge-orange-46);
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.12), 0 0 18px rgba(255, 122, 33, 0.5);
}

.fx-panel {
  padding: 1.35rem 1.45rem;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(var(--tint), 0.045), rgba(var(--tint), 0.012));
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.22);
}

.fx-panel-head {
  display: flex;
  gap: 0.8rem;
  align-items: center;
  margin-bottom: 0.7rem;
}

.fx-panel-ic {
  flex: none;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--cedge-orange-6);
  background: rgba(255, 122, 33, 0.1);
  color: var(--accent);
}

.fx-panel-ic svg {
  width: 1.35rem;
  height: 1.35rem;
}

.fx-panel-eyebrow {
  margin: 0;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-ink);
}

.fx-panel-titles h3 {
  margin: 0.1rem 0 0;
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--text);
}

.fx-panel-intro {
  margin: 0 0 1rem;
  font-size: 0.92rem;
  color: var(--muted);
}

.fx-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(238px, 1fr));
  gap: 0.7rem 1.3rem;
}

.fx-checklist li {
  margin: 0;
  display: grid;
  grid-template-columns: 1.35rem 1fr;
  gap: 0.55rem;
  align-items: start;
}

.fx-check {
  margin-top: 0.1rem;
  flex: none;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(74, 222, 128, 0.16);
  color: var(--good);
}

.fx-check svg {
  width: 0.85rem;
  height: 0.85rem;
}

.fx-checklist li.is-fav .fx-check {
  background: rgba(255, 122, 33, 0.18);
  color: var(--accent);
}

.fx-feat {
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
  min-width: 0;
}

.fx-feat-name {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text);
}

.fx-feat-desc {
  font-size: 0.84rem;
  color: var(--muted);
  line-height: 1.5;
}

.fx-fav-star {
  display: inline-flex;
  flex: none;
  color: var(--gold-ink);
}

.fx-fav-star svg {
  width: 0.85rem;
  height: 0.85rem;
}

/* Scroll-reveal: only active once the client component adds .fx-anim, so the
   server-rendered / no-JS state shows every panel and node fully visible. */
.fx-pipeline.fx-anim .fx-panel {
  opacity: 0;
  transition: opacity 0.55s ease, transform 0.55s ease;
}

.fx-pipeline.fx-anim .fx-station--left .fx-panel {
  transform: translate(-22px, 16px);
}

.fx-pipeline.fx-anim .fx-station--right .fx-panel {
  transform: translate(22px, 16px);
}

.fx-pipeline.fx-anim .fx-station.is-visible .fx-panel {
  opacity: 1;
  transform: none;
}

.fx-pipeline.fx-anim .fx-node {
  opacity: 0.55;
  transform: scale(0.72);
  transition: opacity 0.45s ease, transform 0.45s ease;
}

.fx-pipeline.fx-anim .fx-station.is-visible .fx-node {
  opacity: 1;
  transform: none;
}

/* Visible focus for the keyboard path (deep-link anchors land on stations). */
.fx-station:target .fx-node-ring {
  border-color: var(--cedge-orange-47);
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.16), 0 0 18px rgba(255, 122, 33, 0.55);
}

.fx-hero a.btn:focus-visible,
.fx-tile a:focus-visible,
.cta-band a.btn:focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: 2px;
}

/* ---- Responsive ---------------------------------------------------- */
@media (max-width: 900px) {
  .fx-bento {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .fx-tile--big {
    grid-column: span 2;
    grid-row: span 1;
  }

  .fx-tile--big .fx-tile-ic {
    margin-bottom: 0;
  }

  .fx-tile--wide {
    grid-column: span 2;
  }
}

@media (max-width: 820px) {
  .fx-spine {
    left: 1.4rem;
  }

  .fx-stations {
    gap: 1.9rem;
  }

  .fx-station {
    grid-template-columns: 2.8rem 1fr;
    column-gap: 1.1rem;
  }

  .fx-station--left .fx-panel,
  .fx-station--right .fx-panel {
    grid-column: 2;
  }

  .fx-node {
    grid-column: 1;
    width: 2.8rem;
    height: 2.8rem;
  }

  .fx-node-num {
    font-size: 0.9rem;
  }

  .fx-pipeline.fx-anim .fx-station--left .fx-panel,
  .fx-pipeline.fx-anim .fx-station--right .fx-panel {
    transform: translateY(16px);
  }

  .fx-pipeline.fx-anim .fx-station.is-visible .fx-panel {
    transform: none;
  }
}

@media (max-width: 560px) {
  .fx-bento {
    grid-template-columns: minmax(0, 1fr);
    grid-auto-rows: auto;
  }

  .fx-tile--big,
  .fx-tile--wide {
    grid-column: span 1;
    grid-row: auto;
  }

  .fx-panel {
    padding: 1.1rem;
  }

  .fx-checklist {
    grid-template-columns: 1fr;
  }
}

/* ---- Reduced motion: land on the finished state, no movement ------- */
@media (prefers-reduced-motion: reduce) {
  .fx-tile {
    transition: none;
  }

  .fx-tile:hover {
    transform: none;
  }

  .fx-pipeline.fx-anim .fx-panel,
  .fx-pipeline.fx-anim .fx-node {
    transition: none;
    opacity: 1;
    transform: none;
  }

  .fx-spine-fill {
    transform: scaleY(1) !important;
  }
}

/* ---- Client import preview table ----------------------------------- */
.workspace-preview-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

.workspace-preview-table th {
  text-align: left;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mute-t55);
  font-weight: 700;
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--rule-t14);
}

.workspace-preview-table td {
  padding: 0.55rem 0.75rem;
  border-bottom: 1px solid var(--rule-t06);
  color: var(--ink-neutral-2);
  vertical-align: top;
  white-space: nowrap;
}

.workspace-preview-table tr:last-child td {
  border-bottom: 0;
}

.workspace-preview-table .muted {
  color: var(--mute-t32);
}


/* Navigate, with a choice of map app. Anchored to its trigger and above the
   field app's own stacking so it isn't clipped by the chip row. */
.nav-picker {
  position: relative;
  display: inline-flex;
}

.nav-picker-menu {
  position: absolute;
  top: calc(100% + 0.4rem);
  left: 0;
  z-index: 30;
  min-width: 10rem;
  display: flex;
  flex-direction: column;
  padding: 0.3rem;
  border-radius: 12px;
  /* --ground-2 rather than a hard-coded panel colour: it flips with the theme,
     so the menu stays readable on paper as well as on navy. */
  background: var(--ground-2);
  border: 1px solid var(--edge-t16);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
}

.nav-picker-menu a {
  padding: 0.65rem 0.8rem;
  border-radius: 9px;
  color: var(--ink-neutral-1);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 600;
  white-space: nowrap;
}

.nav-picker-menu a:hover {
  background: rgba(var(--tint), 0.08);
}

/* ---- Arrival performance (Insights) ---------------------------------
   "Are you there when you said you'd be?" — one headline number with the
   three that explain it. Semantic colour is deliberately absent: an on-time
   rate is a fact about the business, and painting it red is a judgement the
   owner hasn't asked for. */
.arrival-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.8rem;
  margin-top: 1rem;
}

.arrival-metric {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.95rem 1rem;
  border-radius: 13px;
  background: rgba(var(--tint), 0.04);
  border: 1px solid var(--edge-t10);
}

.arrival-metric.is-headline {
  background: rgba(56, 189, 248, 0.09);
  border-color: var(--cedge-teal-10);
}

.arrival-metric-value {
  font-size: 1.9rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.arrival-metric.is-headline .arrival-metric-value {
  color: var(--ink-sky-1);
}

.arrival-metric-label {
  font-size: 0.86rem;
  font-weight: 600;
}

.arrival-metric-note {
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--mute-t55);
}

.arrival-bias {
  margin: 1rem 0 0;
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--mute-t55);
}

.arrival-advice {
  margin: 0.9rem 0 0;
  padding: 0.85rem 1rem;
  border-radius: 12px;
  font-size: 0.92rem;
  line-height: 1.6;
  background: rgba(251, 191, 36, 0.09);
  border: 1px solid var(--cedge-amber-24);
}

/* The table is the only thing here that can outgrow a phone, so it scrolls
   inside its own box rather than pushing the page sideways. */
.arrival-crew-scroll {
  margin-top: 1.1rem;
  overflow-x: auto;
}

/* ---- Plan my day (route optimization) -------------------------------
   Rebuilt around one idea: the day is a route, so the map, the numbers, and the
   list are one object seen three ways. Every stop's number is the same number on
   the map, the stats are derived from whatever order the list is currently in,
   and nothing here has touched the calendar until Save schedule is pressed. */

.plan-shell {
  display: grid;
  gap: 1rem;
  align-content: start;
  /* Room for the sticky save bar, so the last panel is never trapped under it. */
  padding-bottom: 6rem;
}

.plan-shell>* {
  min-width: 0;
}

/* A panel here carries more contrast than the workspace default: this page has
   five distinct regions stacked on one screen and they have to read as separate
   objects rather than one long scroll. */
.plan-panel {
  border: 1px solid var(--edge-t13);
  background:
    linear-gradient(180deg, rgba(var(--tint), 0.022), transparent 120px),
    rgba(6, 15, 26, 0.92);
  box-shadow: 0 18px 44px -34px rgba(0, 0, 0, 0.9);
}

/* --- Header ---------------------------------------------------------- */
/* The old header spent a 3.4rem display title and a four-field form on "which
   day am I looking at" — most of a laptop screen before the route appeared. */
.plan-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem 1.5rem;
  padding: 0.25rem 0.1rem 0.35rem;
}

.plan-header-title h1 {
  margin: 0.1rem 0 0;
  font-size: clamp(1.6rem, 3vw, 2.15rem);
  line-height: 1.1;
}

.plan-header-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
}

.plan-daynav {
  display: inline-flex;
  gap: 0.25rem;
  padding: 0.2rem;
  border-radius: 999px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.03);
}

.plan-daynav .btn {
  padding: 0.34rem 0.85rem;
  font-size: 0.83rem;
  border: 0;
  background: none;
}

.plan-daynav .btn:hover {
  background: rgba(var(--tint), 0.07);
}

.plan-controls {
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
  transition: opacity 0.15s ease;
}

.plan-controls.is-busy {
  opacity: 0.55;
  pointer-events: none;
}

.plan-control {
  display: inline-flex;
  flex-direction: column;
  gap: 0.1rem;
}

.plan-control-label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--mute-i50);
  padding-left: 0.15rem;
}

.plan-control input,
.plan-control select {
  min-height: 34px;
  padding: 0 0.6rem;
  border-radius: 9px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font: inherit;
  font-size: 0.86rem;
}

.plan-control select option {
  background: var(--bg-3);
  color: var(--text);
}

.plan-back {
  align-self: flex-end;
}

.plan-flash {
  margin: 0;
  padding: 0.75rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.04);
  font-size: 0.9rem;
}

.plan-flash.good {
  background: rgba(74, 222, 128, 0.12);
  border-color: var(--cedge-green-29);
  color: var(--good);
}

.plan-flash.warn {
  background: rgba(251, 191, 36, 0.12);
  border-color: var(--cedge-amber-40);
  color: var(--ink-amber-2);
}

/* --- Map + route status ---------------------------------------------- */
.plan-route-panel {
  padding: 1rem;
}

.plan-route-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 1fr);
  gap: 1rem;
  align-items: stretch;
}

.plan-map-holder {
  position: relative;
  min-height: 400px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--edge-t10);
  background: #0d1b2a;
}

.plan-map-canvas {
  position: absolute;
  inset: 0;
}

.plan-map-fallback {
  display: grid;
  place-items: center;
  padding: 2rem 1.5rem;
  text-align: center;
  color: var(--mute-t55);
  font-size: 0.9rem;
}

.plan-map-fallback p {
  margin: 0;
  max-width: 40ch;
}

.plan-map-veil {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(var(--panel-rgb), 0.75);
  color: rgba(var(--tint), 0.7);
  font-size: 0.88rem;
}

/* Recalculating is a status, not a blocker: the numbers beside the map already
   updated, so covering it would hide the answer the contractor just asked for.
   Everything sits along the TOP edge — Google's logo and terms own the bottom of
   the canvas, and covering either is both ugly and against their terms. */
.plan-map-busy,
/* The demo's drawn stand-in for the route map. The holder is the real one, so
   it sits in exactly the space Google would occupy — the point of the demo is
   that the layout is the product's, only the data is invented. */
/* The live planner fills this column with controls, so it stretches to the
   map. The demo's is read-only and short, and stretching it leaves half a
   card of empty white beside the route. */
.demo-route-grid {
  align-items: start;
}

.demo-map {
  min-height: 340px;
}

.demo-map .plan-map-canvas {
  width: 100%;
  height: 100%;
}

.demo-map-note {
  position: absolute;
  left: 0.7rem;
  bottom: 0.7rem;
  margin: 0;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(10, 20, 33, 0.86);
  color: rgba(255, 255, 255, 0.74);
  font-size: 0.74rem;
  font-weight: 650;
}

/* The holder is chrome-dark in both themes; on a light sheet its own note has
   to stay light-on-dark with it rather than following the sheet's ink. */
:root[data-theme='light'] .demo-map-note {
  color: rgba(255, 255, 255, 0.78);
}

.plan-map-note {
  position: absolute;
  top: 0.7rem;
  left: 0.7rem;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 600;
  background: rgba(var(--panel-rgb), 0.88);
  border: 1px solid var(--edge-t14);
  color: rgba(var(--tint), 0.72);
}

.plan-map-busy {
  border-color: var(--cedge-orange-28);
  color: var(--ink-orange-3);
}

.plan-map-controls {
  position: absolute;
  right: 0.7rem;
  top: 0.7rem;
  display: flex;
  gap: 0.4rem;
}

.plan-map-fit,
.plan-map-toggle {
  padding: 0.4rem 0.8rem;
  border-radius: 9px;
  border: 1px solid var(--edge-t18);
  background: rgba(var(--panel-rgb), 0.9);
  color: var(--text);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.plan-map-fit:hover:not(:disabled) {
  border-color: var(--cedge-orange-30);
  color: var(--ink-orange-3);
}

.plan-map-fit:disabled,
.plan-map-toggle:disabled {
  opacity: 0.4;
  cursor: default;
}

.plan-map-toggle:hover:not(:disabled) {
  border-color: var(--cedge-teal-11);
  color: var(--ink-sky-2);
}

/* On is a state worth seeing at a glance, because it's the one control here that
   costs money every time it's switched. */
.plan-map-toggle.is-on {
  border-color: var(--cedge-teal-12);
  background: rgba(125, 211, 252, 0.16);
  color: var(--ink-sky-2);
}

.plan-route-side {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  min-width: 0;
}

.plan-verdict {
  display: flex;
  gap: 0.75rem;
  padding: 0.9rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.035);
}

.plan-verdict strong {
  display: block;
  font-size: 1.02rem;
  line-height: 1.3;
}

.plan-verdict p {
  margin: 0.25rem 0 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: var(--mute-t60);
}

.plan-verdict .btn {
  margin-top: 0.65rem;
  padding: 0.3rem 0.75rem;
  font-size: 0.8rem;
}

.plan-verdict-mark {
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  flex-shrink: 0;
  border-radius: 50%;
  font-size: 0.95rem;
  font-weight: 800;
}

.plan-verdict.good {
  border-color: var(--cedge-green-30);
  background: rgba(74, 222, 128, 0.08);
}

.plan-verdict.good .plan-verdict-mark {
  background: rgba(74, 222, 128, 0.2);
  color: var(--ink-green-3);
}

.plan-verdict.good strong {
  color: var(--ink-green-3);
}

.plan-verdict.offer {
  border-color: var(--cedge-orange-32);
  background: rgba(255, 122, 33, 0.09);
}

.plan-verdict.offer .plan-verdict-mark {
  background: rgba(255, 122, 33, 0.2);
  color: var(--ink-orange-3);
}

.plan-verdict.offer strong {
  color: var(--ink-orange-3);
}

.plan-verdict.neutral .plan-verdict-mark {
  background: rgba(var(--tint), 0.09);
  color: var(--mute-t60);
}

/* One row of numbers instead of two cards that repeated each other whenever the
   current and planned routes happened to be the same. */
.plan-stat-row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  margin: 0;
  padding: 0.85rem 0.5rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--tint), 0.03);
}

.plan-stat {
  text-align: center;
  min-width: 0;
}

.plan-stat dt {
  font-size: 0.64rem;
  line-height: 1.3;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--mute-i50);
}

.plan-stat dd {
  margin: 0.2rem 0 0;
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.plan-stat.is-over dd {
  color: var(--ink-orange-3);
}

.plan-route-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: auto;
}

/* --- Overtime warning ------------------------------------------------- */
/* This used to be the fourth bullet in a list of notes. It's the one thing on
   the page that might make somebody change their day, so it gets to be a card. */
.plan-overtime {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.15rem;
  border-color: var(--cedge-orange-28);
  background: linear-gradient(180deg, rgba(255, 122, 33, 0.13), rgba(255, 122, 33, 0.05));
  box-shadow: 0 0 26px -12px rgba(255, 122, 33, 0.55);
}

.plan-overtime-head {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  min-width: 0;
}

.plan-overtime-head strong {
  display: block;
  font-size: 1rem;
  color: var(--ink-orange-3);
  line-height: 1.3;
}

.plan-overtime-head p {
  margin: 0.25rem 0 0;
  font-size: 0.86rem;
  color: rgba(var(--tint), 0.65);
}

.plan-overtime-icon {
  display: grid;
  place-items: center;
  width: 1.8rem;
  height: 1.8rem;
  flex-shrink: 0;
  border-radius: 50%;
  background: rgba(255, 122, 33, 0.22);
  border: 1px solid var(--cedge-orange-30);
  color: var(--ink-orange-3);
  font-weight: 800;
}

.plan-overtime-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
}

.plan-overtime-actions .btn {
  padding: 0.36rem 0.85rem;
  font-size: 0.83rem;
}

/* --- Body: stops + aside ---------------------------------------------- */
.plan-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 20rem);
  gap: 1rem;
  align-items: start;
}

.plan-stops-panel {
  padding: 1.1rem 1.15rem 1.25rem;
}

.plan-stops-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.9rem;
}

.plan-stops-head h2 {
  margin: 0.15rem 0 0;
  font-size: 1.3rem;
}

.plan-drag-hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--mute-t45);
}

/* A route insight that is ABOUT a setting links to it. The panel that changes
   the working day is on this same screen, a few hundred pixels down. */
.plan-insight-fix {
  color: var(--accent);
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.plan-insight-fix:hover,
.plan-insight-fix:focus-visible {
  text-decoration: underline;
}

/* Landing on it must not put its summary under the fixed bar. */
#working-hours {
  scroll-margin-top: calc(var(--appbar-h) + 1rem);
}

.plan-stop-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.plan-stop {
  position: relative;
  display: grid;
  grid-template-columns: 2.4rem minmax(0, 1fr) 6rem 7rem auto;
  grid-template-areas:
    'num who arrive finish actions'
    'num meta meta meta actions';
  gap: 0.3rem 0.9rem;
  align-items: center;
  padding: 0.7rem 0.85rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t09);
  background: rgba(var(--tint), 0.028);
  transition: border-color 0.15s ease, background 0.15s ease, opacity 0.15s ease;
}

.plan-stop:hover {
  border-color: var(--edge-t17);
}

.plan-stop.is-locked {
  background: rgba(74, 222, 128, 0.045);
}

.plan-stop.is-pinned {
  background: rgba(125, 211, 252, 0.05);
}

.plan-stop[draggable='true'] {
  cursor: grab;
}

/* The list rearranges under the cursor, so the card is always sitting exactly
   where it would land and the times on it are the real ones for that slot.
   That makes a separate "drop target" highlight redundant — the answer to "where
   will this go" is that it's already there. */
.plan-stop-list.is-dragging .plan-stop {
  transition: transform 0.16s ease, opacity 0.16s ease;
}

.plan-stop.is-lifted {
  cursor: grabbing;
  border-color: var(--cedge-orange-48);
  background: rgba(255, 122, 33, 0.12);
  box-shadow: 0 0 0 1px rgba(255, 138, 61, 0.45), 0 14px 32px -12px rgba(255, 122, 33, 0.75);
  /* Lifted off the page rather than following the cursor: the browser's own drag
     ghost is suppressed, because a translucent second copy sliding over rows that
     are themselves moving is two contradictory answers to the same question. */
  transform: scale(1.012);
  z-index: 2;
}

.plan-stop.is-shifting {
  opacity: 0.82;
}

/* A pinned stop is the one thing nothing may cross, so during a drag it says so
   instead of silently refusing the drop. */
.plan-stop.is-blocking {
  opacity: 1;
  border-color: var(--cedge-teal-11);
  border-style: dashed;
}

@media (prefers-reduced-motion: reduce) {
  .plan-stop-list.is-dragging .plan-stop {
    transition: none;
  }

  .plan-stop.is-lifted {
    transform: none;
  }
}

/* The numbers double as the route timeline: the connector makes the list read as
   one journey rather than five unrelated rows. */
.plan-stop-num {
  grid-area: num;
  position: relative;
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  align-self: center;
  border-radius: 50%;
  background: linear-gradient(160deg, #ff8a3d, #ff6a12);
  color: #10202f;
  font-family: var(--font-display);
  font-size: 0.92rem;
  z-index: 1;
}

.plan-stop.is-locked .plan-stop-num {
  background: linear-gradient(160deg, #ffd98a, #f5b73c);
}

.plan-stop:not(:last-child) .plan-stop-num::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  width: 2px;
  /* Reaches the next circle: the row's own bottom padding, the list gap, and the
     next row's top padding. */
  height: calc(0.7rem + 0.5rem + 0.7rem);
  margin-left: -1px;
  background: linear-gradient(180deg, rgba(255, 138, 61, 0.5), rgba(255, 138, 61, 0.18));
}

.plan-stop-who {
  grid-area: who;
  min-width: 0;
}

.plan-stop-name {
  font-weight: 700;
  font-size: 0.98rem;
  color: var(--ink-neutral-9);
  text-decoration: none;
  display: block;
  overflow-wrap: anywhere;
}

.plan-stop-name:hover {
  text-decoration: underline;
}

.plan-stop-addr {
  margin: 0.12rem 0 0;
  font-size: 0.82rem;
  color: var(--mute-t55);
  overflow-wrap: anywhere;
}

.plan-stop-drive {
  font-size: 0.76rem;
  color: var(--mute-t42);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.plan-stop-when {
  display: contents;
}

.plan-stop-time {
  min-width: 0;
}

.plan-stop-time:first-child {
  grid-area: arrive;
}

.plan-stop-time:last-child {
  grid-area: finish;
}

.plan-stop-time small {
  display: block;
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--mute-i42);
}

.plan-stop-time strong {
  display: block;
  font-size: 0.95rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--ink-neutral-9);
}

/* Drive info and badges share the second row so a stop is three lines, not five. */
.plan-stop-flags {
  grid-area: meta;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.5rem;
  min-width: 0;
}

.plan-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  background: rgba(var(--tint), 0.07);
  color: var(--mute-t60);
  white-space: nowrap;
}

.plan-badge.locked {
  background: rgba(74, 222, 128, 0.16);
  color: var(--good);
}

.plan-badge.locked::before {
  content: '🔒';
  font-size: 0.68rem;
}

.plan-badge.pinned {
  background: rgba(125, 211, 252, 0.16);
  color: var(--ink-sky-2);
}

.plan-badge.flexible {
  background: rgba(var(--tint), 0.07);
  color: var(--mute-t58);
}

.plan-badge.flexible::before {
  content: '↕';
  font-weight: 800;
}

/* "Day 2 of 4 · ~4 hrs today" — a job the contractor is on site for part of,
   several days running. Orange rather than one of the state colours because it
   is not a state: the stop is as flexible or as locked as any other, and this
   only says the four hours on the row are today's share of a bigger job. */
/* --ink-orange-1 and not --cedge-orange-2: the "cedge" oranges are 38%-alpha
   EDGE colours for borders, and one of them used as text on the quick-stops
   page rendered brown. */
.plan-badge.span {
  background: rgba(255, 122, 41, 0.16);
  color: var(--ink-orange-1);
}

.plan-badge.span::before {
  content: '⧉';
  font-weight: 800;
}

/* "Assumed: 2 hr" — the job has no estimated hours, so the route planned it on
   the account default. Amber because it IS a warning: the same job counts as
   zero against the day's capacity, so the day can read "0 of 136 hours" while
   the route has already spent two of them. A link, so the field that settles it
   is one press away; underlined on hover rather than always, so a row with
   three badges does not read as a row of links. */
.plan-badge.assumed {
  background: rgba(251, 191, 36, 0.16);
  color: var(--ink-amber-1);
}

.plan-badge.assumed::before {
  content: '≈';
  font-weight: 800;
}

.plan-badge.assumed:hover {
  text-decoration: underline;
}

/* Where the day is meant to end. Violet because it's neither a lock (green)
   nor a warning (amber) — it's an intention, and it can be out of date. */
.plan-badge.last {
  background: rgba(167, 139, 250, 0.18);
  color: var(--ink-neutral-14);
}

.plan-badge.last::before {
  content: '🏁';
  font-size: 0.68rem;
}

/* Once it isn't last any more the badge becomes the fix: one click puts it
   back at the end. So it has to look pressable, not decorative. */
button.plan-badge.last.is-adrift {
  border: 1px solid var(--cedge-amber-4);
  background: rgba(255, 209, 102, 0.14);
  color: var(--warn);
  font: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  cursor: pointer;
}

button.plan-badge.last.is-adrift:hover {
  background: rgba(255, 209, 102, 0.24);
}

button.plan-badge.last.is-adrift:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.8);
  outline-offset: 2px;
}

.plan-stop.is-adrift {
  box-shadow: inset 3px 0 0 rgba(255, 209, 102, 0.75);
}

.plan-badge.warn {
  background: rgba(251, 191, 36, 0.18);
  color: var(--ink-amber-2);
  white-space: normal;
}

/* "Cannot be finished today" is the one badge on this row whose entire content
   is "something has to move", and it was a label — with the action three taps
   away behind ⋮. It is the button now, so it has to look pressable. Same
   treatment as the adrift last-stop badge above, which is the same idea. */
button.plan-badge.warn.is-action {
  border: 1px solid var(--cedge-amber-4);
  font: inherit;
  font-size: 0.7rem;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
}

button.plan-badge.warn.is-action:hover {
  background: rgba(251, 191, 36, 0.3);
}

button.plan-badge.warn.is-action:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.8);
  outline-offset: 2px;
}

.plan-stop-actions {
  grid-area: actions;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.plan-stop-actions .btn {
  padding: 0.3rem 0.7rem;
  font-size: 0.79rem;
  white-space: nowrap;
}

/* "I'm on my way", per stop.
   Reads its own state rather than sitting there as a fixed label: a list of ten
   stops is exactly where somebody texts the same customer twice, so a row that
   has already gone out says so and takes the emphasis off. */
.plan-stop-otw {
  font-weight: 700;
}

.plan-stop-otw.is-live {
  border-color: rgba(255, 122, 41, 0.55);
  background: rgba(255, 122, 41, 0.14);
  color: var(--ink-orange-1);
}

.plan-stop-otw.is-done {
  border-color: rgba(74, 222, 128, 0.4);
  background: rgba(74, 222, 128, 0.12);
  color: var(--good);
}

/* The send sheet inside the row's popover. It carries the panel the job screen
   uses, whose own card chrome would be a second border inside this one. */
.plan-stop-arrival .panel,
.plan-stop-arrival .workspace-section-card {
  border: 0;
  background: none;
  padding: 0;
  margin: 0;
}

.plan-stop-arrival .arrival-card-title {
  font-size: 0.9rem;
  margin: 0 0 0.6rem;
}

.plan-stop-arrival .arrival-message {
  width: 100%;
}

.plan-stop-menu-btn {
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 8px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  color: rgba(var(--tint), 0.7);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.plan-stop-menu-btn:hover {
  border-color: var(--cedge-orange-28);
  color: var(--ink-orange-3);
}

.plan-stop-grip {
  position: absolute;
  top: 0.45rem;
  right: 0.5rem;
  font-size: 0.8rem;
  color: var(--mute-t22);
  letter-spacing: -0.1em;
  pointer-events: none;
}

.plan-stop-menu {
  display: flex;
  flex-direction: column;
  padding: 0.3rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t16);
  background: #0f1c2b;
  box-shadow: 0 24px 48px -20px rgba(0, 0, 0, 0.85);
}

.plan-stop-menu-item {
  display: block;
  width: 100%;
  padding: 0.5rem 0.65rem;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--ink-neutral-2);
  font: inherit;
  font-size: 0.85rem;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}

.plan-stop-menu-item:hover {
  background: rgba(var(--tint), 0.07);
}

.plan-stop-menu-nudge {
  display: flex;
  gap: 0.3rem;
  margin-top: 0.25rem;
  padding-top: 0.35rem;
  border-top: 1px solid var(--rule-t09);
}

.plan-stop-menu-nudge button {
  flex: 1;
  padding: 0.4rem 0.3rem;
  border: 1px solid var(--edge-t12);
  border-radius: 8px;
  background: rgba(var(--tint), 0.04);
  color: var(--ink-neutral-2);
  font: inherit;
  font-size: 0.78rem;
  cursor: pointer;
}

.plan-stop-menu-nudge button:hover:not(:disabled) {
  border-color: var(--cedge-orange-28);
  color: var(--ink-orange-3);
}

.plan-stop-menu-nudge button:disabled {
  opacity: 0.35;
  cursor: default;
}

/* --- Aside ------------------------------------------------------------ */
.plan-aside {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}

.plan-aside .plan-panel {
  padding: 1rem 1.1rem;
}

.plan-aside h3 {
  margin: 0 0 0.75rem;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--mute-i55);
}

.plan-summary dl {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.plan-summary dl>div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.42rem 0;
  border-bottom: 1px solid var(--rule-t05);
}

.plan-summary dl>div:last-child {
  border-bottom: 0;
}

.plan-summary dt {
  font-size: 0.85rem;
  color: var(--mute-t60);
}

.plan-summary dd {
  margin: 0;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.plan-summary dl>div.is-over dd {
  color: var(--ink-orange-3);
}

.plan-over-flag {
  margin-left: 0.15rem;
}

.plan-insights ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.plan-insights li {
  display: flex;
  gap: 0.55rem;
  font-size: 0.84rem;
  line-height: 1.45;
  color: rgba(var(--tint), 0.68);
}

.plan-insight-mark {
  display: grid;
  place-items: center;
  width: 1.1rem;
  height: 1.1rem;
  flex-shrink: 0;
  margin-top: 0.12rem;
  border-radius: 50%;
  font-size: 0.66rem;
  font-weight: 800;
  background: rgba(var(--tint), 0.08);
  color: var(--mute-t55);
}

.plan-insights li.good .plan-insight-mark {
  background: rgba(74, 222, 128, 0.18);
  color: var(--ink-green-3);
}

.plan-insights li.warn .plan-insight-mark {
  background: rgba(251, 191, 36, 0.2);
  color: var(--ink-amber-2);
}

.plan-insights li.warn {
  color: var(--ink-amber-2);
}

.plan-quick ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.plan-quick li a {
  display: block;
  padding: 0.48rem 0.55rem;
  margin: 0 -0.55rem;
  border-radius: 9px;
  font-size: 0.86rem;
  color: rgba(var(--tint), 0.75);
  text-decoration: none;
}

.plan-quick li a:hover {
  background: rgba(var(--tint), 0.06);
  color: var(--ink-orange-3);
}

/* --- Sticky save bar --------------------------------------------------- */
/* Appears only when saving would actually change something, so an untouched day
   in sync with the calendar shows nothing at all. */
.plan-savebar {
  position: sticky;
  bottom: 0.85rem;
  z-index: 40;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.85rem 1.25rem;
  margin-top: 0.25rem;
  padding: 0.85rem 1.1rem;
  border-radius: 16px;
  border: 1px solid var(--cedge-orange-29);
  background: rgba(12, 24, 38, 0.96);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 22px 50px -20px rgba(0, 0, 0, 0.9), 0 0 26px -14px rgba(255, 122, 33, 0.6);
}

/* AN OFFER, NOT AN ALARM.
   Until something is dragged, this bar is the planner's opening proposal on a
   day the contractor has only just opened - so it drops the orange edge and the
   glow it wears when there are real edits waiting to be written. */
.plan-savebar.is-offer {
  border-color: var(--edge-t14);
  box-shadow: 0 22px 50px -20px rgba(0, 0, 0, 0.9);
}

.plan-savebar-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.plan-savebar-copy strong {
  font-size: 0.95rem;
}

.plan-savebar-copy span {
  font-size: 0.82rem;
  color: var(--mute-t58);
}

.plan-savebar-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

/* --- Supply stops ------------------------------------------------------ */
/* A stop that isn't a job reads differently: cooler, quieter, and marked with
   what kind of errand it is. It still costs the day real time and real miles —
   the whole reason it's here — but nobody is paying for it. */
.plan-stop.is-errand {
  background: rgba(125, 211, 252, 0.045);
}

.plan-stop.is-errand .plan-stop-num {
  background: linear-gradient(160deg, #7dd3fc, #38bdf8);
  color: #062033;
}

.plan-stop-name.is-errand {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--ink-sky-2);
}

.plan-stop-name.is-errand svg {
  width: 0.95rem;
  height: 0.95rem;
  flex-shrink: 0;
}

.plan-badge.errand {
  background: rgba(125, 211, 252, 0.16);
  color: var(--ink-sky-2);
}

.plan-stop-menu-item.danger {
  color: var(--ink-red-1);
}

.plan-stop-menu-item.danger:hover {
  background: rgba(255, 110, 90, 0.12);
}

.plan-addstop-collapsed {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem 0.9rem;
  margin-top: 0.9rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-t07);
}

.plan-place-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
}

.plan-place-chips-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--mute-i42);
}

/* The place book. Second time to the county dump should be one tap, so these
   sort by how often this contractor actually goes. */
.plan-place-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.26rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-teal-13);
  background: rgba(125, 211, 252, 0.09);
  color: var(--ink-sky-2);
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  max-width: 14rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.plan-place-chip:hover {
  border-color: var(--cedge-teal-14);
  background: rgba(125, 211, 252, 0.16);
}

.plan-place-chip svg {
  width: 0.85rem;
  height: 0.85rem;
  flex-shrink: 0;
}

.plan-addstop {
  margin-top: 0.9rem;
  padding: 1rem 1.05rem;
  border-radius: 14px;
  border: 1px solid var(--cedge-teal-15);
  background: rgba(125, 211, 252, 0.05);
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.plan-addstop-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.plan-addstop-grid {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.7rem;
}

.plan-addstop .field {
  margin: 0;
}

.plan-addstop .form-actions {
  margin: 0;
}

/* --- No home base ------------------------------------------------------- */
.plan-nohome {
  padding: 0.9rem 1.1rem;
  border-color: var(--cedge-amber-41);
  background: rgba(251, 191, 36, 0.07);
}

.plan-nohome>summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.plan-nohome>summary::-webkit-details-marker {
  display: none;
}

.plan-nohome>summary strong {
  color: var(--ink-amber-2);
  font-size: 0.95rem;
}

.plan-nohome>summary span {
  font-size: 0.85rem;
  color: var(--mute-t62);
}

.plan-nohome p {
  margin: 0.75rem 0;
  font-size: 0.88rem;
  color: rgba(var(--tint), 0.7);
}

.plan-empty {
  padding: 2rem 1.5rem;
  text-align: center;
}

.plan-empty h2 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
}

.plan-empty p {
  margin: 0 auto;
  max-width: 52ch;
  color: var(--mute-t60);
}

.plan-empty .form-actions {
  justify-content: center;
  margin-top: 1.2rem;
}

.plan-notify-list {
  margin: 0.9rem 0 1.1rem;
  padding-left: 1.2rem;
  font-size: 0.88rem;
  color: rgba(var(--tint), 0.7);
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

/* Says what the customer will actually receive, right where you decide to
   send it — a window, not the single time the row above shows. */
.plan-notify-note {
  margin: 0 0 1rem;
  font-size: 0.8rem;
  color: var(--mute-t52);
  line-height: 1.5;
  max-width: 46rem;
}

.plan-panel>h2 {
  margin: 0 0 0.5rem;
  font-size: 1.2rem;
}

.plan-panel>p {
  color: rgba(var(--tint), 0.65);
  font-size: 0.9rem;
}

@media (max-width: 1080px) {
  .plan-route-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .plan-map-holder {
    min-height: 300px;
  }

  .plan-body {
    grid-template-columns: minmax(0, 1fr);
  }

  .plan-aside {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .plan-aside>* {
    flex: 1 1 15rem;
  }
}

@media (max-width: 760px) {
  .plan-header {
    align-items: flex-start;
  }

  .plan-header-controls {
    width: 100%;
  }

  .plan-controls {
    flex: 1 1 auto;
  }

  .plan-control {
    flex: 1 1 8rem;
    min-width: 0;
  }

  .plan-control input,
  .plan-control select {
    width: 100%;
  }

  /* The name and address get the full width; a Directions button sharing their
     row turned "4455 Rochester Rd, Troy, MI 48085" into four lines.

     AND THE ACTIONS GET THEIR OWN ROW. They used to share the last row with the
     drive info and the badges, on an `auto` track that sized itself to three
     buttons - about 230px of a 390px screen. Grid does not clip an overflowing
     item, so "1.3 mi - 4 min drive" and the Flexible badge ran on underneath
     the buttons and the card read as a pile. There is no width at which those
     five things fit on one line here. */
  .plan-stop {
    grid-template-columns: 2.2rem minmax(0, 1fr);
    grid-template-areas:
      'num who'
      'num times'
      'num meta'
      'num actions';
    gap: 0.4rem 0.7rem;
    align-items: start;
  }

  .plan-stop-num {
    align-self: start;
  }

  .plan-stop:not(:last-child) .plan-stop-num::after {
    height: calc(100% + 0.5rem);
    top: 2rem;
  }

  .plan-stop-when {
    display: flex;
    grid-area: times;
    gap: 1.5rem;
  }

  .plan-stop-time:first-child,
  .plan-stop-time:last-child {
    grid-area: auto;
  }

  .plan-stop-flags {
    align-self: center;
  }

  /* Wraps rather than overflows: a stop with a long badge and three actions
     still has to stay inside its own card. */
  .plan-stop-actions {
    align-self: center;
    flex-wrap: wrap;
  }

  .plan-stop-actions .btn {
    padding: 0.28rem 0.6rem;
    font-size: 0.76rem;
  }

  .plan-stop-grip {
    display: none;
  }

  .plan-stat-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem 0.5rem;
  }

  .plan-aside {
    flex-direction: column;
  }

  .plan-savebar {
    flex-direction: column;
    align-items: stretch;
  }

  .plan-savebar-actions {
    justify-content: flex-end;
  }
}


/* ---- Settings history (account_events audit trail) ------------------ */
.settings-history-list {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.settings-history-list li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 0.6rem 0.8rem;
  border-radius: 10px;
  background: rgba(var(--tint), 0.035);
  border: 1px solid var(--edge-t07);
}

.settings-history-summary {
  font-size: 0.88rem;
  color: var(--ink-neutral-2);
}

.settings-history-meta {
  font-size: 0.76rem;
  color: var(--mute-t45);
  white-space: nowrap;
}

/* ---- Mobile: keep the lead nudge from swallowing the screen ---------- */
/* At 390px the alert was ~358px wide and ~180px tall, sitting over the bottom
   third of every page — covering the content you were reading and the controls
   you'd tap next. Same urgency, a third of the footprint: the age line drops
   (it's the least load-bearing) and the button moves alongside the headline. */
@media (max-width: 640px) {
  .quote-request-alert {
    left: 0.75rem;
    right: 0.75rem;
    bottom: 0.75rem;
    width: auto;
    padding: 0.75rem 0.85rem;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.15rem 0.75rem;
    border-radius: 14px;
  }

  .quote-request-alert p {
    grid-column: 1;
    grid-row: 1;
    font-size: 0.66rem;
  }

  .quote-request-alert strong {
    grid-column: 1;
    grid-row: 2;
    font-size: 0.92rem;
  }

  .quote-request-alert span {
    display: none;
  }

  .quote-request-alert .btn {
    grid-column: 2;
    grid-row: 1 / span 2;
    white-space: nowrap;
  }

  /* Reserve a gutter for the dismiss control. Left at the corner it overlapped
     "View lead", so a thumb aiming for the lead could dismiss the alert
     instead — the one misfire that loses the thing being nudged about. */
  .quote-request-alert {
    padding-right: 2.15rem;
  }

  .quote-request-alert-close {
    top: 50%;
    transform: translateY(-50%);
    right: 0.3rem;
  }
}

/* ---- Mobile: Plan my day day-stepper ------------------------------- */
/* The four controls wrapped one-per-row on a phone, pushing the route itself
   below the fold. Step buttons share a row; the primary action stays full width. */
@media (max-width: 640px) {
  .route-plan-controls {
    gap: 0.75rem;
  }

  .route-plan-controls .field {
    min-width: 0;
    width: 100%;
  }

  .route-plan-control-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    width: 100%;
  }

  .route-plan-control-actions> :first-child {
    grid-column: 1 / -1;
  }

  .route-plan-control-actions> :last-child {
    grid-column: 1 / -1;
  }

  .route-plan-control-actions .btn {
    width: 100%;
    justify-content: center;
  }
}

/* ---- Touch targets ------------------------------------------------- */
/* The dismiss control was a 27x27 circle — well under the ~44px a thumb needs,
   and it sits right beside the button people actually want. Keep the small
   visual circle, expand the hit area around it. */
.quote-request-alert-close::after {
  content: '';
  position: absolute;
  inset: -0.55rem;
}

/* Two of our own controls sat at ~31px on a phone. Both are ordinary links that
   happen to be styled compactly; on touch they get a full-height target. */
@media (max-width: 640px) {

  .sidenav-sublink,
  .automation-link {
    min-height: 44px;
    align-items: center;
  }
}

/* The "mobile or email" requirement sits directly under that pair of fields, at
   the point the decision is made. The server rejects a booking without one, so
   this is a rule, not a suggestion — two of the four booking forms enforced it
   while saying nothing, and the other two mentioned it below the address field
   where it read as an aside. */
.booking-contact-hint {
  grid-column: 1 / -1;
  margin: -0.35rem 0 0.15rem;
  font-size: 0.82rem;
  color: var(--mute-t62);
}

.booking-contact-hint strong {
  color: rgba(var(--tint), 0.86);
}

/* ---- Mobile: let short labels wrap instead of truncating ------------ */
/* Both of these ellipsis on one line, which is right on a wide row and wrong on
   a 390px phone, where the text IS the content:
     "11 scheduled jobs need crew"  ->  "11 schedul…"
     "Invoice / payment requested"  ->  "Invoice / paym…"
   A card whose whole job is telling you what needs doing can't truncate the
   telling. These are two or three words; wrapping to a second line costs a few
   pixels and keeps the meaning. */
@media (max-width: 640px) {

  .priority-copy strong,
  .pipeline-step strong,
  .pipeline-step small,
  /* "Draft invoice will be created automatically" — an explanation that stops
     explaining anything once it's cut to "Draft invoice will be…". */
  .invoice-context-pill strong {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
  }

  .pipeline-step strong {
    line-height: 1.25;
  }
}

/* ---- Quick Stop explainer (shown while it's switched off) ------------ */
/* This page has one job: explain Quick Stop fast enough that a contractor turns
   it on. Icons carry the meaning at a glance, the flow reads as a connected
   sequence rather than four loose boxes, and the primary action sits in the hero
   where the pitch lands — not at the bottom past everything else. */
.es-explainer {
  display: grid;
  gap: 1.1rem;
  margin-top: 1.1rem;
}

.es-explainer svg {
  width: 1em;
  height: 1em;
  flex: none;
}

/* ---- hero ---- */
.es-hero {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(255px, 0.85fr);
  gap: 1.4rem;
  align-items: center;
  padding: 1.6rem;
  border-radius: 20px;
  border: 1px solid var(--cedge-orange-6);
  background:
    radial-gradient(120% 140% at 88% 0%, rgba(255, 122, 33, 0.2), transparent 58%),
    linear-gradient(150deg, rgba(255, 122, 33, 0.1), rgba(var(--panel-rgb), 0.94) 52%);
}

.es-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.6rem;
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-orange-49);
  background: rgba(255, 122, 33, 0.12);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.es-kicker svg {
  width: 0.9rem;
  height: 0.9rem;
}

.es-hero-copy h2 {
  font-size: clamp(1.7rem, 2.8vw, 2.5rem);
  line-height: 1.08;
  margin: 0 0 0.65rem;
  letter-spacing: -0.01em;
}

.es-accent {
  color: var(--ink-orange-6);
  text-shadow: 0 0 26px rgba(255, 122, 33, 0.35);
}

.es-lead {
  margin: 0 0 1rem;
  color: rgba(var(--tint), 0.74);
  font-size: 0.96rem;
  line-height: 1.55;
  max-width: 48ch;
}

.es-promises {
  list-style: none;
  margin: 0 0 1.15rem;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.15rem;
}

.es-promises li {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  font-size: 0.87rem;
  font-weight: 700;
  color: var(--ink-neutral-2);
}

.es-promises svg {
  color: var(--good);
  width: 1.05rem;
  height: 1.05rem;
}

.es-hero-cta {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  flex-wrap: wrap;
}

.es-hero-cta p {
  margin: 0;
  font-size: 0.8rem;
  color: var(--mute-t55);
}

.es-cta-btn {
  font-size: 1rem;
  padding: 0.85rem 1.5rem;
  box-shadow: 0 12px 34px rgba(255, 122, 33, 0.34);
  transition: transform 0.16s ease, box-shadow 0.16s ease;
}

.es-cta-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 42px rgba(255, 122, 33, 0.44);
}

/* The second button in this row is the same SIZE but not the same weight — the
   orange glow belongs to the one action the section is asking for. */
.btn.secondary.es-cta-btn {
  box-shadow: none;
}

.btn.secondary.es-cta-btn:hover {
  box-shadow: none;
  border-color: var(--edge-t40);
}

.es-earnings {
  position: relative;
  padding: 1.2rem;
  border-radius: 16px;
  border: 1px solid var(--cedge-orange-50);
  background: rgba(3, 10, 18, 0.62);
  text-align: center;
}

/* A near-black fill inside a white sheet is a slab, not a lift — and the label
   on it is the sheet's own near-black ink. */
:root[data-theme='light'] .es-earnings {
  border-color: #a1791a;
  background: #fff8f0;
}

.es-earnings-glow {
  position: absolute;
  inset: -40% -20% auto;
  height: 150px;
  pointer-events: none;
  background: radial-gradient(closest-side, rgba(255, 122, 33, 0.32), transparent 70%);
}

.es-earnings-label {
  position: relative;
  margin: 0;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-t50);
}

.es-earnings-line {
  position: relative;
  margin: 0.5rem 0 0.15rem;
  font-size: 0.9rem;
  color: rgba(var(--tint), 0.78);
}

.es-earnings-line strong {
  color: var(--text);
}

.es-earnings-total {
  position: relative;
  margin: 0.1rem 0 0.5rem;
  line-height: 1;
  font-weight: 900;
  font-size: clamp(2.2rem, 4.4vw, 3.1rem);
  background: linear-gradient(180deg, #ffd7ad, #ff8a2b);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.es-earnings-total span {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--mute-t50);
  -webkit-text-fill-color: rgba(var(--tint), 0.5);
}

.es-earnings-note {
  position: relative;
  margin: 0;
  font-size: 0.73rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

/* ---- shared block ---- */
.es-block {
  padding: 1.25rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t08);
  background: rgba(var(--tint), 0.025);
}

.es-block-title {
  margin: 0 0 1rem;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-t55);
}

/* ---- the four-step flow ---- */
/* A connector runs between the cards so it reads as one sequence: horizontal on
   desktop, vertical once they stack. */
.es-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.4rem 1.1rem;
}

.es-step {
  position: relative;
  padding: 1.5rem 1rem 1rem;
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(255, 122, 33, 0.07), rgba(var(--tint), 0.025) 55%);
  border: 1px solid var(--edge-t09);
}

.es-step::after {
  content: '';
  position: absolute;
  top: 50%;
  right: -1.1rem;
  width: 1.1rem;
  height: 2px;
  background: linear-gradient(90deg, rgba(255, 122, 33, 0.55), rgba(255, 122, 33, 0.12));
}

.es-step:last-child::after {
  display: none;
}

.es-step-badge {
  position: absolute;
  top: -1.05rem;
  left: 1rem;
  display: inline-grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 14px;
  background: linear-gradient(160deg, #ff9d4d, #ff7a21);
  color: var(--bg);
  box-shadow: 0 8px 22px rgba(255, 122, 33, 0.4);
}

.es-step-icon {
  width: 1.3rem;
  height: 1.3rem;
  stroke-width: 2;
}

.es-step-num {
  position: absolute;
  top: -0.35rem;
  right: -0.35rem;
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  border-radius: 999px;
  background: var(--bg);
  color: var(--accent-ink);
  font-size: 0.66rem;
  font-weight: 900;
  border: 1px solid var(--cedge-orange-14);
}

.es-step strong {
  display: block;
  margin: 0.6rem 0 0.35rem;
  font-size: 0.97rem;
  color: var(--text);
}

.es-step p {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.55;
  color: var(--mute-t62);
}

/* ---- customer preview + example ---- */
.es-split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(305px, 1fr));
  gap: 1.1rem;
}

.es-phone {
  padding: 1rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t12);
  background: linear-gradient(180deg, rgba(var(--tint), 0.05), rgba(3, 10, 18, 0.6));
}

.es-phone-from {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 0.6rem;
  font-size: 0.78rem;
  font-weight: 800;
  color: rgba(var(--tint), 0.7);
}

.es-phone-avatar {
  display: grid;
  place-items: center;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 8px;
  background: linear-gradient(160deg, #ff9d4d, #ff7a21);
  color: var(--bg);
  font-weight: 900;
  font-size: 0.8rem;
}

.es-phone-bubble {
  margin: 0 0 0.55rem;
  padding: 0.75rem 0.85rem;
  border-radius: 14px 14px 14px 4px;
  background: rgba(var(--tint), 0.1);
  font-size: 0.92rem;
  line-height: 1.45;
  color: var(--text);
}

.es-phone-sub {
  margin: 0 0 0.75rem;
  font-size: 0.8rem;
  color: var(--mute-t55);
}

.es-phone-choice {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin: 0 0 0.5rem;
  padding: 0.68rem 0.8rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t13);
  font-size: 0.87rem;
  font-weight: 800;
  color: var(--ink-neutral-2);
}

.es-phone-choice small {
  margin-left: auto;
  font-size: 0.71rem;
  font-weight: 600;
  color: var(--mute-t50);
}

.es-phone-choice.primary {
  border-color: var(--cedge-orange-14);
  background: linear-gradient(180deg, rgba(255, 122, 33, 0.22), rgba(255, 122, 33, 0.08));
  box-shadow: 0 6px 18px rgba(255, 122, 33, 0.16);
}

.es-phone-foot {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.7rem 0 0;
  font-size: 0.73rem;
  color: var(--mute-t45);
}

.es-phone-foot svg {
  color: var(--good);
}

.es-example {
  padding: 1rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t12);
  background: rgba(3, 10, 18, 0.5);
}

/* The same slab .es-earnings had, missed ten lines up the file. A 50%-opaque
   near-black over the white sheet composites to mid-grey — measured on paper,
   the example card's own text landed at 1.47:1 ("6:30 – 7:15 PM"), 2.13:1 and
   2.30:1, and the whole card read as a disabled panel rather than an example.
   Neutral paper here, not .es-earnings' warm tint: that block is the orange
   money callout, this is a plain worked example. */
:root[data-theme='light'] .es-example {
  border-color: var(--edge-t12);
  background: #f4f7fb;
}

.es-example-job {
  margin: 0 0 0.7rem;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--text);
}

.es-example-facts {
  list-style: none;
  margin: 0 0 0.9rem;
  padding: 0;
  display: grid;
  gap: 0.4rem;
  font-size: 0.85rem;
  color: rgba(var(--tint), 0.66);
}

.es-example-facts li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.es-example-facts svg {
  color: var(--accent-ink);
  width: 1.05rem;
  height: 1.05rem;
}

.es-example-offer-box {
  padding: 0.85rem;
  border-radius: 12px;
  border: 1px solid var(--cedge-orange-7);
  background: rgba(255, 122, 33, 0.09);
}

.es-example-label {
  margin: 0;
  font-size: 0.63rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-t50);
}

.es-example-offer {
  margin: 0.25rem 0 0.35rem;
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--ink-orange-6);
}

.es-example-fee {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  margin: 0;
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--text);
}

.es-example-fee span {
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--mute-t55);
}

.es-example-note {
  margin: 0.7rem 0 0;
  font-size: 0.77rem;
  color: var(--mute-t45);
}

/* ---- benefits ---- */
/* 215px lands three across in this column, so five cards read as a balanced
   3 + 2 rather than 4 + 1 with a stranded last card. Roomier than cramming all
   five into one row at ~150px each. */
.es-benefits {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 0.85rem;
}

.es-benefit {
  padding: 1rem;
  border-radius: 14px;
  background: rgba(var(--tint), 0.03);
  border: 1px solid var(--edge-t08);
  transition: transform 0.16s ease, border-color 0.16s ease;
}

.es-benefit:hover {
  transform: translateY(-2px);
  border-color: var(--edge-t18);
}

.es-benefit-icon {
  display: grid;
  place-items: center;
  width: 2.3rem;
  height: 2.3rem;
  border-radius: 12px;
  background: rgba(var(--tint), 0.07);
  color: var(--ink-neutral-2);
}

.es-benefit-icon svg {
  width: 1.25rem;
  height: 1.25rem;
}

/* One accent per benefit so the row reads as five distinct reasons, not a wall. */
.es-benefit[data-tone="money"] .es-benefit-icon {
  background: rgba(74, 222, 128, 0.15);
  color: var(--ink-green-3);
}

.es-benefit[data-tone="time"] .es-benefit-icon {
  background: rgba(56, 189, 248, 0.15);
  color: var(--ink-sky-1);
}

.es-benefit[data-tone="route"] .es-benefit-icon {
  background: rgba(255, 122, 33, 0.17);
  color: var(--accent-ink);
}

.es-benefit[data-tone="safe"] .es-benefit-icon {
  background: rgba(167, 139, 250, 0.16);
  color: var(--ink-violet-4);
}

.es-benefit[data-tone="lead"] .es-benefit-icon {
  background: rgba(255, 209, 102, 0.15);
  color: var(--gold-ink);
}

.es-benefit strong {
  display: block;
  margin: 0.6rem 0 0.35rem;
  font-size: 0.92rem;
  color: var(--text);
}

.es-benefit p {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--mute-t62);
}

/* ---- setup checklist ---- */
.es-getstarted {
  border-color: var(--cedge-orange-11);
  background: linear-gradient(180deg, rgba(255, 122, 33, 0.07), rgba(var(--tint), 0.02) 60%);
}

.es-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.es-checklist li {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  flex-wrap: wrap;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t09);
  background: rgba(var(--tint), 0.03);
}

.es-checklist li.done {
  border-color: var(--cedge-green-31);
  background: rgba(74, 222, 128, 0.05);
}

.es-check {
  flex: none;
  display: grid;
  place-items: center;
  width: 1.55rem;
  height: 1.55rem;
  border-radius: 999px;
  border: 1px solid var(--edge-t22);
  color: var(--bg);
  font-weight: 900;
  font-size: 0.82rem;
}

.es-checklist li.done .es-check {
  background: var(--good);
  border-color: var(--good);
}

.es-check-copy {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 0.14rem;
}

.es-check-copy strong {
  font-size: 0.9rem;
  color: var(--ink-neutral-2);
}

.es-check-copy small {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.es-check-state {
  font-size: 0.74rem;
  font-weight: 800;
  color: var(--good);
}

@media (max-width: 900px) {
  .es-hero {
    grid-template-columns: minmax(0, 1fr);
  }

  /* Stacked: the connector turns vertical so the sequence still reads. */
  .es-step::after {
    top: auto;
    right: auto;
    bottom: -1.25rem;
    left: 2.25rem;
    width: 2px;
    height: 1.25rem;
    background: linear-gradient(180deg, rgba(255, 122, 33, 0.55), rgba(255, 122, 33, 0.12));
  }
}

@media (prefers-reduced-motion: reduce) {

  .es-cta-btn,
  .es-benefit {
    transition: none;
  }

  .es-cta-btn:hover,
  .es-benefit:hover {
    transform: none;
  }
}

/* ---- Smart Intake: estimate strategy & alerts (section 3) ------------- */
.intake-ai-lead {
  margin: 0 0 1rem;
}

.intake-summary {
  padding: .9rem 1rem;
  margin-bottom: 1.1rem;
  border-radius: 12px;
  border: 1px solid var(--cedge-green-32);
  background: rgba(74, 222, 128, .06);
}

.intake-summary>strong {
  display: block;
  margin-bottom: .5rem;
  font-size: .92rem;
  color: var(--good);
}

.intake-summary ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: .35rem;
}

.intake-summary li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: .8rem;
  font-size: .85rem;
  color: rgba(var(--tint), .72);
}

.intake-summary a {
  flex: none;
  font-size: .78rem;
  font-weight: 800;
  color: var(--ink-sky-1);
}

.intake-block {
  padding: 1rem 0;
  border-top: 1px solid var(--rule-t07);
}

.intake-block:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.intake-block-head {
  margin-bottom: .7rem;
}

.intake-block-head strong {
  display: block;
  font-size: .95rem;
  color: var(--ink-neutral-2);
}

.intake-block-head small {
  display: block;
  margin-top: .15rem;
  font-size: .8rem;
  line-height: 1.45;
  color: var(--mute-t52);
}

.posture-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(175px, 1fr));
  gap: .65rem;
}

.posture-card {
  display: grid;
  gap: .3rem;
  text-align: left;
  cursor: pointer;
  padding: .85rem .9rem;
  border-radius: 12px;
  color: inherit;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), .03);
  transition: border-color .16s ease, background .16s ease;
}

.posture-card:hover {
  border-color: var(--edge-t26);
}

.posture-card.on {
  border-color: var(--cedge-orange-14);
  background: rgba(255, 122, 33, .1);
}

.posture-card-mark {
  width: 1rem;
  height: 1rem;
  border-radius: 999px;
  border: 2px solid var(--edge-t30);
}

.posture-card.on .posture-card-mark {
  border-color: #ff7a21;
  box-shadow: inset 0 0 0 3.5px #ff7a21;
}

.posture-card strong {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .9rem;
  color: #fff;
}

.posture-card em {
  font-style: normal;
  padding: .08rem .38rem;
  border-radius: 999px;
  font-size: .58rem;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  background: rgba(255, 122, 33, .18);
  border: 1px solid var(--cedge-orange-51);
  color: var(--accent-ink);
}

.posture-card small {
  font-size: .78rem;
  line-height: 1.45;
  color: var(--mute-t58);
}

.posture-card:focus-visible {
  outline: 2px solid rgba(56, 189, 248, .75);
  outline-offset: 2px;
}

.intake-amount {
  display: flex;
  align-items: center;
  gap: .5rem;
  max-width: 15rem;
}

.intake-amount span {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--mute-t60);
}

.intake-amount input {
  flex: 1;
  font-size: 1.05rem;
  font-weight: 700;
}

.intake-toggle {
  display: flex;
  align-items: flex-start;
  gap: .7rem;
  padding: .6rem 0;
  cursor: pointer;
}

.intake-toggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.intake-toggle-track {
  flex: none;
  margin-top: .1rem;
  position: relative;
  width: 2.6rem;
  height: 1.5rem;
  border-radius: 999px;
  background: rgba(var(--tint), .12);
  border: 1px solid var(--edge-t18);
  transition: background .16s ease;
}

.intake-toggle-track>span {
  position: absolute;
  top: .16rem;
  left: .18rem;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 999px;
  background: #cbd5e1;
  transition: transform .16s ease, background .16s ease;
}

.intake-toggle input:checked+.intake-toggle-track {
  background: rgba(52, 211, 153, .4);
  border-color: var(--cedge-green-2);
}

.intake-toggle input:checked+.intake-toggle-track>span {
  transform: translateX(1.05rem);
  background: var(--good);
}

.intake-toggle input:focus-visible+.intake-toggle-track {
  box-shadow: 0 0 0 3px rgba(56, 189, 248, .45);
}

.intake-toggle-copy strong {
  display: block;
  font-size: .9rem;
  color: var(--ink-neutral-2);
}

.intake-toggle-copy small {
  display: block;
  margin-top: .1rem;
  font-size: .79rem;
  line-height: 1.45;
  color: var(--mute-t52);
}

.intake-field {
  display: grid;
  gap: .25rem;
  margin: .2rem 0 .6rem 3.3rem;
  max-width: 18rem;
}

.intake-field span {
  font-size: .82rem;
  color: var(--mute-t62);
}

.intake-savebar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: 1.1rem;
  padding-top: .9rem;
  border-top: 1px solid var(--rule-t08);
}

.intake-savebar p {
  margin: 0;
  font-size: .83rem;
  color: var(--dim-amber-1-20);
}

.intake-save-ok {
  color: var(--good);
  font-weight: 700;
}

.intake-save-error {
  color: var(--bad);
  font-weight: 700;
}

/* Sticks to the bottom only while there's something to save. */
.intake-savebar.stuck {
  position: sticky;
  bottom: 0;
  z-index: 5;
  margin: 1.1rem -1.05rem -1.05rem;
  padding: .8rem 1.05rem;
  border-radius: 0 0 12px 12px;
  background: rgba(var(--panel-rgb), .96);
  border-top: 1px solid var(--cedge-amber-31);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

@media (prefers-reduced-motion: reduce) {

  .posture-card,
  .intake-toggle-track,
  .intake-toggle-track>span {
    transition: none;
  }
}

/* ---------------------------------------------------------------------------
   Folded workspace panels
   A page that carries several configure-once surfaces (schedule: time off,
   booking link, booking availability) shows them as a short stack of named
   rows. Open one and its neighbours fold, so only one form is ever on screen.
--------------------------------------------------------------------------- */

.schedule-setup {
  display: grid;
  gap: 0.6rem;
}

.schedule-setup-head {
  margin-bottom: 0.15rem;
}

.schedule-setup-head .eyebrow {
  margin: 0 0 0.3rem;
}

.schedule-setup-head h2 {
  margin: 0;
  font-size: 1.28rem;
  letter-spacing: -0.01em;
}

.schedule-setup-head p {
  margin: 0.3rem 0 0;
  color: var(--muted, var(--muted-2));
  font-size: 0.88rem;
}

.workspace-disclosure {
  background: var(--bg-elevated);
  border: 1px solid var(--edge-g14);
  border-radius: 16px;
  overflow: hidden;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.workspace-disclosure:hover {
  border-color: var(--edge-g24);
}

.workspace-disclosure[open] {
  background: rgba(10, 22, 37, 0.92);
  border-color: var(--cedge-orange-52);
}

.workspace-disclosure-head {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.05rem 1.3rem;
  cursor: pointer;
  list-style: none;
  -webkit-user-select: none;
  user-select: none;
}

.workspace-disclosure-head::-webkit-details-marker {
  display: none;
}

.workspace-disclosure-head:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: -2px;
}

.workspace-disclosure-copy {
  display: grid;
  gap: 0.22rem;
  min-width: 0;
  flex: 1;
}

.workspace-disclosure-eyebrow {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim-orange-3-2);
}

.workspace-disclosure-title {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  font-size: 1.05rem;
  font-weight: 650;
  color: var(--text, #e8eef6);
  letter-spacing: -0.01em;
}

.workspace-disclosure-pill {
  font-size: 0.7rem;
  font-weight: 650;
  letter-spacing: 0.02em;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--edge-g24);
  color: var(--muted, var(--muted-2));
  white-space: nowrap;
}

.workspace-disclosure-pill.tone-on {
  border-color: var(--cedge-green-33);
  background: rgba(52, 199, 123, 0.12);
  color: var(--ink-green-2);
}

.workspace-disclosure-pill.tone-warn {
  border-color: var(--cedge-orange-53);
  background: rgba(255, 176, 32, 0.1);
  color: var(--ink-amber-1);
}

/* Readable while folded — this is what makes the closed state useful rather
   than just hidden. Clamped so a long line can't turn the row into a
   paragraph. */
.workspace-disclosure-summary {
  font-size: 0.86rem;
  line-height: 1.45;
  color: var(--muted, var(--muted-2));
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.workspace-disclosure-chevron {
  flex: none;
  width: 1.9rem;
  height: 1.9rem;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--edge-g20);
  color: var(--muted, var(--muted-2));
  transition: transform 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.workspace-disclosure-chevron svg {
  width: 1rem;
  height: 1rem;
}

.workspace-disclosure[open] .workspace-disclosure-chevron {
  transform: rotate(180deg);
  color: var(--ink-orange-8);
  border-color: var(--cedge-orange-38);
}

.workspace-disclosure-body {
  padding: 0.35rem 1.3rem 1.35rem;
  border-top: 1px solid var(--rule-g10);
  margin-top: -0.1rem;
  padding-top: 1.2rem;
}

@media (prefers-reduced-motion: reduce) {

  .workspace-disclosure,
  .workspace-disclosure-chevron {
    transition: none;
  }
}

/* ---------------------------------------------------------------------------
   Schedule map, now below the calendar
--------------------------------------------------------------------------- */

/* ---------------------------------------------------------------------------
   The schedule workbench: calendar + a rail of everything you drag from
--------------------------------------------------------------------------- */

/* Single column by default — this is the phone, and three surfaces cannot share
   a phone screen. Two columns only once there is genuinely room for a 7-column
   grid AND a readable rail beside it. */
/* QUEUE, CALENDAR, OPEN JOB — left to right.
   The page put the calendar first with the queue in a rail beside it, and every
   card in that rail carried its own inline scheduling form. Most of the CSS
   that used to live here existed to make that form survive a 21rem column:
   unfloating its popovers so an overflow ancestor could not clip them,
   collapsing its three-column grid to one, un-capping the rail's height while a
   picker was open so the Save button was reachable, and stopping the rows being
   flattened to 57px by the flex container they were trapped in. All of it goes
   with the form. The list is a list again.

   THREE COLUMNS ONLY WHERE THERE IS ROOM FOR THREE. Below 1440 the detail is an
   overlay instead — see .sched-detail.is-sheet — because a third column carved
   out of 1280px leaves a calendar narrower than the rail beside it, which is
   the shape this layout exists to avoid. */
/* Sticky while it fits, then naturally part of the page scroll when it does
   not. The old viewport cap put a second scrollbar inside this rail; removing
   it leaves the document as the only vertical scroll surface. */
@media (min-width: 1024px) {
  .sched-queue-col {
    position: sticky;
    top: 1rem;
    display: flex;
    flex-direction: column;
    padding: 0.9rem 0.85rem;
  }

  .sched-queue-col .workspace-section-heading {
    margin-bottom: 0.6rem;
  }

  .sched-queue-col .workspace-section-heading h2 {
    font-size: 1.15rem;
    letter-spacing: -0.01em;
  }

  /* min-height keeps an empty rail useful without turning it into a scroller. */
  .sched-queue-col .sched-rows {
    flex: 1 1 auto;
    min-height: 6rem;
  }

  /* A column flex container makes its children shrinkable by default. */
  .sched-queue-col .sched-rows>* {
    flex: 0 0 auto;
  }
}

.sched-rows {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sched-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 0.6rem 0.65rem;
  padding: 0.75rem 0.8rem;
  border: 1px solid var(--edge-t10);
  border-left: 3px solid var(--cap-open);
  border-radius: 12px;
  background: rgba(var(--tint), 0.03);
}

.sched-row .schedule-drag-handle {
  grid-column: 1;
  grid-row: 1;
  margin-top: 0.1rem;
}

/* Approval state is a word on the row as well — see .sched-row-flag. The edge
   is the same hue the calendar gives an unapproved chip, so a row and its
   future chip agree, but a hue is not a sentence. */
.sched-row.is-unapproved {
  border-left-color: var(--cap-busy);
}

.sched-row.is-on {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.1);
}

/* The whole row is the control. */
.sched-row-open {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  gap: 0.25rem;
  min-width: 0;
  min-height: 44px;
  padding: 0.1rem 0;
  border: 0;
  background: none;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.sched-row-open:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 8px;
}

.sched-row-top {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.sched-row-top strong {
  font-size: 0.9rem;
  font-weight: 750;
  word-break: break-word;
}

.sched-row-flag {
  padding: 0.08rem 0.42rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.12);
  color: var(--mute-i62);
  font-size: 0.64rem;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  white-space: nowrap;
}

.sched-row-what {
  color: var(--mute-i56);
  font-size: 0.76rem;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-row-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.15rem 0.5rem;
  font-size: 0.72rem;
  color: var(--mute-i62);
}

.sched-row-facts>span+span::before {
  content: '\00b7 ';
}

/* A missing duration is why a day can read as empty when it is not, and a job
   with no crew is a job nobody has been told about. Both are named rather than
   left blank, and dimmer than the facts that ARE known. */
/* 3.82:1 at 12px, on a line that exists to warn you the hours are unknowable.
   Not italic-and-faint: it is the row's most consequential fact. */
.sched-row-missing {
  color: var(--mute-i62);
  font-style: italic;
}

.sched-row-state {
  color: var(--gold-ink);
  font-size: 0.7rem;
  font-weight: 700;
}

.sched-row-go,
.sched-row-actions {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  align-items: center;
  width: 100%;
  margin-top: 0.2rem;
}

.sched-row-actions>* {
  flex: 1 1 calc(50% - 0.25rem);
  min-width: 0;
  justify-content: center;
  text-align: center;
}

.sched-row>.sched-row-go {
  width: 100%;
  justify-content: center;
  text-align: center;
}

.sched-row-go {
  min-height: 44px;
  padding: 0 0.75rem;
  font-size: 0.82rem;
  white-space: nowrap;
}

/* Came in today. Gold rather than grey: the queue is ordered by readiness
   rather than by age, so this is the only thing saying a row is new. */
.sched-row-new {
  padding: 0.08rem 0.42rem;
  border-radius: 999px;
  background: rgba(255, 209, 102, 0.14);
  color: var(--gold-ink);
  font-size: 0.64rem;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* WHAT THE JOB IS SHORT OF. Chips rather than the three greyed-out facts these
   replaced — an absence rendered as dimmer text reads as unimportant, which is
   the opposite of true for a job with no duration on a calendar that measures
   how full a day is. */
.sched-row-blockers {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: 0.1rem;
}

.sched-row-blocker {
  padding: 0.08rem 0.4rem;
  border: 1px solid var(--edge-t16);
  border-radius: 6px;
  background: rgba(var(--tint), 0.05);
  color: var(--mute-i62);
  font-size: 0.65rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.sched-row-tentative {
  min-height: 44px;
  padding: 0 0.6rem;
  font-size: 0.76rem;
  white-space: nowrap;
}

/* The outstanding list under the confirmation. Quiet, because none of it blocks
   the save — a job can be scheduled before you know the crew or the duration,
   and styling these as errors would say otherwise. */
.sched-confirm-todo {
  margin-top: 0.5rem;
}

.sched-confirm-todo-head {
  margin: 0 0 0.2rem;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-i62);
}

.sched-confirm-todo ul {
  margin: 0;
  padding-left: 1rem;
  display: grid;
  gap: 0.15rem;
}

.sched-confirm-todo li {
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--mute-i56);
}

.sched-confirm-todo a {
  color: var(--dim-orange-3-6);
}

.sched-rows-foot {
  margin: 0.6rem 0 0;
  font-size: 0.8rem;
}

.sched-rows-foot a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--dim-orange-3-6);
  text-decoration: none;
}

.sched-rows-foot a:hover {
  text-decoration: underline;
}

/* ---- the job you have open ----------------------------------------------- */
/**
 * THIS PANEL HAD NO BACKGROUND AT ALL, and that is the whole of the
 * "the drawer is see-through" report.
 *
 * It said `background: var(--panel)`. There is no `--panel` token in this
 * stylesheet — only `--panel-rgb`. The name is defined in three places
 * (feature-wheel-story.css, command-center-deck.css, flagship.module.css) and
 * every one of them is scoped to a marketing component that never renders on
 * /dashboard. So on the schedule page the substitution was invalid, the
 * declaration computed to `unset`, and the drawer painted transparent over the
 * calendar — which is why the calendar's dates and the panel's own text were
 * landing on the same pixels.
 *
 * rgb(var(--panel-rgb)) is the token that actually exists here, taken at full
 * opacity. Not var(--bg-elevated): that is rgba(...,0.86) and a 14%-transparent
 * drawer over a dense month grid is the same bug with a smaller number.
 */
.sched-detail {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.9rem 0.85rem;
  border: 1px solid var(--edge-t12);
  border-radius: 16px;
  background: rgb(var(--panel-rgb));
}

@media (min-width: 1600px) {
  .sched-detail {
    position: sticky;
    top: 1rem;
    max-height: calc(100vh - 2rem);
    overflow-y: auto;
  }
}

/* The docked column keeps its place rather than collapsing — a third of the
   width appearing and disappearing as you click around the queue is worse than
   a column that says what it is for. */
.sched-detail.is-empty {
  justify-content: center;
  min-height: 12rem;
}

.sched-detail-hint {
  display: grid;
  gap: 0.25rem;
  margin: 0;
  text-align: center;
}

.sched-detail-hint strong {
  font-size: 0.95rem;
}

.sched-detail-hint span {
  color: var(--mute-i56);
  font-size: 0.8rem;
  line-height: 1.45;
}

/* Below 1440 it is an overlay: a right-hand drawer where there is room, a
   bottom sheet on a phone. Fixed, so it escapes the sticky column's overflow. */
.sched-detail-scrim {
  position: fixed;
  inset: 0;
  z-index: 60;
  background: rgba(0, 0, 0, 0.45);
}

.sched-detail.is-sheet {
  position: fixed;
  z-index: 61;
  inset: auto 0 0 0;
  max-height: 88vh;
  overflow-y: auto;
  border-radius: 18px 18px 0 0;
  box-shadow: 0 -18px 48px rgba(0, 0, 0, 0.42);
}

@media (min-width: 720px) {
  .sched-detail.is-sheet {
    inset: 0 0 0 auto;
    /* A STABLE 440-520px, not a percentage of the viewport.
       min(26rem, 92vw) was 416px at best and shrank with the window, so the
       crew list and the slot rows reflowed while you were reading them. The
       clamp holds the panel still between 440 and 520; the outer min() is only
       the small-screen backstop, and below 720 this rule does not apply at
       all. */
    width: min(92vw, clamp(440px, 34vw, 520px));
    max-height: none;
    border-radius: 18px 0 0 18px;
    box-shadow: -18px 0 48px rgba(0, 0, 0, 0.42);
  }
}

/**
 * The header and the commit button stay put while the middle scrolls.
 *
 * The panel is one long scroll — suggestions, a manual picker, a crew list,
 * then the confirmation — and both ends were scrolling away with it: on a
 * short window you could not see whose job you were scheduling, and "Schedule
 * job" was below the fold of a panel you had to scroll to the bottom of twice.
 *
 * Opaque backgrounds on both, for the same reason the panel itself needed one:
 * a sticky element with a transparent background has the scrolling content
 * pass through it.
 */
.sched-detail.is-sheet .sched-detail-head {
  position: sticky;
  top: 0;
  z-index: 2;
  padding-bottom: 0.6rem;
  background: rgb(var(--panel-rgb));
  border-bottom: 1px solid var(--edge-t08);
}

.sched-detail.is-sheet .sched-step-confirm {
  position: sticky;
  bottom: 0;
  z-index: 2;
  margin-top: auto;
  padding-top: 0.75rem;
  padding-bottom: 0.2rem;
  background: rgb(var(--panel-rgb));
  border-top: 1px solid var(--edge-t08);
}

@media (min-width: 1600px) {

  /* The docked column scrolls too — see the sticky/max-height rule above — so
     it needs the same two anchors. */
  .sched-detail .sched-detail-head {
    position: sticky;
    top: 0;
    z-index: 2;
    padding-bottom: 0.6rem;
    background: rgb(var(--panel-rgb));
  }

  .sched-detail .sched-step-confirm {
    position: sticky;
    bottom: 0;
    z-index: 2;
    padding-top: 0.75rem;
    background: rgb(var(--panel-rgb));
    border-top: 1px solid var(--edge-t08);
  }
}

.sched-detail-head {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
}

.sched-detail-head h2 {
  margin: 0.1rem 0 0;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
}

.sched-detail-sub {
  margin: 0.15rem 0 0;
  color: var(--mute-i56);
  font-size: 0.8rem;
  line-height: 1.35;
}

.sched-detail-close {
  margin-left: auto;
  min-width: 44px;
  min-height: 44px;
  border: 1px solid var(--edge-t16);
  border-radius: 12px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.sched-detail-close:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-detail-facts {
  display: grid;
  gap: 0.4rem;
  margin: 0;
}

.sched-detail-facts>div {
  display: grid;
  grid-template-columns: 5.5rem minmax(0, 1fr);
  gap: 0.5rem;
}

.sched-detail-facts dt {
  color: var(--mute-i62);
  font-size: 0.75rem;
}

.sched-detail-facts dd {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.35;
}

/* THE DURATION, EDITED IN PLACE. It used to be a link to the job page, which
   is a round trip through another screen for one number — and it came back to
   a queue that had lost your place. */
.sched-duration {
  display: inline-flex;
  align-items: baseline;
  gap: 0.3rem;
  flex-wrap: wrap;
}

.sched-duration-input {
  width: 4.2rem;
  /* 44px, because it is a real control in a panel that is used on a phone. */
  min-height: 44px;
  padding: 0 0.45rem;
  border: 1px solid var(--edge-t16);
  border-radius: 8px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font: inherit;
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
}

.sched-duration-input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.sched-duration-unit {
  color: var(--mute-i62);
  font-size: 0.75rem;
}

.sched-duration-note {
  flex-basis: 100%;
  font-size: 0.72rem;
  color: var(--mute-i62);
}

.sched-duration-note.is-error {
  color: #f8a5a5;
}

/* ---- the three steps ------------------------------------------------------ */
.sched-step {
  display: grid;
  gap: 0.5rem;
  padding-top: 0.65rem;
  border-top: 1px solid var(--edge-t10);
}

.sched-step h3 {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  color: var(--mute-i62);
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.sched-step h3 i {
  display: grid;
  place-items: center;
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 50%;
  background: rgba(var(--tint), 0.12);
  color: var(--text);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 850;
}

.sched-step-note {
  margin: 0;
  color: var(--mute-i56);
  font-size: 0.74rem;
  line-height: 1.4;
}

.sched-step-empty {
  margin: 0;
  color: var(--mute-i56);
  font-size: 0.8rem;
}

/* Which of you picks the time — the question that used to be two buttons of
   equal weight on every card in the list. */
.sched-mode {
  display: inline-flex;
  padding: 0.2rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
}

.sched-mode-btn {
  flex: 1;
  min-height: 44px;
  padding: 0 0.7rem;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--mute-t60);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 750;
  cursor: pointer;
}

.sched-mode-btn.is-on {
  background: var(--accent);
  color: var(--on-accent);
  font-weight: 850;
}

.sched-mode-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Days that actually have room, with the reason attached. */
.sched-slots {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sched-slot {
  display: grid;
  gap: 0.15rem;
  width: 100%;
  min-height: 48px;
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--edge-t12);
  border-radius: 11px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.sched-slot.is-on {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.12);
}

.sched-slot:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-slot-when {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
}

.sched-slot-when strong {
  font-size: 0.86rem;
  font-weight: 750;
}

.sched-slot-when em {
  color: var(--accent-ink);
  font-style: normal;
  font-size: 0.82rem;
  font-weight: 700;
}

.sched-slot-why {
  color: var(--mute-i56);
  font-size: 0.72rem;
  line-height: 1.3;
}

.sched-slots-none {
  margin: 0;
  color: var(--mute-i56);
  font-size: 0.78rem;
  line-height: 1.45;
}

.sched-manual>summary {
  display: flex;
  align-items: center;
  min-height: 44px;
  color: var(--dim-orange-3-6);
  font-size: 0.8rem;
  font-weight: 650;
  cursor: pointer;
}

.sched-manual-grid {
  display: grid;
  gap: 0.45rem;
  margin-top: 0.3rem;
}

/* ROLE FILTER, shown only when there is more than one role to filter by. */
.sched-crew-roles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  margin-bottom: 0.5rem;
}

.sched-crew-role {
  min-height: 44px;
  padding: 0 0.6rem;
  border: 1px solid var(--edge-t16);
  border-radius: 999px;
  background: transparent;
  color: var(--mute-i56);
  font: inherit;
  font-size: 0.74rem;
  font-weight: 700;
  cursor: pointer;
}

.sched-crew-role:hover {
  color: var(--text);
  border-color: var(--edge-t22);
}

/* The chosen one is marked by fill AND weight, not by hue alone. */
.sched-crew-role.is-on {
  border-color: var(--cedge-orange-5);
  background: rgba(255, 122, 33, 0.12);
  color: var(--ink-orange-12);
  font-weight: 800;
}

.sched-crew-role:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Already booked elsewhere that day. A WARNING, NOT A BLOCK — doubling
   somebody up is sometimes right, so this states the fact and leaves the
   decision alone. Gold rather than red for the same reason. */
.sched-crew-clash {
  color: var(--gold-ink);
  font-style: normal;
  font-weight: 700;
}

.sched-crew-option.has-clash {
  background: rgba(255, 209, 102, 0.05);
}

.sched-crew-list {
  display: grid;
  gap: 0.25rem;
}

.sched-crew-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.25rem 0.4rem;
  border-radius: 10px;
  cursor: pointer;
}

.sched-crew-option:hover {
  background: rgba(var(--tint), 0.05);
}

.sched-crew-option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.sched-crew-check {
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  border: 1px solid var(--edge-t22);
  border-radius: 6px;
  color: transparent;
  font-size: 0.72rem;
  font-weight: 900;
}

.sched-crew-option input:checked~.sched-crew-check {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--on-accent);
}

.sched-crew-option input:focus-visible~.sched-crew-check {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-crew-copy {
  display: grid;
  gap: 0.02rem;
}

.sched-crew-copy strong {
  font-size: 0.82rem;
  font-weight: 700;
}

.sched-crew-copy small {
  color: var(--mute-i56);
  font-size: 0.7rem;
}

/* Assigning somebody texts them, so it is a choice and not a side effect.
   Shown only when there is somebody to notify. */
.sched-notify {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.25rem 0.4rem;
  border-radius: 10px;
  color: var(--mute-i62);
  font-size: 0.78rem;
  cursor: pointer;
}

.sched-notify input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.sched-notify input:checked~.sched-crew-check {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--on-accent);
}

.sched-notify input:focus-visible~.sched-crew-check {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-step-confirm {
  padding-bottom: 0.3rem;
}

.sched-confirm-line {
  display: grid;
  gap: 0.12rem;
  margin: 0;
}

.sched-confirm-line strong {
  font-size: 0.88rem;
}

.sched-confirm-line span {
  color: var(--mute-i56);
  font-size: 0.76rem;
  line-height: 1.4;
}

.sched-confirm-go {
  width: 100%;
  min-height: 46px;
  margin-top: 0.15rem;
}

.sched-confirm-go:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sched-ask-form {
  display: grid;
  gap: 0.6rem;
}

/* THE AVAILABILITY STRIP WAS BUILT FOR A FULL-WIDTH CARD, and this panel is
   340-400px. Measured docked at 1920: four day-cards side by side at ~90px
   each, their city pills and "+ Add" buttons clipped, and the three option
   slots below them squeezed to nothing.
   One column here — the strip is a list of days you scroll, which is what it
   is on a phone too, so this is the shape it already knows how to be. */
.sched-detail .client-schedule-calendar-grid { grid-template-columns: minmax(0, 1fr); }
.sched-detail .client-schedule-selected-list { grid-template-columns: minmax(0, 1fr); }


.schedule-map {
  margin-bottom: 0;
}

/* ---- the map, on request --------------------------------------------------
   Open by default it was the single largest thing left on this page once the
   settings moved off — a Google map, its script, its tiles and its markers,
   under a calendar somebody came here to read. Closed, nothing is mounted: not
   hidden with CSS, absent from the tree. The gear stays reachable in both
   states, or there would be no way back. */
.sched-map-shut {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.sched-map-open {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 44px;
}

.sched-map-open-wrap {
  display: grid;
  gap: 0.6rem;
}

.sched-map-open-wrap[data-pending] {
  opacity: 0.6;
}

/* space-between, not a margin on the last child: the gear is the only thing to
   the right of the tabs now that Hide (which carried the `margin-left: auto`)
   is gone. */
.sched-map-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

/* Map and List are two readings of the same month, so they are tabs rather
   than a map with a list bolted under it. */
.sched-map-tabs {
  display: inline-flex;
  padding: 0.2rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
}

.sched-map-tab {
  min-height: 44px;
  padding: 0 0.95rem;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--mute-t60);
  font: inherit;
  font-size: 0.86rem;
  font-weight: 750;
  cursor: pointer;
}

/* Selected is a fill AND a weight change, never the fill alone. */
.sched-map-tab.is-on {
  background: var(--accent);
  color: var(--on-accent);
  font-weight: 850;
}

.sched-map-tab:focus-visible,
.sched-map-open:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ---- the same month as rows ---------------------------------------------- */
.sched-map-sort {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
  color: var(--mute-i62);
  font-size: 0.8rem;
}

.sched-map-sort select {
  min-height: 44px;
  padding: 0 0.6rem;
  border: 1px solid var(--edge-t16);
  border-radius: 10px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font: inherit;
  font-size: 0.84rem;
}

.sched-map-sort>span {
  margin-left: auto;
}

.sched-map-rows {
  display: grid;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sched-map-row {
  display: grid;
  grid-template-columns: 3.6rem minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 0.7rem;
  min-height: 48px;
  padding: 0.4rem 0.6rem;
  border: 1px solid var(--edge-t10);
  border-radius: 11px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  text-decoration: none;
}

.sched-map-row:hover {
  border-color: var(--cedge-orange-17);
}

.sched-map-row:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-map-row-when {
  color: var(--mute-i62);
  font-size: 0.78rem;
  font-variant-numeric: tabular-nums;
}

.sched-map-row-who {
  display: grid;
  gap: 0.05rem;
  min-width: 0;
}

.sched-map-row-who strong {
  font-size: 0.88rem;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-map-row-who small {
  color: var(--mute-i56);
  font-size: 0.74rem;
}

.sched-map-row-figures {
  display: flex;
  gap: 0.5rem;
  font-size: 0.78rem;
}

.sched-map-row-figures em {
  font-style: normal;
  font-weight: 700;
}

.sched-map-row-figures i {
  font-style: normal;
  color: var(--mute-i56);
}

.sched-map-row-crew {
  display: grid;
  gap: 0.08rem;
  color: var(--mute-i62);
  font-size: 0.76rem;
  font-weight: 700;
}

.schedule-map .pin-map-legend-item:disabled {
  display: none;
}

/* A phone has no room for four columns; the figures and the crew drop under
   the name rather than being squeezed into 40px each. */
@media (max-width: 560px) {
  .sched-map-row {
    grid-template-columns: 3.4rem minmax(0, 1fr);
  }

  .sched-map-row-figures,
  .sched-map-row-crew {
    grid-column: 2;
  }
}

/* ---------------------------------------------------------------------------
   Form density
   These forms were rows of inputs with the label welded to the box above and
   the submit button floating at the left edge under a hint. The column count
   stays as .form-grid sets it (1fr 1fr suits every one of these); what changes
   is the breathing room, and giving .field-hint / .form-actions the styling
   they never had.
--------------------------------------------------------------------------- */

.compact-form {
  gap: 0.95rem 1.05rem;
  align-items: start;
}

.compact-form .field {
  min-width: 0;
}

.compact-form .field-hint {
  font-size: 0.78rem;
  line-height: 1.4;
  color: rgba(var(--grey-5), 0.85);
  margin-top: 0.1rem;
}

.compact-form .form-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 0.6rem;
  margin-top: 0.25rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--rule-g10);
}

/* A checkbox with a paragraph of explanation next to it needs the whole row —
   in one column of a two-column grid the text wrapped every five words. */
.compact-form>.checkbox-row {
  grid-column: 1 / -1;
}

/* A dollar amount or a count in a full-bleed input reads as though it wants a
   sentence. Cap them; the label still spans the column. */
.compact-form .input-narrow {
  max-width: 13rem;
}

/* Named groups, so a long settings form reads as a few decisions rather than
   one undifferentiated run of fields. */
.form-group {
  border: 0;
  border-top: 1px solid var(--rule-g12);
  margin: 0;
  padding: 1.1rem 0 0;
}

.form-group:first-of-type {
  border-top: 0;
  padding-top: 0.25rem;
}

.form-group>legend {
  padding: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dim-orange-3-4);
}

.form-group>.form-grid {
  margin-top: 0.55rem;
}

.booking-form {
  display: grid;
  gap: 1.4rem;
}

/* Divides the shareable link from the rules that govern it inside the one
   Online booking panel — they're the same feature, so this is a seam rather
   than a second card. */
.booking-settings-seam {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  margin: 1.5rem 0 0.6rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(var(--grey-5), 0.9);
}

.booking-settings-seam::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(var(--grey-1), 0.16);
}

.booking-availability-body .workspace-details-copy {
  margin: 0 0 1rem;
}

/* ---------------------------------------------------------------------------
   Schedule header
   Identity, numbers and the primary action on one row; month nav and the view
   switcher on the next; then the grid. Everything explanatory moved below the
   calendar, because a hint you read after looking doesn't need to sit above it.
--------------------------------------------------------------------------- */

.schedule-bar {
  display: flex;
  align-items: center;
  gap: 1rem 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1.1rem;
}

/* Scoped to the bar, not to .schedule-bar-id — the title carries that class
   itself now, and a descendant selector silently stopped matching. */
.schedule-bar .workspace-title {
  flex: none;
  margin: 0;
  font-size: clamp(1.4rem, 2.2vw, 1.85rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
}

/* Takes the slack between the title and the CTA so the button stays pinned
   right on a wide screen and wraps cleanly on a narrow one. */
.schedule-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  flex: 1 1 auto;
  justify-content: flex-end;
}

/* Lit outlines rather than grey boxes: a hairline in cool light with a soft
   halo behind it, so the numbers read as instruments on a dark dash. The icon
   spans both text rows on the left, which costs no extra height — this bar was
   deliberately compressed so the calendar is visible on arrival, and a stacked
   icon would have undone that. */
.sched-stat {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  align-items: center;
  gap: 0 0.55rem;
  padding: 0.45rem 0.85rem;
  border-radius: 14px;
  border: 1px solid var(--cedge-sky-9);
  background: linear-gradient(180deg, rgba(58, 160, 255, 0.08), rgba(58, 160, 255, 0.02));
  box-shadow: 0 0 16px rgba(58, 160, 255, 0.14), inset 0 0 14px rgba(58, 160, 255, 0.05);
  text-decoration: none;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.sched-stat:hover {
  border-color: var(--cedge-sky-10);
  box-shadow: 0 0 22px rgba(58, 160, 255, 0.3), inset 0 0 16px rgba(58, 160, 255, 0.08);
}

.sched-stat-icon {
  grid-row: span 2;
  width: 1.45rem;
  height: 1.45rem;
  color: var(--ink-sky-7);
  filter: drop-shadow(0 0 6px rgba(58, 160, 255, 0.5));
}

.sched-stat strong {
  grid-column: 2;
  font-size: 1.02rem;
  font-weight: 750;
  letter-spacing: -0.01em;
  color: var(--text, #e8eef6);
  line-height: 1.15;
}

.sched-stat small {
  grid-column: 2;
  font-size: 0.66rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--dim-sky-6);
  white-space: nowrap;
}

/* Only lit amber when there's actually something waiting — the one card that
   is asking you to do something shouldn't look like the three that aren't. */
.sched-stat.needs {
  border-color: var(--cedge-orange-54);
  background: linear-gradient(180deg, rgba(255, 176, 32, 0.11), rgba(255, 176, 32, 0.03));
  box-shadow: 0 0 18px rgba(255, 176, 32, 0.2), inset 0 0 14px rgba(255, 176, 32, 0.06);
}

.sched-stat.needs:hover {
  border-color: var(--cedge-orange-55);
  box-shadow: 0 0 24px rgba(255, 176, 32, 0.34), inset 0 0 16px rgba(255, 176, 32, 0.09);
}

.sched-stat.needs strong {
  color: var(--ink-amber-1);
}

.sched-stat.needs small {
  color: var(--dim-amber-4);
}

.sched-stat.needs .sched-stat-icon {
  color: var(--ink-amber-6);
  filter: drop-shadow(0 0 6px rgba(255, 176, 32, 0.55));
}

.schedule-bar-cta {
  flex: none;
  white-space: nowrap;
}

/* ---- Action buttons -------------------------------------------------------
   The squared-off, glyph-led button that started on the job pane's hero and now
   has to look the same wherever it turns up. It lives HERE rather than in
   focus.module.css because it is no longer one pane's furniture — Plan my day
   sits on the schedule bar, and a second copy of these rules would drift from
   the first the moment either got a tweak.

   Shape and type are borrowed from "Skip to quote" on the lead deck: .85rem/800
   over a 13px radius rather than the app's default 999px pill.

   Tone carries meaning and is the only thing a variant changes:
     lead      orange, solid   — open the record this panel is describing
     money-in  green,  solid   — collect money
     money-out red,    hairline— spend money
     plan      purple, solid   — go somewhere that decides your day
   Colour is never the ONLY signal: every one of these is also labelled. */
.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 3.15rem;
  padding: 0.7rem 0.9rem;
  border-radius: 13px;
  border: 1px solid var(--cedge-orange-5);
  background: rgba(255, 122, 33, 0.11);
  color: var(--accent);
  font-size: 0.85rem;
  font-weight: 800;
  white-space: nowrap;
  text-align: center;
  text-decoration: none;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.action-btn:hover {
  border-color: var(--cedge-orange-56);
  background: rgba(255, 122, 33, 0.19);
  box-shadow: 0 10px 24px -12px var(--accent);
  transform: translateY(-1px);
}

.action-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.action-btn--lead {
  border-color: transparent;
  background: linear-gradient(135deg, #ff5a1f 0%, #ff8a3d 100%);
  color: var(--on-accent);
  box-shadow: 0 12px 30px -14px rgba(255, 122, 33, 0.95);
}

.action-btn--lead:hover {
  border-color: transparent;
  background: linear-gradient(135deg, #ff5a1f 0%, #ff9a52 100%);
  box-shadow: 0 16px 36px -14px rgba(255, 122, 33, 1);
}

/* The lead deck's "win" gradient — getting paid is the point of the software,
   so this is the loudest button in any row it appears in. */
.action-btn--money-in {
  border-color: transparent;
  background: linear-gradient(135deg, #2f9e5c 0%, #46c08d 100%);
  color: #fff;
  box-shadow: 0 12px 32px -12px rgba(63, 191, 139, 0.95);
}

.action-btn--money-in:hover {
  border-color: transparent;
  background: linear-gradient(135deg, #35b269 0%, #56d29d 100%);
  box-shadow: 0 18px 40px -12px rgba(63, 191, 139, 1);
}

/* Outlined, not solid: a filled red button is this app's delete/void signal
   (.btn.danger, the job danger zone), and spending money is neither. */
.action-btn--money-out {
  border-color: var(--cedge-red-12);
  background: rgba(255, 101, 101, 0.12);
  color: var(--bad);
}

.action-btn--money-out:hover {
  border-color: var(--cedge-red-13);
  background: rgba(255, 101, 101, 0.2);
  box-shadow: 0 10px 24px -12px rgba(255, 101, 101, 0.9);
}

/* Purple is the one hue on this palette that isn't already spoken for — orange
   is the brand, green is paid, red is spend, amber is a warning. That makes it
   free to mean "planning", which is a mode rather than a money event. */
/* Built like the Stripe alert banner — saturated fill, neon rim, layered bloom,
   faint lattice — in purple. The glow is four shadows rather than one big blur
   for the same reason it is there: a tight rim, a mid halo, a wide pool and a
   downward cast read as light; a single soft shadow reaching that far reads as
   fog. */
.action-btn--plan {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-color: var(--planning, var(--cedge-violet-2));
  color: #fff;
  background:
    var(--planning-glow, radial-gradient(135% 120% at 50% 118%, rgba(214, 176, 255, 0.42) 0%, rgba(168, 85, 247, 0.2) 42%, transparent 70%)),
    var(--planning-gradient, linear-gradient(180deg, #7c3aed 0%, #6320c9 55%, #4f169f 100%));
  box-shadow: var(--planning-shadow, 0 0 9px rgba(180, 120, 255, 0.6), 0 0 24px rgba(147, 51, 234, 0.42), 0 0 62px rgba(124, 40, 220, 0.3), 0 14px 46px -14px rgba(120, 40, 210, 0.5));
}

/* Texture, so the fill isn't flat paint. Two hatches, no asset to ship. */
.action-btn--plan::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  /* above the background, below the label — see isolation above */
  pointer-events: none;
  background:
    repeating-linear-gradient(60deg, rgba(var(--tint), 0.055) 0 1px, transparent 1px 15px),
    repeating-linear-gradient(-60deg, rgba(var(--tint), 0.055) 0 1px, transparent 1px 15px);
}

/* The shine. It sweeps and then WAITS — most of the timeline is the pause. A
   highlight crossing every second is a loading bar; one that crosses now and
   then is a button catching the light. */
.action-btn--plan::after {
  content: '';
  position: absolute;
  inset: -1px;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(105deg, transparent 34%, rgba(var(--tint), 0.42) 50%, transparent 66%);
  transform: translateX(-135%);
  animation: planSheen 5.2s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes planSheen {

  0%,
  62% {
    transform: translateX(-135%);
  }

  86%,
  100% {
    transform: translateX(135%);
  }
}

.action-btn--plan:hover {
  border-color: var(--planning, var(--cedge-violet-3));
  background:
    var(--planning-glow, radial-gradient(135% 120% at 50% 118%, rgba(224, 195, 255, 0.5) 0%, rgba(178, 105, 255, 0.24) 42%, transparent 70%)),
    var(--planning-gradient, linear-gradient(180deg, #8b4bf0 0%, #6f2ada 55%, #591cb4 100%));
  box-shadow: var(--planning-shadow);
  transform: translateY(-1px);
}

:root[data-theme='monochrome'] .action-btn--lead {
  background: var(--accent-gradient);
  color: var(--on-accent);
  box-shadow: 0 12px 30px -14px rgba(255, 255, 255, 0.4);
}

:root[data-theme='monochrome'] .action-btn--money-in {
  background: linear-gradient(135deg, #71717a 0%, #a1a1aa 100%);
  color: #ffffff;
  box-shadow: 0 12px 32px -12px rgba(255, 255, 255, 0.3);
}

:root[data-theme='monochrome'] .action-btn--money-out {
  border-color: rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

:root[data-theme='clarity'] .action-btn--lead {
  background: var(--accent-gradient);
  color: var(--on-accent);
  box-shadow: 0 12px 30px -14px rgba(86, 180, 233, 0.6);
}

:root[data-theme='clarity'] .action-btn--money-in {
  background: linear-gradient(135deg, #56b4e9 0%, #8ecdf0 100%);
  color: #08131f;
  box-shadow: 0 12px 32px -12px rgba(86, 180, 233, 0.6);
}

:root[data-theme='clarity'] .action-btn--money-out {
  border-color: rgba(255, 107, 74, 0.4);
  background: rgba(255, 107, 74, 0.12);
  color: #ff6b4a;
}

/* A button that pulses on its own is exactly what reduced-motion is asking you
   not to do. The fill and the glow stay; only the sweep goes. */
@media (prefers-reduced-motion: reduce) {
  .action-btn--plan::after {
    animation: none;
    opacity: 0;
  }
}

/* 24-grid stroke glyphs, same drawing style as the sidebar rail. */
.action-btn-ic {
  flex: none;
  width: 1.15rem;
  height: 1.15rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* An outlined glyph sits on the panel's own dark ground and needs the lift; on
   a solid fill it already has all the contrast it can use, and a halo there
   just smears the stroke. Set per variant so a colour added later can't
   silently inherit the wrong one. */
.action-btn .action-btn-ic {
  filter: drop-shadow(0 0 4px rgba(255, 122, 33, 0.65));
}

.action-btn--money-out .action-btn-ic {
  filter: drop-shadow(0 0 4px rgba(255, 101, 101, 0.65));
}

.action-btn--lead .action-btn-ic,
.action-btn--money-in .action-btn-ic,
.action-btn--plan .action-btn-ic {
  filter: none;
}

@media (prefers-reduced-motion: reduce) {
  .action-btn {
    transition: none;
  }

  .action-btn:hover {
    transform: none;
  }
}

/* Primary actions inside the dashboard glow. Scoped to the workspace shell on
   purpose — .btn.primary is also the button on every contractor's public site
   and on the marketing pages, and those are not this theme. */
.workspace-shell .btn.primary {
  box-shadow:
    0 0 0 1px rgba(255, 178, 122, 0.5),
    0 0 18px rgba(255, 122, 33, 0.4),
    0 6px 18px rgba(0, 0, 0, 0.35);
  transition: box-shadow 0.16s ease, transform 0.16s ease;
}

.workspace-shell .btn.primary:hover {
  box-shadow:
    0 0 0 1px rgba(255, 200, 158, 0.75),
    0 0 26px rgba(255, 122, 33, 0.6),
    0 8px 22px rgba(0, 0, 0, 0.4);
}

/* HARBOUR — outlined primary, Deep Ocean.
   ---------------------------------------------------------------------------
   Was a raised blue slab with white text, which is a handsome button and 4.1:1
   — under AA at the size it actually renders. It is hollow now, to match the
   dark theme, and Harbour KEEPS ITS BLUE: the accent on paper is a colour
   decision this file made deliberately, and the outline treatment is about
   which part carries the colour, not which colour it is. #1c56a8 as ink on
   white is 7.1:1.

   Still scoped to .workspace-shell for the same reason it always was —
   .btn.primary is also the button on a contractor's public surfaces, and that
   is their brand, not ours. */
:root[data-theme='light'] .workspace-shell .btn.primary {
  background: linear-gradient(180deg, #ea580c 0%, #c2410c 100%);
  color: #ffffff;
  border-color: #9a3412;
  box-shadow: 0 2px 8px rgba(234, 88, 12, 0.35);
}

:root[data-theme='light'] .workspace-shell .btn.primary:hover {
  background: linear-gradient(180deg, #f97316 0%, #ea580c 100%);
  color: #ffffff;
  border-color: #c2410c;
  box-shadow: 0 4px 14px rgba(234, 88, 12, 0.45);
}

@media (prefers-reduced-motion: reduce) {

  .workspace-shell .btn.primary,
  .stripe-alert-banner,
  .stripe-alert-chevron,
  .sched-stat,
  .calendar-view-toggle button {
    transition: none;
  }

  .stripe-alert-banner:hover,
  .stripe-alert-banner:hover .stripe-alert-chevron {
    transform: none;
  }
}

/* Month nav, sharing the toolbar row with the view switcher */
.month-nav {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
}

.month-nav-label {
  margin: 0 0.35rem;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.month-nav-arrow,
.month-nav-today {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--edge-g20);
  background: rgba(var(--tint), 0.03);
  color: var(--text, #e8eef6);
  text-decoration: none;
  font-weight: 700;
  transition: border-color 0.16s ease, background 0.16s ease;
}

/* 44px, not the 32px these measured. They are the most-pressed controls on the
   calendar and two of them are circles the size of a fingertip's error. The row
   does not get taller for it: the view controls beside them are 46px. */
.month-nav-arrow {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  font-size: 0.95rem;
}

.month-nav-today {
  min-height: 44px;
  padding: 0 0.85rem;
  border-radius: 999px;
  font-size: 0.78rem;
}

.month-nav-arrow:hover,
.month-nav-today:not([aria-disabled='true']):hover {
  border-color: var(--cedge-orange-38);
  background: rgba(255, 122, 41, 0.1);
}

/* Way in to the booking setup screen, reading as a status line so the schedule
   page still says whether the public booking page is working. */
.schedule-setup-link {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.05rem 1.3rem;
  border: 1px solid var(--edge-g16);
  border-radius: 16px;
  background: var(--bg-elevated);
  text-decoration: none;
  color: inherit;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.schedule-setup-link:hover {
  border-color: var(--cedge-orange-57);
  background: rgba(10, 22, 37, 0.92);
}

.schedule-setup-link:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.schedule-setup-link-copy {
  display: grid;
  gap: 0.2rem;
  flex: 1;
  min-width: 0;
}

.schedule-setup-link-copy .eyebrow {
  margin: 0;
}

.schedule-setup-link-copy strong {
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.schedule-setup-link-copy>span:last-child {
  font-size: 0.85rem;
  color: var(--muted, var(--muted-2));
}

.schedule-setup-pill {
  flex: none;
  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--edge-g24);
  font-size: 0.75rem;
  font-weight: 650;
  color: var(--muted, var(--muted-2));
  white-space: nowrap;
}

.schedule-setup-pill.tone-on {
  border-color: var(--cedge-green-33);
  background: rgba(52, 199, 123, 0.12);
  color: var(--ink-green-2);
}

.schedule-setup-pill.tone-warn {
  border-color: var(--cedge-orange-53);
  background: rgba(255, 176, 32, 0.1);
  color: var(--ink-amber-1);
}

.schedule-setup-go {
  flex: none;
  color: var(--ink-orange-8);
  font-weight: 700;
}

/* ---------------------------------------------------------------------------
   Online bookings waiting on the contractor

   Amber, not the brand orange. Orange on this page means "do the thing" (Plan
   my day, + New, Set booking availability). This panel is not an action the
   owner chose to take — it is somebody waiting on them — and it has to read as
   a held state rather than as another button to press.
--------------------------------------------------------------------------- */

.booking-requests {
  border-color: var(--cedge-orange-58);
  background: linear-gradient(180deg, rgba(255, 176, 32, 0.07), rgba(var(--tint), 0.02));
}

.booking-requests-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.booking-requests-head .eyebrow {
  color: var(--ink-amber-1);
}

.booking-requests-head h2 {
  margin: 0.1rem 0 0;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
}

/* States the thing the panel exists to say, where the eye lands first. */
.booking-requests-pill {
  flex: none;
  padding: 0.3rem 0.6rem;
  border-radius: 999px;
  border: 1px solid var(--cedge-orange-59);
  background: rgba(255, 176, 32, 0.14);
  color: var(--ink-amber-1);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.booking-requests-lead {
  margin: 0.75rem 0 0;
  font-size: 0.88rem;
  line-height: 1.55;
  color: rgba(var(--grey-6), 0.86);
}

.booking-requests-lead strong {
  color: var(--warn);
}

.booking-requests-overdue {
  margin: 0.6rem 0 0;
  padding: 0.55rem 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--cedge-red-6);
  background: rgba(255, 107, 107, 0.09);
  color: var(--bad);
  font-size: 0.83rem;
  line-height: 1.5;
}

.booking-requests-list {
  list-style: none;
  margin: 0.85rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.booking-request {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.5rem 1rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid var(--edge-g20);
  border-radius: 13px;
  background: rgba(var(--tint), 0.03);
}

.booking-request[data-past] {
  border-color: var(--cedge-red-14);
}

.booking-request-main {
  min-width: 0;
  display: grid;
  gap: 0.3rem;
}

.booking-request-who {
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
  flex-wrap: wrap;
}

.booking-request-who strong {
  font-size: 0.98rem;
  font-weight: 750;
}

.booking-request-when {
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--warn);
}

.booking-request-past {
  margin-left: 0.4rem;
  font-style: normal;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--bad);
}

/* TWO WINDOWS, ON TWO LINES.
   Side by side they read as a range — "Thu 8–12, Fri 1–5" looks like a two-day
   job rather than a choice between two mornings. Stacked and numbered, the
   shape of the thing is a list of options, which is what it is. */
/* The row is a baseline-aligned flex line built for "Name · when". A stacked
   pair of windows is a block, and baseline-aligning a block against a name
   hangs the name off the first of the two. Grid when there are two. */
.booking-request-who:has(.booking-request-choices) {
  display: grid;
  gap: 0.28rem;
}

.booking-request-choices {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.booking-request-choice {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  min-width: 0;
}

.booking-request-choice em {
  flex: none;
  font-style: normal;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(var(--grey-5), 0.9);
}

/* The backup is the quieter of the two — the customer put them in an order. */
.booking-request-choice:last-child .booking-request-when {
  color: rgba(var(--grey-5), 0.95);
}

/* A backup that somebody else has taken since. Amber, not red: the day has not
   gone and confirming it is still the contractor's call — this is so it isn't
   a surprise, not so it reads as an error. On its own line rather than trailing
   the window, which on a phone left "NO" hanging at the end of it. */
.booking-request-gone {
  display: block;
  margin-top: 0.1rem;
  font-style: normal;
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ink-amber-1);
}

@media (min-width: 721px) {
  .booking-request-gone {
    display: inline;
    margin-left: 0.4rem;
  }
}

.booking-request-detail {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
  font-size: 0.8rem;
  color: var(--dim-grey-2);
}

.booking-request-detail>span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.booking-request-address,
.booking-request-contact {
  color: rgba(var(--grey-5), 0.95);
}

/* The homeowner's own words, quoted. Italic so it reads as theirs rather than as
   another field the system filled in. */
.booking-request-note {
  font-style: italic;
  color: rgba(var(--grey-5), 0.95);
}

.booking-request-actions {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  flex-wrap: wrap;
}

/* Confirm stays the standard orange .btn.primary — deliberately NOT green.
   Green in this app means money agreed or money recorded (approving hours,
   marking paid), and it only keeps that meaning if nothing else borrows it.
   Confirming an appointment is a promise about time, not about money. */

.booking-request-foot {
  grid-column: 1 / -1;
  margin: 0.15rem 0 0;
  font-size: 0.74rem;
  color: rgba(var(--grey-5), 0.85);
}

@media (max-width: 720px) {
  .booking-request {
    grid-template-columns: minmax(0, 1fr);
  }

  .booking-request-actions>* {
    flex: 1 1 9rem;
  }

  .booking-request-actions .btn {
    width: 100%;
  }
}

/* ---------------------------------------------------------------------------
   THE WEEKEND CHIPS ARE GONE FROM HERE.

   Two pills reading "Saturday 0 / Sunday 0", 224px of a 728px toolbar, in every
   month with no weekend work — and the reason that row measured 85px tall at
   1920, 1440, 1366 and 1024 alike. The switches are rows in the views menu now
   (.calendar-col-*) and the one fact worth interrupting for has its own object
   (.calendar-hidden-days). See CalendarDayColumns.tsx for the argument.

   The row itself stays: it holds the recurring-visits note.
--------------------------------------------------------------------------- */

.calendar-days-row {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.45rem;
}

/* Hint + setup shortcuts, under the grid */
.schedule-panel-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.6rem 1rem;
  margin-top: 1rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-g10);
}

.schedule-panel-foot p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
}

.schedule-panel-foot-links {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  flex-wrap: wrap;
}

.schedule-panel-foot-links>a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  /* 44px. Measured at 17px on a phone, which is a link you hit by luck. Both of
     these are navigations off this page, and they are the only two controls at
     the foot of a 700px calendar — being small did not make them unobtrusive,
     it made them unusable. */
  min-height: 44px;
  font-size: 0.82rem;
  font-weight: 650;
  color: var(--dim-orange-3-6);
  text-decoration: none;
}

.schedule-panel-foot-links>a:hover {
  text-decoration: underline;
}

.schedule-panel-foot-links>a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 8px;
}

/* The way back off the settings route. A control, not the browser button —
   somebody who arrived here from the calendar is mid-task on the calendar. */
.sched-settings-back {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 44px;
  margin-bottom: 0.15rem;
  color: var(--dim-orange-3-6);
  font-size: 0.84rem;
  font-weight: 700;
  text-decoration: none;
}

.sched-settings-back:hover {
  text-decoration: underline;
}

.sched-settings-back:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 8px;
}

@media (max-width: 780px) {
  .schedule-bar {
    gap: 0.7rem;
  }

  .schedule-bar-id {
    flex: 1 1 100%;
  }

  /* Four evenly-sized tiles beat a ragged wrap at phone widths — and the label
     goes beside the number rather than under it, which halves the block's
     height. Stacked, these four alone cost 190px of the screen before you saw
     a single date. */
  /* minmax(0, 1fr), NOT 1fr. A bare `1fr` has a minimum of min-content, so
     these four tiles refused to shrink below the width of "Revenue" and their
     icon: measured at 320px the row came out 299px wide inside 234px of room
     and pushed the whole document 22px sideways. `1fr` on its own does not
     mean "an equal share", it means "an equal share, but never smaller than
     what is inside me". */
  .schedule-stats {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.4rem;
    justify-content: flex-start;
    flex: 1 1 100%;
  }

  .sched-stat {
    min-width: 0;
  }

  .sched-stat small {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .sched-stat {
    display: flex;
    align-items: baseline;
    gap: 0.35rem;
    padding: 0.42rem 0.6rem;
    border-radius: 10px;
  }

  .sched-stat strong {
    font-size: 0.92rem;
  }

  .sched-stat small {
    font-size: 0.6rem;
    letter-spacing: 0.05em;
  }

  .schedule-bar-cta {
    flex: 1 1 100%;
    justify-content: center;
  }

  .month-nav-label {
    font-size: 1.05rem;
  }

  .schedule-panel-foot {
    justify-content: flex-start;
  }
}

.booking-form-actions {
  display: flex;
  justify-content: flex-end;
  padding-top: 1rem;
  border-top: 1px solid var(--rule-g12);
}

/* ===========================================================================
   Booking & availability setup (/dashboard/schedule/booking)

   Three depths of surface, so nesting reads without needing a border on
   everything: the page, a section card, and a field group inside it. Orange is
   reserved for what's SELECTED and for the primary action — nothing decorative
   uses it, or "on" stops meaning anything.
=========================================================================== */

/* Booking and Quick Stops declare their own surface palette, which is why they
   were the last two screens still dark under Harbour: a local --bset-card:
   rgba(10,20,33,.92) wins over anything the flip has to say.

   Declared on the CARDS, not on .bset. Putting them on the region meant its
   header, its coverage map and its save bar all read paper values while
   standing on the dark canvas — the region is desk (see the note in THE FLIP's
   selector list). Only what paints itself a sheet gets the sheet's palette. */
:root[data-theme='light'] .bset-master,
:root[data-theme='light'] .bset-card,
:root[data-theme='light'] .bset-section,
:root[data-theme='light'] .bset-preview,
:root[data-theme='light'] .bset-recurring,
:root[data-theme='light'] .bset-tipcard {
  --bset-card: #ffffff;
  --bset-inner: rgba(17, 27, 41, 0.035);
  /* Edged like everything else on paper now — these were 1.28:1 and 1.55:1. */
  --bset-line: #28384b;
  --bset-line-strong: #1f2a39;
  /* The accent when it is READ rather than filled. --bset-accent stays #ff7a29
     because it is also a fill, and on a fill it is correct; as bare text on a
     white sheet it measured 2.6:1. Deep burnt orange keeps the hue — this is
     still the brand's colour, at the value paper needs. */
  --bset-accent-ink: #a54f1b;
}

.bset {
  --bset-card: var(--bg-gradient-card, rgba(16, 24, 38, 0.92));
  --bset-inner: rgba(var(--tint), 0.028);
  --bset-line: rgba(var(--grey-1), 0.16);
  --bset-line-strong: rgba(var(--grey-1), 0.26);
  --bset-accent: #ff7a29;
  /* Same value in dark: an accent on navy is already readable. Only paper
     needs the deep one (see the light block above). */
  --bset-accent-ink: #ff7a29;
  display: grid;
  gap: 1.5rem;
  align-content: start;
  padding-bottom: 6rem;
  /* room for the sticky save bar */
}

/* --- header --- */
.bset-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

/* The heading block takes the slack; without this it shrank to fit and broke
   "Booking & availability" across two lines with room to spare beside it. */
.bset-head>div {
  flex: 1 1 auto;
  min-width: 0;
}

.bset-head h1 {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0;
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  letter-spacing: -0.02em;
  white-space: nowrap;
}

/* Quick Stops' heading is its badge. Scaled off the same clamp the type uses so
   it grows and shrinks with the headings on every neighbouring page instead of
   being one fixed lump that is too big on a laptop and too small on a monitor.
   max-width keeps it inside a narrow column rather than forcing the flex row to
   wrap the "View booking page" button onto its own line. */
.qs-logo-head {
  line-height: 0;
}

.qs-logo-badge {
  height: clamp(2.5rem, 4.4vw, 3.4rem);
  width: auto;
  max-width: 100%;
  object-fit: contain;
  object-position: left center;
}

.bset-head h1 svg {
  width: 1.4rem;
  height: 1.4rem;
  color: var(--bset-accent-ink);
}

.bset-head p {
  margin: 0.3rem 0 0;
  color: var(--muted, var(--muted-2));
  font-size: 0.9rem;
}

.bset-head-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  white-space: nowrap;
}

.bset-head-cta svg {
  width: 0.9rem;
  height: 0.9rem;
}

.bset-head-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.bset-head-cta.copied {
  border-color: var(--ink-green-7, #34c77b);
  color: var(--ink-green-2, #34c77b);
  background: rgba(52, 199, 123, 0.12);
}

/* --- master switch --- */
.bset-master {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  flex-wrap: wrap;
  padding: 1.15rem 1.35rem;
  border: 1.5px solid var(--bset-line-strong);
  border-radius: 18px;
  background: var(--bset-card);
  box-shadow: 0 18px 50px -12px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(var(--tint), 0.12);
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}

.bset-master-switch {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  flex: 1 1 22rem;
  min-width: 0;
  cursor: pointer;
}

.bset-master-switch input,
.bset-check input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.bset-switch-track {
  flex: none;
  width: 3.4rem;
  height: 1.85rem;
  border-radius: 999px;
  background: rgba(var(--grey-1), 0.22);
  padding: 0.22rem;
  transition: background 0.18s ease;
}

.bset-switch-track>span {
  display: block;
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.18s ease;
}

.bset-switch-track.small {
  width: 2.4rem;
  height: 1.35rem;
  padding: 0.17rem;
}

.bset-switch-track.small>span {
  width: 1rem;
  height: 1rem;
}

.bset-master-switch input:checked+.bset-switch-track,
.bset-check input:checked+.bset-switch-track {
  background: var(--bset-accent);
}

.bset-master-switch input:checked+.bset-switch-track>span {
  transform: translateX(1.55rem);
}

.bset-check input:checked+.bset-switch-track.small>span {
  transform: translateX(1.05rem);
}

.bset-master-switch input:focus-visible+.bset-switch-track,
.bset-check input:focus-visible+.bset-switch-track {
  outline: 2px solid rgba(255, 122, 41, 0.75);
  outline-offset: 2px;
}

.bset-master-copy {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.bset-master-copy strong {
  font-size: 1.12rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.bset-master-copy strong em {
  font-style: normal;
  font-weight: 800;
}

.bset-master-copy strong em.on {
  color: var(--bset-accent-ink);
}

.bset-master-copy strong em.off {
  color: var(--muted, var(--muted-2));
}

.bset-master-copy small {
  font-size: 0.84rem;
  color: var(--muted, var(--muted-2));
}

.bset-master-save-note {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 0.18rem;
  color: var(--mute-t55);
  font-size: 0.72rem;
  line-height: 1.35;
}

.bset-master-save-note svg {
  width: 0.8rem;
  height: 0.8rem;
  flex: none;
  color: var(--ink-green-7);
}

.bset-master-status {
  flex: 1 1 15rem;
  min-width: 0;
  padding-left: 1.25rem;
  border-left: 1px solid var(--bset-line);
}

.bset-master-status p {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0 0 0.2rem;
  font-weight: 650;
  font-size: 0.92rem;
}

.bset-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--muted, var(--muted-2));
}

@keyframes liveDotPulse {
  0%, 100% {
    box-shadow: 0 0 0 3px rgba(52, 199, 123, 0.18), 0 0 10px rgba(52, 199, 123, 0.35);
  }
  50% {
    box-shadow: 0 0 0 5px rgba(52, 199, 123, 0.32), 0 0 16px rgba(52, 199, 123, 0.55);
  }
}

.bset-master-status.live .bset-dot {
  background: #34c77b;
  box-shadow: 0 0 0 3px rgba(52, 199, 123, 0.18), 0 0 10px rgba(52, 199, 123, 0.35);
  animation: liveDotPulse 2.4s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .bset-master-status.live .bset-dot {
    animation: none;
  }
}

.bset-master-status.live p {
  color: var(--ink-green-2);
}

.bset-master-status.live.attention p {
  color: var(--ink-amber-1);
}

.bset-master-status small {
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.4;
}

.bset-pause {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.bset-pause svg {
  width: 0.9rem;
  height: 0.9rem;
}

/* The master switch's buttons, kept together so they wrap as a group rather
   than one at a time dropping under the status text on its own. */
.bset-master-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.bset-how,
.bset-open,
.bset-setup {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

.bset-how svg,
.bset-open svg,
.bset-setup svg {
  width: 0.95rem;
  height: 0.95rem;
}

/* The foot of the page: the way back up, since every path through this page
   runs downhill and the longest panel is the last one. */
.qs-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  flex-wrap: wrap;
}

.qs-foot-copy {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
  flex: 1 1 20rem;
}

.qs-foot-copy strong {
  font-size: 1.02rem;
  font-weight: 700;
}

.qs-foot-copy p {
  margin: 0;
  font-size: 0.86rem;
  line-height: 1.5;
  color: var(--muted, var(--muted-2));
}

.qs-foot-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

/* Both jump targets clear the sticky top bar rather than landing under it. */
#quick-stop-earn-more,
#quick-stop-demand {
  scroll-margin-top: calc(var(--appbar-h) + 1.25rem);
}

/* --- summary cards --- */
.bset-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 0.9rem;
}

.bset-card {
  display: grid;
  gap: 0.25rem;
  /* The card holds a hostname, and a hostname has no spaces to break on — a
     long subdomain ran straight out of the card and onto the page. */
  min-width: 0;
  overflow-wrap: anywhere;
  padding: 1.1rem 1.15rem 0.9rem;
  border: 1px solid var(--bset-line);
  border-radius: 16px;
  background: var(--bset-card);
  box-shadow: 0 12px 36px -10px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(var(--tint), 0.1);
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s cubic-bezier(0.16, 1, 0.3, 1), transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.bset-card:hover {
  border-color: rgba(var(--tint), 0.26);
  transform: translateY(-2px);
  box-shadow: 0 18px 48px -8px rgba(0, 0, 0, 0.55), 0 0 20px -4px rgba(255, 122, 33, 0.16), inset 0 1px 0 rgba(var(--tint), 0.2);
}

.bset-card:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.bset-card-icon {
  display: grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  margin-bottom: 0.55rem;
  border-radius: 12px;
  background: rgba(var(--tint), 0.05);
  transition: transform 0.2s ease, background 0.2s ease;
}

.bset-card:hover .bset-card-icon {
  transform: scale(1.06);
  background: rgba(var(--tint), 0.09);
}

.bset-card-icon svg {
  width: 1.25rem;
  height: 1.25rem;
}

/* Icon tint is identity, not state — it never means "selected". */
.bset-card-icon.tone-days {
  color: var(--accent-ink);
  background: rgba(255, 122, 41, 0.12);
}

.bset-card-icon.tone-time {
  color: var(--ink-amber-1);
  background: rgba(255, 176, 32, 0.12);
}

.bset-card-icon.tone-off {
  color: var(--ink-violet-1);
  background: rgba(150, 110, 255, 0.14);
}

.bset-card-icon.tone-link {
  color: var(--ink-green-7);
  background: rgba(52, 199, 123, 0.13);
}

.bset-card-label {
  font-size: 0.8rem;
  color: var(--muted, var(--muted-2));
}

.bset-card>strong {
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.bset-card>small {
  font-size: 0.8rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.4;
}

.bset-card-edit {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  margin-top: 0.65rem;
  padding-top: 0.6rem;
  border-top: 1px solid var(--bset-line);
  font-size: 0.84rem;
  font-weight: 650;
  color: var(--bset-accent-ink);
}

.bset-card-edit svg {
  width: 0.85rem;
  height: 0.85rem;
}

/* Booking requests use a compact read-back instead of four dashboard cards.
   The values stay editable jump targets, but the actual controls now begin in
   the first viewport on a phone instead of several cards later. */
.bset-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
}

.bset-summary-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.8rem 0.9rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-card);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, transform 0.16s ease;
}

.bset-summary-item:hover {
  border-color: var(--bset-line-strong);
  transform: translateY(-1px);
}

.bset-summary-item:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.bset-summary-item.has-warning {
  border-color: var(--cedge-amber-11);
}

.bset-summary-item.is-static {
  cursor: default;
}

.bset-summary-item.is-static:hover {
  border-color: var(--bset-line);
  transform: none;
}

.bset-summary-icon,
.bset-section-icon {
  flex: none;
  display: grid;
  place-items: center;
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 10px;
}

.bset-summary-icon svg,
.bset-section-icon svg {
  width: 1.05rem;
  height: 1.05rem;
}

.bset-summary-icon.tone-days,
.bset-section-icon.tone-days {
  color: var(--bset-accent-ink);
  background: rgba(255, 122, 41, 0.12);
}

.bset-summary-icon.tone-time,
.bset-section-icon.tone-time {
  color: var(--ink-amber-1);
  background: rgba(255, 176, 32, 0.12);
}

.bset-summary-icon.tone-off,
.bset-section-icon.tone-off {
  color: var(--ink-violet-1);
  background: rgba(150, 110, 255, 0.14);
}

.bset-summary-icon.tone-link,
.bset-section-icon.tone-link {
  color: var(--ink-green-7);
  background: rgba(52, 199, 123, 0.13);
}

.bset-summary-copy {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
  flex: 1;
}

.bset-summary-copy small {
  font-size: 0.72rem;
  color: var(--muted, var(--muted-2));
}

.bset-summary-copy strong {
  overflow: hidden;
  font-size: 0.92rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bset-summary-copy>span {
  overflow: hidden;
  font-size: 0.76rem;
  color: var(--muted, var(--muted-2));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bset-summary-copy>span.is-warning {
  color: var(--ink-amber-1);
  font-weight: 700;
}

.bset-summary-chevron {
  width: 0.9rem;
  height: 0.9rem;
  flex: none;
  color: var(--muted, var(--muted-2));
}

/* Phones get one read-back disclosure instead of three cards repeating the
   accordion immediately below them. */
.bset-mobile-summary {
  display: none;
}

.bset-mobile-summary>summary {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-card);
  cursor: pointer;
  list-style: none;
}

.bset-mobile-summary>summary::-webkit-details-marker {
  display: none;
}

.bset-mobile-summary>summary>span:first-child {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
  flex: 1;
}

.bset-mobile-summary>summary small {
  color: var(--muted, var(--muted-2));
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bset-mobile-summary>summary strong {
  overflow: hidden;
  font-size: 0.86rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bset-mobile-summary>summary em {
  flex: none;
  padding: 0.18rem 0.4rem;
  border: 1px solid var(--cedge-amber-11);
  border-radius: 999px;
  color: var(--ink-amber-1);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 750;
  white-space: nowrap;
}

.bset-mobile-summary>summary>svg {
  width: 0.95rem;
  height: 0.95rem;
  flex: none;
  transition: transform 0.18s ease;
}

.bset-mobile-summary[open]>summary {
  border-radius: 14px 14px 0 0;
}

.bset-mobile-summary[open]>summary>svg {
  transform: rotate(180deg);
}

.bset-mobile-summary.has-warning>summary {
  border-color: var(--cedge-amber-11);
}

.bset-mobile-summary-actions {
  display: grid;
  border: 1px solid var(--bset-line);
  border-top: 0;
  border-radius: 0 0 14px 14px;
  background: var(--bset-card);
}

.bset-mobile-summary-actions>* {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.65rem 0.85rem;
  border: 0;
  border-top: 1px solid var(--bset-line);
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
}

.bset-mobile-summary-actions>button {
  cursor: pointer;
}

.bset-mobile-summary-actions>button:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: -2px;
}

.bset-mobile-summary-actions>*>span {
  flex: none;
  color: var(--muted, var(--muted-2));
  font-size: 0.75rem;
}

.bset-mobile-summary-actions>*>strong {
  overflow: hidden;
  font-size: 0.78rem;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* --- two-column body --- */
.bset-body {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(19rem, 0.85fr);
  gap: 1.15rem;
  align-items: start;
}

.bset-main {
  display: grid;
  gap: 1.15rem;
  min-width: 0;
}

/* --- sections --- */
.bset-section {
  border: 2px solid var(--bset-line-strong);
  border-radius: 18px;
  background: var(--bset-card);
  /* NOT overflow:hidden — it clipped the three-dot menu in Time off. The
     header carries the radius itself so the corners still look right. */
}

.bset-section-head[aria-expanded='false'] {
  border-radius: 16px;
}

.bset-section-head[aria-expanded='true'] {
  border-radius: 16px 16px 0 0;
}

.bset-section-quiet {
  border-width: 1px;
  border-color: var(--bset-line);
}

.bset-section-head {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  width: 100%;
  padding: 1.05rem 1.25rem;
  background: none;
  border: 0;
  text-align: left;
  cursor: pointer;
  color: inherit;
}

.bset-section-head:hover {
  background: rgba(var(--tint), 0.02);
}

.bset-section-head:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: -2px;
}

.bset-num {
  flex: none;
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 50%;
  background: var(--bset-accent);
  color: #10131a;
  font-size: 0.85rem;
  font-weight: 800;
}

.bset-section-copy {
  display: grid;
  gap: 0.12rem;
  flex: 1;
  min-width: 0;
}

.bset-section-copy strong {
  font-size: 1.08rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.bset-section-copy small {
  font-size: 0.84rem;
  color: var(--muted, var(--muted-2));
}

.bset-section-badge {
  flex: none;
  padding: 0.22rem 0.55rem;
  border: 1px solid var(--cedge-amber-11);
  border-radius: 999px;
  background: rgba(255, 209, 102, 0.1);
  color: var(--gold-ink);
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.bset-chev {
  width: 1.1rem;
  height: 1.1rem;
  flex: none;
  color: var(--muted, var(--muted-2));
  transition: transform 0.18s ease;
}

.bset-chev.open {
  transform: rotate(180deg);
}

.bset-expand {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex: none;
  padding: 0.35rem 0.7rem;
  border: 1px solid var(--bset-line);
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 650;
  color: var(--muted, var(--muted-2));
}

.bset-section-body {
  padding: 0.25rem 1.25rem 1.3rem;
  border-top: 1px solid var(--bset-line);
}

.bset-field-group {
  padding-top: 1.05rem;
}

.bset-group-title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 650;
}

.bset-group-hint {
  margin: 0.15rem 0 0.75rem;
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
}

.bset-divider {
  height: 1px;
  margin: 1.25rem 0 0;
  background: var(--bset-line);
}

/* --- booking days --- */
/* Seven equal columns, so the week reads as a week. Wrapping put Saturday on a
   row of its own, which made a 7-day choice look like a 6-day one. */
.bset-daygrid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.5rem;
}

.bset-day {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.6rem 0.5rem;
  min-width: 0;
  border: 1px solid var(--bset-line);
  border-radius: 12px;
  background: var(--bset-inner);
  color: var(--muted, var(--muted-2));
  font-size: 0.82rem;
  font-weight: 750;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, color 0.16s ease;
}

.bset-day:hover {
  border-color: var(--bset-line-strong);
  color: var(--text, #e8eef6);
}

.bset-day:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.bset-day.on {
  border-color: var(--bset-accent-ink);
  background: rgba(255, 122, 41, 0.12);
  color: var(--text);
}

.bset-day-check {
  display: grid;
  place-items: center;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 4px;
  border: 1px solid var(--edge-g40);
}

.bset-day.on .bset-day-check {
  background: var(--bset-accent);
  border-color: var(--bset-accent-ink);
  color: #10131a;
}

.bset-day-check svg {
  width: 0.75rem;
  height: 0.75rem;
  stroke-width: 3;
}

.bset-workhours {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-top: 0.75rem;
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--bset-line);
  border-radius: 12px;
  background: var(--bset-inner);
}

.bset-workhours-icon {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  flex: none;
  border-radius: 9px;
  background: rgba(255, 176, 32, 0.1);
  color: var(--ink-amber-1);
}

.bset-workhours-icon svg {
  width: 1rem;
  height: 1rem;
}

.bset-workhours>span:not(.bset-workhours-icon) {
  display: grid;
  gap: 0.05rem;
  min-width: 0;
  flex: 1;
}

.bset-workhours small {
  font-size: 0.7rem;
  color: var(--muted, var(--muted-2));
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bset-workhours strong {
  font-size: 0.88rem;
  font-weight: 700;
}

.bset-workhours em {
  font-size: 0.76rem;
  font-style: normal;
  color: var(--muted, var(--muted-2));
}

.bset-workhours-actions {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.bset-workhours-quickedit {
  padding: 0.25rem 0.6rem;
  border: 1px solid var(--bset-line);
  border-radius: 8px;
  background: var(--bset-card);
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.76rem;
  font-weight: 650;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.bset-workhours-quickedit:hover {
  border-color: var(--bset-accent-ink);
  color: var(--bset-accent-ink);
}

.bset-workhours a {
  flex: none;
  color: var(--bset-accent-ink);
  font-size: 0.8rem;
  font-weight: 700;
  text-decoration: none;
}

.bset-workhours a:hover {
  text-decoration: underline;
}

.bset-workhours-form {
  margin-top: 0.75rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--bset-line-strong);
  border-radius: 12px;
  background: var(--bset-inner);
  display: grid;
  gap: 0.75rem;
}

.bset-workhours-fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 0.75rem;
}

.bset-workhours-fields label {
  display: grid;
  gap: 0.25rem;
}

.bset-workhours-fields span {
  font-size: 0.74rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted, var(--muted-2));
}

.bset-workhours-form-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* --- arrival windows --- */
.bset-windows {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: 0.6rem;
}

/* How long an arrival window runs. Each option carries its trade-off, because
   "1 hour" and "4 hours" are the same click and very different promises. */
.bset-lengths {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  gap: 0.55rem;
}

.bset-length {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.65rem 0.8rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-inner);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.bset-length strong {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
  font-size: 0.95rem;
}

.bset-length small {
  font-size: 0.74rem;
  line-height: 1.35;
  color: var(--mute-t55);
}

.bset-length.on {
  border-color: var(--ink-amber-3);
  background: rgba(255, 179, 122, 0.12);
}

.bset-recommended {
  padding: 0.1rem 0.35rem;
  border-radius: 999px;
  background: rgba(255, 176, 32, 0.12);
  color: var(--ink-amber-1);
  font-size: 0.6rem;
  font-style: normal;
  font-weight: 750;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.bset-window-warn {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin: 0.6rem 0 0;
  font-size: 0.8rem;
  line-height: 1.45;
  color: var(--ink-amber-1, var(--mute-t55));
}

.bset-window-warn>svg {
  width: 1rem;
  height: 1rem;
  flex: none;
  margin-top: 0.08rem;
}

.bset-window {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-inner);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.bset-window:hover {
  border-color: var(--bset-line-strong);
}

.bset-window:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.bset-window.on {
  border-color: var(--bset-accent-ink);
  background: rgba(255, 122, 41, 0.08);
}

.bset-window.on.unavailable {
  border-color: var(--cedge-amber-11);
  background: rgba(255, 209, 102, 0.06);
}

.bset-window-icon {
  flex: none;
  color: var(--ink-amber-1);
}

.bset-window-icon svg {
  width: 1.2rem;
  height: 1.2rem;
}

.bset-window.on .bset-window-icon {
  color: var(--bset-accent-ink);
}

.bset-window-copy {
  display: grid;
  gap: 0.08rem;
  flex: 1;
  min-width: 0;
}

.bset-window-copy strong {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
  font-weight: 650;
}

.bset-window-copy strong em {
  font-style: normal;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.1rem 0.35rem;
  border-radius: 999px;
  border: 1px solid var(--bset-line-strong);
  color: var(--muted, var(--muted-2));
}

.bset-window-copy strong em.is-warning {
  border-color: var(--cedge-amber-11);
  color: var(--gold-ink);
}

.bset-window-copy small {
  font-size: 0.78rem;
  color: var(--muted, var(--muted-2));
}

.bset-window-check {
  flex: none;
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  border-radius: 5px;
  border: 1px solid var(--edge-g40);
}

.bset-window.on .bset-window-check {
  background: var(--bset-accent);
  border-color: var(--bset-accent-ink);
  color: #10131a;
}

.bset-window.on.unavailable .bset-window-check {
  border-color: var(--cedge-amber-11);
  background: transparent;
  color: var(--gold-ink);
}

.bset-window-check svg {
  width: 0.8rem;
  height: 0.8rem;
  stroke-width: 3;
}

.bset-addwindow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  width: 100%;
  margin-top: 0.6rem;
  padding: 0.65rem;
  border: 1px dashed var(--bset-line-strong);
  border-radius: 12px;
  background: none;
  color: var(--muted, var(--muted-2));
  font-size: 0.85rem;
  font-weight: 650;
  cursor: pointer;
}

.bset-addwindow:hover:not(:disabled) {
  color: var(--bset-accent-ink);
  border-color: var(--cedge-orange-60);
}

.bset-addwindow:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.bset-addwindow svg {
  width: 0.9rem;
  height: 0.9rem;
}

.bset-window-fix {
  margin: 0.6rem 0 0;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--cedge-amber-11);
  border-radius: 10px;
  background: rgba(255, 209, 102, 0.06);
  color: var(--muted, var(--muted-2));
  font-size: 0.8rem;
  line-height: 1.45;
}

.bset-window-fix p {
  margin: 0;
}

.bset-window-fix>div {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.45rem 0.8rem;
  margin-top: 0.45rem;
}

.bset-window-fix a,
.bset-window-fix button {
  padding: 0;
  border: 0;
  background: none;
  color: var(--gold-ink);
  font: inherit;
  font-weight: 700;
  text-decoration: underline;
  cursor: pointer;
}

.bset-window-fix a:focus-visible,
.bset-window-fix button:focus-visible {
  outline: 2px solid rgba(255, 209, 102, 0.7);
  outline-offset: 2px;
}

.bset-inline-tip {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  margin: 0.75rem 0 0;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
  color: var(--muted, var(--muted-2));
  font-size: 0.8rem;
  line-height: 1.45;
}

.bset-inline-tip svg {
  width: 1rem;
  height: 1rem;
  flex: none;
  margin-top: 0.08rem;
  color: var(--ink-amber-1);
}

.bset-addwindow-form {
  display: flex;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.6rem;
  padding: 0.8rem;
  border: 1px solid var(--bset-line-strong);
  border-radius: 12px;
  background: var(--bset-inner);
}

.bset-addwindow-form label {
  display: grid;
  gap: 0.3rem;
}

.bset-addwindow-form label span {
  font-size: 0.75rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted, var(--muted-2));
}

.bset-addwindow-error {
  flex: 1 1 100%;
  margin: 0;
  font-size: 0.8rem;
  color: var(--bad);
}

/* --- live summary --- */
.bset-live {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  margin-top: 1.15rem;
  padding: 0.8rem 0.95rem;
  border: 1px solid var(--cedge-green-34);
  border-radius: 12px;
  background: rgba(52, 199, 123, 0.07);
}

.bset-live>svg {
  width: 1.1rem;
  height: 1.1rem;
  flex: none;
  color: var(--ink-green-7);
  margin-top: 0.05rem;
}

.bset-live strong {
  font-size: 0.85rem;
  font-weight: 650;
  color: var(--ink-green-2);
}

.bset-live p {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem 0.85rem;
  margin: 0.25rem 0 0;
  font-size: 0.86rem;
}

.bset-live p span {
  position: relative;
}

.bset-live p span+span::before {
  content: '•';
  position: absolute;
  left: -0.55rem;
  color: var(--muted, var(--muted-2));
}

.bset-live.warn {
  border-color: var(--cedge-orange-53);
  background: rgba(255, 176, 32, 0.08);
}

.bset-live.warn>svg {
  color: var(--ink-amber-1);
}

.bset-live.warn strong {
  color: var(--ink-amber-1);
}

/* --- fields --- */
.bset-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 0.9rem 1rem;
  padding-top: 1.05rem;
}

.bset-field {
  display: grid;
  gap: 0.35rem;
  min-width: 0;
}

.bset-field-wide {
  grid-column: 1 / -1;
}

.bset-field>span {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted, var(--muted-2));
}

.bset-field select,
.bset-field input,
.bset-addwindow-form input,
.bset-blockform input,
.bset-recurring-form input,
.bset-recurring-form select {
  width: 100%;
  padding: 0.62rem 0.75rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.9rem;
}

.bset-field select:focus-visible,
.bset-field input:focus-visible,
.bset-blockform input:focus-visible,
.bset-recurring-form input:focus-visible,
.bset-recurring-form select:focus-visible,
.bset-addwindow-form input:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 1px;
  border-color: transparent;
}

.bset select option,
.bset select optgroup {
  background: var(--bg-3);
  color: var(--text);
}

/* $ lives in the field, so the label doesn't need "($)" and the number lines
   up with the currency mark rather than floating in an empty box. */
.bset-money {
  display: flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0 0.75rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
}

.bset-money:focus-within {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 1px;
  border-color: transparent;
}

.bset-money>span {
  color: var(--muted, var(--muted-2));
  font-size: 0.9rem;
  font-weight: 650;
}

.bset-money input {
  flex: 1;
  min-width: 0;
  padding: 0.62rem 0;
  border: 0;
  background: none;
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.9rem;
  font-variant-numeric: tabular-nums;
}

.bset-money input:focus-visible {
  outline: none;
}

.bset-check {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.85rem 0;
  cursor: pointer;
}

.bset-check .bset-switch-track {
  margin-top: 0.1rem;
}

.bset-check-copy {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.bset-check-copy strong {
  font-size: 0.92rem;
  font-weight: 650;
}

.bset-check-copy small {
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.45;
}

/* Fields that only apply while the switch above them is on. */
.bset-dependent {
  margin-top: 0.35rem;
  padding: 0 0 0.35rem 1rem;
  border-left: 2px solid var(--cedge-orange-61);
}

.bset-rule-summary {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  margin-top: 0.85rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid var(--cedge-green-34);
  border-radius: 12px;
  background: rgba(52, 199, 123, 0.06);
}

.bset-rule-summary>svg {
  width: 1.05rem;
  height: 1.05rem;
  flex: none;
  margin-top: 0.08rem;
  color: var(--ink-green-7);
}

.bset-rule-summary>div {
  min-width: 0;
}

.bset-rule-summary strong {
  font-size: 0.84rem;
  color: var(--ink-green-2);
}

.bset-rule-summary p {
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  line-height: 1.45;
  color: var(--muted, var(--muted-2));
}

/* --- time off --- */
.bset-timeoff-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  padding-top: 1.05rem;
}

.bset-addblock {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.bset-addblock svg {
  width: 0.9rem;
  height: 0.9rem;
}

.bset-quick {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.85rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
  color: var(--text, #e8eef6);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease;
}

.bset-quick:hover:not(:disabled) {
  border-color: var(--bset-line-strong);
  background: rgba(var(--tint), 0.05);
}

.bset-quick:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 2px;
}

.bset-quick:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.bset-quick svg {
  width: 0.85rem;
  height: 0.85rem;
  color: var(--muted, var(--muted-2));
}

.bset-blockform {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  align-items: end;
  gap: 0.7rem;
  margin-top: 0.85rem;
  padding: 0.9rem;
  border: 1px solid var(--bset-line-strong);
  border-radius: 12px;
  background: var(--bset-inner);
}

.bset-blockform label {
  display: grid;
  gap: 0.3rem;
}

.bset-blockform label span {
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted, var(--muted-2));
}

.bset-blockform-reason {
  grid-column: 1 / -1;
}

.bset-blocks {
  list-style: none;
  display: grid;
  gap: 0.45rem;
  margin: 0.9rem 0 0;
  padding: 0;
}

.bset-blocks li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--bset-line);
  border-radius: 12px;
  background: var(--bset-inner);
}

.bset-block-icon {
  flex: none;
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 8px;
  background: rgba(150, 110, 255, 0.13);
  color: var(--ink-violet-1);
}

.bset-block-icon svg {
  width: 1rem;
  height: 1rem;
}

.bset-block-copy {
  display: grid;
  gap: 0.05rem;
  flex: 1;
  min-width: 0;
}

.bset-block-copy strong {
  font-size: 0.88rem;
  font-weight: 650;
}

.bset-block-copy small {
  font-size: 0.78rem;
  color: var(--muted, var(--muted-2));
}

.bset-block-len {
  flex: none;
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--bset-line);
  font-size: 0.72rem;
  font-weight: 650;
  color: var(--muted, var(--muted-2));
  white-space: nowrap;
}

.bset-block-menu {
  position: relative;
  flex: none;
}

.bset-dots {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 8px;
  border: 1px solid transparent;
  background: none;
  color: var(--muted, var(--muted-2));
  cursor: pointer;
}

.bset-dots:hover {
  border-color: var(--bset-line);
  color: var(--text, #e8eef6);
}

.bset-dots:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.7);
  outline-offset: 1px;
}

.bset-dots svg {
  width: 1.05rem;
  height: 1.05rem;
}

.bset-dots-pop {
  position: absolute;
  right: 0;
  top: calc(100% + 0.3rem);
  z-index: 60;
  display: grid;
  min-width: 13rem;
  padding: 0.3rem;
  border: 1px solid var(--bset-line-strong);
  border-radius: 12px;
  background: #0d1a2b;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.5);
}

.bset-dots-pop button {
  padding: 0.5rem 0.6rem;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.85rem;
  text-align: left;
  cursor: pointer;
}

.bset-dots-pop button:hover {
  background: rgba(var(--tint), 0.06);
}

.bset-empty {
  margin: 1rem 0 0;
  font-size: 0.86rem;
  color: var(--muted, var(--muted-2));
}

.bset-error {
  margin: 0.75rem 0 0;
  font-size: 0.84rem;
  color: var(--bad);
}

.bset-timeoff-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.bset-timeoff-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.bset-view-toggle {
  display: inline-flex;
  padding: 0.18rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
}

.bset-view-btn {
  padding: 0.35rem 0.7rem;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--muted, var(--muted-2));
  font: inherit;
  font-size: 0.78rem;
  font-weight: 650;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease;
}

.bset-view-btn.on {
  background: var(--bset-card);
  color: var(--text, #e8eef6);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

.bset-cal {
  margin-top: 0.9rem;
  padding: 0.9rem 1rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-inner);
  display: grid;
  gap: 0.75rem;
}

.bset-cal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.bset-cal-title {
  font-size: 0.96rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.bset-cal-nav {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.bset-cal-navbtn {
  width: 1.8rem;
  height: 1.8rem;
  border: 1px solid var(--bset-line);
  border-radius: 8px;
  background: var(--bset-card);
  color: var(--text, #e8eef6);
  font-size: 1rem;
  font-weight: 700;
  display: grid;
  place-items: center;
  cursor: pointer;
  line-height: 1;
}

.bset-cal-navbtn:hover {
  border-color: var(--bset-line-strong);
}

.bset-cal-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.35rem;
}

.bset-cal-dow {
  font-size: 0.65rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  color: var(--muted, var(--muted-2));
  text-align: center;
  padding: 0.2rem 0;
}

.bset-cal-cell {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 2.6rem;
  padding: 0.35rem 0.2rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-card);
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, transform 0.16s ease;
}

.bset-cal-cell.empty {
  border: 0;
  background: transparent;
  cursor: default;
}

.bset-cal-cell:hover:not(.empty):not(:disabled) {
  border-color: var(--bset-line-strong);
  transform: translateY(-1px);
}

.bset-cal-cell.is-today {
  border-color: var(--bset-accent-ink);
}

.bset-cal-cell.is-blocked {
  border-color: var(--cedge-amber-11);
  background: rgba(255, 176, 32, 0.12);
  color: var(--ink-amber-1);
}

.bset-cal-cell.is-past {
  opacity: 0.4;
  cursor: not-allowed;
}

.bset-cal-pill {
  font-size: 0.58rem;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1;
  margin-top: 0.15rem;
  color: var(--ink-amber-1);
}

.bset-cal-legend {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  margin-top: 0.25rem;
  font-size: 0.76rem;
  color: var(--muted, var(--muted-2));
}

.bset-cal-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.bset-cal-dot {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
}

.bset-cal-dot.open {
  background: var(--bset-line-strong);
}

.bset-cal-dot.blocked {
  background: var(--ink-amber-1);
}

/* Modal styles for QR / Share */
.bset-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 999;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: rgba(0, 0, 0, 0.75);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}

.bset-modal-card {
  width: 100%;
  max-width: 28rem;
  padding: 1.5rem;
  border: 1px solid var(--bset-line-strong);
  border-radius: 20px;
  background: var(--bset-card, #0a1421);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.7);
  display: grid;
  gap: 1.25rem;
}

.bset-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.bset-modal-head h3 {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.bset-modal-head p {
  margin: 0.3rem 0 0;
  font-size: 0.84rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.4;
}

.bset-modal-close {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border: 1px solid var(--bset-line);
  border-radius: 8px;
  background: transparent;
  color: var(--muted, var(--muted-2));
  font-size: 0.95rem;
  cursor: pointer;
}

.bset-modal-close:hover {
  border-color: var(--bset-line-strong);
  color: var(--text, #e8eef6);
}

.bset-qr-display {
  display: grid;
  justify-items: center;
  gap: 0.6rem;
  padding: 1.25rem;
  border: 1px solid var(--bset-line);
  border-radius: 16px;
  background: #ffffff;
  color: #10131a;
}

.bset-qr-frame {
  display: grid;
  place-items: center;
}

.bset-qr-hint {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 650;
  color: #556579;
}

.bset-qr-input-row {
  display: flex;
  gap: 0.5rem;
}

.bset-qr-url {
  flex: 1;
  min-width: 0;
  padding: 0.6rem 0.8rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
  background: var(--bset-inner);
  color: var(--text, #e8eef6);
  font: inherit;
  font-size: 0.82rem;
}

.bset-modal-foot {
  display: flex;
  justify-content: flex-end;
}

/* --- right rail --- */
.bset-rail {
  display: grid;
  gap: 1rem;
  min-width: 0;
  position: sticky;
  top: 1rem;
}

.bset-preview-toggle {
  display: none;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  width: 100%;
  padding: 0.8rem 0.9rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: var(--bset-card);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.bset-preview-toggle>span {
  display: grid;
  gap: 0.08rem;
}

.bset-preview-toggle small {
  color: var(--muted, var(--muted-2));
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bset-preview-toggle strong {
  font-size: 0.9rem;
}

.bset-preview-toggle>svg {
  width: 1rem;
  height: 1rem;
  transition: transform 0.18s ease;
}

.bset-preview-toggle>svg.open {
  transform: rotate(180deg);
}

.bset-preview {
  padding: 1.15rem 1.2rem 1.3rem;
  border: 2px solid var(--bset-line-strong);
  border-radius: 18px;
  background: var(--bset-card);
}

.bset-preview h2 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.bset-preview-sub {
  margin: 0.2rem 0 1rem;
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
}

.bset-preview-context {
  margin: 0.8rem 0 0;
  font-size: 0.78rem;
  line-height: 1.45;
  color: var(--muted, var(--muted-2));
}

.bset-preview-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.65rem;
  color: var(--bset-accent-ink);
  font-size: 0.82rem;
  font-weight: 700;
  text-decoration: none;
}

.bset-preview-link:hover {
  text-decoration: underline;
}

.bset-preview-link svg {
  width: 0.85rem;
  height: 0.85rem;
}

.bset-phone {
  display: grid;
  gap: 0.55rem;
  padding: 1rem;
  border: 1px solid var(--bset-line);
  border-radius: 14px;
  background: rgba(var(--tint), 0.022);
}

.bset-phone-title {
  font-size: 0.98rem;
  font-weight: 650;
}

.bset-phone-sub {
  margin: -0.35rem 0 0.35rem;
  font-size: 0.8rem;
  color: var(--muted, var(--muted-2));
}

.bset-phone-days {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.4rem;
}

.bset-phone-day {
  display: grid;
  gap: 0.1rem;
  justify-items: center;
  min-width: 0;
  padding: 0.5rem 0.35rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
}

.bset-phone-day small {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  color: var(--muted, var(--muted-2));
}

.bset-phone-day strong {
  font-size: 1rem;
  font-weight: 700;
}

.bset-phone-day.on {
  background: var(--bset-accent);
  border-color: var(--bset-accent-ink);
}

.bset-phone-day.on small,
.bset-phone-day.on strong {
  color: #10131a;
}

.bset-phone-label {
  margin: 0.5rem 0 0;
  font-size: 0.8rem;
  color: var(--muted, var(--muted-2));
}

.bset-phone-window {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--bset-line);
  border-radius: 10px;
}

.bset-phone-window.on {
  border-color: var(--bset-accent-ink);
  background: rgba(255, 122, 41, 0.07);
}

.bset-phone-window>svg {
  width: 1.1rem;
  height: 1.1rem;
  flex: none;
  color: var(--ink-amber-1);
}

.bset-phone-window>span:not(.bset-phone-check) {
  display: grid;
  gap: 0.05rem;
  flex: 1;
  min-width: 0;
}

.bset-phone-window strong {
  font-size: 0.86rem;
  font-weight: 650;
}

.bset-phone-window small {
  font-size: 0.75rem;
  color: var(--muted, var(--muted-2));
}

.bset-phone-check {
  flex: none;
  display: grid;
  place-items: center;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 5px;
  border: 1px solid var(--edge-g40);
}

.bset-phone-window.on .bset-phone-check {
  background: var(--bset-accent);
  border-color: var(--bset-accent-ink);
  color: #10131a;
}

.bset-phone-check svg {
  width: 0.75rem;
  height: 0.75rem;
  stroke-width: 3;
}

.bset-phone-cta {
  display: block;
  margin-top: 0.5rem;
  padding: 0.7rem;
  border-radius: 10px;
  background: var(--bset-accent);
  color: #10131a;
  font-weight: 750;
  text-align: center;
}

.bset-phone-empty {
  display: grid;
  justify-items: center;
  gap: 0.35rem;
  padding: 1.5rem 0.5rem;
  text-align: center;
}

.bset-phone-empty svg {
  width: 1.5rem;
  height: 1.5rem;
  color: var(--ink-amber-1);
}

.bset-phone-empty strong {
  font-size: 0.95rem;
}

.bset-phone-empty p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.45;
}

.bset-tipcard,
.bset-recurring {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem 1.1rem;
  border: 1px solid var(--bset-line);
  border-radius: 16px;
  background: var(--bset-card);
}

.bset-section-body>.bset-recurring {
  margin-top: 1rem;
}

.bset-tipcard>svg,
.bset-recurring>svg {
  width: 1.25rem;
  height: 1.25rem;
  flex: none;
  color: var(--ink-amber-1);
  margin-top: 0.1rem;
}

.bset-recurring>svg {
  color: var(--ink-violet-1);
}

.bset-tipcard>div,
.bset-recurring>div {
  min-width: 0;
  flex: 1;
}

.bset-tipcard strong,
.bset-recurring strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 650;
}

.bset-tipcard p,
.bset-recurring p {
  margin: 0.25rem 0 0.55rem;
  font-size: 0.83rem;
  color: var(--muted, var(--muted-2));
  line-height: 1.45;
}

.bset-tipcard a,
.bset-recurring-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--bset-accent-ink);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 650;
  text-decoration: none;
  cursor: pointer;
}

.bset-tipcard a:hover,
.bset-recurring-link:hover {
  text-decoration: underline;
}

.bset-tipcard a svg,
.bset-recurring-link svg {
  width: 0.85rem;
  height: 0.85rem;
}

.bset-recurring-form {
  display: grid;
  gap: 0.6rem;
}

.bset-recurring-form label {
  display: grid;
  gap: 0.25rem;
}

.bset-recurring-form label span {
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted, var(--muted-2));
}

.bset-recurring-actions {
  display: flex;
  gap: 0.5rem;
}

.bset-recurring-note {
  margin: 0 !important;
  font-size: 0.76rem !important;
}

.bset-recurring-msg {
  margin: 0.5rem 0 0 !important;
  font-size: 0.8rem !important;
  color: var(--ink-green-2) !important;
}

/* --- sticky save bar --- */
.bset-savebar {
  position: sticky;
  bottom: 1rem;
  z-index: 45;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 0.85rem 1.15rem;
  border: 2px solid var(--cedge-orange-38);
  border-radius: 16px;
  background: rgba(9, 18, 30, 0.97);
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.55);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}

.bset-savebar>p {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  margin: 0;
}

.bset-savebar>p>svg {
  width: 1.35rem;
  height: 1.35rem;
  flex: none;
  color: var(--bset-accent-ink);
}

.bset-savebar>p span {
  display: grid;
  gap: 0.1rem;
}

.bset-savebar strong {
  font-size: 0.95rem;
  font-weight: 650;
}

.bset-savebar small {
  font-size: 0.8rem;
  color: var(--muted, var(--muted-2));
}

.bset-savebar>div {
  display: flex;
  gap: 0.55rem;
}

.bset-saved {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-size: 0.85rem;
  color: var(--ink-green-2);
}

.bset-saved svg {
  width: 1rem;
  height: 1rem;
}

@media (max-width: 1080px) {
  .bset-body {
    grid-template-columns: minmax(0, 1fr);
  }

  /* Preview becomes a disclosure above the settings instead of a full replica
     below the longest accordion. */
  .bset-rail {
    position: static;
    order: -1;
  }

  .bset-preview-toggle {
    display: flex;
  }

  .bset-preview {
    display: none;
  }

  .bset-preview.mobile-open {
    display: block;
  }
}

@media (max-width: 860px) {

  /* Seven across stops fitting long before the page does. */
  .bset-daygrid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .bset-head h1 {
    white-space: normal;
  }
}

@media (max-width: 640px) {
  .bset-summary {
    display: none;
  }

  .bset-mobile-summary {
    display: block;
  }

  .bset-daygrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .bset-master {
    gap: 0.9rem;
  }

  .bset-master-status {
    padding-left: 0;
    border-left: 0;
    border-top: 1px solid var(--bset-line);
    padding-top: 0.75rem;
  }

  .bset-section-head {
    padding: 0.9rem 1rem;
  }

  .bset-section-badge {
    padding: 0.18rem 0.4rem;
    font-size: 0.6rem;
  }

  .bset-section-body {
    padding: 0.25rem 1rem 1.1rem;
  }

  .bset-workhours {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .bset-workhours a {
    flex-basis: 100%;
    padding-left: 2.7rem;
  }

  .bset-savebar {
    position: fixed;
    left: 0.75rem;
    right: 0.75rem;
    bottom: 0.75rem;
  }

  .bset-savebar>div {
    flex: 1 1 100%;
  }

  .bset-savebar>div .btn {
    flex: 1;
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {

  .bset-card,
  .bset-summary-item,
  .bset-day,
  .bset-window,
  .bset-chev,
  .bset-preview-toggle>svg,
  .bset-switch-track,
  .bset-switch-track>span {
    transition: none;
  }
}

/* Applied for ~1.5s by revealRow() when a map pin points at a record, so the
   row you were sent to identifies itself instead of leaving you to work out
   which of twenty it was. Outline rather than border: it doesn't reflow the
   row, so nothing shifts under the cursor as it fades. */
.row-revealed {
  animation: row-reveal-flash 1.5s ease-out 1;
  border-radius: 12px;
}

@keyframes row-reveal-flash {
  0% {
    outline: 2px solid rgba(255, 122, 41, 0.9);
    outline-offset: 2px;
    background-color: rgba(255, 122, 41, 0.16);
  }

  70% {
    outline: 2px solid rgba(255, 122, 41, 0.5);
    outline-offset: 2px;
    background-color: rgba(255, 122, 41, 0.08);
  }

  100% {
    outline: 2px solid rgba(255, 122, 41, 0);
    outline-offset: 2px;
    background-color: transparent;
  }
}

@media (prefers-reduced-motion: reduce) {

  /* Still mark it — just hold the highlight rather than pulsing it away. */
  .row-revealed {
    animation: none;
    outline: 2px solid rgba(255, 122, 41, 0.75);
    outline-offset: 2px;
  }
}

/* ===== Clients workspace — four views =====
   One dataset, four shapes, because "who are my customers" is four different
   questions: skim the book, recognise a face, compare and sort, or work one
   person with the list to hand.

   Selecting does something in every view. Motion is transform + opacity only,
   so a 500-row list stays smooth, and all of it is switched off under
   prefers-reduced-motion at the bottom. */

.clients-toolbar {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-bottom: 0.9rem;
}

.clients-toolbar .client-search-bar {
  flex: 1 1 18rem;
  margin: 0;
}

.clients-toolbar .btn {
  flex: none;
}

.clients-repeat-toggle {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.85rem;
  color: rgba(var(--ink-rgb), 0.78);
  white-space: nowrap;
  cursor: pointer;
}

.clients-repeat-toggle input {
  accent-color: #ff7a21;
  width: 1rem;
  height: 1rem;
}

/* --- the initials chip, shared by every view --- */
/* ---------------------------------------------------------------------------
   Initials-circle palette, shared by Clients and Crew & Labor

   Every avatar being the same orange meant the circle carried no information:
   in a list of thirty-odd people you read two letters to find a row you had
   already scrolled past. See lib/avatar-tone.ts for how a person gets a tone —
   the short version is that it is stable, so the same person is the same colour
   everywhere and after a refresh.

   The palette lives here, not in the component, so a tone is one number
   crossing the wire and so the Crew skins keep overriding what they already
   override. It is one hue per tone with fixed saturation and lightness, which
   is what stops twelve colours looking like twelve accidents.

   Hues deliberately skip the app's signal bands: orange is the brand accent,
   amber means a warning, red means danger and green means money agreed. An
   avatar is an identity, never a status, and must not be mistaken for one.
--------------------------------------------------------------------------- */

[data-avatar-tone] {
  --avatar-bg: hsl(var(--avatar-h) 48% 24%);
  --avatar-fg: hsl(var(--avatar-h) 86% 80%);
  --avatar-line: hsl(var(--avatar-h) 46% 44%);
}

[data-avatar-tone='0'] {
  --avatar-h: 168;
}

[data-avatar-tone='1'] {
  --avatar-h: 246;
}

[data-avatar-tone='2'] {
  --avatar-h: 202;
}

[data-avatar-tone='3'] {
  --avatar-h: 312;
}

[data-avatar-tone='4'] {
  --avatar-h: 188;
}

[data-avatar-tone='5'] {
  --avatar-h: 274;
}

[data-avatar-tone='6'] {
  --avatar-h: 330;
}

[data-avatar-tone='7'] {
  --avatar-h: 216;
}

[data-avatar-tone='8'] {
  --avatar-h: 292;
}

[data-avatar-tone='9'] {
  --avatar-h: 348;
}

[data-avatar-tone='10'] {
  --avatar-h: 230;
}

[data-avatar-tone='11'] {
  --avatar-h: 258;
}

.client-avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 50%;
  /* Falls back to the original orange, so any avatar that never gets a tone —
     an empty state, a row built somewhere this hasn't reached — looks exactly
     as it did rather than losing its colour entirely. */
  border: 1px solid var(--avatar-line, var(--cedge-orange-37));
  background: var(--avatar-bg, linear-gradient(135deg, rgba(255, 122, 33, 0.3), rgba(255, 209, 102, 0.14)));
  color: var(--avatar-fg, #ffd7b8);
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.client-avatar.small {
  width: 2.1rem;
  height: 2.1rem;
  font-size: 0.7rem;
}

.client-avatar.large {
  width: 3.4rem;
  height: 3.4rem;
  font-size: 1.05rem;
}

/* --- Cards --- */
.client-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr));
  gap: 0.7rem;
  max-height: 34rem;
  overflow-y: auto;
  padding: 0.15rem;
}

.client-card {
  display: grid;
  gap: 0.3rem;
  padding: 0.9rem;
  border: 1px solid var(--edge-t09);
  border-radius: 14px;
  background: rgba(var(--tint), 0.025);
  text-decoration: none;
  color: inherit;
  transition: transform 0.18s cubic-bezier(0.2, 0.9, 0.3, 1.2), border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.client-card:hover,
.client-card.is-selected {
  transform: translateY(-4px);
  border-color: var(--cedge-orange-17);
  background: rgba(255, 138, 61, 0.06);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.4);
}

.client-card:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.85);
  outline-offset: 3px;
}

.client-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.client-card-name {
  font-size: 0.98rem;
  font-weight: 780;
  letter-spacing: -0.01em;
}

.client-card-contact {
  font-size: 0.78rem;
  color: var(--mute-i60);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.client-card-stats {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.25rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--rule-t08);
  font-size: 0.82rem;
}

.client-card-total {
  font-weight: 800;
  color: var(--accent-ink);
  font-variant-numeric: tabular-nums;
}

.client-card-last {
  font-size: 0.72rem;
  color: var(--mute-i45);
}

/* --- Table --- */
.client-table-wrap {
  max-height: 34rem;
  overflow: auto;
  border: 1px solid var(--edge-t09);
  border-radius: 14px;
}

.client-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 40rem;
}

.client-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 0.55rem 0.7rem;
  border-bottom: 1px solid var(--rule-t12);
  background: var(--bg-3);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mute-i60);
  text-align: left;
}

.client-table thead th.num,
.client-table td.num {
  text-align: right;
}

.client-table thead button {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  cursor: pointer;
}

.client-table thead button span {
  opacity: 0.5;
  font-size: 0.7em;
}

.client-table thead button:hover {
  color: #fff;
}

.client-table td {
  padding: 0.5rem 0.7rem;
  border-bottom: 1px solid var(--rule-t06);
  font-size: 0.86rem;
}

.client-table tbody tr {
  transition: background 0.14s ease, box-shadow 0.14s ease;
}

.client-table tbody tr:hover,
.client-table tbody tr.is-selected {
  background: rgba(255, 138, 61, 0.07);
  box-shadow: inset 3px 0 0 #ff7a21;
}

.client-table-name {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: inherit;
  text-decoration: none;
  font-weight: 700;
}

.client-table-name:hover {
  color: var(--accent-ink);
}

.client-table-contact {
  color: var(--mute-i62);
  font-size: 0.8rem;
}

/* --- Focus: list beside an open customer --- */
.client-focus {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.8rem;
}

@media (min-width: 900px) {
  .client-focus {
    grid-template-columns: minmax(0, 20rem) minmax(0, 1fr);
    align-items: start;
  }
}

.client-focus-list {
  display: grid;
  gap: 0.3rem;
  align-content: start;
  max-height: 34rem;
  overflow-y: auto;
  padding: 0.15rem;
}

.client-focus-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  padding: 0.55rem 0.6rem;
  border: 1px solid transparent;
  border-radius: 11px;
  background: rgba(var(--tint), 0.02);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 0.15s cubic-bezier(0.2, 0.9, 0.3, 1.2), background 0.15s ease, border-color 0.15s ease;
}

.client-focus-row:hover {
  background: rgba(var(--tint), 0.05);
  transform: translateX(2px);
}

.client-focus-row.is-selected {
  border-color: var(--cedge-orange-17);
  background: rgba(255, 138, 61, 0.1);
  transform: translateX(4px);
}

.client-focus-row:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.8);
  outline-offset: 2px;
}

.client-focus-who {
  display: grid;
  gap: 0.05rem;
  min-width: 0;
}

.client-focus-who strong {
  font-size: 0.87rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.client-focus-who small {
  font-size: 0.72rem;
  color: var(--mute-i55);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.client-focus-total {
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--accent-ink);
  font-variant-numeric: tabular-nums;
}

/* Remounted on every selection (keyed by id), so this entrance plays each time
   — the movement is what tells you the click landed. */
.client-focus-pane {
  padding: 1.1rem 1.2rem;
  border: 1px solid var(--cedge-orange-44);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(255, 138, 61, 0.07), rgba(var(--tint), 0.02));
  animation: client-focus-in 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.05);
}

@keyframes client-focus-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.995);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.client-focus-head {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-bottom: 0.9rem;
}

.client-focus-head h3 {
  margin: 0;
  font-size: 1.15rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.client-focus-head p {
  margin: 0.15rem 0 0;
  font-size: 0.85rem;
  color: var(--mute-i62);
}

.client-focus-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin: 0 0 0.9rem;
}

.client-focus-stats div {
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--edge-t09);
  border-radius: 12px;
  background: rgba(var(--tint), 0.03);
}

.client-focus-stats dt {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mute-i55);
}

.client-focus-stats dd {
  margin: 0.1rem 0 0;
  font-size: 1.05rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.client-focus-address {
  margin: 0 0 0.9rem;
  font-size: 0.85rem;
  color: rgba(var(--ink-rgb), 0.7);
}

.client-focus-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

/* --- Follow up: banded by silence ---------------------------------------- */
/* The band colours are SEMANTIC and deliberately not the orange accent, which
   on this page already means money. Green/amber/rose carry state so a column
   reads as "fine" or "chase this" before any of the words are read. */

.client-followup {
  display: grid;
  gap: 0.8rem;
}

.client-followup-headline {
  margin: 0;
  padding: 0.55rem 0.8rem;
  border-radius: 10px;
  border: 1px solid var(--cedge-orange-62);
  background: rgba(217, 164, 65, 0.08);
  font-size: 0.86rem;
  color: var(--ink-amber-7);
}

/* Explicit column counts rather than auto-fit: there are exactly four bands and
   they read as a sequence, so a wrap that leaves three up and one orphaned
   below a column of dead space breaks the shape. */
.client-followup-board {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.8rem;
  align-items: start;
}

@media (min-width: 42rem) {
  .client-followup-board {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 64rem) {
  .client-followup-board {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.client-band {
  --band: rgba(var(--tint), 0.22);
  min-width: 0;
}

.client-band[data-band='booked'] {
  --band: #7fb583;
}

.client-band[data-band='recent'] {
  --band: rgba(var(--grey-3), 0.55);
}

.client-band[data-band='drifting'] {
  --band: #d9a441;
}

.client-band[data-band='unbooked'] {
  --band: #d2757c;
}

.client-band-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--band);
}

.client-band-head h3 {
  margin: 0;
  font-size: 0.78rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--band);
  font-weight: 800;
}

.client-band-head span {
  font-size: 0.78rem;
  color: var(--mute-i55);
  font-variant-numeric: tabular-nums;
}

.client-band-note {
  margin: 0.5rem 0 0.6rem;
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--mute-i50);
}

.client-band-empty {
  margin: 0;
  font-size: 0.8rem;
  color: var(--mute-i40);
  font-style: italic;
}

.client-band-stack {
  display: grid;
  gap: 0.4rem;
}

.client-band-card {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.55rem 0.65rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t09);
  border-left: 3px solid var(--band);
  background: rgba(var(--tint), 0.04);
  color: inherit;
  text-decoration: none;
}

.client-band-card:hover,
.client-band-card:focus-visible {
  background: rgba(var(--tint), 0.07);
  border-color: var(--edge-t16);
  border-left-color: var(--band);
  outline: none;
}

.client-band-card:focus-visible {
  box-shadow: 0 0 0 2px rgba(255, 122, 33, 0.55);
}

.client-band-who {
  min-width: 0;
  flex: 1;
}

.client-band-who strong {
  display: block;
  font-size: 0.87rem;
  font-weight: 650;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.client-band-who small {
  display: block;
  font-size: 0.74rem;
  color: var(--mute-i55);
  font-variant-numeric: tabular-nums;
}

.client-band-flag {
  display: inline-block;
  margin-top: 0.25rem;
  margin-right: 0.25rem;
  padding: 0.06rem 0.4rem;
  border-radius: 4px;
  font-size: 0.68rem;
  font-style: normal;
  border: 1px solid var(--edge-t14);
  color: var(--mute-i60);
}

.client-band-flag[data-tone='warn'] {
  border-color: var(--cedge-red-15);
  background: rgba(210, 117, 124, 0.14);
  color: var(--ink-pink-2);
}

.client-band-total {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--accent);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.client-band-total.is-zero {
  color: var(--mute-i35);
  font-weight: 500;
}

/* --- Add client dialog --- */
.client-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgba(3, 8, 15, 0.74);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  overflow-y: auto;
  animation: client-modal-fade 0.16s ease;
}

@keyframes client-modal-fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.client-modal {
  width: min(34rem, 100%);
  max-height: calc(100vh - 2rem);
  overflow-y: auto;
  border: 1px solid var(--cedge-orange-34);
  border-radius: 18px;
  background: #0d1a29;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
  animation: client-focus-in 0.2s cubic-bezier(0.2, 0.9, 0.3, 1.05);
}

.client-modal>header {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  padding: 1rem 1.15rem 0.7rem;
  border-bottom: 1px solid var(--rule-t10);
}

.client-modal>header h3 {
  margin: 0;
  font-size: 1.1rem;
}

.client-modal>header p {
  margin: 0.25rem 0 0;
  font-size: 0.8rem;
  color: var(--mute-i60);
  line-height: 1.45;
}

.client-modal>header button {
  margin-left: auto;
  flex: none;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  border: 1px solid var(--edge-t18);
  background: rgba(var(--tint), 0.05);
  color: var(--ink-neutral-15);
  font: inherit;
  cursor: pointer;
}

.client-modal-form {
  display: grid;
  gap: 0.75rem;
  padding: 1rem 1.15rem 1.2rem;
}

.client-modal-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.client-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.2rem;
}

@media (max-width: 620px) {
  .client-modal-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .client-focus-stats {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* Every bit of the above is decoration over information that is already there
   in words, so switching it off costs nothing. */
@media (prefers-reduced-motion: reduce) {

  .client-row,
  .client-card,
  .client-focus-row,
  .client-table tbody tr {
    transition: none;
  }

  .client-row:hover,
  .client-row.is-selected,
  .client-card:hover,
  .client-card.is-selected,
  .client-focus-row:hover,
  .client-focus-row.is-selected {
    transform: none;
  }

  .client-focus-pane,
  .client-modal,
  .client-modal-backdrop {
    animation: none;
  }
}

/* CREW OVERVIEW IS THE ONE SCREEN THAT WANTS A CAP, AND KEEPS IT.
   `crew-wide` used to mean "raise the 1100px cap to 1500" — the Review layout
   pins an action rail beside a nine-column table, and at 1100 that left roughly
   650px for a table needing 840, pushing Payment and Payment date off the right
   edge. Now that the app shell fills the screen, a 1500px cap would make this
   class do the opposite of its name, and switching views on a 1920 monitor
   would visibly jump between full width and 1500.

   So the class keeps its meaning and the rule inverts: the views that asked for
   room get the whole screen with everything else, and the ONE view that
   deliberately did not — Overview — keeps the standard column. That was a
   measured decision, not an oversight: it is a 21rem list beside one open
   person, and giving it 1900px strands the pane's buttons a screen-width from
   the list you picked them from. `.crew-shell` is the stable hook; `crew-wide`
   is toggled per view, server-side from the cookie and again on the client. */
.app-main-sidenav .wide-shell.crew-shell:not(.crew-wide) {
  max-width: 1100px;
}

/* The colour of this stop's incoming leg, matching the line on the map. Purely
   a cross-reference — the miles and minutes beside it say the same thing in
   words, and the arrows on the map carry direction. */
.plan-leg-key {
  display: inline-block;
  width: 0.85rem;
  height: 0.3rem;
  margin-right: 0.4rem;
  border-radius: 999px;
  vertical-align: middle;
}

/* Quick Stops, under the day it would land in. Same condensed shape as the
   working-hours panel beside it. */
.extrastop-panel {
  margin-top: 1rem;
  padding: 0.85rem 1.1rem;
}

.extrastop-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.extrastop-copy {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.extrastop-copy strong {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 750;
}

.extrastop-copy small {
  font-size: 0.82rem;
  color: var(--mute-t58);
  line-height: 1.5;
  max-width: 52rem;
}

/* The word is the state; the colour only agrees with it. */
.extrastop-state {
  padding: 0.12rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--edge-g35);
  background: rgba(var(--tint), 0.05);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(var(--tint), 0.65);
}

.extrastop-state[data-state='on'] {
  border-color: var(--cedge-green-24);
  background: rgba(72, 199, 142, 0.14);
  color: var(--good);
}

.extrastop-state[data-state='locked'] {
  border-color: var(--cedge-amber-13);
  background: rgba(255, 209, 102, 0.12);
  color: var(--warn);
}

.extrastop-panel[data-state='on'] {
  border-color: var(--cedge-green-35);
}

.extrastop-panel[data-state='locked'] {
  border-color: var(--cedge-amber-6);
}

.extrastop-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

/* ---------------------------------------------------------------------------
   Fill a gap with a nearby lead (Plan my day)

   The panel that suggests texting a waiting lead about a hole in today's route.
   Styled quieter than the route itself on purpose: it is an opportunity, not a
   commitment, and it sits under the day rather than competing with it.
   --------------------------------------------------------------------------- */

.offer-panel {
  margin-top: 1rem;
}

.offer-head {
  margin-bottom: 0.9rem;
}

.offer-head h2 {
  margin: 0 0 0.35rem;
  font-size: 1.15rem;
}

.offer-head p {
  margin: 0;
  max-width: 60ch;
  font-size: 0.86rem;
  line-height: 1.55;
  color: var(--mute-t60);
}

.offer-empty {
  margin: 0;
  padding: 0.9rem 1rem;
  border: 1px dashed var(--edge-g22);
  border-radius: 12px;
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--mute-t55);
  max-width: 62ch;
}

/* -- Suggestions ---------------------------------------------------------- */

.offer-suggestions,
.offer-waiting,
.offer-settled {
  list-style: none;
  margin: 0 0 0.9rem;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.offer-suggestions>li {
  border: 1px solid var(--edge-g18);
  border-radius: 14px;
  background: rgba(var(--tint), 0.02);
  padding: 0.85rem 1rem;
  transition: border-color 140ms ease, background 140ms ease;
}

.offer-suggestions>li[data-open] {
  border-color: var(--cedge-orange-8);
  background: rgba(255, 122, 33, 0.05);
}

.offer-suggestion-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.offer-suggestion-copy {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
  flex: 1 1 22rem;
}

.offer-suggestion-copy strong {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  font-size: 0.95rem;
  font-weight: 750;
}

.offer-suggestion-copy strong a {
  color: inherit;
  text-decoration: none;
}

.offer-suggestion-copy strong a:hover {
  text-decoration: underline;
}

.offer-suggestion-copy small {
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

/* The gap itself is the reason this row exists, so it reads brighter than the
   address line above it. */
.offer-slot {
  color: rgba(var(--tint), 0.72) !important;
}

.offer-chip {
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  border: 1px solid var(--edge-g30);
  background: rgba(var(--tint), 0.05);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--mute-t62);
}

/* -- The draft ------------------------------------------------------------ */

.offer-draft {
  margin-top: 0.9rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-g16);
  display: grid;
  gap: 0.85rem;
}

.offer-draft textarea {
  width: 100%;
  min-height: 4.5rem;
  resize: vertical;
  line-height: 1.5;
}

.offer-draft .field>small {
  font-size: 0.75rem;
  color: var(--mute-t45);
}

.offer-draft .field>small.warn {
  color: var(--ink-amber-2);
}

.offer-draft-row {
  display: flex;
  gap: 0.85rem;
  flex-wrap: wrap;
}

.offer-draft-row .field {
  flex: 1 1 11rem;
  min-width: 0;
}

/* Exactly what lands on their phone, envelope and all. Monospace-ish framing so
   it reads as a quoted message rather than as more page text. */
.offer-preview {
  border: 1px solid var(--edge-g22);
  border-radius: 12px;
  background: rgba(10, 16, 28, 0.55);
  padding: 0.7rem 0.85rem;
}

.offer-preview>span {
  display: block;
  margin-bottom: 0.35rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--mute-t45);
}

.offer-preview p {
  margin: 0;
  font-size: 0.86rem;
  line-height: 1.6;
  color: rgba(var(--tint), 0.86);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* -- Holding -------------------------------------------------------------- */

.offer-waiting>li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 0.8rem 1rem;
  border: 1px solid var(--cedge-amber-6);
  border-radius: 14px;
  background: rgba(255, 209, 102, 0.07);
}

.offer-waiting-copy {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
  flex: 1 1 24rem;
}

.offer-waiting-copy strong {
  font-size: 0.93rem;
  font-weight: 750;
}

.offer-waiting-copy small {
  font-size: 0.81rem;
  line-height: 1.5;
  color: var(--mute-t62);
}

/* -- Settled -------------------------------------------------------------- */

.offer-settled>li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.7rem 0.9rem;
  border: 1px solid var(--edge-g16);
  border-radius: 12px;
}

.offer-settled>li>div {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.offer-settled strong {
  font-size: 0.9rem;
  font-weight: 700;
}

.offer-settled strong a {
  color: inherit;
  text-decoration: none;
}

.offer-settled strong a:hover {
  text-decoration: underline;
}

.offer-settled small {
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

/* The word carries the state; colour only agrees with it. */
.offer-status {
  flex: 0 0 auto;
  margin-top: 0.1rem;
  padding: 0.14rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--edge-g35);
  background: rgba(var(--tint), 0.05);
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--mute-t62);
  white-space: nowrap;
}

.offer-status[data-status='accepted'] {
  border-color: var(--cedge-green-24);
  background: rgba(72, 199, 142, 0.14);
  color: var(--good);
}

.offer-status[data-status='accepted_late'] {
  border-color: var(--cedge-amber-13);
  background: rgba(255, 209, 102, 0.12);
  color: var(--warn);
}

.offer-settled>li[data-status='accepted'] {
  border-color: var(--cedge-green-36);
}

@media (max-width: 760px) {
  .offer-suggestion-head>button {
    width: 100%;
  }

  .offer-waiting>li form {
    width: 100%;
  }

  .offer-waiting>li form button {
    width: 100%;
  }
}

.offer-said {
  font-style: italic;
  color: rgba(var(--tint), 0.68) !important;
}

/* --- recurring visits on the calendar --------------------------------------
   A visit a recurring plan will create on the morning of the day. It is not a
   job yet, so it must not look like one: dashed, quieter, and carrying a ↻ that
   says why. Never the same solid chip as real work — an owner glancing at the
   month has to be able to tell what's actually booked.
   -------------------------------------------------------------------------- */

.calendar-planned-chip {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  width: 100%;
  padding: 0.16rem 0.35rem;
  border: 1px dashed var(--edge-g45);
  border-radius: 5px;
  background: rgba(var(--grey-1), 0.06);
  color: var(--dim-grey-1-3);
  font-size: 0.66rem;
  line-height: 1.3;
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
}

.calendar-planned-chip:hover {
  border-color: var(--cedge-orange-17);
  background: rgba(255, 138, 61, 0.1);
  color: #fff;
}

.calendar-planned-chip:focus-visible {
  outline: 2px solid rgba(255, 122, 41, 0.75);
  outline-offset: 1px;
}

.calendar-planned-mark {
  flex: 0 0 auto;
  font-size: 0.72rem;
  opacity: 0.85;
}

.calendar-planned-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Agenda rows keep the columns of a real row so the two line up, but the same
   dashed treatment says which is which. */
.calendar-agenda-planned {
  border-style: dashed !important;
  background: rgba(var(--grey-1), 0.05) !important;
  text-decoration: none;
}

.calendar-agenda-planned .calendar-planned-mark {
  margin-right: 0.3rem;
}

.calendar-planned-note {
  flex: 1;
  margin: 0;
  align-self: center;
  font-size: 0.76rem;
  line-height: 1.5;
  color: rgba(var(--grey-5), 0.95);
}

.calendar-planned-note .calendar-planned-mark {
  margin-right: 0.35rem;
}

.calendar-planned-note a {
  color: var(--accent-ink);
}

.calendar-days-row {
  gap: 0.75rem;
  align-items: center;
}

/* Quick Stop's on/off state, in the sidebar.
   It is the one automation that can put a stranger on today's route, and its
   switch is three clicks deep in Settings — so the rail says which way it's set
   from every page in the app. The WORD carries the state; the colour only
   agrees with it, so it still reads for anyone who can't tell red from green. */
.sidenav-state {
  margin-left: auto;
  display: inline-grid;
  place-items: center;
  padding: 0.1rem 0.4rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.6rem;
  font-weight: 900;
  letter-spacing: 0.07em;
  line-height: 1.5;
}

.sidenav-state[data-state='on'] {
  border-color: var(--cedge-green-24);
  background: rgba(72, 199, 142, 0.16);
  color: var(--good);
}

.sidenav-state[data-state='off'] {
  border-color: var(--cedge-red-16);
  background: rgba(255, 107, 107, 0.14);
  color: var(--ink-red-5);
}

.sidenav-state[data-state='paused'] {
  border-color: var(--cedge-amber-13);
  background: rgba(255, 209, 102, 0.14);
  color: var(--warn);
}

/* A count and a state pill on the same row would both claim the right edge. */
.sidenav-link .sidenav-state+.sidenav-count {
  margin-left: 0.3rem;
  margin-right: 0;
}

/* A row carrying a state gets it in the row itself, not only in the pill: an
   outlined row and a green icon read across the rail at a glance, where a
   0.6rem pill has to be looked for. ON only — "live and taking work" is the
   fact worth a colour, and painting every OFF automation red would turn the
   rail into a wall of alarms for someone who has simply not switched them on.
   The pill is still the thing that SAYS which way it is set, in either
   direction.

   A full ring rather than the left bar this used to be. The bar wanted the same
   three pixels the ACTIVE row uses for a different meaning, so the two could
   never be told apart when they sat next to each other — and they do, because
   Schedule is directly above Online Booking. An outline is a shape the active
   row never takes. */
.sidenav-link[data-state='on'] {
  box-shadow: inset 0 0 0 1px rgba(63, 191, 135, 0.5);
}

.sidenav-link[data-state='on'] .sidenav-ic {
  color: var(--ink-green-11);
}

.sidenav-link[data-state='on']:hover .sidenav-ic {
  color: var(--ink-green-12);
}

/* "You are here" outranks "this is on". One channel, one meaning — and the
   pill goes on saying ON regardless, so nothing is lost by the active row
   keeping the accent. Specificity, not source order, decides it. */
.sidenav-link.active[data-state] {
  box-shadow: inset 3px 0 0 var(--accent), inset 0 0 0 1px rgba(255, 122, 33, 0.22);
}

.sidenav-link.active[data-state] .sidenav-ic {
  color: var(--accent);
}

/* One line, always. The row is a fixed width while the label is not — at a
   larger browser font or an OS display scale above 100%, "Online Booking" (the
   longest label that also carries a pill) wrapped under its own icon. The label
   truncates instead; the pill and the icon never give up their space. */
.sidenav-link>span:not([class]) {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.sidenav-link .sidenav-ic,
.sidenav-link .sidenav-state,
.sidenav-link .sidenav-count,
.sidenav-link .sidenav-total {
  flex: none;
}

/* Quick Stops reuses the booking summary cards, but as links rather than
   in-page jumps — an anchor would otherwise pick up the global link colour and
   underline and stop matching the buttons beside it. */
a.bset-card {
  color: inherit;
  text-decoration: none;
}

/* The empty queue now sits in a panel of its own rather than under a heading,
   so it no longer needs to clear one — the panel padding is the only padding. */
.quick-stop-empty-panel {
  background: radial-gradient(circle at 50% 30%, rgba(255, 122, 33, 0.08), transparent 60%), var(--bg-gradient-card, var(--bg-elevated));
  border: 1px dashed rgba(var(--tint), 0.18);
}

.quick-stop-empty-panel .quick-stop-empty {
  margin-top: 0;
  padding: 1.6rem 1rem;
}

/* Crew & Labor Focus theme — the page-level furniture that is not in the crew
   CSS module. The panel surfaces lift slightly so the bordered cards inside
   them read as sitting ON something rather than being cut out of it. */
.crew-focus .workspace-section-card {
  border-radius: 18px;
  border-color: var(--edge-g20);
}

.crew-focus .stat-ticker {
  border-radius: 16px;
  border-color: var(--edge-g20);
}

.crew-focus .stat-ticker-value {
  font-size: 1.45rem;
  letter-spacing: -0.02em;
}

/* ==========================================================================
   Crew & Labor SKINS.

   Two token sets. Everything structural is in crew.module.css against the
   page's existing containers; this file only says what colour the tokens are
   and dresses the shell furniture that lives outside the module.

   Both stay on a dark ground. A light Crew & Labor inside an otherwise dark
   dashboard would be one bright page in a dark app, which reads as a bug
   rather than a choice — a light theme is a site-wide job, not a page one.
   ========================================================================== */

/* --- Daylight: the standard palette, but crisper -------------------------
   Brighter surfaces, a stronger edge and higher text contrast, for reading in
   a lit cab or through a windscreen's glare. Not the light theme it started
   as: same ground, more separation. */
.crew-skin-daylight {
  --skin-surface: rgba(var(--tint), 0.085);
  --skin-line: rgba(190, 208, 230, 0.34);
  --skin-ink: #ffffff;
  --skin-muted: #e4e9f0;
  --skin-head: rgba(228, 233, 240, 0.92);
  --skin-accent: #ff9440;
  --skin-accent-soft: rgba(255, 148, 64, 0.18);
  --skin-radius: 12px;
  --skin-head-track: 0.09em;
}

/* Secondary text is the first thing to disappear in bright light, so the
   muted greys the standard page uses get pulled up rather than left alone. */
.crew-skin-daylight .workspace-section-card {
  border-color: var(--cedge-sky-13);
}

.crew-skin-daylight .stat-ticker {
  border-color: var(--cedge-sky-13);
  background: rgba(var(--tint), 0.07);
}

.crew-skin-daylight .stat-ticker-label {
  color: rgba(var(--grey-6), 0.8);
}

.crew-skin-daylight .eyebrow {
  color: rgba(var(--grey-6), 0.85);
}

/* --- Blueprint: a drawing sheet ------------------------------------------
   Cyan for everything structural, monospaced figures, a faint grid and a
   register tick on each panel. One rule holds it honest: money stays orange,
   because a figure that means dollars has to keep meaning dollars whichever
   skin it is wearing. */
.crew-skin-blueprint {
  --skin-surface: rgba(94, 200, 240, 0.05);
  --skin-line: rgba(94, 200, 240, 0.26);
  --skin-ink: #e6f3fa;
  --skin-muted: #a8ccdf;
  --skin-head: #5ec8f0;
  --skin-accent: #5ec8f0;
  --skin-accent-soft: rgba(94, 200, 240, 0.14);
  --skin-radius: 3px;
  --skin-head-track: 0.12em;
  --skin-figure-font: ui-monospace, 'Cascadia Mono', 'SF Mono', Menlo, Consolas, monospace;
  --skin-label-font: var(--skin-figure-font);
  --skin-avatar-radius: 3px;

  background-color: #06192c;
  background-image:
    linear-gradient(rgba(94, 200, 240, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 200, 240, 0.05) 1px, transparent 1px);
  background-size: 26px 26px;
  /* Pinned to the top-left of the shell so the grid doesn't crawl as the page
     scrolls — a drawing sheet's grid belongs to the sheet, not the window. */
  background-attachment: local;
}

.crew-skin-blueprint .workspace-section-card {
  border-color: var(--cedge-teal-18);
  border-radius: 3px;
  background: rgba(6, 25, 44, 0.72);
}

.crew-skin-blueprint .stat-ticker {
  border-color: var(--cedge-teal-18);
  border-radius: 3px;
  background: rgba(94, 200, 240, 0.05);
}

.crew-skin-blueprint .stat-ticker-label {
  color: var(--ink-sky-9);
  letter-spacing: 0.12em;
}

.crew-skin-blueprint .stat-ticker-value {
  font-family: ui-monospace, 'Cascadia Mono', 'SF Mono', Menlo, Consolas, monospace;
}

.crew-skin-blueprint .eyebrow {
  color: var(--ink-sky-10);
  letter-spacing: 0.16em;
}

/* --- Both skins, on paper -------------------------------------------------
   The comment at the top of this section says both skins stay on a dark ground
   and that a light theme would be a site-wide job. It became one; nothing came
   back here. The skin tokens are declared on <main> — the CANVAS, above the
   boundary THE FLIP works at — and custom properties inherit downward only, so
   the flip could never re-point them. A skinned page carried #ffffff ink onto a
   #ffffff sheet: crew names at 1.0:1 in Daylight and 1.13:1 in Blueprint, the
   active tab's own label invisible, and the row buttons getting WORSE on hover
   (--skin-muted -> --skin-ink). Cards and Table views were unaffected, which is
   the tell: they are the two layouts with no :global(.crew-skin) colour rule.

   Re-pointed on the SHEET, not on the shell, for two reasons. A var() inside a
   custom property resolves against the element it is DECLARED on, so a value
   written on the shell would read the canvas's --tint and land right back where
   it started. And anything skinned that is not on a sheet is still standing on
   the dark canvas, where the original values are correct.

   The rules that consume these live in crew.module.css and cannot be reached by
   anything global — but the tokens are declared on a global class, so this is
   enough. The skins keep their identity: radius, letter-spacing, monospaced
   figures, Blueprint's grid and register ticks are all untouched. Only the
   colours that assumed a dark ground move. */
:root[data-theme='light'] .crew-skin .panel,
:root[data-theme='light'] .crew-skin .client-modal,
:root[data-theme='light'] .crew-skin .crew-assign-panel,
:root[data-theme='light'] .crew-skin .unsaved-guard-panel {
  --skin-ink: var(--text);
  --skin-muted: var(--muted);
  --skin-head: var(--muted);
  --skin-line: var(--line);
  --skin-surface: rgba(var(--tint), 0.045);
}

/* Each skin keeps its hue and takes paper's value of it — orange stays orange,
   cyan stays cyan. These are read as text, as a 2px register tick and as the
   selected tab's border, so they have to clear 3:1 as well as 4.5:1. */
:root[data-theme='light'] .crew-skin-daylight .panel,
:root[data-theme='light'] .crew-skin-daylight .client-modal,
:root[data-theme='light'] .crew-skin-daylight .crew-assign-panel,
:root[data-theme='light'] .crew-skin-daylight .unsaved-guard-panel {
  --skin-accent: var(--ink-orange-8);
  --skin-accent-soft: rgba(165, 79, 27, 0.1);
}

:root[data-theme='light'] .crew-skin-blueprint .panel,
:root[data-theme='light'] .crew-skin-blueprint .client-modal,
:root[data-theme='light'] .crew-skin-blueprint .crew-assign-panel,
:root[data-theme='light'] .crew-skin-blueprint .unsaved-guard-panel {
  --skin-accent: var(--ink-sky-10);
  --skin-accent-soft: rgba(24, 112, 145, 0.1);
}

/* A summary card with nowhere to go. It keeps the shape of its siblings so
   the row stays even, but drops the affordances that promise a click. */
.bset-card.is-static {
  cursor: default;
}

.bset-card.is-static:hover {
  border-color: var(--bset-line);
  transform: none;
}

/* ---------------------------------------------------------------------------
   Two-handle range (components/range-slider.tsx)
   Two stacked native range inputs. Only the THUMBS take pointer events, so the
   handle underneath stays grabbable — the usual trick, and the reason this can
   keep native keyboard behaviour.
--------------------------------------------------------------------------- */
.range-slider {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  gap: 0.45rem;
  padding: 0.9rem 1.05rem 0.8rem;
  border: 1px solid var(--cedge-orange-5);
  border-radius: 14px;
  background: rgba(255, 122, 33, 0.055);
}

/* A slow shimmer across the card, so the control reads as live rather than a
   flat box. Long and low-contrast on purpose: this sits beside form fields you
   are trying to read, and anything faster would compete with them. */
.range-slider::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(105deg, transparent 38%, rgba(255, 170, 100, 0.14) 50%, transparent 62%);
  transform: translateX(-140%);
  animation: rangeShimmer 6.5s cubic-bezier(0.45, 0, 0.25, 1) infinite;
}

@keyframes rangeShimmer {

  0%,
  58% {
    transform: translateX(-140%);
  }

  92%,
  100% {
    transform: translateX(140%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .range-slider::before {
    animation: none;
    opacity: 0;
  }
}

.range-slider-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.range-slider-label {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-orange-8);
}

.range-slider-value {
  font-size: 1rem;
  font-weight: 800;
  color: var(--ink-orange-8);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 3rem tall, not 2.1. The whole row is the grab area, and a thumb you have to
   hit within a couple of pixels vertically is the difference between dragging a
   fee and nudging the page. */
.range-slider-track {
  position: relative;
  height: 3rem;
}

.range-slider-track::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 7px;
  margin-top: -3.5px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.14);
}

.range-slider-fill {
  position: absolute;
  top: 50%;
  height: 7px;
  margin-top: -3.5px;
  left: var(--low);
  right: calc(100% - var(--high));
  border-radius: 999px;
  background: linear-gradient(90deg, #ff5a1f, #ff9a52);
}

.range-slider-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 3rem;
  margin: 0;
  padding: 0;
  background: none;
  -webkit-appearance: none;
  appearance: none;
  pointer-events: none;
  /* only the thumbs are grabbable */
}

.range-slider-input:focus {
  outline: none;
}

/* 2rem handles. They were 1.35rem, which is under the 44px touch target every
   guideline asks for and felt fiddly with a mouse too. */
.range-slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  pointer-events: auto;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  cursor: grab;
  border: 2px solid var(--on-accent);
  background: radial-gradient(circle at 35% 30%, #ffab63, #ff7a21 62%, #f06a12);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.6), 0 0 14px rgba(255, 122, 33, 0.5);
}

.range-slider-input::-moz-range-thumb {
  pointer-events: auto;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  cursor: grab;
  border: 2px solid var(--on-accent);
  background: radial-gradient(circle at 35% 30%, #ffab63, #ff7a21 62%, #f06a12);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.6), 0 0 14px rgba(255, 122, 33, 0.5);
}

.range-slider-input:focus-visible::-webkit-slider-thumb {
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.55);
}

.range-slider-input:focus-visible::-moz-range-thumb {
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.55);
}

.range-slider-input:active::-webkit-slider-thumb {
  cursor: grabbing;
}

/* The value that travels with its handle. */
.range-slider-bubbles {
  position: relative;
  height: 1.1rem;
}

.range-slider-bubble {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--ink-neutral-9);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.8);
}

.range-slider-ends {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
  color: var(--mute-i42);
  font-variant-numeric: tabular-nums;
}

/* Unsaved-changes confirmation (components/unsaved-guard.tsx). */
.unsaved-guard-backdrop {
  position: fixed;
  inset: 0;
  z-index: 260;
  display: grid;
  place-items: center;
  padding: 1.25rem;
  background: rgba(3, 8, 15, 0.74);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}

.unsaved-guard-panel {
  width: min(30rem, 100%);
  display: grid;
  gap: 0.6rem;
  padding: 1.25rem;
  border: 1px solid var(--cedge-orange-9);
  border-radius: 16px;
  background: #101824;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
}

.unsaved-guard-panel h3 {
  margin: 0;
  color: #fff;
  font-size: 1.15rem;
}

.unsaved-guard-panel p {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.unsaved-guard-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.5rem;
}

.unsaved-guard-actions .btn {
  flex: 1 1 10rem;
}

/* A closed drawer is HIDDEN, not unmounted — its inputs still have to reach the
   form action, or saving would write blanks over whatever you couldn't see.
   .bset-section-body sets a display, which would otherwise beat [hidden]. */
.bset-section-body[hidden] {
  display: none;
}

/* "How Quick Stops works" — the pitch, folded away once the feature is live.
   A native <details>, so it needs no client JS on a server-rendered page and
   Ctrl+F still finds what is inside it. */
.es-how {
  padding: 0;
  overflow: hidden;
}

.es-how-summary {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.15rem;
  cursor: pointer;
  list-style: none;
  -webkit-user-select: none;
  user-select: none;
}

.es-how-summary::-webkit-details-marker {
  display: none;
}

.es-how-summary:hover {
  background: rgba(255, 122, 33, 0.05);
}

.es-how-summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.es-how-copy {
  display: grid;
  gap: 0.15rem;
  flex: 1;
  min-width: 0;
}

.es-how-copy strong {
  color: var(--text);
  font-size: 1.02rem;
}

.es-how-copy small {
  color: var(--mute-i55);
  font-size: 0.8rem;
}

.es-how-chev {
  /* --accent-paper, not --accent: this glyph is the open/closed state of the
     disclosure and it sits on the sheet, where #ff7a21 measures 2.61:1. The
     token resolves to var(--accent) in dark, so this is a no-op there. */
  flex: none;
  color: var(--accent-paper);
  font-size: 1.1rem;
  line-height: 1;
  transition: transform 0.18s ease;
}

.es-how[open] .es-how-chev {
  transform: rotate(180deg);
}

.es-how-body {
  padding: 0 1.15rem 1.15rem;
}

/* The explainer brings its own panels; inside the drawer they'd be a panel in a
   panel, so flatten the outer chrome. */
.es-how-body>* {
  margin-top: 0;
}

@media (prefers-reduced-motion: reduce) {
  .es-how-chev {
    transition: none;
  }
}

/* Quick Stops summary configuration chips */
.qs-chip {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.qs-chip:not(.is-static):hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

/* The right-hand end of the toolbar: the hidden-days warning when there is one,
   and the view menu. `nowrap` is deliberate — these two have to stay on the
   nav's line, and the container queries above are what makes room for them
   rather than a second row. Below 640px the whole toolbar is gone. */
.calendar-toolbar-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: nowrap;
  min-width: 0;
  margin-left: auto;
}

/* ---------------------------------------------------------------------------
   Unscheduled job cards, coloured by where they're going
   Same status keys the calendar chips use (.calendar-job-chip.status-*), so a
   card and the chip it becomes are the same colour. The stripe down the left is
   the part that reads at a glance in a narrow rail.
--------------------------------------------------------------------------- */
.schedule-method-row {
  position: relative;
  overflow: hidden;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.schedule-method-row::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--job-tone, rgba(var(--tint), 0.18));
}

.schedule-method-row.status-new_lead {
  --job-tone: #ffd166;
  border-color: var(--cedge-amber-32);
  background: rgba(255, 209, 102, 0.07);
}

.schedule-method-row.status-in_progress {
  --job-tone: #ff8a3d;
  border-color: var(--cedge-orange-63);
  background: rgba(255, 138, 61, 0.075);
}

.schedule-method-row.status-complete {
  --job-tone: #78dc96;
  border-color: var(--cedge-green-37);
  background: rgba(120, 220, 150, 0.07);
}

.schedule-method-row:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 26px -16px rgba(0, 0, 0, 0.9), 0 0 0 1px var(--job-tone);
}

/* A card being dragged should look like it has left the stack. */
.schedule-method-row:has(.schedule-drag-handle.armed) {
  border-color: var(--job-tone);
  background: color-mix(in srgb, var(--job-tone) 14%, transparent);
  box-shadow: 0 0 0 1px var(--job-tone), 0 0 26px -8px var(--job-tone);
}

@media (prefers-reduced-motion: reduce) {
  .schedule-method-row {
    transition: none;
  }

  .schedule-method-row:hover {
    transform: none;
  }
}

/* ---- Accepting a recurring plan on the owner's side ------------------- */
/* Teal, matching the subscription line items in the quote builder, so the plan
   reads as the same object in both places. */
.accept-plan-list {
  display: grid;
  gap: 0.75rem;
}

.accept-plan-card {
  display: grid;
  gap: 0.7rem;
  padding: 0.95rem;
  border: 1px solid var(--cedge-teal-4);
  border-left: 4px solid #2dbed2;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(45, 190, 210, 0.12), rgba(45, 190, 210, 0.02) 62%), rgba(var(--tint), 0.03);
}

.accept-plan-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.accept-plan-head strong {
  font-size: 0.98rem;
  color: var(--text);
}

.accept-plan-head span {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--ink-teal-1);
}

.accept-plan-field {
  display: grid;
  gap: 0.3rem;
  max-width: 20rem;
}

.accept-plan-field>span {
  font-size: 0.78rem;
  font-weight: 700;
  color: rgba(var(--ink-rgb), 0.85);
}

.accept-plan-field input {
  width: 100%;
  min-height: 44px;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--edge-t18);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.25);
  color: inherit;
  font: inherit;
}

.accept-plan-field small {
  font-size: 0.72rem;
  color: var(--mute-i50);
}

.accept-plan-modes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
