}

.accept-plan-modes button {
  display: grid;
  gap: 0.15rem;
  padding: 0.6rem 0.75rem;
  text-align: left;
  cursor: pointer;
  border: 1px solid var(--edge-t16);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.2);
