}

.accept-plan-modes strong {
  font-size: 0.86rem;
}

.accept-plan-modes small {
  font-size: 0.72rem;
  color: var(--mute-i55);
}

.accept-plan-toggle {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
