  background: rgba(var(--tint), 0.08);
}

.ins-opp-icon.is-high {
  color: var(--ink-orange-7);
  background: rgba(255, 122, 33, 0.14);
}

.ins-opp-icon.is-medium {
  color: var(--ink-blue-2);
  background: rgba(74, 144, 226, 0.16);
}

.ins-opp-icon.is-low {
  color: var(--ink-violet-5);
  background: rgba(167, 139, 250, 0.16);
}

.ins-opp-icon .action-btn-ic {
  width: 1.15rem;
  height: 1.15rem;
}

.ins-opp-body {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.ins-opp-titlerow {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.ins-opp-title {
  font-size: 0.92rem;
}

.ins-opp-pri {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.1rem 0.42rem;
  border-radius: 999px;
  white-space: nowrap;
}

.ins-opp-pri.is-high {
  color: var(--ink-orange-7);
  background: rgba(255, 122, 33, 0.14);
}

.ins-opp-pri.is-medium {
  color: var(--ink-blue-2);
  background: rgba(74, 144, 226, 0.16);
}

.ins-opp-pri.is-low {
  color: var(--mute-t55);
  background: rgba(var(--tint), 0.08);
}

.ins-opp-detail {
