  white-space: nowrap;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-ink);
  text-decoration: none;
  background: none;
  border: 0;
  cursor: pointer;
  padding: 0.35rem 0.2rem;
}

.ins-opp-cta:hover {
  text-decoration: underline;
}

@media (max-width: 1100px) {
  .ins-row-actions3 {
