  height: 0.8rem;
  border-radius: 3px;
}

.ins-revsvc-label {
  color: var(--mute-t60);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ins-revsvc-amt {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.ins-revsvc-pct {
  font-variant-numeric: tabular-nums;
  color: var(--mute-t45);
  min-width: 2.6rem;
  text-align: right;
}

.ins-revsvc-note {
  margin-top: 0.6rem;
}

.ins-mkt-summary {
  margin-top: 0.1rem;
}

.ins-mkt-list {
  list-style: none;
  margin: 0.3rem 0 0;
  padding: 0;
  display: grid;
}

.ins-mkt-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem 1rem;
  flex-wrap: wrap;
  padding: 0.55rem 0;
  border-top: 1px solid var(--rule-t09);
}

.ins-mkt-row:first-child {
  border-top: 0;
}

.ins-mkt-when {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.ins-mkt-when strong {
  font-size: 0.9rem;
}

.ins-mkt-stats {
  display: flex;
  align-items: baseline;
  gap: 0.3rem 0.8rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.ins-mkt-stat {
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
}

.ins-mkt-muted {
  font-size: 0.76rem;
  color: var(--mute-t45);
  font-variant-numeric: tabular-nums;
}

.ins-mkt-fail {
  font-size: 0.76rem;
  color: var(--ink-orange-1);
  font-variant-numeric: tabular-nums;
}

.ins-mkt-note {
  margin-top: 0.5rem;
}

@media (max-width: 760px) {
  .ins-revsvc-legend {
    min-width: 100%;
  }

  .ins-mkt-stats {
