/* Executive summary */
/* This class was owned by TWO different components. Settings → Trust wrapped
   the insurance certificate in `.ins-summary` too — "ins" for insurance, landing
   squarely on insights' namespace — and its rule sits ~1,100 lines further down,
   so at equal specificity it won: this card was `display: flex`, not grid.
   That is why the mobile rule below (grid-template-columns: 1fr) did nothing at
   all — you cannot collapse the columns of a flex container — and the headline
   and the revenue breakdown printed on top of each other on a phone. The
   certificate is now .cert-summary. */
.ins-summary {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 1.6rem;
  padding: 1.3rem 1.4rem;
}

/* Was inherited from the certificate rule that used to share this name. A bare
   `1fr` column has a minimum of min-content, so without this the headline
   ("You spent $5,571 more than you collected") sets the column's floor and
   pushes the breakdown off the card. */
.ins-summary-main {
  min-width: 0;
}

.ins-shell .ins-summary-headline {
  margin: 0.35rem 0 1.2rem;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.ins-figures {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
}

.ins-figure {
  display: grid;
  gap: 0.25rem;
  align-content: start;
  padding-right: 0.8rem;
  border-right: 1px solid var(--rule-t09);
}

.ins-figure:last-child {
  border-right: 0;
}

.ins-figure-label {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.ins-figure-value {
  font-size: 1.55rem;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.ins-figure-value.is-positive {
  color: var(--ink-lime-1);
}

.ins-figure-value.is-negative {
  color: var(--ink-orange-1);
}

.ins-caveat {
  margin: 1rem 0 0;
  font-size: 0.8rem;
  line-height: 1.55;
  color: var(--gold-ink);
}

.ins-caveat a {
  color: inherit;
  text-decoration: underline;
}

.ins-breakdown {
  display: grid;
  gap: 0.6rem;
  align-content: start;
  padding-left: 1.6rem;
  border-left: 1px solid var(--rule-t09);
}

.ins-stack {
  display: flex;
  gap: 3px;
  height: 1.5rem;
}

.ins-stack-seg {
  border-radius: 4px;
}

.ins-stack-seg.is-revenue {
  background: #4a90e2;
}

.ins-stack-seg.is-costs {
  background: var(--accent);
}

.ins-stack-seg.is-profit {
  background: #4ade80;
}

.ins-stack-legend {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.6rem;
  font-size: 0.76rem;
  color: var(--mute-t50);
}

.ins-stack-legend span {
  display: grid;
  gap: 0.15rem;
}

.ins-stack-legend b {
  color: var(--text);
  font-size: 0.8rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.ins-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  display: inline-block;
  margin-right: 0.35rem;
}

.ins-dot.is-revenue {
  background: #4a90e2;
}

.ins-dot.is-costs {
  background: var(--accent);
}

.ins-dot.is-profit {
  background: #4ade80;
}

.ins-subfigures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.8rem;
  margin-top: 0.5rem;
  padding-top: 0.8rem;
  border-top: 1px solid var(--rule-t09);
}

.ins-subfigures>div {
  display: grid;
  gap: 0.2rem;
}

.ins-subfigures strong {
  font-size: 1.05rem;
  font-variant-numeric: tabular-nums;
}

/* Card grid */
.ins-row {
  display: grid;
  gap: 1rem;
}

.ins-row-2 {
  grid-template-columns: 1fr 1fr;
}

.ins-row-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ins-shell .ins-card {
  display: grid;
  gap: 0.5rem;
  align-content: start;
  padding: 1.05rem 1.15rem;
}

.ins-card-head {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0 0 0.3rem;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-t55);
}

.ins-chip {
  display: grid;
  place-items: center;
  width: 1.6rem;
  height: 1.6rem;
  flex: none;
  border-radius: 8px;
  font-size: 0.8rem;
}

.ins-chip.is-cash {
  background: rgba(74, 222, 128, 0.14);
  color: var(--ink-green-13);
}

.ins-chip.is-open {
  background: rgba(255, 122, 33, 0.14);
  color: var(--ink-orange-7);
}

.ins-chip.is-chart {
  background: rgba(74, 144, 226, 0.16);
  color: var(--ink-blue-2);
}

.ins-chip.is-value {
  background: rgba(255, 122, 33, 0.14);
  color: var(--ink-orange-7);
}

.ins-chip.is-ok {
  background: rgba(74, 222, 128, 0.14);
  color: var(--ink-green-13);
}

.ins-chip.is-speed {
  background: rgba(74, 144, 226, 0.16);
  color: var(--ink-blue-2);
}

.ins-chip.is-source {
  background: rgba(167, 139, 250, 0.16);
  color: var(--ink-violet-5);
}

.ins-big {
  font-size: 1.7rem;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.ins-mid {
  font-size: 1.25rem;
  font-variant-numeric: tabular-nums;
}

.ins-shell .ins-sub {
  margin: 0;
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--mute-t50);
}

.ins-warn {
  font-size: 0.78rem;
  color: var(--gold-ink);
}

.ins-empty-note {
  margin: 0.3rem 0 0;
  font-size: 0.8rem;
  line-height: 1.55;
  color: var(--mute-t45);
}

.ins-card-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  margin-top: 0.4rem;
  padding-top: 0.7rem;
  border-top: 1px solid var(--rule-t09);
  font-size: 0.78rem;
  color: var(--mute-t45);
}

.ins-card-foot a,
.ins-inline-link {
  color: var(--accent-ink);
  text-decoration: underline;
}

.ins-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.ins-pair>div {
  display: grid;
  gap: 0.2rem;
  padding-right: 0.9rem;
  border-right: 1px solid var(--rule-t09);
}

.ins-pair>div:last-child {
  border-right: 0;
}

/* More detail. A plain, always-visible section (not a <details> — a page
   anchor like #arrival-performance must never land inside a closed disclosure)
   that holds the fuller legacy report below the mockup's headline cards. */
.ins-more {
  display: grid;
  gap: 1rem;
  padding-top: 0.4rem;
  border-top: 1px solid var(--rule-t09);
}

.ins-more-head {
  display: grid;
  gap: 0.25rem;
}

.ins-shell .ins-more-title {
  margin: 0;
  font-size: 1.3rem;
  letter-spacing: -0.01em;
}

.ins-more-sub {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

/* Invoice aging. Older money is redder: an invoice sitting 60 days is a
   different kind of problem from one raised on Tuesday. */
.ins-aging {
  margin-top: 0.5rem;
}

.ins-aging-head {
  display: flex;
  justify-content: space-between;
  margin: 0 0 0.45rem;
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.ins-aging-head span {
  color: var(--gold-ink);
}

.ins-aging-bars {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.4rem;
}

.ins-aging-band {
  display: grid;
  gap: 0.25rem;
  justify-items: center;
}

.ins-aging-track {
  display: flex;
  align-items: flex-end;
  width: 100%;
  height: 3rem;
  border-radius: 6px;
  background: rgba(var(--tint), 0.05);
  overflow: hidden;
}

.ins-aging-fill {
  width: 100%;
  border-radius: 6px 6px 0 0;
  background: var(--accent);
}

.ins-aging-fill.band-fresh {
  background: #4ade80;
}

.ins-aging-fill.band-recent {
  background: #a3e635;
}

.ins-aging-fill.band-month {
  background: #ffd166;
}

.ins-aging-fill.band-late {
  background: #ff9440;
}

.ins-aging-fill.band-stale {
  background: #ff5f4d;
}

.ins-aging-label {
  font-size: 0.66rem;
  color: var(--mute-t45);
}

.ins-aging-value {
  font-size: 0.7rem;
  color: var(--mute-t55);
  font-variant-numeric: tabular-nums;
}

/* Open opportunity */
.ins-open {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1rem;
  align-items: start;
}

.ins-open>div:first-child {
  display: grid;
  gap: 0.2rem;
  align-content: start;
}

.ins-open-chart {
  display: grid;
  gap: 0.4rem;
}

.ins-minibars {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas: 'max plot' 'min plot';
  gap: 0 0.5rem;
  align-items: center;
}

.ins-minibars-max {
  grid-area: max;
  align-self: start;
  font-size: 0.68rem;
  color: var(--mute-t45);
}

.ins-minibars-min {
  grid-area: min;
  align-self: end;
  font-size: 0.68rem;
  color: var(--mute-t45);
}

.ins-minibars-plot {
  grid-area: plot;
  display: flex;
  align-items: flex-end;
  gap: 0.3rem;
  height: 4rem;
  border-bottom: 1px dashed var(--rule-t18);
}

.ins-minibar {
  width: 1.1rem;
  border-radius: 3px 3px 0 0;
  background: var(--accent);
}

.ins-cta {
  grid-column: 1 / -1;
  justify-self: end;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  padding: 0.45rem 0.95rem;
  border-radius: 9px;
  border: 1px solid var(--cedge-orange-5);
  background: rgba(255, 122, 33, 0.1);
  color: var(--accent-ink);
  font-size: 0.84rem;
  font-weight: 700;
}

.ins-cta:hover {
  background: rgba(255, 122, 33, 0.2);
}

/* Funnel */
.ins-funnel-row {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) auto minmax(0, 0.95fr);
  gap: 1.4rem;
  align-items: center;
}

.ins-funnel {
  display: flex;
  gap: 0.5rem;
}

.ins-funnel-stage {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
  padding: 0.75rem 0.9rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t20);
  background: rgba(var(--tint), 0.03);
}

.ins-funnel-stage strong {
  font-size: 1.5rem;
  font-variant-numeric: tabular-nums;
}

.ins-funnel-stage span {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.ins-funnel-stage.is-leads {
  border-color: var(--cedge-sky-16);
}

.ins-funnel-stage.is-quoted {
  border-color: var(--cedge-orange-3);
}

.ins-funnel-stage.is-won {
  border-color: var(--cedge-green-41);
}

.ins-funnel-rates {
  display: flex;
  gap: 1.5rem;
}

.ins-funnel-rates>div {
  display: grid;
  gap: 0.15rem;
}

.ins-funnel-rates strong {
  font-size: 1.5rem;
  font-variant-numeric: tabular-nums;
}

.ins-drop {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  padding: 0.85rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--cedge-orange-8);
  background: rgba(255, 122, 33, 0.07);
}

.ins-drop-mark {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--cedge-orange-5);
  color: var(--accent);
}

.ins-drop div {
  display: grid;
  gap: 0.2rem;
}

.ins-drop strong {
  font-size: 0.88rem;
}

.ins-drop span {
  font-size: 0.79rem;
  line-height: 1.5;
  color: var(--mute-t55);
}

/* Charts */
.ins-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.45rem;
  height: 6rem;
  margin-top: 0.3rem;
}

.ins-bar-col {
  display: grid;
  gap: 0.3rem;
  justify-items: center;
  flex: 1 1 0;
  min-width: 0;
}

.ins-bar-col>span {
  font-size: 0.68rem;
  color: var(--mute-t45);
}

.ins-bar-stack {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  width: 100%;
  height: 5rem;
}

.ins-bar {
  flex: 1 1 0;
  min-height: 2px;
  border-radius: 3px 3px 0 0;
}

.ins-bar.is-revenue {
  background: #4a90e2;
}

.ins-bar.is-costs {
  background: var(--accent);
}

.ins-mini-legend {
  display: flex;
  gap: 0.9rem;
  font-size: 0.72rem;
  color: var(--mute-t45);
}

.ins-line {
  width: 100%;
  height: 5rem;
  margin-top: 0.4rem;
  overflow: visible;
}

.ins-line polyline {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2.2;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ins-line circle {
  fill: var(--accent);
}

.ins-line-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.68rem;
  color: var(--mute-t45);
}

.ins-meter {
  height: 0.6rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.08);
  overflow: hidden;
}

.ins-meter-fill {
  height: 100%;
  border-radius: 999px;
  background: #4ade80;
}

.ins-meter-scale {
  display: flex;
  justify-content: space-between;
  font-size: 0.68rem;
  color: var(--mute-t45);
}

.ins-stat-row {
  display: grid;
  gap: 0.15rem;
  padding-bottom: 0.6rem;
  margin-bottom: 0.2rem;
  border-bottom: 1px solid var(--rule-t08);
}

.ins-stat-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

/* Lead sources */
.ins-sources {
  display: grid;
  gap: 0.5rem;
}

.ins-source {
  display: grid;
  grid-template-columns: 8rem 1fr 2.5rem 4.5rem;
  align-items: center;
  gap: 0.7rem;
  font-size: 0.82rem;
}

.ins-source-label {
  color: var(--mute-t60);
}

.ins-source-track {
  height: 0.55rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.06);
  overflow: hidden;
}

.ins-source-fill {
  height: 100%;
  border-radius: 999px;
  background: #a78bfa;
}

.ins-source-count {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.ins-source-win {
  text-align: right;
  font-size: 0.76rem;
  color: var(--mute-t45);
}

@media (max-width: 1100px) {
  .ins-summary {
    grid-template-columns: 1fr;
  }

  .ins-breakdown {
    padding-left: 0;
    border-left: 0;
    padding-top: 1rem;
    border-top: 1px solid var(--rule-t09);
  }

  .ins-row-3 {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 720px) {
  .ins-figures {
    grid-template-columns: 1fr 1fr;
  }

  .ins-figure {
    border-right: 0;
  }

  .ins-row-2,
  .ins-row-3 {
    grid-template-columns: 1fr;
  }

  .ins-source {
    grid-template-columns: 6rem 1fr auto;
  }

  .ins-source-win {
    display: none;
  }
}

/* INSIGHTS AND CASH FLOW GAVE THEIR SIGNATURE COLOURS BACK.
   Each of these two rows carried a hue of its own — cyan for the numbers, green
   for the money — matched on href, each surviving hover and the active state,
   each with a light-theme value under it. They were the right idea in a rail
   where nothing else was coloured. They are the wrong one in a rail where the
   SECTION is: both sit in Money, so two of that group's four icons read as
   mint and two did not, which says the group is three things rather than one.
   Nothing about them is lost that the rail was using. Money's hue (--nav-money,
   #44e0a4) is within a few points of the green cash flow already wore, both
   rows keep the standard hover wash and the active row's orange still says
   where you are. If a single row ever needs to be picked out again, it wants a
   shape — a mark, a badge — not a colour that has to fight its own section. */

/* Revenue breakdown: three bars on ONE scale, not a stacked bar. A stack has to
   clamp the moment costs exceed revenue, which is the month you most need to
   see that they did. */
.ins-splits {
  display: grid;
  gap: 0.45rem;
}

.ins-split {
  display: grid;
  grid-template-columns: 5.5rem 1fr auto 2.8rem;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.78rem;
}

.ins-split-label {
  color: var(--mute-t55);
  white-space: nowrap;
}

.ins-split-track {
  height: 0.75rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.06);
  overflow: hidden;
}

.ins-split-fill {
  height: 100%;
  border-radius: 999px;
}

.ins-split-fill.is-revenue {
  background: #4a90e2;
}

.ins-split-fill.is-costs {
  background: var(--accent);
}

.ins-split-fill.is-profit {
  background: #4ade80;
}

.ins-split-fill.is-profit.is-negative {
  background: #ff5f4d;
}

.ins-split b {
  color: var(--text);
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.ins-split b.is-negative {
  color: var(--ink-orange-1);
}

.ins-split-pct {
  color: var(--mute-t45);
  font-size: 0.75rem;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* ── Intake AI setup ─────────────────────────────────────────────────────────
   Two columns: the checklist you set, and what it produces. Prefixed .iq- and
   scoped under .intake-quality — .row, .group and .badge would each collide
   with something else in a 13k-line stylesheet. */
/* Separated from the form above it. The intake form ends in a right-aligned
   "Save intake settings" and this block opens with a right-aligned "Open full
   preview" — measured, both sat at y=414 with a zero-pixel gap, so two buttons
   in the same corner read as one on top of the other. It had no base rule at
   all; only .is-paused was ever written. */
.intake-quality {
  margin-top: 1.5rem;
  padding-top: 1.4rem;
  border-top: 1px solid var(--rule-t09);
}

.intake-quality.is-paused .iq-preview-col {
  opacity: 0.5;
}

.iq-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.15fr);
  gap: 1.1rem;
  align-items: start;
}

.iq-setup {
  display: grid;
  gap: 0.8rem;
  padding: 1rem 1.05rem;
  border-radius: 18px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.03);
}

.iq-setup-head {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.iq-setup-head>div {
  display: grid;
  gap: 0.1rem;
}

.iq-setup-head strong {
  font-size: 1.15rem;
  letter-spacing: -0.01em;
}

.iq-setup-head small {
  font-size: 0.82rem;
  color: var(--mute-t50);
}

.iq-spark {
  display: grid;
  place-items: center;
  width: 2.6rem;
  height: 2.6rem;
  flex: none;
  border-radius: 13px;
  border: 1px solid var(--cedge-orange-7);
  background: rgba(255, 122, 33, 0.13);
  color: var(--accent);
  font-size: 1.15rem;
}

.iq-presets-bar {
  display: grid;
  gap: 0.35rem;
  padding: 0.65rem 0.8rem;
  border-radius: 12px;
  border: 1px solid var(--cedge-orange-7);
  background: rgba(255, 122, 33, 0.06);
}

.iq-presets-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.76rem;
  font-weight: 800;
  color: var(--accent);
}

.iq-preset-success {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ink-lime-1);
}

.iq-presets-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.iq-preset-chip {
  padding: 0.28rem 0.55rem;
  border-radius: 8px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.06);
  color: var(--text);
  font-size: 0.74rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.iq-preset-chip:hover {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.15);
  color: var(--accent);
}

.iq-preset-chip.iq-preset-recommended {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.12);
  color: var(--accent);
  font-weight: 700;
}

.iq-preset-star {
  color: #ff9800;
  font-size: 0.8rem;
}

.iq-exclusions-suggestions {
  display: grid;
  gap: 0.3rem;
  margin-top: 0.35rem;
}

.iq-sugg-label {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--mute-t50);
}

.iq-sugg-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.iq-sugg-chip {
  padding: 0.2rem 0.45rem;
  border-radius: 6px;
  border: 1px dashed var(--edge-t20);
  background: rgba(var(--tint), 0.03);
  font-size: 0.7rem;
  color: var(--mute-t70);
  cursor: pointer;
  transition: all 0.15s ease;
}

.iq-sugg-chip:hover {
  border-color: var(--cedge-green-42);
  color: var(--ink-lime-1);
  background: rgba(74, 222, 128, 0.08);
}

.iq-group {
  display: grid;
  gap: 0.4rem;
  padding: 0.85rem 0.9rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--shade), 0.14);
}

.iq-group>header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.iq-group h4 {
  margin: 0;
  font-size: 1rem;
}

.iq-num {
  display: grid;
  place-items: center;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--edge-t22);
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--mute-t60);
}

.iq-badge {
  margin-left: auto;
  flex: none;
  padding: 0.22rem 0.6rem;
  border-radius: 999px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--mute-t55);
  white-space: nowrap;
}

.iq-badge.is-ok {
  border-color: var(--cedge-green-42);
  background: rgba(74, 222, 128, 0.09);
  color: var(--ink-lime-1);
}

.iq-badge.is-soft {
  border-color: var(--cedge-amber-7);
  background: rgba(255, 209, 102, 0.09);
  color: var(--gold-ink);
}

.iq-group-lede {
  margin: 0 0 0.25rem;
  font-size: 0.79rem;
  line-height: 1.5;
  color: var(--mute-t45);
}

/* A tick box row. The detail only exists once the box is ticked — a minimum
   job amount is meaningless while there is no minimum. */
.iq-row {
  border-radius: 11px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--tint), 0.03);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.iq-row.is-on {
  border-color: var(--cedge-green-43);
  background: rgba(74, 222, 128, 0.045);
}

.iq-row.is-disabled {
  opacity: 0.55;
}

.iq-row-head {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  padding: 0.6rem 0.75rem;
  cursor: pointer;
}

.iq-row.is-fixed .iq-row-head {
  cursor: default;
}

.iq-row-head input[type='checkbox'] {
  width: 1.15rem;
  height: 1.15rem;
  margin-top: 0.1rem;
  flex: none;
  accent-color: #4ade80;
  cursor: pointer;
}

.iq-tick {
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  margin-top: 0.1rem;
  flex: none;
  border-radius: 4px;
  background: #4ade80;
  color: #06210f;
  font-size: 0.72rem;
  font-weight: 900;
}

.iq-row-copy {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.iq-row-copy strong {
  font-size: 0.88rem;
  font-weight: 600;
}

.iq-row-copy small {
  font-size: 0.77rem;
  line-height: 1.45;
  color: var(--mute-t45);
}

.iq-row-detail {
  display: grid;
  gap: 0.55rem;
  padding: 0 0.75rem 0.7rem 2.4rem;
}

.iq-field {
  display: grid;
  gap: 0.25rem;
}

.iq-field>span {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--mute-t55);
}

.iq-field>small {
  font-size: 0.72rem;
  color: var(--mute-t40);
}

.iq-field select,
.iq-field input {
  min-height: 38px;
  padding: 0.35rem 0.6rem;
  border-radius: 9px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-family: inherit;
  font-size: 0.84rem;
}

.iq-exclusions {
  display: grid;
  gap: 0.4rem;
}

.iq-exclusion {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.4rem;
}

.iq-exclusion input {
  min-height: 38px;
  padding: 0.35rem 0.6rem;
  border-radius: 9px;
  border: 1px solid var(--edge-t16);
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-family: inherit;
  font-size: 0.84rem;
}

.iq-add {
  justify-self: start;
  min-height: 34px;
  padding: 0.3rem 0.7rem;
  border-radius: 9px;
  border: 1px dashed var(--edge-t24);
  background: none;
  color: var(--mute-t55);
  font-family: inherit;
  font-size: 0.79rem;
  font-weight: 600;
  cursor: pointer;
}

.iq-add:hover {
  border-color: var(--cedge-orange-5);
  color: var(--accent-ink);
}

.iq-autosave {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--tint), 0.03);
}

.iq-autosave>div {
  display: grid;
  gap: 0.1rem;
}

.iq-autosave strong {
  font-size: 0.85rem;
}

.iq-autosave small {
  font-size: 0.76rem;
  color: var(--mute-t45);
}

.iq-autosave-mark {
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--cedge-green-28);
  color: var(--ink-lime-1);
  font-size: 0.8rem;
}

.iq-save-error .iq-autosave-mark {
  border-color: var(--cedge-orange-5);
  color: var(--ink-orange-1);
}

.iq-save-error strong {
  color: var(--ink-orange-1);
}

/* Right column */
.iq-preview-col {
  display: grid;
  gap: 0.8rem;
  align-content: start;
}

.iq-preview-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.7rem;
}

.iq-live {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
}

.iq-live i {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: #4ade80;
}

.iq-preview-head small {
  font-size: 0.79rem;
  color: var(--mute-t45);
}

.iq-phone {
  display: grid;
  gap: 0.7rem;
  justify-items: center;
  padding: 2rem 1.4rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t12);
  background:
    radial-gradient(120% 90% at 50% 120%, rgba(255, 122, 33, 0.16), transparent 62%),
    rgba(var(--shade), 0.28);
}

.iq-phone-q {
  margin: 0;
  max-width: 22rem;
  padding: 0.85rem 1.1rem;
  border-radius: 14px 14px 14px 4px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.09);
  font-size: 1.05rem;
  text-align: center;
}

.iq-phone-steps {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  max-width: 22rem;
}

.iq-phone-steps i {
  width: 0.55rem;
  height: 0.55rem;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--edge-t28);
}

.iq-phone-steps i.is-on {
  width: 5rem;
  border-radius: 999px;
  border-color: transparent;
  background: var(--accent);
}

.iq-phone-btn {
  margin: 0;
  width: 100%;
  max-width: 22rem;
  padding: 0.85rem 1rem;
  border-radius: 10px;
  background: linear-gradient(180deg, #ff8a3d, #ff7a21);
  color: var(--on-accent);
  font-size: 1.05rem;
  font-weight: 700;
  text-align: center;
}

.iq-phone-fine {
  margin: 0;
  font-size: 0.79rem;
  color: var(--mute-t45);
}

.iq-benefits {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
}

.iq-benefits>div {
  display: grid;
  gap: 0.15rem;
}

.iq-benefits strong {
  font-size: 0.82rem;
}

.iq-benefits small {
  font-size: 0.74rem;
  line-height: 1.45;
  color: var(--mute-t45);
}

.iq-bicon {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 50%;
  font-size: 0.85rem;
}

.iq-bicon.is-a {
  background: rgba(74, 222, 128, 0.14);
  color: #4ade80;
}

.iq-bicon.is-b {
  background: rgba(74, 144, 226, 0.16);
  color: #6aa8ee;
}

.iq-bicon.is-c {
  background: rgba(167, 139, 250, 0.16);
  color: #a78bfa;
}

.iq-effect {
  display: grid;
  gap: 0.5rem;
  padding: 0.9rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--tint), 0.03);
}

.iq-effect-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.iq-effect-head strong {
  font-size: 0.95rem;
}

.iq-score {
  font-size: 0.78rem;
  color: var(--mute-t50);
}

.iq-score b {
  margin-left: 0.4rem;
  padding: 0.18rem 0.6rem;
  border-radius: 999px;
  font-size: 0.75rem;
}

.iq-score b.is-high {
  background: rgba(74, 222, 128, 0.16);
  color: var(--ink-lime-1);
}

.iq-score b.is-medium {
  background: rgba(255, 209, 102, 0.16);
  color: var(--gold-ink);
}

.iq-score b.is-low {
  background: rgba(255, 122, 33, 0.16);
  color: var(--ink-orange-1);
}

.iq-signal {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  padding: 0.7rem 0.8rem;
  border-radius: 11px;
  border: 1px solid var(--edge-t08);
  background: rgba(var(--tint), 0.03);
}

.iq-signal>div {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.iq-signal strong {
  font-size: 0.85rem;
}

.iq-signal small {
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--mute-t45);
}

.iq-sicon {
  display: grid;
  place-items: center;
  width: 2.1rem;
  height: 2.1rem;
  flex: none;
  border-radius: 50%;
  font-size: 0.9rem;
}

.iq-sicon.is-fit {
  background: rgba(74, 222, 128, 0.14);
  color: #4ade80;
}

.iq-sicon.is-expectations {
  background: rgba(255, 209, 102, 0.16);
  color: #ffd166;
}

.iq-sicon.is-response {
  background: rgba(74, 144, 226, 0.16);
  color: #6aa8ee;
}

.iq-impact {
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.iq-impact.is-strong {
  color: var(--ink-lime-1);
}

.iq-impact.is-medium {
  color: var(--gold-ink);
}

.iq-impact.is-weak {
  color: var(--ink-orange-1);
}

@media (max-width: 1100px) {
  .iq-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .iq-benefits {
    grid-template-columns: 1fr;
  }

  .iq-signal {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .iq-impact {
    grid-column: 2;
    justify-self: start;
  }

  .iq-row-detail {
    padding-left: 0.75rem;
  }
}

.intake-preview-compact {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  flex: none;
  min-height: 38px;
  padding: 0.45rem 0.9rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t18);
  background: rgba(var(--tint), 0.06);
  color: var(--text);
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
}

.intake-preview-compact:hover {
  border-color: var(--cedge-orange-3);
  background: rgba(255, 122, 33, 0.1);
}


/* ── True labor cost ─────────────────────────────────────────────────────────
   The worked sum runs across the top, then three cards: the two settings and
   what they add up to. "Labor burden" appears nowhere visible — it is the trade
   term, and a setting whose LABEL has to be looked up is a setting that gets
   left at its default. It lives in one tooltip for the people who came looking
   for it by name. Prefixed .jc- and scoped under .jc-card. */
.jc-card {
  display: grid;
  gap: 1rem;
}

.jc-top {
  display: flex;
  align-items: flex-start;
  gap: 0.9rem;
}

.jc-top-text {
  flex: 1 1 20rem;
  min-width: 0;
  display: grid;
  gap: 0.25rem;
}

.jc-top-text h2 {
  margin: 0;
  font-size: 1.55rem;
  letter-spacing: -0.02em;
}

.jc-lead {
  margin: 0.15rem 0 0;
  max-width: 62ch;
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--mute-t55);
}

.jc-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 2.9rem;
  height: 2.9rem;
  margin-top: 0.15rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.04);
  color: var(--accent);
}

.jc-icon svg {
  width: 1.5rem;
  height: 1.5rem;
}

.jc-save {
  flex: none;
  min-height: 1.2em;
  align-self: center;
  white-space: nowrap;
  font-size: 0.82rem;
  font-weight: 700;
}

.jc-save-saved {
  color: var(--ink-green-11);
}

.jc-save-error {
  color: var(--ink-red-1);
}

/* THE SUM. This is the explanation; everything else is a control. */
.jc-example {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem 0.9rem;
  padding: 0.85rem 1rem;
  border-radius: 14px;
  border: 1px solid var(--edge-t10);
  background: rgba(var(--tint), 0.03);
}

.jc-example-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  border: 1px solid var(--cedge-green-6);
  background: rgba(72, 199, 142, 0.12);
  color: var(--ink-green-11);
  font-weight: 800;
}

.jc-example-tag {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--mute-t45);
}

.jc-example-part {
  display: inline-flex;
  align-items: baseline;
  gap: 0.35rem;
}

.jc-example-part strong {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}

.jc-example-part small {
  font-size: 0.82rem;
  color: var(--mute-t50);
}

.jc-example-part.is-total strong {
  color: var(--ink-green-11);
  font-size: 1.5rem;
}

.jc-example-op {
  color: var(--mute-t40);
  font-size: 1.05rem;
  font-weight: 700;
}

.jc-grid {
  display: grid;
  gap: 0.85rem;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  align-items: start;
}

.jc-block {
  display: grid;
  gap: 0.55rem;
  align-content: start;
  padding: 1rem 1.05rem;
  border-radius: 16px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.025);
}

.jc-block-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

/* The tooltip is a real focus stop and tap target — works on hover, focus, and touch tap. */
.jc-hint-wrapper {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.jc-hint {
  display: grid;
  place-items: center;
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  padding: 0;
  border-radius: 50%;
  border: 1px solid var(--edge-t22);
  background: rgba(var(--tint), 0.04);
  color: var(--mute-t55);
  font-size: 0.72rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
}

.jc-hint:hover,
.jc-hint:focus-visible,
.jc-hint.is-open {
  border-color: var(--accent);
  color: var(--accent-ink);
  background: rgba(255, 122, 33, 0.14);
  outline: none;
}

.jc-hint-popover {
  position: absolute;
  top: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  width: max-content;
  max-width: 250px;
  padding: 0.5rem 0.7rem;
  border-radius: 10px;
  border: 1px solid var(--rule-t16);
  background: var(--bg-2);
  color: var(--text);
  font-size: 0.8rem;
  font-weight: 500;
  line-height: 1.4;
  box-shadow: 0 8px 24px -4px rgba(0, 0, 0, 0.45);
}

.jc-value-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
}

.jc-value {
  font-size: 2.3rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.jc-stepper {
  display: inline-flex;
  flex: none;
  border-radius: 11px;
  border: 1px solid var(--edge-t16);
  overflow: hidden;
}

.jc-stepper button {
  min-width: 2.5rem;
  min-height: 2.5rem;
  border: 0;
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease;
}

.jc-stepper button+button {
  border-left: 1px solid var(--edge-t16);
}

.jc-stepper button:hover:not(:disabled) {
  background: rgba(255, 122, 33, 0.14);
}

.jc-stepper button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Steppers move in fives; the box is for the contractor whose accountant gave
   them a number. */
.jc-exact {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  width: fit-content;
  padding: 0.2rem 0.55rem 0.2rem 0.6rem;
  border-radius: 9px;
  border: 1px dashed var(--edge-t20);
  font-size: 0.76rem;
  color: var(--mute-t50);
}

.jc-exact input {
  width: 3.6rem;
  min-height: 1.9rem;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text);
  font-size: 0.9rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.jc-exact input:focus-visible {
  outline: none;
}

.jc-exact:focus-within {
  border-style: solid;
  border-color: var(--accent);
}

.jc-exact i {
  font-style: normal;
  color: var(--mute-t50);
}

.jc-note {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--mute-t50);
}

.jc-note a {
  color: var(--accent-ink);
  text-decoration: underline;
}

.jc-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  width: fit-content;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--edge-t14);
  background: rgba(var(--tint), 0.04);
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--mute-t58);
}

.jc-tag.is-ok {
  border-color: var(--cedge-green-6);
  background: rgba(72, 199, 142, 0.12);
  color: var(--ink-green-11);
}

.jc-tag.is-warn {
  border-color: var(--cedge-amber-3);
  background: rgba(255, 209, 102, 0.12);
  color: var(--gold-ink);
}

.jc-effect-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.jc-effect-list li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0;
  border-bottom: 1px solid var(--rule-t08);
  font-size: 0.88rem;
}

.jc-effect-list li:last-child {
  border-bottom: 0;
}

.jc-effect-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 8px;
  border: 1px solid var(--edge-t12);
  background: rgba(var(--tint), 0.05);
  color: var(--mute-t55);
  font-size: 0.8rem;
}

.jc-effect-mark.is-money {
  border-color: var(--cedge-green-6);
  background: rgba(72, 199, 142, 0.1);
  color: var(--ink-green-11);
}

.jc-effect-mark.is-flag {
  border-color: var(--cedge-orange-5);
  background: rgba(255, 122, 33, 0.1);
  color: var(--ink-orange-8);
}

.jc-effect-label {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--mute-t58);
}

.jc-effect-value {
  flex: none;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.jc-effect-value small {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--mute-t45);
}

.jc-effect-value.is-total {
  color: var(--ink-green-11);
}

.jc-effect-value.is-flag {
  color: var(--ink-orange-8);
}

.jc-foot {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-t09);
  font-size: 0.79rem;
  line-height: 1.55;
  color: var(--mute-t50);
}

.jc-foot-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  border: 1px solid var(--edge-t16);
  font-size: 0.72rem;
  font-weight: 800;
  font-style: italic;
}

@media (max-width: 560px) {
  .jc-example {
    gap: 0.4rem 0.6rem;
  }

  .jc-example-part strong {
    font-size: 1.1rem;
  }

  .jc-example-part.is-total strong {
    font-size: 1.3rem;
  }

  .jc-value {
    font-size: 1.9rem;
  }
}


/* ── Quick Stops on Insights ─────────────────────────────────────────────────
   The split bar is the argument: a speed fee and the work it led to are two
   different businesses, and one figure hides which of them is carrying the
   other. Prefixed .insq- and scoped under .insq-card; .qs- was already taken by
   the coverage map. */
.insq-card {
  display: grid;
  gap: 1.1rem;
}

.insq-money {
  display: grid;
  gap: 0.65rem;
}

.insq-total {
  display: grid;
  gap: 0.15rem;
}

.insq-split {
  display: flex;
  overflow: hidden;
  height: 12px;
  border-radius: 999px;
  /* A wash, not an edge token — --edge-* is near-black on paper and this is a
     surface. The segments cover it whenever there is revenue; it only shows
     as the empty track. */
  background: rgba(var(--tint), 0.09);
}

.insq-seg {
  display: block;
  height: 100%;
  min-width: 2px;
  transition: width 0.3s ease;
}

.insq-seg.is-fee {
  background: linear-gradient(90deg, #ff7a21, #ffb454);
}

.insq-seg.is-service {
  background: linear-gradient(90deg, #3db8ff, #7fe0ef);
}

.insq-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 1.4rem;
}

.insq-key {
  display: inline-flex;
  align-items: baseline;
  gap: 0.45rem;
  font-size: 0.82rem;
  color: var(--mute-t55);
}

.insq-key strong {
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.insq-key em {
  font-style: normal;
  color: var(--mute-t45);
  font-variant-numeric: tabular-nums;
}

.insq-dot {
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 3px;
  flex: none;
  align-self: center;
}

.insq-dot.is-fee {
  background: #ff9440;
}

.insq-dot.is-service {
  background: #3db8ff;
}

.insq-stats {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-t09);
}

.insq-stat {
  display: grid;
  gap: 0.1rem;
  align-content: start;
}

/* --- funnel -----------------------------------------------------------------
   Three stages that step down in width, so the drop-off is visible before any
   number is read. Chevrons rather than bars: this is a sequence, not a
   comparison of three independent quantities. */
.insq-funnel {
  display: flex;
  align-items: stretch;
  gap: 0.3rem;
  margin-top: 0.2rem;
}

.insq-funnel-stage {
  flex: 1 1 0;
  display: grid;
  gap: 0.1rem;
  justify-items: center;
  padding: 0.7rem 0.5rem;
  border: 1px solid var(--edge-t12);
  border-radius: 10px;
  background: rgba(var(--tint), 0.04);
  text-align: center;
}

.insq-funnel-stage strong {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.insq-funnel-stage span {
  color: var(--muted);
  font-size: 0.76rem;
}

/* Each stage is a subset of the one before it, so it sits a step narrower. */
.insq-funnel-stage.is-accepted {
  flex: 0.88 1 0;
}

.insq-funnel-stage.is-completed {
  flex: 0.76 1 0;
}

.insq-funnel-stage.is-offered strong {
  color: var(--ink-sky-10);
}

.insq-funnel-stage.is-accepted strong {
  color: var(--ink-teal-1);
}

.insq-funnel-stage.is-completed strong {
  color: var(--ink-green-1);
}

/* --- the road cost ---------------------------------------------------------- */
.insq-efficiency,
.insq-opportunity {
  display: grid;
  gap: 0.4rem;
}

.insq-effgrid,
.insq-oppgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.6rem 0.9rem;
}

.insq-effgrid>div,
.insq-oppgrid>div {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.insq-effgrid .ins-mid.is-good {
  color: var(--ink-green-1);
}

.insq-oppgrid .ins-mid.is-warn {
  color: var(--gold-ink);
}

/* The sentence the card exists to be able to say. */
.insq-topline {
  margin: 0.35rem 0 0;
  padding: 0.6rem 0.8rem;
  border: 1px solid var(--cedge-green-40);
  border-radius: 10px;
  background: rgba(74, 222, 128, 0.06);
  font-size: 0.9rem;
  line-height: 1.5;
}

.insq-oppfoot {
  margin: 0.1rem 0 0;
}

.insq-rate {
  display: grid;
  gap: 0.35rem;
}

.insq-rate .ins-meter {
  margin: 0.15rem 0 0.1rem;
}

.insq-crew {
  display: grid;
  gap: 0.45rem;
}

.insq-crew-list {
  display: grid;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.insq-crew-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.45rem 0.65rem;
  border: 1px solid var(--edge-t08);
  border-radius: 9px;
  font-size: 0.86rem;
}

.insq-crew-list li.is-top {
  border-color: var(--edge-t16);
  background: rgba(255, 122, 33, 0.08);
}

.insq-crew-name {
  color: var(--text);
  font-weight: 600;
}

.insq-crew-count {
  min-width: 1.8rem;
  padding: 0.05rem 0.4rem;
  border-radius: 6px;
  background: rgba(var(--tint), 0.09);
  color: var(--text);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.insq-crew-list li.is-top .insq-crew-count {
  background: rgba(255, 122, 33, 0.2);
  color: var(--accent-ink);
}

@media (min-width: 900px) {
  .insq-card {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
    align-items: start;
  }

  .insq-card>.ins-card-head,
  .insq-card>.ins-card-foot {
    grid-column: 1 / -1;
  }

  .insq-stats {
    grid-column: 1 / -1;
  }
}

/* ---------------------------------------------------------------------------
   TEXT INBOX — the Slate dressing
   ---------------------------------------------------------------------------
   The same three columns as Classic, wearing different clothes: blue replies on
   black, conversations as cards, and the time under each turn instead of tucked
   beside it. Everything here hangs off `.inbox-slate` on <main>, so Classic is
   untouched by construction rather than by care.
   --------------------------------------------------------------------------- */

/* The magnifier is in both dressings — a search field that doesn't look like
   one is a search field people scroll past. */
.inbox-search {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.inbox-search-ic {
  position: absolute;
  left: 0.75rem;
  width: 15px;
  height: 15px;
  color: var(--mute-t55);
  pointer-events: none;
}

.inbox-search input {
  padding-left: 2.15rem;
}

/* --- conversations as cards -------------------------------------------------- */
.inbox-slate .inbox-thread-list {
  gap: 0.5rem;
}

.inbox-slate .inbox-thread-item {
  padding: 0.8rem 0.85rem;
  border-radius: 14px;
  border-color: var(--edge-t10);
  background: rgba(var(--tint), 0.02);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.inbox-slate .inbox-thread-item:hover {
  border-color: var(--edge-t22);
  background: rgba(var(--tint), 0.05);
}

.inbox-slate .inbox-thread-item.is-active {
  border-color: var(--cedge-orange-32);
  background: rgba(255, 138, 61, 0.07);
  /* A ring rather than a spread shadow: the cards sit 0.5rem apart and a soft
     glow at that distance bleeds onto its neighbour, which reads as two
     selected rows. */
  box-shadow: inset 0 0 0 1px var(--cedge-orange-32);
}

.inbox-slate .inbox-thread-item.is-active strong {
  color: var(--accent-ink);
}

.inbox-slate .inbox-thread-top strong {
  font-size: 0.94rem;
  font-weight: 700;
}

/* The count survives the restyle. The mockup draws a plain dot, but "3 waiting"
   and "1 waiting" are different mornings and the dot cannot tell them apart. */
.inbox-slate .inbox-unread {
  min-width: 16px;
  height: 16px;
  padding: 0 5px;
  background: #2f6fe0;
  color: #ffffff;
  font-size: 0.66rem;
}

.inbox-slate .inbox-thread-item.is-active .inbox-unread {
  background: var(--accent);
  color: var(--on-accent);
}

/* --- the thread -------------------------------------------------------------- */
.inbox-slate .inbox-thread-who h2 {
  font-size: 1.32rem;
  letter-spacing: -0.01em;
}

.inbox-slate .inbox-thread-actions .btn {
  border-radius: 999px;
  padding: 0.45rem 0.95rem;
}

.inbox-slate .inbox-messages {
  gap: 1rem;
}

.inbox-slate .inbox-run-stack {
  max-width: 78%;
}

.inbox-slate .inbox-bubble {
  border-radius: 14px;
  padding: 0.68rem 0.95rem;
}

/* Black, and a border so it is a bubble rather than a hole in the panel. Kept
   dark in the light theme too: the dark bubble IS the skin, and a Slate inbox
   that turns pale on paper is just Classic in blue. */
.inbox-slate .inbox-bubble-inbound {
  background: #080d14;
  border-color: rgba(255, 255, 255, 0.11);
  color: #f2f6fb;
}

/* Deeper than the blue in the mockup on purpose, exactly as the orange bubble
   is deeper than the brand orange. #3b82f6 carries white at 3.68:1 — under the
   4.5:1 body-text bar — and this gradient runs 4.70:1 at its lightest end, so
   the bubble keeps white text and stays readable outdoors on a phone. */
.inbox-slate .inbox-bubble-outbound {
  background: linear-gradient(135deg, #2f6fe0, #1f57c4);
  border-color: rgba(255, 255, 255, 0.14);
  color: #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.28);
}

/* No tail. The corner notch is Classic's way of pointing a run at its speaker;
   Slate points with colour and side, and a notch on top of that is a third
   answer to a question already settled twice. */
.inbox-slate .inbox-bubble-inbound.is-last {
  border-bottom-left-radius: 14px;
}

.inbox-slate .inbox-bubble-outbound.is-last {
  border-bottom-right-radius: 14px;
}

.inbox-slate .inbox-run-time {
  margin-top: 0.4rem;
  font-size: 0.72rem;
}

/* --- the reply box ----------------------------------------------------------- */
/* One bordered container holding the saved-reply chips, the box and Send —
   the mockup's shape. The seams inside it come off so it reads as one control. */
.inbox-slate .inbox-reply-area {
  margin-top: 0.85rem;
  padding: 0.75rem;
  border: 1px solid var(--edge-t14);
  border-radius: 18px;
  background: rgba(0, 0, 0, 0.18);
  gap: 0.6rem;
}

:root[data-theme='light'] .inbox-slate .inbox-reply-area {
  background: rgba(var(--tint), 0.03);
}

.inbox-slate .inbox-reply {
  margin-top: 0;
  padding-top: 0;
  border-top: none;
}

.inbox-slate .inbox-reply textarea {
  border-color: transparent;
  background: transparent;
  border-radius: 12px;
  padding: 0.5rem 0.55rem;
}

:root[data-theme='light'] .inbox-slate .inbox-reply textarea {
  background: transparent;
}

.inbox-slate .inbox-reply textarea:focus-visible {
  border-color: var(--edge-t22);
  box-shadow: none;
}

/* --- the customer rail -------------------------------------------------------- */
.inbox-slate .inbox-ctx-block:first-child {
  justify-items: center;
  text-align: center;
}

.inbox-slate .inbox-ctx-block:first-child .eyebrow {
  justify-self: start;
}

.inbox-ctx-avatar {
  width: 5.2rem;
  height: 5.2rem;
  margin: 0.7rem 0 0.5rem;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1.5px solid var(--cedge-orange-32);
  background: rgba(255, 138, 61, 0.06);
  color: var(--accent-ink);
  font-size: 1.35rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  box-shadow: 0 0 0 6px rgba(255, 138, 61, 0.05);
}

.inbox-ctx-avatar.is-unknown svg {
  width: 2.6rem;
  height: 2.6rem;
}

.inbox-slate .inbox-ctx-block:first-child .ins-empty-note {
  text-align: center;
}

.inbox-slate .inbox-ctx-block .btn {
  justify-self: center;
  border-radius: 999px;
}

/* --- the search box ----------------------------------------------------------- */
/* The button is not decoration. The form had no submit control at all and
   relied on the browser submitting a lone text field on Enter, which did not
   happen here — typing a name and pressing Enter reloaded the unfiltered inbox
   and threw the term away. It is also the only search affordance a touch
   keyboard is guaranteed to offer. */
.inbox-search-go {
  border: 1px solid var(--edge-t16);
  border-radius: 999px;
  background: rgba(var(--tint), 0.06);
  color: var(--ink-neutral-1);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 650;
  padding: 0.38rem 0.85rem;
  margin-left: 0.35rem;
  cursor: pointer;
}

.inbox-search-go:hover {
  border-color: var(--cedge-orange-51);
  color: var(--accent-ink);
}

.inbox-search-clear {
  display: inline-grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  margin-left: 0.25rem;
  border-radius: 50%;
  color: var(--mute-t62);
  font-size: 1.05rem;
  line-height: 1;
  text-decoration: none;
}

.inbox-search-clear:hover {
  background: rgba(var(--tint), 0.08);
  color: var(--text);
}

/* --- an empty list says which KIND of empty ------------------------------------ */
.inbox-empty {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.45rem;
  padding: 1.6rem 0.4rem;
}

.inbox-empty-title {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

.inbox-empty-body {
  margin: 0;
  font-size: 0.85rem;
  color: var(--mute-t55);
  line-height: 1.5;
}

.inbox-empty .btn {
  margin-top: 0.3rem;
  padding: 0.4rem 0.85rem;
  font-size: 0.82rem;
  border-radius: 999px;
}

/* --- a link in a bubble -------------------------------------------------------- */
/* The label is short (host + one path segment); the href is whole. Underlined
   rather than coloured, because the outbound bubble is already a saturated blue
   and a blue link inside it is invisible. */
.inbox-bubble-link {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
  word-break: break-word;
}

.inbox-bubble-link:hover {
  text-decoration-thickness: 2px;
}

/* ---------------------------------------------------------------------------
   .inbox-slate — A WORKSPACE, NOT A DOCUMENT
   ---------------------------------------------------------------------------
   Measured on a 1440x900 laptop before this: the reply box — the control the
   page exists for — began at y≈909, one pixel-row below the fold, and the page
   went on for another 4,800px of saved replies and message reference. At 320px
   it was over 16,000px tall. Every one of those numbers is the same mistake:
   an inbox laid out as a document that grows downward, when an inbox is a
   surface with a fixed frame and three things scrolling inside it.

   So the shell becomes a flex column and the layout takes what is left of the
   viewport. `flex: 1 1 0` matters more than it looks: flex-basis 0 means the
   thread's content — which is unbounded, that is the entire problem — cannot
   inflate the box, and an explicit min-height (any value, as long as it is not
   `auto`) switches off the automatic minimum size that would otherwise let it.
   Everything below that is the same two lines repeated: min-height 0 so a flex
   or grid child MAY shrink below its content, then overflow on the one part
   that should scroll.

   Scoped to .inbox-slate, which is on the real inbox's <main> and not on the
   marketing demo that shares these class names. --------------------------- */
.inbox-slate.workspace-shell {
  display: flex;
  flex-direction: column;
  /* .wide-shell reserves 4rem at the foot for a page that ends. This one does
     not end; it stops where the viewport does. */
  padding-bottom: 1.6rem;
}

.inbox-slate .inbox-layout {
  flex: 1 1 0;
  /* A floor, so a short window gets a usable thread instead of a sliver — and
     below it the page is allowed to scroll, which is the honest outcome. */
  min-height: 24rem;
  align-items: stretch;
}

.inbox-slate .inbox-list,
.inbox-slate .inbox-thread,
.inbox-slate .inbox-context {
  min-height: 0;
  max-height: 100%;
}

.inbox-slate .inbox-list {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.inbox-slate .inbox-thread-list {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  /* Room for the scrollbar so the cards do not sit under it. */
  padding-right: 0.2rem;
  scrollbar-width: thin;
}

.inbox-slate .inbox-context {
  overflow-y: auto;
  scrollbar-width: thin;
}

.inbox-slate .inbox-messages {
  flex: 1 1 0;
  min-height: 0;
  /* The 30rem cap is what made this a document: on a tall screen it left dead
     space under the thread, and on a short one it overran the composer. */
  max-height: none;
}

.inbox-slate .inbox-thread-head,
.inbox-slate .inbox-reply-area {
  flex: none;
}

/* One pane at a time, still — but the pane now fills the frame rather than
   stacking below the last one. The composer needs no sticky trick here: it is
   the last row of a column whose middle row is the only thing that scrolls. */
@media (max-width: 820px) {
  .inbox-slate .inbox-layout {
    display: flex;
    flex-direction: column;
  }

  .inbox-slate .inbox-list,
  .inbox-slate .inbox-thread {
    flex: 1 1 0;
  }

  .inbox-slate .inbox-reply-area {
    position: static;
    padding-bottom: 0;
    background: none;
  }
}

/* The shell's help "?" is fixed to the bottom-right below 900px, and the
   composer is now pinned to the bottom of the frame rather than living at the
   end of a long scroll — so Send and the ? want the same 44px of corner. Send
   steps aside; it is the one that has somewhere else to be. */
@media (max-width: 900px) {
  .inbox-slate .inbox-reply {
    padding-right: 3.4rem;
  }
}

/* 100vh on a phone is the viewport WITH the URL bar collapsed, so a frame built
   from it puts its last row — here, the reply box — under the browser chrome
   until you scroll. dvh is the live number. Browsers without it ignore this and
   keep the vh line above, which is the behaviour they had anyway. */
@media (max-width: 1080px) {
  .app-main-sidenav .inbox-slate.wide-shell {
    min-height: calc(100dvh - 4.4rem);
  }
}

/* ---------------------------------------------------------------------------
   SETTINGS → BUSINESS — a workspace, not a scroll
   ---------------------------------------------------------------------------
   Eight forms stacked one on top of the other, with no way to tell whether
   anything was missing without opening every one of them. Now: a rail of named
   sections, and an Overview that answers "is my account set up?" in a number.
   --------------------------------------------------------------------------- */
.bz-shell {
  display: grid;
  grid-template-columns: minmax(0, 15rem) minmax(0, 1fr);
  gap: 1.4rem;
  align-items: start;
}

@media (max-width: 900px) {

  /* The rail becomes a scrolling row of chips above the panel rather than
     stacking seven full-width buttons — on a phone that is a screen of nav
     before you reach a single setting. */
  .bz-shell {
    grid-template-columns: minmax(0, 1fr);
  }

  .bz-rail {
    position: static;
  }

  .bz-rail .eyebrow,
  .bz-rail-title {
    display: none;
  }

  .bz-rail ul {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 0.35rem;
    scrollbar-width: thin;
  }

  .bz-rail li {
    flex: none;
  }

  .bz-rail-link {
    white-space: nowrap;
  }
}

.bz-rail {
  position: sticky;
  top: 1rem;
}

.bz-rail .eyebrow {
  margin: 0 0 0.15rem 0.55rem;
}

.bz-rail-title {
  margin: 0 0 0.9rem 0.55rem;
  font-size: 1.45rem;
  font-weight: 750;
  letter-spacing: -0.01em;
}

.bz-rail ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.bz-rail-link {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.6rem 0.7rem;
  border: 1px solid transparent;
  border-radius: 10px;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: color 0.14s ease, background 0.14s ease;
}

.bz-rail-link svg {
  flex: none;
  width: 18px;
  height: 18px;
  opacity: 0.9;
}

.bz-rail-link:hover {
  color: var(--text);
  background: rgba(var(--tint), 0.045);
}

.bz-rail-link.is-active {
  color: var(--accent-ink);
  background: rgba(255, 138, 61, 0.09);
  border-color: var(--cedge-orange-32);
}

/* The count of things wrong INSIDE that section, so the rail carries the
   Overview's alerts rather than making you go back to find them. */
.bz-rail-badge {
  margin-left: auto;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--accent);
  color: var(--on-accent);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.bz-panel {
  min-width: 0;
}

.bz-section-head {
  margin: 0 0 1rem;
}

.bz-section-head h3 {
  margin: 0;
  font-size: 1.32rem;
  font-weight: 750;
  letter-spacing: -0.01em;
}

.bz-section-head p {
  margin: 0.25rem 0 0;
  color: var(--muted);
  font-size: 0.88rem;
}

/* --- the overview ------------------------------------------------------------ */
.bz-overview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.bz-overview-head h3 {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 750;
}

.bz-overview-head p {
  margin: 0.2rem 0 0;
  color: var(--muted);
  font-size: 0.88rem;
}

.bz-ring {
  position: relative;
  flex: none;
  width: 74px;
  height: 74px;
  display: grid;
  place-items: center;
}

.bz-ring svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.bz-ring-track {
  fill: none;
  stroke: rgba(var(--tint), 0.1);
  stroke-width: 6;
}

.bz-ring-fill {
  fill: none;
  stroke: var(--ink-green-1);
  stroke-width: 6;
  stroke-linecap: round;
  transition: stroke-dasharray 0.4s ease;
}

.bz-ring-num {
  display: grid;
  justify-items: center;
  line-height: 1;
}

.bz-ring-num strong {
  font-size: 1.3rem;
  font-weight: 780;
  font-variant-numeric: tabular-nums;
}

.bz-ring-num small {
  margin-top: 2px;
  color: var(--mute-t55);
  font-size: 0.62rem;
}

.bz-alerts {
  display: grid;
  gap: 0.5rem;
  margin-top: 1.1rem;
}

.bz-alert {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.7rem 0.85rem;
  border: 1px solid var(--cedge-orange-32);
  border-radius: 12px;
  background: rgba(255, 138, 61, 0.07);
}

.bz-alert>span {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
  flex: 1;
}

.bz-alert strong {
  font-size: 0.9rem;
  font-weight: 700;
}

.bz-alert small {
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.45;
}

.bz-alert .btn {
  flex: none;
  padding: 0.4rem 0.8rem;
  font-size: 0.82rem;
}

.bz-checklist {
  list-style: none;
  margin: 1.1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.1rem;
}

.bz-check {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.7rem 0.15rem;
}

.bz-check+.bz-check {
  border-top: 1px solid var(--rule-t08);
}

.bz-check-copy {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
  flex: 1;
}

.bz-check-copy strong {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.9rem;
  font-weight: 680;
}

.bz-check-copy small {
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.45;
}

.bz-optional {
  padding: 0.05rem 0.4rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.08);
  color: var(--mute-t55);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.bz-check .linklike {
  flex: none;
  font-size: 0.82rem;
}

.bz-mark {
  flex: none;
  width: 20px;
  height: 20px;
}

.bz-mark.is-complete {
  color: var(--ink-green-1);
}

.bz-mark.is-attention {
  color: var(--accent-ink);
}

.bz-mark.is-todo {
  color: var(--mute-t55);
}

/* --- the section index -------------------------------------------------------- */
.bz-jump {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.bz-jump-card {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.9rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--edge-t10);
  border-radius: 14px;
  background: rgba(var(--tint), 0.02);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.14s ease, background 0.14s ease;
}

.bz-jump-card:hover {
  border-color: var(--cedge-orange-32);
  background: rgba(255, 138, 61, 0.05);
}

/* :not(.bz-jump-num) matters — the number is a direct <span> child too, and
   without this it takes the flex: 1 and stretches across the whole card. */
.bz-jump-card>span:not(.bz-jump-num) {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
  flex: 1;
}

.bz-jump-card strong {
  font-size: 0.95rem;
  font-weight: 700;
}

.bz-jump-card small {
  color: var(--muted);
  font-size: 0.83rem;
}

.bz-jump-card>svg {
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--mute-t55);
}

.bz-jump-num {
  flex: none;
  width: 2rem;
  height: 2rem;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(var(--tint), 0.06);
  color: var(--muted);
  font-size: 0.85rem;
  font-weight: 780;
  font-variant-numeric: tabular-nums;
}

/* --- Settings → Trust: the certificate as a summary, not a form -------------- */
.cert-summary {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: 0.9rem;
  padding: 0.9rem 1rem;
  border: 1px solid var(--edge-t14);
  border-left-width: 3px;
  border-radius: 12px;
  background: rgba(var(--tint), 0.025);
}

.cert-summary.is-ok {
  border-left-color: var(--ink-green-1);
}

.cert-summary.is-warn,
.cert-summary.is-expired {
  border-left-color: var(--accent);
}

.cert-summary.is-off {
  border-left-color: var(--mute-t55);
}

.cert-summary-main {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 0.22rem;
}

.cert-summary-main strong {
  font-size: 0.98rem;
  font-weight: 730;
}

.cert-summary-facts {
  margin: 0;
  color: var(--text);
  font-size: 0.86rem;
}

.cert-summary-state {
