  gap: 0.4rem;
}

.insprev-lines li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.86rem;
}

.insprev-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 0.75rem;
  padding-top: 0.65rem;
  border-top: 1px solid rgba(15, 26, 40, 0.12);
  font-size: 0.9rem;
}

.insprev-total strong {
  font-size: 1.15rem;
  font-weight: 780;
}

.insprev-approve {
  display: block;
  margin: 0.8rem 0 0;
  padding: 0.6rem;
  border-radius: 999px;
  background: #ff7a21;
  color: #1a1005;
  font-size: 0.9rem;
  font-weight: 750;
  text-align: center;
}

.insprev-absent {
  margin: 0.9rem 0 0;
  padding: 0.7rem;
  border: 1px dashed rgba(15, 26, 40, 0.2);
  border-radius: 10px;
  color: #5a6b80;
  font-size: 0.82rem;
  text-align: center;
}

/* ---------------------------------------------------------------------------
   DASHBOARD — the mobile rebuild
   ---------------------------------------------------------------------------
   The page was ~4,140px tall on a 390px phone: five screens. Everything here is
   about the first one — what needs doing, in a shape a thumb can use.
   --------------------------------------------------------------------------- */

/* --- priority cards stack on a phone ------------------------------------------ */
/* Three columns held at 390px squeezed the message to ~100px and the action to
   ~72px, so both wrapped and each row grew to 130–190px tall. Stacked, the same
   row is one readable block and the action is a full-width target. */
@media (max-width: 640px) {
  .priority-item {
    grid-template-columns: 28px minmax(0, 1fr);
    gap: 0.5rem 0.6rem;
    padding: 0.7rem 0.75rem;
    align-items: start;
  }

  .priority-index {
    width: 28px;
    height: 28px;
    font-size: 0.85rem;
  }

  .priority-copy {
    grid-column: 2;
  }

  .priority-cta {
    grid-column: 2;
    justify-self: start;
    /* A real target, not a caption. 44px tall including the padding. */
    padding: 0.55rem 0.9rem;
    border: 1px solid var(--cedge-amber-20);
    border-radius: 999px;
    font-size: 0.82rem;
  }
}

.priority-more {
  margin-top: 0.65rem;
}

.priority-more>summary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 0.85rem;
  border: 1px solid var(--edge-t14);
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
  list-style: none;
}

.priority-more>summary::-webkit-details-marker {
  display: none;
}

.priority-more>summary::after {
  content: '▾';
  font-size: 0.7rem;
}

.priority-more[open]>summary::after {
  content: '▴';
}

.priority-more>summary:hover {
  color: var(--text);
  border-color: var(--edge-t22);
}

.priority-more .priority-list {
  margin-top: 0.65rem;
}

/* --- the week --------------------------------------------------------------- */
.week-glance-quiet {
  display: none;
  margin: 0 0 0.7rem;
  color: var(--muted);
  font-size: 0.85rem;
}

/* "No jobs" was 11.5px at about 3.2:1 — a label you cannot read telling you
   there is nothing to read. */
.week-glance-empty {
  font-size: 0.78rem;
  color: var(--muted);
}

/* 10.9px for the time and the town, which is the line you actually squint at. */
.week-glance-job span {
  font-size: 0.76rem;
  color: var(--muted);
}

/* 9.3px initials on a 1.35rem pill: legible to nobody, and the tooltip that
   explained them does not exist on a touch screen. */
.week-glance-job .week-glance-crew {
  min-width: 1.6rem;
  padding: 0.16rem 0.36rem;
  font-size: 0.7rem;
}

/* Job rows were ~42px. 44 is the floor for a thumb. */
.week-glance-job {
  min-height: 44px;
  justify-content: center;
  padding: 0.45rem 0.55rem;
}

@media (max-width: 640px) {

  /* One column means seven rows, four of them saying "No jobs". Name the quiet
     days once and give the space to the days with work in them. */
  .week-glance-quiet {
    display: block;
  }

  .week-glance-day.is-quiet {
    display: none;
  }

  /* Less nested chrome: the card inside the panel inside the shell was eating
     the width the job needed. */
  .week-glance-day {
    padding: 0.5rem 0.55rem;
  }
}

/* --- automation, split ------------------------------------------------------- */
.automation-status-row {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.6rem;
}

.dash-subheading {
  margin-top: 1.4rem;
}

.dash-subheading h3 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 720;
}

.dash-activity {
  margin-top: 1rem;
}

.dash-activity>summary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 0.85rem;
  border: 1px solid var(--edge-t14);
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
  list-style: none;
}

.dash-activity>summary::-webkit-details-marker {
  display: none;
}

.dash-activity>summary::after {
  content: '▾';
  font-size: 0.7rem;
}

.dash-activity[open]>summary::after {
  content: '▴';
}

.dash-activity>summary:hover {
  color: var(--text);
  border-color: var(--edge-t22);
}

/* --- primary actions on the mobile bar ---------------------------------------- */
.mobilebar-plan,
.mobilebar-new,
.mobilebar-new-wrap {
  display: none;
}

@media (max-width: 900px) {

  /* The "+ New" button is a menu trigger now, so it needs a positioned wrapper
     for the menu to hang off. The wrapper takes the button's place in the bar's
     flex row; the button inside it keeps every rule it already had. */
  .sidenav-mobilebar .mobilebar-new-wrap {
    display: block;
    position: relative;
    flex: 0 0 auto;
  }

  .sidenav-mobilebar .mobilebar-plan,
  .sidenav-mobilebar .mobilebar-new {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    /* 44px, both of them. */
    min-height: 44px;
    border-radius: 999px;
    font-size: 0.88rem;
    font-weight: 700;
    text-decoration: none;
  }

  .sidenav-mobilebar .mobilebar-plan {
    width: 44px;
    margin-left: auto;
    border: 1px solid var(--cedge-violet-4, var(--edge-t22));
    background: rgba(139, 92, 246, 0.14);
    color: var(--text);
  }

  .sidenav-mobilebar .mobilebar-plan svg {
    width: 20px;
    height: 20px;
  }

  .sidenav-mobilebar .mobilebar-plan.active {
    background: rgba(139, 92, 246, 0.28);
  }

  .sidenav-mobilebar .mobilebar-new {
    padding: 0 0.95rem;
    border: 1px solid var(--accent);
    background: rgba(255, 122, 33, 0.14);
    color: var(--accent-ink);
  }

  /* The Menu button gives up its auto-margin — Plan my day claims it now, so
     the three sit together at the right rather than Menu drifting off alone. */
  .sidenav-mobilebar .nav-toggle {
    margin-left: 0.4rem;
  }
}

/* Four things on a 390px bar.
   Putting Plan my day and + New up here took the bar from two items to four,
   and at 390px they came to ~408px of content in 390px of room. Flexbox does
   not warn about that: `margin-left: auto` simply collapses and the last item —
   Menu, the whole navigation — hangs 37px off the right edge, still measuring a
   perfectly correct 72x44 while half of it is unreachable. Which is why the
   check is now on the right EDGE, not the width.

   Everything gives up a little rather than one thing disappearing: tighter
   padding on the bar and on both pills, a smaller gap, and the wordmark down a
   size. No label is dropped and no target goes under 44px. */
@media (max-width: 440px) {
  .sidenav-mobilebar {
    gap: 0.3rem;
    padding-left: 0.5rem;
    padding-right: 0.5rem;
  }

  .sidenav-mobilebar .sidenav-brand {
    min-width: 0;
  }

  .sidenav-mobilebar .sidenav-wordmark {
    font-size: 0.78rem;
    padding: 0.3rem 0.45rem;
  }

  .sidenav-mobilebar .mobilebar-new {
    padding: 0 0.65rem;
  }

  .sidenav-mobilebar .nav-toggle {
    padding: 0.65rem 0.65rem;
    margin-left: 0.2rem;
  }
}

/* 360px is a real Android width, not a corner case. */
@media (max-width: 400px) {
  .sidenav-mobilebar {
    gap: 0.2rem;
    padding-left: 0.4rem;
    padding-right: 0.4rem;
  }

  .sidenav-mobilebar .sidenav-brand {
    min-width: 0;
  }

  .sidenav-mobilebar .sidenav-wordmark {
    font-size: 0.7rem;
    padding: 0.25rem 0.38rem;
    letter-spacing: 0.02em;
  }

  .sidenav-mobilebar .mobilebar-new {
    padding: 0 0.48rem;
  }

  .sidenav-mobilebar .nav-toggle {
    padding: 0.6rem 0.55rem;
    margin-left: 0.1rem;
  }
}

/* Below ~345px the wordmark and three 44px targets cannot both fit, and the
   wordmark is the one that loses: the rail behind Menu still carries it, and an
   unreachable Menu is the whole navigation gone. */
@media (max-width: 345px) {
  .sidenav-mobilebar .sidenav-brand {
    display: none;
  }
}

/* --- focus you can actually see ------------------------------------------------ */
/* A thin dark outline on a dark bar is not a focus indicator. */
.nav-toggle:focus-visible,
.mobilebar-plan:focus-visible,
.mobilebar-new:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(255, 122, 33, 0.28);
}

/* --- the lead alert stops covering things -------------------------------------- */
.quote-request-alert-close {
  /* 27x27 was under every touch-target guideline, sitting next to the button it
     must not be mistaken for. */
  width: 2.75rem;
  height: 2.75rem;
}

.quote-request-alert-close svg {
  width: 15px;
  height: 15px;
}

/* --- status, not a switch ------------------------------------------------------- */
/* A green pill reading ON beside a row you can tap looks like a control, and
   these rows navigate. Same word, same colour — no capsule, and a dot in front,
   which is how a status is drawn everywhere else. */
.sidenav-state {
  border: none;
  background: none;
  padding: 0.1rem 0 0.1rem 0.55rem;
  position: relative;
  letter-spacing: 0.05em;
}

.sidenav-state::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.sidenav-state[data-state='on'],
.sidenav-state[data-state='off'],
.sidenav-state[data-state='paused'] {
  border-color: transparent;
  background: none;
}

/* --- Dashboard is not part of Grow ----------------------------------------------- */
/* It sits below the last group with nothing between them, so it read as the
   fifth Grow item. */
.sidenav-bottom {
  margin-top: 1rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-t10);
}

/* Measured, not assumed: the pill came out 37px and the Menu button 43. Both
   are one line of padding away from a target a thumb can hit, and "nearly 44"
   is the same as not 44. */
@media (max-width: 640px) {
  .priority-cta {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
  }
}

@media (max-width: 900px) {
  .sidenav-mobilebar .nav-toggle {
    min-height: 44px;
  }

  /* A flex item shrinks past its width unless told not to. It came out 22px
     wide — half a target — with the height correct, which is exactly what
     flex-shrink does and nothing else does. */
  .sidenav-mobilebar .mobilebar-plan {
    flex: none;
  }

  .sidenav-mobilebar .mobilebar-new {
    flex: none;
  }
}

/* Four full-width result cards on a phone is ~600px of page for four numbers
   nobody acts on. Two across keeps the figures and gives the height back. */
@media (max-width: 640px) {

  /* Scoped to the automation results, which is the grid with four cards in it.
     Applied to every metric grid it left the two-card snapshot with one card
     full width and the other orphaned at half, wrapping its own label. */
  .dash-results-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.5rem;
  }

  .dash-results-grid .workspace-metric-card {
    padding: 0.7rem 0.75rem;
  }

  .dash-results-grid .workspace-metric-value {
    font-size: 1.5rem;
  }

  .dash-results-grid .workspace-metric-note {
    font-size: 0.76rem;
    line-height: 1.35;
  }
}

/* --- the lead alert comes in from the cold ------------------------------------- */
/* It was position: fixed over the bottom-right, which on a phone meant a
   351x98 box sitting on top of whatever you were reading — and it made every
   dashboard page reserve 14rem of empty space underneath so nothing hid behind
   it. In the flow it interrupts nothing and costs only its own height. */
.quote-request-alert {
  /* RELATIVE, not static. The dismiss button is position:absolute, so it needs
     this card to be its containing block — and `static` is precisely the value
     that isn't one. Taking the alert out of position:fixed therefore sent the X
     off to whichever ancestor happened to be positioned: adrift in the top-right
     of the page on a desktop, and off the visible card entirely on a phone,
     where it read as simply missing.
     Relative keeps the card in the flow exactly as static did. */
  position: relative;
  /* The offsets from the position:fixed rule above have to be cleared with it.
     On a relatively positioned box they stop being "where to pin this" and
     become "how far to nudge it" — `right: 2rem` would shove the card two rems
     LEFT of where it is laid out, and `bottom` would lift it. */
  top: auto;
  right: auto;
  bottom: auto;
  left: auto;
  width: auto;
  max-width: 46rem;
  margin: 0 auto 1.1rem;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
  backdrop-filter: none;
}

/* No longer needed — there is nothing overhead to clear. */
.app-main-alerted {
  padding-bottom: 0;
}

@media (max-width: 640px) {
  .quote-request-alert {
    margin: 0 0 0.9rem;
  }

  /* The X rides in its own gutter down the right-hand edge, vertically centred,
     NOT in the corner. The corner is where "View lead" is on a phone — the
     layout above puts the button in column 2 spanning both rows — so a dismiss
     control there would sit on top of the one thing the alert exists to get
     tapped. The gutter is sized to clear the circle rather than by eye. */
  .quote-request-alert {
    padding-right: 3.3rem;
  }

  .quote-request-alert-close {
    top: 50%;
    right: 0.3rem;
    transform: translateY(-50%);
  }
}

/* ==========================================================================
   THE SCHEDULE PAGE ON A PHONE — AGENDA FIRST
   ==========================================================================

   Measured before this existed, at 390px: each day cell in the month grid was
   33px wide, each job chip inside one was 10px wide and 46px tall at a 9.92px
   font, and all 13 client names on screen were clipped. At 320px the page also
   scrolled 39px sideways. A 10x46 box with a name in it is not a small chip,
   it is a vertical fragment — the name renders one character per line.

   Seven columns of detail do not fit on a phone and no amount of shrinking
   makes them; below 640px the month grid is replaced by one day at a time.
   Both trees render and this is what picks between them, so there is no JS
   media query, no hydration mismatch and no flash of the wrong layout. */

.sched-mobile {
  display: none;
}

@media (max-width: 640px) {
  .calendar-desktop-views {
    display: none;
  }

  .sched-mobile {
    display: block;
  }

  /* THE WHOLE TOOLBAR GOES, not three of its four children.
     Every control in it belongs to the desktop grid, which is not on the screen
     here: the agenda has its own day nav, its own Day/Month tabs and its own
     Today. Hiding the month nav and the view menu but leaving the row was how
     the phone ended up showing two weekend chips and nothing else — "Saturday
     0 / Sunday 0", 308px wide, switching columns off a grid that is not there.
     (Measured at 390: those two chips were the only thing left in it.) */
  .calendar-toolbar-wrap {
    display: none;
  }

  /* Reclaimed for the date grid below. Seven columns need every pixel the
     panel is prepared to give up, and the agenda's cards supply their own
     inset, so the panel's own padding was doing nothing but narrowing them. */
  .workspace-section-card.schedule-calendar-panel {
    padding-left: 0.65rem;
    padding-right: 0.65rem;
  }

  /* THE TWO DATE GRIDS BLEED TO THE PANEL'S INNER EDGE.
     Both are a fixed number of columns whose width is decided by the room they
     are given: five days, and seven. Everything else here is text in a card
     and wants the inset; these two want the pixels. Bleeding by exactly the
     panel's own padding is the whole trick — a bleed past that would cross the
     panel's border and read as a bug, and a viewport bleed (100vw) counts the
     scrollbar and would reintroduce the sideways scroll this pass removed. */
  .sched-strip,
  .sched-mini-head,
  .sched-mini-grid {
    margin-left: -0.65rem;
    margin-right: -0.65rem;
  }
}

/* --- the bar: Agenda | Month, and Today ---------------------------------- */

.sched-mobile-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.55rem;
}

.sched-tabs {
  display: inline-flex;
  flex: 1;
  padding: 0.2rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
}

.sched-tab {
  flex: 1;
  min-height: 44px;
  padding: 0 0.9rem;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--mute-t60);
  font: inherit;
  font-size: 0.88rem;
  font-weight: 750;
  cursor: pointer;
}

/* Selected is a fill AND a weight change, never the fill alone. */
.sched-tab.is-on {
  background: var(--accent);
  color: var(--on-accent);
  font-weight: 850;
}

.sched-tab:focus-visible,
.sched-nav-btn:focus-visible,
.sched-nav-today:focus-visible,
.sched-strip-day:focus-visible,
.sched-mini-day:focus-visible,
.sched-card-options:focus-visible,
.sched-cta-primary:focus-visible,
.sched-cta-secondary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-nav-today {
  flex: none;
  min-height: 44px;
  min-width: 44px;
  padding: 0 0.85rem;
  border: 1px solid var(--edge-t16);
  border-radius: 12px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 750;
  cursor: pointer;
}

.sched-nav-today:disabled {
  opacity: 0.42;
  cursor: default;
}

/* --- the day, named in full --------------------------------------------- */

.sched-nav {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.5rem;
}

.sched-nav-btn {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--edge-t16);
  border-radius: 12px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.sched-nav-btn:hover {
  border-color: var(--cedge-orange-30);
}

.sched-nav-date {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.sched-mobile-date {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.06rem;
  font-weight: 800;
  line-height: 1.2;
  color: var(--text);
}

.sched-nav-sub {
  display: flex;
  justify-content: center;
  gap: 0.4rem;
  margin: 0.1rem 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

.sched-nav-rel {
  color: var(--accent-ink);
  font-weight: 800;
}

.sched-nav-rel::after {
  content: '\00b7';
  margin-left: 0.4rem;
  color: var(--mute-i42);
  font-weight: 400;
}

/* --- five days ----------------------------------------------------------- */

.sched-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.3rem;
  /* Longhand, NOT `margin: 0 0 0.7rem`. The shorthand is declared after the
     media query that bleeds this row to the panel edge, and at equal
     specificity the later rule wins whether or not the earlier one is inside
     an @media — so the shorthand silently reset the bleed to 0 and cost each
     of the five days 4px at 320. */
  margin-top: 0;
  margin-bottom: 0.7rem;
  padding: 0;
  list-style: none;
}

.sched-strip-day {
  display: grid;
  justify-items: center;
  gap: 0.05rem;
  width: 100%;
  min-height: 62px;
  padding: 0.35rem 0.1rem;
  border: 1px solid var(--edge-t12);
  border-radius: 12px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  cursor: pointer;
}

.sched-strip-day small {
  color: var(--mute-i56);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.sched-strip-day strong {
  font-size: 1.02rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

/* Today is marked by an underline as well as a tint, so it survives being
   next to the selected day. */
.sched-strip-day.is-today strong {
  box-shadow: 0 2px 0 var(--accent);
}

.sched-strip-day.is-on {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.14);
  box-shadow: inset 0 0 0 1px var(--cedge-orange-30);
}

/* The count is the badge; an empty day gets a dash so the row keeps its
   rhythm and "nothing booked" is stated rather than left blank. */
.sched-strip-count {
  display: inline-grid;
  place-items: center;
  min-width: 1.15rem;
  height: 1.15rem;
  padding: 0 0.25rem;
  border-radius: 999px;
  background: rgba(255, 122, 33, 0.18);
  color: var(--accent-ink);
  font-size: 0.68rem;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}

.sched-strip-count.is-empty {
  background: none;
}

.sched-strip-count.is-empty::before {
  content: '\2013';
  color: var(--mute-i42);
}

/* --- capacity ------------------------------------------------------------ */

.sched-cap {
  display: grid;
  gap: 0.35rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--edge-t10);
  border-radius: 12px;
  background: rgba(var(--tint), 0.03);
}

.sched-cap-text {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15rem 0.45rem;
  margin: 0;
  font-size: 0.82rem;
  color: var(--muted);
}

.sched-cap-text strong {
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 800;
}

.sched-cap-bar {
  height: 6px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.1);
  overflow: hidden;
}

.sched-cap-bar>span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
}

/* Colour is the second signal here, never the first — .sched-cap-text already
   says "Nearly full" in words. */
.sched-cap[data-state='empty'] .sched-cap-bar>span {
  background: var(--mute-i42);
}

.sched-cap[data-state='nearly'] .sched-cap-bar>span {
  background: var(--gold-ink);
}

.sched-cap[data-state='full'] .sched-cap-bar>span,
.sched-cap[data-state='over'] .sched-cap-bar>span {
  background: #ff6b6b;
}

.sched-cap[data-state='over'] .sched-cap-text strong,
.sched-cap[data-state='full'] .sched-cap-text strong {
  color: var(--ink-orange-2);
}

/* The bar is measuring something it cannot finish measuring, so it says so:
   the filled part is the hours that ARE known, and the rest of the track is
   hatched rather than empty. An empty track reads as "room". */
.sched-cap[data-state='unknown'] .sched-cap-bar {
  background-image: repeating-linear-gradient(135deg, color-mix(in srgb, var(--cap-unknown) 34%, transparent) 0 4px, transparent 4px 8px);
}

.sched-cap[data-state='unknown'] .sched-cap-bar>span {
  background: var(--cap-unknown);
}

.sched-blocked {
  margin: 0.5rem 0 0;
  padding: 0.5rem 0.7rem;
  border: 1px solid var(--cedge-orange-30);
  border-radius: 10px;
  background: rgba(255, 122, 33, 0.08);
  font-size: 0.82rem;
  color: var(--ink-orange-2);
}

/* --- the two actions ----------------------------------------------------- */

.sched-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin: 0.65rem 0 0.7rem;
}

.sched-cta-primary {
  flex: 1 1 11rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 46px;
  padding: 0 1rem;
  border: 1px solid rgba(139, 118, 255, 0.42);
  border-radius: 12px;
  background: rgba(108, 92, 231, 0.9);
  color: #fff;
  font: inherit;
  font-size: 0.92rem;
  font-weight: 800;
  text-decoration: none;
  cursor: pointer;
}

.sched-cta-primary:hover {
  background: rgba(122, 106, 245, 0.95);
}

.sched-cta-secondary {
  flex: 1 1 9rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 44px;
  padding: 0 0.85rem;
  border: 1px solid var(--edge-t16);
  border-radius: 12px;
  background: rgba(var(--tint), 0.04);
  color: var(--text);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
}

/* The count had no rules at all, so a <small> at inherited size and weight sat
   flush against the label: "Plan this day's route3 stops". */
.sched-cta-secondary small {
  font-size: 0.76rem;
  font-weight: 650;
  color: var(--mute-t55);
}

.sched-empty {
  margin: 0;
  padding: 1.5rem 1rem;
  border: 1px dashed var(--edge-t14);
  border-radius: 12px;
  color: var(--muted);
  font-size: 0.88rem;
  text-align: center;
}

/* --- the jobs, as rows you can read -------------------------------------- */

.sched-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sched-card {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  padding: 0.65rem 0.7rem 0.7rem;
  border: 1px solid var(--edge-t12);
  border-left: 3px solid var(--edge-t22);
  border-radius: 12px;
  background: rgba(var(--tint), 0.03);
}

/* The status stripe repeats what the badge says in words. */
.sched-card.status-new_lead {
  border-left-color: var(--gold-ink);
}

.sched-card.status-in_progress {
  border-left-color: var(--accent);
}

.sched-card.status-complete {
  border-left-color: var(--ink-green-1);
}

.sched-card-planned {
  border-left-style: dashed;
}

.sched-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin: 0;
}

/* The time leads, at a size you can read across a truck cab. */
.sched-card-time {
  color: var(--text);
  font-size: 1rem;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.sched-card-badge {
  flex: none;
  padding: 0.12rem 0.5rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.1);
  color: var(--mute-t60);
  font-size: 0.7rem;
  font-weight: 800;
  white-space: nowrap;
}

.sched-card-badge.status-warn {
  background: rgba(255, 209, 102, 0.16);
  color: var(--gold-ink);
}

.sched-card-badge.status-complete {
  background: rgba(120, 220, 150, 0.16);
  color: var(--ink-green-1);
}

.sched-card-badge.status-danger {
  background: rgba(255, 107, 107, 0.16);
  color: var(--ink-orange-2);
}

.sched-card-name {
  color: var(--text);
  font-size: 1.02rem;
  font-weight: 800;
  line-height: 1.25;
  text-decoration: none;
}

.sched-card-name:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.sched-card-where {
  margin: 0;
  color: var(--muted);
  font-size: 0.84rem;
}

/* Two lines and then an ellipsis. A scope can run to a paragraph, and a card
   that is mostly one job's description stops being a list of the day. */
.sched-card-what {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0.1rem 0 0;
  color: var(--mute-t60);
  font-size: 0.83rem;
  line-height: 1.35;
}

.sched-card-figures {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.2rem 0.55rem;
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  color: var(--mute-t60);
}

.sched-card-money {
  color: var(--warn);
  font-size: 0.92rem;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}

.sched-card-hours {
  font-variant-numeric: tabular-nums;
}

.sched-card-crew {
  color: var(--muted);
}

.sched-card-options {
  align-self: stretch;
  min-height: 44px;
  margin-top: 0.45rem;
  border: 1px solid var(--edge-t16);
  border-radius: 10px;
  background: rgba(var(--tint), 0.05);
  color: var(--text);
  font: inherit;
  font-size: 0.86rem;
  font-weight: 750;
  cursor: pointer;
}

.sched-card-options:hover {
  border-color: var(--cedge-orange-30);
  background: rgba(255, 122, 33, 0.08);
}

/* --- Month: a date selector ---------------------------------------------- */

.sched-mini-hint {
  margin: 0 0 0.5rem;
  color: var(--muted);
  font-size: 0.83rem;
}

.sched-mini-head,
.sched-mini-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 2px;
}

.sched-mini-head span {
  padding: 0.2rem 0;
  color: var(--mute-i56);
  font-size: 0.68rem;
  font-weight: 800;
  text-align: center;
}

.sched-mini-pad {
  min-height: 44px;
}

.sched-mini-day {
  display: grid;
  place-items: center;
  gap: 0;
  min-height: 46px;
  padding: 0.15rem 0;
  border: 1px solid transparent;
  border-radius: 9px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  cursor: pointer;
}

.sched-mini-day strong {
  font-size: 0.9rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
}

/* A count, not a name. The moment a client's name goes in one of these cells
   this is the 33px column the agenda exists to replace. */
.sched-mini-count {
  min-height: 0.85rem;
  color: var(--accent-ink);
  font-size: 0.64rem;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.sched-mini-day.is-today {
  box-shadow: inset 0 -2px 0 var(--accent);
}

.sched-mini-day.is-on {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.16);
  font-weight: 850;
}

.sched-mini-day.is-blocked {
  background: repeating-linear-gradient(135deg, rgba(255, 122, 33, 0.09) 0 5px, transparent 5px 10px);
}

/* HOW FULL, ON THE PICKER. The same [data-load] ramp the Capacity view uses, at
   the only size a 46px cell can spare: a hairline under the date. `open` draws
   nothing — a wall of green under three empty weeks is noise, and the absence
   of a band already says it. The count above and the button's own label carry
   the fact in numbers and words, so this is never the only signal. */
.sched-mini-day {
  position: relative;
}

.sched-mini-band {
  position: absolute;
  inset: auto 20% 3px;
  height: 3px;
  border-radius: 999px;
  background: var(--load-ink, var(--accent));
}

.sched-mini-day[data-load='light'] {
  --load-ink: var(--cap-light);
}

.sched-mini-day[data-load='busy'] {
  --load-ink: var(--cap-busy);
}

.sched-mini-day[data-load='full'] {
  --load-ink: var(--cap-full);
}

.sched-mini-day[data-load='over'] {
  --load-ink: var(--cap-over);
}

/* Off the ramp here too — the hatch is what says "not a level of full". */
.sched-mini-day[data-load='unknown'] {
  --load-ink: var(--cap-unknown);
}

.sched-mini-day[data-load='unknown'] .sched-mini-band {
  background-image: repeating-linear-gradient(135deg, rgba(0, 0, 0, .4) 0 2px, transparent 2px 4px);
}

/* --- paper ---------------------------------------------------------------- */

:root[data-theme='light'] .panel .sched-strip-day,
:root[data-theme='light'] .panel .sched-mini-day,
:root[data-theme='light'] .panel .sched-card {
  background: #f7f8fa;
  border-color: #e2e8f0;
}

:root[data-theme='sunlight'] .panel .sched-strip-day,
:root[data-theme='sunlight'] .panel .sched-mini-day,
:root[data-theme='sunlight'] .panel .sched-card {
  background: #ffffff;
  border-color: #cbd5e1;
}

:root[data-theme='light'] .panel .sched-mini-grid,
:root[data-theme='sunlight'] .panel .sched-mini-grid {
  padding: 4px;
  border-radius: 12px;
  background: #eff3f8;
  box-shadow: inset 0 1px 2px rgba(17, 27, 41, 0.07);
}

:root[data-theme='onyx'] .panel .sched-strip-day,
:root[data-theme='onyx'] .panel .sched-mini-day,
:root[data-theme='onyx'] .panel .sched-card {
  background: #000000;
  border-color: rgba(255, 255, 255, 0.22);
}

:root[data-theme='parchment'] .panel .sched-strip-day,
:root[data-theme='parchment'] .panel .sched-mini-day,
:root[data-theme='parchment'] .panel .sched-card {
  background: #fff7e6;
  border-color: rgba(75, 60, 42, 0.15);
}

:root[data-theme='parchment'] .panel .sched-mini-grid {
  padding: 4px;
  border-radius: 12px;
  background: #e8d8bc;
  box-shadow: inset 0 1px 2px rgba(48, 38, 27, 0.08);
}

/* ==========================================================================
   The contractor's brand, on the pages a HOMEOWNER opens
   ==========================================================================
   Used by /client/jobs/[token], /invoice/[id], /pay/[id] and /portal/view/
   [token]. Every one of these used to be topped by the Let's Get Quoted mark
   and wordmark, because the bar is drawn by AppShell — a client component in
   the root layout that cannot see which account a link token belongs to.

   AppShell now renders nothing on these routes (see isHomeownerBranded) and
   each page draws <ContractorBrandBar> instead. The component re-points
   --accent for its whole subtree, so the buttons and amounts on the page
   underneath take the contractor's colour without knowing it exists. */

.cbrand {
  position: sticky;
  top: 0;
  z-index: 30;
  border-bottom: 1px solid var(--rule-t10);
  background: var(--panel, rgba(9, 18, 30, 0.92));
  /* The pages below scroll under this, and a translucent bar over moving text
     is unreadable at a glance — which on an invoice is the wrong place to be
     saving 4px of contrast. Prefixed too: these are the pages a homeowner opens
     on a phone, and iOS Safari still needs -webkit-. */
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}

.cbrand-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  max-width: 1180px;
  margin: 0 auto;
  padding: 0.75rem 1.4rem;
}

.cbrand-id {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.cbrand-logo,
.cbrand-mark {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 11px;
  overflow: hidden;
}

/* An uploaded logo is whatever shape the contractor uploaded — a wide lockup, a
   tall badge, a square. `contain` shows all of it rather than cropping the
   middle out of somebody's own logo. */
.cbrand-logo {
  object-fit: contain;
  background: rgba(var(--tint), 0.06);
}

.cbrand-mark {
  display: block;
}

.cbrand-mark svg {
  display: block;
  width: 100%;
  height: 100%;
}

.cbrand-copy {
  display: grid;
  gap: 0.05rem;
  min-width: 0;
}

.cbrand-name {
  font-size: 1.02rem;
  font-weight: 750;
  letter-spacing: -0.01em;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cbrand-context {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 600;
}

.cbrand-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex: 0 0 auto;
}

.cbrand-call,
.cbrand-site {
  display: inline-flex;
  align-items: center;
  /* 44px: this sits next to a payment button on a phone, and the misfire that
     matters is dialling when you meant to pay (or the reverse). */
  min-height: 44px;
  padding: 0 0.9rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  font-size: 0.84rem;
  font-weight: 650;
  white-space: nowrap;
}

.cbrand-call {
  border-color: var(--accent);
  color: var(--accent);
}

.cbrand-site {
  color: var(--muted);
}

.cbrand-call:hover {
  background: rgba(var(--tint), 0.06);
}

.cbrand-site:hover {
  color: var(--text);
}

/* Us, at the bottom, small — see ContractorBrandFoot. A page with no
   attribution at all is the shape of a phishing page, so this stays; it just
   isn't the headline any more. */
.cbrand-foot {
  max-width: 1180px;
  margin: 2.2rem auto 2.6rem;
  padding: 0 1.4rem;
  color: var(--mute-t55);
  font-size: 0.78rem;
  text-align: center;
}

.cbrand-foot a {
  color: var(--muted);
  text-decoration: underline;
}

.cbrand-foot a:hover {
  color: var(--text);
}

@media (max-width: 640px) {
  .cbrand-inner {
    padding: 0.6rem 1rem;
    gap: 0.6rem;
  }

  .cbrand-logo,
  .cbrand-mark {
    width: 38px;
    height: 38px;
  }

  .cbrand-name {
    font-size: 0.94rem;
  }

  /* The website link is the one thing here nobody opened this page to do. It
     goes first when there isn't room, so the phone number keeps its target. */
  .cbrand-site {
    display: none;
  }
}

/* === Marketing workspace ==================================================
   Overview / Campaigns / Blog / Calendar / Performance. One local nav across
   the top of all five, one tile row, and one set of status words.

   Every button in here declares its own background and border. The stylesheet
   resets only `color` on <button> (see the note near the top), so a control
   that sets padding and a radius but no background falls through to the UA's
   `buttonface` — a light-grey pill on a dark panel. That is what happened to
   the window tabs, and it is silent: it looks like a deliberate style. */

.mkt-nav {
  margin-bottom: 1.1rem;
  border-bottom: 1px solid var(--rule-t10);
  /* The tab row scrolls rather than wrapping to two lines on a phone. Five
     labels do not fit at 320px and a wrapped nav pushes the page title below
     the fold. */
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.mkt-nav::-webkit-scrollbar {
  display: none;
}

.mkt-nav-list {
  display: flex;
  gap: 0.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
  min-width: max-content;
}

.mkt-nav-link {
  display: inline-flex;
  align-items: center;
  /* 44px tall including the border, so the whole row is a real target. */
  min-height: 44px;
  padding: 0 0.9rem;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--mute-t58);
  font-size: 0.9rem;
  font-weight: 600;
  white-space: nowrap;
  transition: color 0.16s ease, border-color 0.16s ease;
}

.mkt-nav-link:hover {
  color: var(--text);
}

.mkt-nav-link.is-active {
  border-bottom-color: var(--accent);
  color: var(--text);
}

.mkt-nav-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: 6px;
}

.mkt-overview-hero {
  display: block;
  padding-block: 1.35rem;
}

.mkt-overview-hero .workspace-title {
  max-width: none;
  margin: 0.15rem 0 0.25rem;
  font-size: clamp(1.9rem, 3.4vw, 2.75rem);
  line-height: 1.06;
}

.mkt-overview-hero .workspace-lead {
  max-width: 68ch;
  margin: 0;
}

/* --- The one decision this page exists to make ---------------------------- */
.mkt-priority {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(10.5rem, 13rem);
  gap: 1.5rem;
  align-items: stretch;
  border-color: var(--cedge-orange-14, var(--edge-t18));
  background:
    linear-gradient(120deg, rgba(255, 122, 33, 0.075), transparent 45%),
    rgba(var(--panel-rgb), 0.88);
}

.mkt-priority-copy {
  align-self: center;
  min-width: 0;
}

.mkt-priority-copy .eyebrow {
  margin: 0 0 0.35rem;
}

.mkt-priority-copy h2 {
  margin: 0;
  font-size: clamp(1.35rem, 2.5vw, 1.85rem);
  line-height: 1.16;
  text-wrap: balance;
}

.mkt-priority-copy>p:not(.eyebrow) {
  max-width: 70ch;
  margin: 0.55rem 0 0;
  font-size: 0.92rem;
  line-height: 1.58;
}

.mkt-priority-actions {
  display: flex;
  gap: 0.55rem;
  flex-wrap: wrap;
  margin-top: 1rem;
}

.mkt-priority-metric {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding-left: 1.35rem;
  border-left: 1px solid var(--edge-t12);
}

.mkt-priority-metric span {
  color: var(--mute-t58);
  font-size: 0.72rem;
  font-weight: 750;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.mkt-priority-metric strong {
  margin-top: 0.25rem;
  font-size: clamp(1.8rem, 3vw, 2.45rem);
  line-height: 1.05;
  overflow-wrap: anywhere;
}

.mkt-priority-metric small {
  margin-top: 0.25rem;
  color: var(--muted);
  font-size: 0.78rem;
}

/* --- The four tiles ------------------------------------------------------- */
.mkt-tiles {
  display: grid;
  /* minmax(0, 1fr), never a bare 1fr: a bare 1fr has a minimum of min-content,
     so a long note in one tile pushes the row wider than the page and the whole
     document scrolls sideways. */
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.9rem;
  margin-bottom: 1.1rem;
}

.mkt-tile {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
  padding: 1rem 1.1rem;
  border: 1px solid var(--edge-t12);
  border-radius: 14px;
  transition: border-color 0.16s ease, transform 0.16s ease;
}

a.mkt-tile:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}

a.mkt-tile:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.mkt-tile-label {
  color: var(--mute-t58);
  font-size: 0.78rem;
  font-weight: 600;
}

.mkt-tile-value {
  font-size: 1.9rem;
  font-weight: 800;
  line-height: 1.1;
}

.mkt-tile-note {
  color: var(--muted);
  font-size: 0.78rem;
}

/* Four distinct stages instead of repeating the same draft total in two
   unrelated cards. The heading names the journey; each tile names one state. */
.mkt-pipeline-section {
  display: grid;
  gap: 0.75rem;
}

.mkt-pipeline-section .mkt-section-head {
  margin-bottom: 0;
}

.mkt-pipeline-section .eyebrow {
  margin: 0 0 0.25rem;
}

.mkt-pipeline-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.9rem;
}

.mkt-pipeline-note {
  margin: 0;
  font-size: 0.84rem;
}

.mkt-pipeline-note a {
  color: var(--accent-ink);
  font-weight: 700;
}

/* --- Overview layout ------------------------------------------------------ */
.mkt-overview-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(0, 1fr);
  gap: 1.1rem;
  align-items: start;
}

.mkt-side {
  display: grid;
  gap: 1.1rem;
  align-content: start;
}

.mkt-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.mkt-section-head h2 {
  margin: 0;
  font-size: 1.02rem;
  font-weight: 700;
}

.mkt-section-link {
  border: 0;
  background: transparent;
  padding: 0.2rem 0;
  color: var(--muted);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
}

.mkt-section-link:hover {
  color: var(--text);
}

/* --- Recommended next actions --------------------------------------------- */
.mkt-rec-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mkt-rec {
  padding: 1.05rem 0;
  border-top: 1px solid var(--rule-t10);
}

.mkt-rec:first-child {
  border-top: 0;
  padding-top: 0.4rem;
}

.mkt-rec-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin: 0 0 0.35rem;
}

.mkt-rec-window {
  padding: 0.15rem 0.5rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.05);
  color: var(--mute-t58);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Text, not a colour. The badge SAYS "Draft created" — the tint only repeats
   what the words already carry, so it survives greyscale and colour blindness. */
.mkt-rec-badge {
  padding: 0.15rem 0.5rem;
  border: 1px solid var(--cedge-green-3, var(--edge-t12));
  border-radius: 999px;
  background: rgba(74, 222, 128, 0.12);
  color: var(--ok-ink, var(--text));
  font-size: 0.68rem;
  font-weight: 700;
}

.mkt-rec-title {
  font-size: 1rem;
  font-weight: 700;
}

.mkt-rec-why {
  margin: 0 0 0.7rem;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.55;
}

.mkt-rec-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

/* --- Coming up ------------------------------------------------------------ */
.mkt-coming-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mkt-coming-list li+li {
  border-top: 1px solid var(--rule-t10);
}

.mkt-coming-row {
  display: grid;
  grid-template-columns: 4.2rem minmax(0, 1fr);
  gap: 0.6rem;
  align-items: baseline;
  min-height: 44px;
  padding: 0.6rem 0;
}

.mkt-coming-row:hover .mkt-coming-copy strong {
  color: var(--accent);
}

.mkt-coming-row:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 8px;
}

.mkt-coming-date {
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 700;
}

.mkt-coming-copy {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.mkt-coming-copy strong {
  font-size: 0.9rem;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.mkt-coming-copy small {
  color: var(--mute-t58);
  font-size: 0.76rem;
}

.mkt-inline-empty {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.75rem;
  padding-top: 0.85rem;
}

.mkt-inline-empty p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.55;
}

.mkt-inline-empty .btn {
  padding-block: 0.65rem;
}

.mkt-blogsum-line {
  margin: 0 0 0.8rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.mkt-email-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  padding-block: 1.15rem;
}

.mkt-email-summary>div {
  min-width: 0;
}

.mkt-email-summary .eyebrow {
  margin: 0 0 0.2rem;
}

.mkt-email-summary h2 {
  margin: 0;
  font-size: 1.02rem;
}

.mkt-email-summary p:not(.eyebrow) {
  margin: 0.25rem 0 0;
  font-size: 0.82rem;
  line-height: 1.45;
}

.mkt-email-summary .btn {
  flex: 0 0 auto;
}

/* --- Status filters ------------------------------------------------------- */
.mkt-filters {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
  margin: 0.9rem 0 1rem;
}

.mkt-filter {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 36px;
  padding: 0.3rem 0.75rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.03);
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease;
}

.mkt-filter:hover {
  border-color: var(--accent);
  color: var(--text);
}

.mkt-filter:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.mkt-filter.is-active {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.14);
  color: var(--text);
}

.mkt-filter-count {
  color: var(--mute-t58);
  font-size: 0.76rem;
  font-weight: 700;
}

.mkt-filter.is-active .mkt-filter-count {
  color: var(--accent);
}

/* --- Post list ------------------------------------------------------------ */
.mkt-post-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mkt-post-list li+li {
  border-top: 1px solid var(--rule-t10);
}

.mkt-post-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 56px;
  padding: 0.75rem 0.2rem;
}

.mkt-post-copy {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
  flex: 1 1 auto;
  text-decoration: none;
  color: inherit;
}

.mkt-post-copy:hover strong {
  color: var(--accent);
}

.mkt-post-copy:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.mkt-post-copy strong {
  font-size: 0.95rem;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.mkt-post-copy small {
  color: var(--mute-t58);
  font-size: 0.78rem;
}

.mkt-post-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.mkt-post-actions .btn,
.btn-sm {
  padding: 0.28rem 0.7rem;
  font-size: 0.78rem;
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  white-space: nowrap;
}

/* --- The status word ------------------------------------------------------
   The WORD is the signal. Colour is a second, redundant channel — nothing here
   is distinguishable by hue alone. */
.mkt-state {
  flex: 0 0 auto;
  padding: 0.2rem 0.6rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  background: rgba(var(--tint), 0.05);
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 700;
  white-space: nowrap;
}

.mkt-state-published {
  border-color: rgba(74, 222, 128, 0.4);
  background: rgba(74, 222, 128, 0.12);
  color: var(--ok-ink, var(--text));
}

.mkt-state-scheduled {
  border-color: rgba(255, 122, 33, 0.4);
  background: rgba(255, 122, 33, 0.12);
  color: var(--accent);
}

.mkt-state-ready {
  border-color: rgba(96, 165, 250, 0.4);
  background: rgba(96, 165, 250, 0.12);
  color: var(--text);
}

.mkt-state-archived {
  opacity: 0.72;
}

/* --- Post editor ---------------------------------------------------------- */
.mkt-crumb {
  margin: 0 0 0.7rem;
  font-size: 0.86rem;
}

.mkt-crumb a {
  color: var(--muted);
  font-weight: 600;
}

.mkt-crumb a:hover {
  color: var(--text);
}

.mkt-editor-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.2rem;
  flex-wrap: wrap;
}

.mkt-editor-hero .workspace-lead {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.mkt-editor-meta {
  color: var(--muted);
  font-size: 0.86rem;
}

.mkt-save {
  flex: 0 0 auto;
  margin: 0;
  color: var(--mute-t58);
  font-size: 0.8rem;
}

/* Draft → Ready → Scheduled/Published. A list, because it is an ordered
   sequence and a screen reader should say so. */
.mkt-progress {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
  counter-reset: none;
}

.mkt-progress-step {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.3rem 0.7rem 0.3rem 0.55rem;
  border: 1px solid var(--edge-t12);
  border-radius: 999px;
  color: var(--mute-t58);
  font-size: 0.82rem;
  font-weight: 600;
}

.mkt-progress-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--edge-t12);
}

.mkt-progress-step.is-done {
  border-color: rgba(255, 122, 33, 0.35);
  color: var(--text);
}

.mkt-progress-step.is-done .mkt-progress-dot {
  background: var(--accent);
}

.mkt-progress-step.is-here {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.12);
}

/* "Written for window cleaning. Your trade is now plumbing." Sits directly
   above the status buttons it disables, because a warning somewhere else on the
   page explains a greyed-out button the reader has already given up on. Amber
   for the unrecorded case (look at this) and red for a confirmed drift (this is
   wrong), which is the same pair the rest of the dashboard uses. */
.mkt-trade-drift {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 0.75rem;
  padding: 0.6rem 0.8rem;
  border-radius: 0.6rem;
  border-left: 3px solid var(--ink-amber-1);
  background: rgba(251, 191, 36, 0.12);
}

.mkt-trade-drift.is-blocking {
  border-left-color: var(--bad);
  background: rgba(248, 113, 113, 0.12);
}

.mkt-trade-drift-text {
  margin: 0;
  flex: 1 1 16rem;
  font-size: 0.82rem;
  line-height: 1.5;
  font-weight: 600;
}

.mkt-status-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
}

.mkt-after-publish {
  margin-top: 1.1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--rule-t10);
}

.mkt-preview {
  margin: 0 0 1.2rem;
  padding: 1.2rem;
  border: 1px solid var(--edge-t12);
  border-radius: 14px;
  background: rgba(var(--tint), 0.03);
}

.mkt-preview h3 {
  margin: 0 0 0.5rem;
  font-size: 1.3rem;
  font-weight: 800;
}

.mkt-preview p {
  margin: 0 0 0.8rem;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.65;
}

.mkt-preview-excerpt {
  font-style: italic;
}

.mkt-preview-cover {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  margin-bottom: 1rem;
  border-radius: 10px;
}

/* Kept apart from the document, with its own heading, so "delete" is never
   adjacent to a field somebody is tabbing through. */
.mkt-danger {
  border-color: rgba(248, 113, 113, 0.28);
}

/* --- Performance ---------------------------------------------------------- */
.mkt-perf-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.mkt-perf-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.mkt-perf-table th,
.mkt-perf-table td {
  padding: 0.6rem 0.7rem;
  text-align: left;
  border-bottom: 1px solid var(--rule-t10);
}

.mkt-perf-table th {
  color: var(--mute-t58);
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.mkt-perf-table td:first-child {
  white-space: nowrap;
}

.mkt-perf-muted {
  color: var(--mute-t58);
}

.mkt-perf-miss {
  color: var(--gold-ink);
  font-weight: 700;
}

/* --- Narrow --------------------------------------------------------------- */
@media (max-width: 1000px) {
  .mkt-overview-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .mkt-tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mkt-pipeline-tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {

  /* One column, and every action row stacks to full width rather than
     squeezing two buttons into 320px. */
  .mkt-tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.6rem;
  }

  .mkt-tile {
    padding: 0.8rem 0.85rem;
  }

  .mkt-tile-value {
    font-size: 1.5rem;
  }

  .mkt-overview-hero {
    padding-block: 1.1rem;
  }

  .mkt-overview-hero .workspace-title {
    font-size: clamp(1.85rem, 9vw, 2.35rem);
  }

  .mkt-editor-hero {
    flex-direction: column;
    align-items: stretch;
  }

  .mkt-priority {
    grid-template-columns: minmax(0, 1fr);
    gap: 1.15rem;
  }

  .mkt-priority-metric {
    padding: 1rem 0 0;
    border-top: 1px solid var(--edge-t12);
    border-left: 0;
  }

  .mkt-priority-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .mkt-priority-actions .btn {
    width: 100%;
  }

  .mkt-rec-actions,
  .mkt-status-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .mkt-rec-actions .btn,
  .mkt-status-actions .btn {
    width: 100%;
    justify-content: center;
  }

  .mkt-post-row {
    align-items: flex-start;
  }

  .mkt-coming-row {
    grid-template-columns: 3.6rem minmax(0, 1fr);
  }

  .mkt-email-summary {
    align-items: stretch;
    flex-direction: column;
  }

  .mkt-email-summary .btn {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .mkt-tiles {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 360px) {
  .mkt-pipeline-tiles {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* === Cash chart: grouped markers, selection, and the detail panel ==========
   The chart is hand-rolled SVG measured off its own container — see
   lib/cash-chart-layout for the geometry, which is pure and tested. Nothing
   here hardcodes a coordinate. */

/* A marker is a real target now (MIN_TOUCH/2 = 16px radius). It is affordable
   because markers closer together than a touch target are folded into one — the
   old code shrank the target to as little as 6px instead, which kept every
   marker drawn and made most of them impossible to hit. */
.cash-markers {
  outline: none;
}

/* One tab stop for the layer, arrow keys within it. The focus ring has to be
   drawn on the group because the hit circle is transparent and a browser
   outline on an SVG <g> lands somewhere unhelpful. */
.cash-marker {
  outline: none;
  cursor: pointer;
}

.cash-marker:focus-visible .cash-marker-focus,
.cash-marker.is-selected .cash-marker-focus {
  opacity: 1;
}

.cash-marker-focus {
  fill: none;
  stroke: var(--accent, #ff7a21);
  stroke-width: 2;
  opacity: 0;
  pointer-events: none;
}

/* Selection is a ring OUTSIDE the shape — not a fill change and not a size
   change. It must be visible without covering the neighbouring point and
   without moving the thing you just aimed at. */
.cash-marker-ring {
  fill: none;
  stroke: rgba(var(--tint), 0.9);
  stroke-width: 2;
  pointer-events: none;
}

:root[data-theme='light'] .cash-marker-ring {
  stroke: rgba(17, 27, 41, 0.75);
}

/* A grouped marker is a disc carrying its count. Shape and colour still
   separate incoming from outgoing on the ungrouped markers; a group is neither
   one nor the other, so it says how many instead of guessing a direction. */
.cash-marker-cluster {
  fill: #0e1622;
  stroke: rgba(var(--tint), 0.85);
  stroke-width: 1.5;
}

:root[data-theme='light'] .cash-marker-cluster {
  fill: #1b2534;
  stroke: #ffffff;
}

.cash-marker-count {
  fill: #ffffff;
  font-size: 10px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

/* --- The selected-transaction panel ---------------------------------------
   Below the plot, never over it. A floating callout covers the data it is
   describing, and at 320px there is nowhere to put one that isn't on top of
   something. */
.cash-detail {
  margin: 0.5rem 0.15rem 0;
  padding: 0.7rem 0.8rem 0.75rem;
  border: 1px solid var(--edge-t12);
  border-radius: 14px;
  background: rgba(var(--tint), 0.035);
}

.cash-detail-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.8rem;
}

.cash-detail-date {
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mute-i55);
}

.cash-detail-amount {
  font-size: 1.05rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* Sign and colour both. The "+"/"−" carries it in greyscale. */
.cash-detail-amount.is-in {
  color: var(--cash-in);
}

.cash-detail-amount.is-out {
  color: var(--cash-out);
}

.cash-detail-name {
  margin: 0.15rem 0 0.3rem;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text);
  overflow-wrap: anywhere;
}

.cash-detail-after {
  margin: 0;
  font-size: 0.84rem;
  color: rgba(var(--ink-rgb), 0.68);
}

.cash-detail-after b {
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.cash-detail-list {
  margin: 0.55rem 0 0;
  padding: 0.5rem 0 0;
  border-top: 1px solid var(--rule-t10);
  list-style: none;
  display: grid;
  gap: 0.3rem;
}

.cash-detail-list li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.8rem;
  font-size: 0.84rem;
}

.cash-detail-item-name {
  color: rgba(var(--ink-rgb), 0.78);
  min-width: 0;
  overflow-wrap: anywhere;
}

.cash-detail-item-amount {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.cash-detail-item-amount.is-in {
  color: var(--cash-in);
}

.cash-detail-item-amount.is-out {
  color: var(--cash-out);
}

.cash-detail-more {
  color: var(--mute-i45);
  font-size: 0.8rem;
}

.cash-detail-alt {
  margin: 0.5rem 0 0;
  font-size: 0.8rem;
  color: var(--mute-i45);
}

.cash-detail-alt b {
  color: rgba(var(--ink-rgb), 0.8);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 560px) {

  /* The wrap's own padding is plot width on a phone. */
  .cash-chart-wrap {
    padding: 0.25rem 0.2rem 0.5rem;
    border-radius: 14px;
  }

  .cash-detail {
    margin-left: 0;
    margin-right: 0;
  }

  .cash-detail-name {
    font-size: 1rem;
  }

  .cash-chart-hint {
    padding: 0 0.3rem;
  }
}

/* Hover emphasis, distinct from selection: a hovered marker lifts slightly,
   a selected one gets the ring. Conflating the two made Escape look broken. */
.cash-marker.is-active .cash-marker-shape {
  filter: brightness(1.18);
}


/* An actions row whose only control has hidden itself must go too.
   .compact-form .form-actions carries a border-top and 0.85rem of padding, so a
   form with nothing to save was drawing a rule under empty space — a divider
   introducing a section that isn't there. :has() is already used elsewhere in
   this file for exactly this kind of container-follows-its-contents rule. */
.form-actions:not(:has(> *:not([hidden]))) {
  display: none;
}


/* Native <select> popups, once, instead of per-component.
   A styled select sets its own colour — near-white in dark — but the option
   LIST is drawn by the OS on its own background, so the text inherits that
   near-white and renders white-on-white. Three separate rules already existed
   for .auth-form, .inline-action-form and .field, each added the day somebody
   found another unreadable dropdown; .cash-bill-field never got one, which is
   what the cash-flow 'payments arriving late' menu was hitting.
   Both tokens flip with the theme, so this is correct on paper too. */
select option,
select optgroup {
  background: var(--bg-3);
  color: var(--text);
}

/* ── The information bubble ───────────────────────────────────────────────────
   A sentence a card used to spend a line on, folded behind a subtle ⓘ that sits
   immediately after the words it explains. Hover and keyboard focus are pure
   CSS; tap latches through data-open, because a phone has no hover to leave. */
.infotip {
  position: relative;
  display: inline-flex;
  vertical-align: middle;
  margin-left: 0.3rem;
}

.infotip-btn {
  display: grid;
  place-items: center;
  /* Visually small, but the tap target is expanded below — the glyph is 14px
     and a 14px button is not something a thumb can hit. */
  width: 14px;
  height: 14px;
  padding: 0;
  border: none;
  background: none;
  color: var(--mute-t50);
  cursor: pointer;
  border-radius: 999px;
}

.infotip-btn::after {
  content: '';
  position: absolute;
  inset: -0.6rem;
}

.infotip-btn svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
}

.infotip-btn:hover,
.infotip-btn:focus-visible {
  color: var(--accent-ink);
}

.infotip-bubble {
  position: absolute;
  /* BELOW the icon, never over it: the value and the action this annotates sit
     above, and a bubble that covers them trades one unreadable thing for
     another. */
  top: calc(100% + 0.45rem);
  z-index: 40;
  width: max-content;
  max-width: min(18rem, calc(100vw - 2rem));
  padding: 0.5rem 0.65rem;
  border-radius: 10px;
  border: 1px solid var(--edge-t16);
  background: var(--chrome, #101c2b);
  color: var(--text);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.4);
  font-size: 0.78rem;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: normal;
  /* Sentence case whatever it is dropped into — several of these sit inside
     uppercase metric labels. */
  text-transform: none;
  white-space: normal;
  /* NOT `visibility: hidden`, AND THIS IS WHY THE WHOLE APP PANNED SIDEWAYS.
     A visibility:hidden box is invisible but still laid out, and it still
     contributes scrollable overflow. This bubble is up to 288px wide, absolutely
     positioned from a 14px icon, and there is one in most metric cards — so on a
     390px phone the closed tooltips alone pushed the layout viewport to 534px
     (497px at 320, 522 at 360). Every dashboard page carrying a metric card
     could be dragged right into empty space, before anybody had touched a thing.

     The measurement that was supposed to prevent it could not: place() clamps
     the bubble against window.innerWidth, which is the ALREADY-WIDENED viewport,
     so it read 534px of room and clamped to a width that fits inside the
     overflow it caused.

     display:none costs the 0.12s fade on browsers without allow-discrete, which
     is the whole price. */
  display: none;
  opacity: 0;
  transition: opacity 0.12s ease, display 0.12s allow-discrete;
  pointer-events: none;
}

.infotip[data-align='start'] .infotip-bubble {
  left: 0;
}

.infotip[data-align='end'] .infotip-bubble {
  right: 0;
}

.infotip:hover .infotip-bubble,
.infotip:focus-within .infotip-bubble,
.infotip .infotip-bubble[data-open='true'] {
  display: block;
  opacity: 1;
}

/* The fade survives where the browser can transition a discrete property; where
   it cannot, the bubble simply appears, which is what a tooltip did for years. */
@starting-style {

  .infotip:hover .infotip-bubble,
  .infotip:focus-within .infotip-bubble,
  .infotip .infotip-bubble[data-open='true'] {
    opacity: 0;
  }
}

/* Touch has no hover state to leave, and :hover on a touch device sticks after
   a tap — which would leave two bubbles open at once. There, only the latched
   state counts. */
@media (hover: none) {
  .infotip:hover .infotip-bubble {
    display: none;
    opacity: 0;
  }

  .infotip .infotip-bubble[data-open='true'] {
    display: block;
    opacity: 1;
  }
}

/* ===========================================================================
   THE SCHEDULE PAGE, RESPONSIVE
   ===========================================================================
   Appended last on purpose: several rules below have to beat earlier ones at
   equal specificity (the four stat cards, the job dialog's stacking), and
   cascade order is the honest way to do that rather than an arms race of
   !important.

   THE BREAKPOINTS, AND WHAT EACH ONE IS FOR

     >= 1024   desktop / landscape tablet. The compact unscheduled queue is a
               permanent 250-300px column beside the calendar.
     768-1023  portrait tablet. One column. The queue becomes a panel you open
               from the banner, because two columns here means neither works.
     < 768     phone. A day planner (ScheduleMobileAgenda), not a month grid.
   =========================================================================== */

/* --- the shell ------------------------------------------------------------
   .wide-shell used to do this job and capped the page at 1100px. On a 1920
   screen that left ~400px of empty gutter down each side while the calendar --
   the entire point of the page -- was squeezed narrower than the rail beside
   it. Fluid instead: the app rail takes what it needs, this takes the rest. */
.schedule-shell {
  display: grid;
  gap: 1.1rem;
  align-content: start;
  /* 20-24px outer, and it must be padding rather than margin so the sticky rail
     inside measures against the right edge. */
  padding: 1.35rem clamp(1.25rem, 1.6vw, 1.5rem) 3rem;
  width: 100%;
  max-width: none;
  min-height: calc(100vh - 5.5rem);
  /* No page-level sideways scrolling at any supported width. Anything genuinely
     wider than the screen (the timeline view) scrolls inside its own box. */
  overflow-x: clip;
}

/* Grid items refuse to shrink below min-content unless told otherwise, and the
   calendar's 7 columns are exactly the kind of content that then pushes the
   page sideways. */
.schedule-shell>* {
  min-width: 0;
}

/* --- the workbench: queue, calendar, open job ------------------------------
   Single column is the default (phone and portrait tablet); columns arrive only
   once there is room for a readable grid beside them.

   At 1024 the queue becomes a deliberately compact rail: its cards use two
   fact columns and put actions below the facts, leaving the calendar the rest.
   Below that the page returns to one column and opens the queue from the bar.

   THE QUEUE IS SIZED AGAINST WHAT IS LEFT, NOT AGAINST THE SCREEN.
   A 1366x768 laptop has ~1054px for this whole page. A flat 420px column there
   left the calendar 595px -- seven columns of 85px, which measured 36 clipped
   labels. It starts at 300px and only widens once the screen can pay for it.

   1024 IS THE QUEUE'S OWN BREAKPOINT, not a new one: below it UnscheduledQueue
   is a full-screen overlay, so a column reserved for it would be an empty gap.

   THE THIRD COLUMN STARTS AT 1760, AND THAT NUMBER IS MEASURED RATHER THAN
   ESTIMATED -- twice, because the estimate was wrong both times.
   It was 1440 first, then 1600 on an arithmetic guess that the nav and page
   gutters cost 268px. They cost 338px: this grid measures viewport minus 338 at
   1440, 1600 and 1920 alike. So 1600 was really 1262px of grid, and two rails
   at their 340/380 growth limits plus two gaps left the calendar 506px --
   68px per weekday, WORSE than the ~82px this whole pass exists to fix.
   1760 gives 1422px of grid and a 666px calendar (95px per weekday); 1920 gives
   786px. Below 1760 the detail is an overlay instead; see .sched-detail.is-sheet.

   The rails take their MAX, not their min: a minmax() track fills to its growth
   limit before an fr track sees any free space, which is why sizing this off
   the 300px/320px minimums under-counted them by 100px. */
.schedule-workbench {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
}

@media (min-width: 1024px) {
  .schedule-workbench {
    grid-template-columns: minmax(250px, 300px) minmax(0, 1fr);
    gap: 1.15rem;
  }

  /* At least the rest of the viewport, so a quiet month still looks like a
     workspace instead of a card floating in a field of background. */
  .schedule-calendar-panel {
    min-height: calc(100vh - 12rem);
  }
}

@media (min-width: 1760px) {
  .schedule-workbench { grid-template-columns: minmax(300px, 340px) minmax(0, 1fr) minmax(320px, 380px); }
}

@media (min-width: 1860px) {
  .schedule-workbench {
    grid-template-columns: minmax(320px, 360px) minmax(0, 1fr) minmax(340px, 400px);
  }
}

/* --- the header row -------------------------------------------------------- */

.schedule-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.75rem 1rem;
}

.schedule-bar-id {
  flex: 1 1 14rem;
  min-width: 0;
}

.schedule-bar-id .workspace-title {
  margin: 0;
}

.schedule-bar-actions {
  flex: 0 0 auto;
}

/* ONE BAR WHERE THERE WERE FOUR CONTROLS.
   The primary button, the attention banner, the summary-line counter and a
   fourth stat card all said the same thing about the same jobs and pointed at
   the same list. On a phone three of them stacked one under the other before
   the calendar had drawn a date, and two of them counted a different population
   from the other two — so the page printed 11 and 3 for the same question.

   It renders at every width. The banner used to appear only below 1024 on the
   theory that the desktop rail said it already, which left the desktop with a
   button naming a count and nothing saying what the count was made of. */
.sched-queue-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem 0.9rem;
  width: 100%;
  margin: 0.15rem 0 0.9rem;
  padding: 0.6rem 0.85rem;
  border: 1px solid var(--cedge-amber-7);
  border-radius: 13px;
  background: rgba(255, 209, 102, 0.09);
  color: var(--text);
}

/* Nothing waiting is not an alert. Same bar, no amber — the state is calm and
   the control on it is "make a job", not "deal with this". */
.sched-queue-bar.is-clear {
  border-color: var(--edge-t12);
  background: rgba(var(--tint), 0.03);
}

/* Quotes only: this is a sales task, not a scheduling one, and colouring it the
   same as work-ready-to-book is what let the two get confused in the first
   place. Kept as a tone rather than a hue change so it is never colour alone —
   the sentence says "awaiting approval" outright. */
.sched-queue-bar[data-tone='waiting'] {
  border-style: dashed;
}

.sched-queue-bar-line {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex: 1 1 16rem;
  min-width: 0;
  margin: 0;
}

.sched-queue-bar-line strong {
  font-size: 0.95rem;
  font-weight: 750;
}

.sched-queue-bar-copy-mobile,
.sched-queue-action-copy-mobile {
  display: none;
}

.sched-queue-bar-line span:not(.sched-queue-bar-count) {
  color: var(--mute-i56);
  font-size: 0.84rem;
}

.sched-queue-bar.is-clear .sched-queue-bar-line {
  display: grid;
  gap: 0.1rem;
}

.sched-queue-bar-count {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  min-width: 2rem;
  height: 2rem;
  padding: 0 0.4rem;
  border-radius: 999px;
  background: #ffd166;
  color: #1a1206;
  font-size: 0.95rem;
  font-weight: 850;
}

.sched-queue-bar[data-tone='waiting'] .sched-queue-bar-count {
  background: rgba(var(--tint), 0.14);
  color: var(--text);
}

.sched-queue-bar-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-left: auto;
}

/* 44px, the floor for a touch target and also just a comfortable button. */
.sched-queue-bar-go {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
}

/* The compact summary that replaces the stat cards on a phone. Hidden wherever
   the cards themselves fit. */
.sched-sum {
  display: none;
}

/* --- the unscheduled queue -------------------------------------------------
   Desktop: transparent wrapper, the section flows into the rail. */
/**
 * THE DESKTOP RAIL IS A REAL COLUMN NOW, not display: contents.
 *
 * It had to become one to hold the collapse toggle. As `display: contents` the
 * wrapper vanished and its children became grid items directly — so a toggle
 * added here would have been a THIRD item in a two-column grid
 * (minmax(300px,340px) minmax(0,1fr)), pushing the calendar into a column that
 * does not exist.
 *
 * As a flex column the wrapper is the grid item, the toggle and the panel stack
 * inside it, and the grid is untouched. .sched-queue-panel stays
 * `display: contents` so the section it wraps is still the thing being laid
 * out, exactly as before.
 */
.sched-queue {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 0;
}

.sched-queue-panel {
  display: contents;
}

/* Collapsed: the list goes, the toggle stays. The panel is also marked `inert`
   in the component — a column you can still Tab into while it is hidden is
   worse than one that is simply there. */
.sched-queue.is-collapsed .sched-queue-panel {
  display: none;
}

.sched-queue-collapse {
  display: none;
  /* Only the desktop rail collapses; see the 1024 block. */
  align-items: center;
  gap: 0.35rem;
  align-self: flex-start;
  min-height: 44px;
  padding: 0 0.6rem;
  border: 1px solid var(--edge-t16);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
  color: var(--mute-i56);
  font: inherit;
  font-size: 0.74rem;
  font-weight: 700;
  cursor: pointer;
}

.sched-queue-collapse:hover {
  color: var(--text);
  border-color: var(--edge-t22);
}

.sched-queue-collapse:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

@media (min-width: 1024px) {
  .sched-queue-collapse {
    display: inline-flex;
  }

  /* Reclaim the column. Without this the rail keeps its 300px minimum and
     collapsing hides the list without giving the calendar the room — which is
     the only reason anybody would collapse it.
     :has() is the whole mechanism; where it is unsupported the toggle still
     works and the space simply is not reclaimed, which is a degradation rather
     than a break. */
  .schedule-workbench:has(.sched-queue.is-collapsed) {
    grid-template-columns: auto minmax(0, 1fr);
  }
}

/* EVERY RECLAIM RULE MUST DECLARE AS MANY TRACKS AS THE WIDTH IT LANDS ON.
 *
 * The rule above used to be the only one, and above 1760 it did the opposite of
 * what it exists for. At those widths the workbench holds THREE items — queue,
 * calendar, docked detail rail — and two declared tracks put the third into an
 * IMPLICIT ROW, underneath the collapsed toggle in column one. The auto track
 * then sized to that panel instead of to the toggle, so collapsing the queue
 * grew its column from 340px to 456px and pushed the calendar further right.
 * Measured at 1800 and 1920; below 1760 the same rule was always correct,
 * because there the detail rail is an overlay and there really are two items.
 *
 * So each breakpoint restates its own third track. Sharing one rule is what
 * caused this. */
@media (min-width: 1760px) {
  .schedule-workbench:has(.sched-queue.is-collapsed) {
    grid-template-columns: auto minmax(0, 1fr) minmax(320px, 380px);
  }
}

@media (min-width: 1860px) {
  .schedule-workbench:has(.sched-queue.is-collapsed) {
    grid-template-columns: auto minmax(0, 1fr) minmax(340px, 400px);
  }
}

.sched-queue-scrim,
.sched-queue-head {
  display: none;
}

/* Narrow: a real panel over the page, opened from the banner and dismissed with
   a Back button. NOT a fixed bottom dock -- that is what this replaces. The old
   one was pinned to the viewport bottom at every width under 1100px, so on a
   tablet and a phone it permanently covered the last row of dates and fought
   the job dialog for stacking order. */
@media (max-width: 1023.98px) {
  .sched-queue {
    display: block;
    position: fixed;
    inset: 0;
    /* Above the app chrome and both schedule toasts, below the job dialog. */
    z-index: 120;
    visibility: hidden;
    pointer-events: none;
  }

  .sched-queue.is-open {
    visibility: visible;
    pointer-events: auto;
  }

  .sched-queue-scrim {
    display: block;
    position: absolute;
    inset: 0;
    background: rgba(4, 8, 14, 0.72);
    opacity: 0;
    transition: opacity 0.2s ease;
  }

  .sched-queue.is-open .sched-queue-scrim {
    opacity: 1;
  }

  .sched-queue-panel {
    display: flex;
    flex-direction: column;
    position: absolute;
    inset: 0;
    /* dvh, so the panel ends at the visible bottom rather than under a phone's
       address bar. The vh line is the fallback for anything older. */
    height: 100vh;
    height: 100dvh;
    background: #0b1220;
    transform: translateY(1.5rem);
    opacity: 0;
    transition: transform 0.22s ease, opacity 0.22s ease;
  }

  .sched-queue.is-open .sched-queue-panel {
    transform: none;
    opacity: 1;
  }

  .sched-queue-panel:focus {
    outline: none;
  }

  .sched-queue-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex: 0 0 auto;
    padding: max(0.7rem, env(safe-area-inset-top, 0px)) 0.9rem 0.7rem;
    border-bottom: 1px solid var(--cedge-orange-8);
    background: rgba(10, 16, 25, 0.96);
  }

  .sched-queue-back {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    min-height: 44px;
    min-width: 44px;
    padding: 0 0.7rem;
    border: 1px solid var(--cedge-orange-8);
    border-radius: 11px;
    background: transparent;
    font: inherit;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--text);
    cursor: pointer;
  }

  .sched-queue-head-id {
    margin: 0;
    font-size: 0.9rem;
    font-weight: 750;
    color: var(--mute-i56);
  }

  .sched-queue-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  /* The sheet IS the panel; the card inside it should not draw a second one. */
  .sched-queue-body .workspace-section-card {
    border: 0;
    border-radius: 0;
    background: none;
  }

  /* Floating popovers cannot open inside a scrolling panel without being
     clipped, so in here they lay out inline. */
  .sched-queue-body .schedule-popover-panel {
    position: static;
    width: auto;
    max-height: none;
    margin-top: 0.5rem;
    box-shadow: none;
  }

  .sched-queue-body .schedule-popover-panel::before {
    display: none;
  }

  .sched-queue-body .schedule-action-buttons {
    flex-wrap: wrap;
  }

  .sched-queue-body .schedule-action-buttons>* {
    flex: 1 1 9rem;
  }

  .sched-queue-body .schedule-action-buttons .btn {
    min-width: 0;
    width: 100%;
  }
}

/* Portrait tablet and landscape tablet get a centred sheet rather than a full
   bleed -- a 420px job card stretched across 1024px is not a better card. */
@media (min-width: 768px) and (max-width: 1023.98px) {
  .sched-queue-panel {
    inset: 2.5rem;
    height: auto;
    max-height: calc(100dvh - 5rem);
    border: 1px solid var(--cedge-orange-8);
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 40px 90px -30px rgba(0, 0, 0, 0.8);
  }
}

/* ONLY ONE MAJOR OVERLAY AT A TIME. useModal marks the body with whichever is
   open; a job dialog stands the queue down rather than stacking on top of it. */
body[data-schedule-overlay="job"] .sched-queue {
  visibility: hidden;
  pointer-events: none;
}

/* --- the job dialog --------------------------------------------------------
   Above every page-level dock and sticky element, and bounded by the visible
   viewport so it can never hang off the bottom of a phone. */
.schedule-job-backdrop {
  z-index: 200;
  align-items: center;
  padding: clamp(0.75rem, 3vw, 2rem);
}

.schedule-job-backdrop .schedule-job-actions-panel {
  max-height: calc(100dvh - 2rem);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.schedule-job-actions-panel:focus {
  outline: none;
}

/* The facts that no longer fit on a month chip, printed with their labels. */
/* ---- the open job, in three named sections -------------------------------
   It was one scroll: facts, a row of four buttons with the crew picker hidden
   inside it as a fifth, a reschedule form, a remove box. Nothing said where one
   job ended and the next began. */
.schedule-job-section {
  padding-top: 0.9rem;
  border-top: 1px solid var(--edge-t10);
}

.schedule-job-section:first-of-type {
  padding-top: 0;
  border-top: 0;
}

.schedule-job-section-title {
  margin: 0 0 0.6rem;
  font-family: var(--font-display);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mute-t55);
}

.schedule-job-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.55rem 0.9rem;
  margin: 0.9rem 0 0;
  padding: 0.8rem 0.9rem;
  border: 1px solid var(--cedge-orange-5);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.02);
}

.schedule-job-facts>div {
  min-width: 0;
}

.schedule-job-facts-wide {
  grid-column: 1 / -1;
}

.schedule-job-facts dt {
  margin: 0 0 0.15rem;
  color: var(--mute-i56);
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.schedule-job-facts dd {
  margin: 0;
  color: var(--text);
  font-size: 0.88rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

/* --- month chips ----------------------------------------------------------
   Three lines that each say one whole thing, instead of six half-things. */
.calendar-job-chip-when {
  display: block;
  color: var(--mute-i56);
  /* 10.7px. The old chip ran to 9.6px on three of its lines; anything under
     ~10.5px on a dark ground is where these stopped being readable. */
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1.25;
}

.calendar-job-chip-sig {
  display: block;
  overflow: hidden;
  font-size: 0.66rem;
  font-weight: 700;
  line-height: 1.3;
  /* WRAPS RATHER THAN ELLIPSISES. "Work scheduled" does not fit one line in a
     ~99px cell at a readable size, and half a status word tells you less than a
     status word on two lines. Capped so a long label cannot push the cell. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow-wrap: anywhere;
}

.calendar-job-chip-main {
  font-size: 0.75rem;
  line-height: 1.25;
}

/* --- the calendar footer --------------------------------------------------- */

.schedule-foot-plan {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 44px;
  padding: 0 0.75rem;
  border: 1px solid var(--cedge-orange-8);
  border-radius: 11px;
  font-size: 0.85rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--text);
}

.schedule-foot-plan:hover {
  border-color: var(--cedge-orange-17);
  color: var(--ink-orange-10);
}

/* --- schedule settings -----------------------------------------------------
   Everything you configure once, in one group, after everything you do daily. */
.sched-settings {
  display: grid;
  gap: 0.8rem;
  margin-top: 0.5rem;
  padding-top: 1.1rem;
  border-top: 1px solid var(--cedge-orange-5);
}

.sched-settings>* {
  min-width: 0;
}

.sched-settings-h {
  margin: 0;
  color: var(--mute-i56);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.sched-settings-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

/* --- phone ----------------------------------------------------------------- */

@media (max-width: 767.98px) {
  .schedule-shell {
    padding: 0.9rem 0.85rem 2.5rem;
    gap: 0.85rem;
  }

  /* FOUR STAT CARDS BECOME ONE SENTENCE. At 390px the cards went two-up at
     ~168px, which truncated "Costs logged", or four-up at 84px, which fits
     nothing at all. The sentence carries the same numbers and wraps. */
  .schedule-stats {
    display: none;
  }

  .sched-sum {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0.15rem 0.7rem;
    margin: 0.3rem 0 0;
    color: var(--mute-i56);
    font-size: 0.82rem;
    line-height: 1.45;
  }

  .sched-sum span {
    white-space: nowrap;
  }

  .sched-sum strong {
    color: var(--text);
    font-weight: 800;
  }

  /* The bar's buttons go full width rather than squeezing onto the same row as
     a wrapping heading, and the count keeps its own line above them. */
  .schedule-bar {
    gap: 0.6rem;
  }

  .sched-queue-bar-line {
    flex: 1 1 100%;
  }

  .sched-queue-bar-copy,
  .sched-queue-action-copy {
    display: none;
  }

  .sched-queue-bar-copy-mobile,
  .sched-queue-action-copy-mobile {
    display: inline;
  }

  .sched-queue-bar-actions {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(7rem, 1fr));
    flex: 1 1 100%;
    width: 100%;
    margin-left: 0;
  }

  .sched-queue-bar-go {
    min-width: 0;
    justify-content: center;
  }

  .schedule-calendar-panel {
    padding: 0.9rem 0.8rem 1rem;
  }
}

/* --- interaction floors ----------------------------------------------------
   Applied here rather than per-control so nothing added later quietly falls
   below them. */
.schedule-shell button:focus-visible,
.schedule-shell a:focus-visible,
.schedule-shell summary:focus-visible,
.schedule-shell [tabindex]:focus-visible,
.sched-queue button:focus-visible,
.sched-queue a:focus-visible,
.sched-queue summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 8px;
}

@media (pointer: coarse) {

  .schedule-shell .sched-card-options,
  .schedule-shell .schedule-action-buttons .btn,
  .schedule-shell .schedule-popover>summary,
  .sched-queue-body .schedule-popover>summary,
  .sched-queue-body .schedule-action-buttons .btn {
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {

  .sched-queue-panel,
  .sched-queue-scrim {
    transition: none;
  }
}

/* --- KPI cards -------------------------------------------------------------
   The caption under each figure was 9.6px and nowrap, so "Jobs · 30d" and
   "Costs logged" were both a truncation waiting for a narrow enough column.
   11.2px and allowed to wrap: the card grows a line rather than losing a word. */
.schedule-shell .sched-stat small {
  font-size: 0.7rem;
  letter-spacing: 0.045em;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.25;
}

.schedule-shell .sched-stat {
  min-height: 44px;
  align-content: center;
}

.schedule-shell .sched-stat-message {
  max-width: 17ch;
  font-size: 1rem;
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.schedule-shell .sched-stat-action {
  color: var(--accent-ink);
  font-weight: 800;
}

.sched-sum-alert strong {
  color: var(--ink-amber-1);
}

/* The schedule is an operational surface, so status earns color and ordinary
   navigation does not. Removing the instrument-panel halos leaves the queue,
   missing durations, and over-capacity states as the things that carry heat. */
.schedule-shell .sched-stat,
.schedule-shell .sched-stat:hover {
  border-color: var(--edge-t16);
  background: rgba(var(--tint), 0.035);
  box-shadow: none;
}

.schedule-shell .sched-stat.needs,
.schedule-shell .sched-stat.needs:hover {
  border-color: var(--cedge-amber-7);
  background: rgba(255, 209, 102, 0.075);
  box-shadow: none;
}

.schedule-shell .sched-stat-icon,
.schedule-shell .sched-stat.needs .sched-stat-icon {
  filter: none;
}

.schedule-shell .calendar-view-quick,
.schedule-shell .calendar-view-trigger {
  border-color: var(--edge-t16);
  background: rgba(var(--tint), 0.035);
}

.calendar-view-option-link {
  text-decoration: none;
}

/* One page scroll. The range and view controls stay available while the axis
   moves beneath them, but the timeline and queue no longer add their own
   vertical scrollbars. */
@media (min-width: 641px) {
  .schedule-shell .calendar-toolbar-wrap {
    position: sticky;
    top: 0.5rem;
    z-index: 15;
    margin: -0.35rem -0.35rem 0;
    padding: 0.35rem;
    border: 1px solid var(--edge-t10);
    border-radius: 13px;
    background: rgba(var(--panel-rgb), 0.94);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }
}

@media (max-width: 640px) {
  .schedule-shell .sched-card-top {
    align-items: flex-start;
  }

  .schedule-shell .sched-card-badge {
    max-width: 62%;
    white-space: normal;
    overflow-wrap: anywhere;
    text-align: right;
    line-height: 1.25;
  }
}

/* --- the chip stops truncating names ---------------------------------------
   .calendar-job-chip has carried `white-space: nowrap` since it was a one-line
   chip, and .calendar-job-chip-main added `text-overflow: ellipsis` on top. With
   the chip down to three short lines there is no longer any reason to cut a
   customer's name: measured at 1440 the name line had ~57px to render
   "Colton E." in, and ellipsised it rather than using the second line sitting
   empty beneath it. Wrapping to at most two lines fits every name in the fixture
   set and lets the cell grow the few pixels it needs.

   Not scoped to .schedule-shell on purpose — this is the chip's own markup, and
   the demo calendar renders exactly the same component. */
.calendar-job-chip {
  white-space: normal;
}

.calendar-job-chip-main {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
  overflow-wrap: anywhere;
  text-overflow: clip;
}

/* THE CREW-BADGE RESERVATION MOVES TO THE LINE THE BADGE ACTUALLY SITS ON.
   .calendar-crew-toggle is absolutely positioned at the chip's top right, and
   the 1.25rem of padding reserved for it was welded to .calendar-job-chip-main
   because the name used to be the first line. The name is the SECOND line now,
   so that reservation was 20px taken out of the middle of the chip for a badge
   nowhere near it — measured as 8-13px of overflow on every name at 1366 and
   1440, which is what produced "N i..." and "M a...". The time line is what sits
   under the badge, so the reservation belongs there. */
.calendar-job-item .calendar-job-chip .calendar-job-chip-main {
  padding-right: 0;
}

.calendar-job-chip-when {
  padding-right: 1.25rem;
}

/* BREAK AT SPACES, NOT ANYWHERE. `overflow-wrap: anywhere` is what turned
   "Nina D." into one character per line once the box got tight — the same
   failure the mobile agenda was built to escape. Names break between words or
   not at all; a single word too long for the cell ellipsises, which is the one
   case where cutting is better than stacking letters. */
.calendar-job-chip-main {
  overflow-wrap: normal;
  word-break: normal;
  text-overflow: ellipsis;
}

/* AND THE LARGER OF THE TWO RESERVATIONS, WHICH IS THE ONE THAT HURT.
   A second rule reserves 3rem — 48px — on the name line when a crew toggle is
   present, sized for the widest possible badge ("WW+9"). Out of a ~60px name box
   at 1366 that leaves about 12px, which is one letter. Same reasoning as above:
   the badge is at the chip's top right, so the reservation belongs to the line
   under it. Matched selector-for-selector because :has() carries the specificity
   of its argument and a shorter selector would silently lose. */
.calendar-job-item>.calendar-job-chip:has(+ .calendar-crew-toggle) .calendar-job-chip-main {
  padding-right: 0;
}

.calendar-job-item>.calendar-job-chip:has(+ .calendar-crew-toggle) .calendar-job-chip-when {
  padding-right: 3rem;
}

/* --- and the fourth thing has to go ----------------------------------------
   A month cell at 1366 is ~76px wide, ~62px of it usable. The brief asks a
   month card for three things — start time, customer, one operational signal —
   and the crew badge is a fourth. Reserving even the badge's minimum beside a
   "10:30a" time leaves nothing, and reserving its maximum ("WW+9", 3rem) made
   the chip's min-content 82px inside a 62px box: measured as +29px of overflow,
   which is what was cutting "Quote sen" and "Margueri".

   So below the width where the grid can pay for it, the badge comes off the
   month chip. Nothing is lost: the chip opens the job dialog, which now lists
   crew by full name along with everything else that used to be crammed in here,
   and the Agenda and Week views still show crew inline. */
@media (max-width: 1519.98px) {
  .calendar-grid .calendar-job-item>.calendar-crew-toggle {
    display: none;
  }

  .calendar-grid .calendar-job-chip-when,
  .calendar-grid .calendar-job-item>.calendar-job-chip:has(+ .calendar-crew-toggle) .calendar-job-chip-when {
    padding-right: 0;
  }
}

/* Above it there is room for the badge and the time to share a line. */
@media (min-width: 1520px) {

  .calendar-job-chip-when,
  .calendar-job-item>.calendar-job-chip:has(+ .calendar-crew-toggle) .calendar-job-chip-when {
    padding-right: 2.9rem;
  }
}

/* The signal wraps to a second line rather than being cut mid-word. */
.calendar-job-chip-sig {
  white-space: normal;
}

/* --- the queue's cards, in the overlay -------------------------------------
   The rail gets a compact treatment above 1024 (stacked card, one-column form,
   inline popovers). The overlay never did, because until now the overlay was a
   bottom dock with its own rules. Same shape, same reasons: at these widths the
   row's name-beside-buttons layout has nowhere to go. */
@media (max-width: 1023.98px) {
  .sched-queue-body .sign-in-method-row {
    flex-direction: column;
    align-items: stretch;
    /* Without this the row stretches to the tallest sibling and leaves a band of
       dead space between the address and the buttons. */
    justify-content: flex-start;
    gap: 0.6rem;
  }

  .sched-queue-body .schedule-method-row .method-info {
    flex: 0 1 auto;
    min-width: 0;
  }

  .sched-queue-body .schedule-inline-form {
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
  }
}

/* On a phone the two actions stack full width. Side by side they were 9rem
   each, which broke "Choose date & time" over two lines and "Offer customer
   times" over three. */
@media (max-width: 640px) {
  .sched-queue-body .schedule-action-buttons {
    flex-direction: column;
    gap: 0.5rem;
  }

  .sched-queue-body .schedule-action-buttons>* {
    flex: 0 0 auto;
    width: 100%;
  }

  .sched-queue-body .schedule-action-buttons .btn {
    width: 100%;
  }
}

/* ===========================================================================
   THE SCHEDULE, AGAINST A CLOCK
   ===========================================================================
   Day / Week / three-day timeline, the crew lanes, and the month rebuilt as a
   capacity overview.

   WHAT THIS REPLACED. A month grid where every cell was ~95px at 1366 and was
   being asked to hold a customer, a start time, a price, a crew, a status and a
   duration. Six ellipses. Worse, it could not answer the question the page is
   for: two jobs on a Tuesday look identical whether they are at 8am and 2pm or
   both at 9am with the same person on both.

   ONE SET OF COLOUR TOKENS. The six job colours were written directly onto
   `.calendar-band.calendar-band-color-N`, which the new elements do not carry.
   Rather than copy six declarations three more times, the tokens below sit on
   the bare class so anything with a job colour can read them. The existing
   .calendar-band rules are untouched and still win on their own elements. */

.calendar-band-color-0 {
  --job-line: var(--rail-crew-0);
  --job-fill: rgba(255, 138, 61, .24);
  --job-ink: var(--ink-orange-4);
}

.calendar-band-color-1 {
  --job-line: var(--rail-crew-1);
  --job-fill: rgba(61, 184, 255, .2);
  --job-ink: var(--ink-sky-3);
}

.calendar-band-color-2 {
  --job-line: var(--rail-crew-2);
  --job-fill: rgba(120, 220, 150, .2);
  --job-ink: var(--ink-green-4);
}

.calendar-band-color-3 {
  --job-line: var(--rail-crew-3);
  --job-fill: rgba(255, 209, 102, .2);
  --job-ink: var(--ink-amber-5);
}

.calendar-band-color-4 {
  --job-line: var(--rail-crew-4);
  --job-fill: rgba(255, 112, 163, .2);
  --job-ink: var(--ink-pink-1);
}

.calendar-band-color-5 {
  --job-line: var(--rail-crew-5);
  --job-fill: rgba(176, 141, 255, .2);
  --job-ink: var(--ink-violet-3);
}

/* The fills are translucent over a dark panel. On the light theme the same
   alpha reads as a grey smudge, so they are lifted — the --job-line and
   --job-ink tokens are already theme-aware and need nothing here. */
:root[data-theme='light'] .calendar-band-color-0,
:root[data-theme='sunlight'] .calendar-band-color-0 {
  --job-fill: rgba(255, 138, 61, .16);
}

:root[data-theme='light'] .calendar-band-color-1,
:root[data-theme='sunlight'] .calendar-band-color-1 {
  --job-fill: rgba(61, 184, 255, .14);
}

:root[data-theme='light'] .calendar-band-color-2,
:root[data-theme='sunlight'] .calendar-band-color-2 {
  --job-fill: rgba(76, 190, 120, .14);
}

:root[data-theme='light'] .calendar-band-color-3,
:root[data-theme='sunlight'] .calendar-band-color-3 {
  --job-fill: rgba(233, 178, 60, .16);
}

:root[data-theme='light'] .calendar-band-color-4,
:root[data-theme='sunlight'] .calendar-band-color-4 {
  --job-fill: rgba(255, 112, 163, .14);
}

:root[data-theme='light'] .calendar-band-color-5,
:root[data-theme='sunlight'] .calendar-band-color-5 {
  --job-fill: rgba(146, 110, 235, .14);
}

:root[data-theme='clarity'] .calendar-band-color-0 {
  --job-line: #56b4e9;
  --job-fill: rgba(86, 180, 233, 0.20);
  --job-ink: #56b4e9;
}

:root[data-theme='clarity'] .calendar-band-color-1 {
  --job-line: #8ecdf0;
  --job-fill: rgba(142, 205, 240, 0.20);
  --job-ink: #8ecdf0;
}

:root[data-theme='clarity'] .calendar-band-color-2 {
  --job-line: #f0e442;
  --job-fill: rgba(240, 228, 66, 0.20);
  --job-ink: #f0e442;
}

:root[data-theme='clarity'] .calendar-band-color-3 {
  --job-line: #ff6b4a;
  --job-fill: rgba(255, 107, 74, 0.20);
  --job-ink: #ff6b4a;
}

:root[data-theme='clarity'] .calendar-band-color-4 {
  --job-line: #cc79a7;
  --job-fill: rgba(204, 121, 167, 0.20);
  --job-ink: #cc79a7;
}

:root[data-theme='clarity'] .calendar-band-color-5 {
  --job-line: #d55e00;
  --job-fill: rgba(213, 94, 0, 0.20);
  --job-ink: #d55e00;
}

:root[data-theme='monochrome'] .calendar-band-color-0,
:root[data-theme='monochrome'] .calendar-band-color-1,
:root[data-theme='monochrome'] .calendar-band-color-2,
:root[data-theme='monochrome'] .calendar-band-color-3,
:root[data-theme='monochrome'] .calendar-band-color-4,
:root[data-theme='monochrome'] .calendar-band-color-5 {
  --job-line: #ffffff;
  --job-fill: rgba(255, 255, 255, 0.14);
  --job-ink: #ffffff;
}

:root[data-theme='parchment'] .calendar-band-color-0 {
  --job-line: #a84c00;
  --job-fill: rgba(168, 76, 0, 0.15);
  --job-ink: #a84c00;
}

:root[data-theme='parchment'] .calendar-band-color-1 {
  --job-line: #17518f;
  --job-fill: rgba(23, 81, 143, 0.15);
  --job-ink: #17518f;
}

:root[data-theme='parchment'] .calendar-band-color-2 {
  --job-line: #2d6a4f;
  --job-fill: rgba(45, 106, 79, 0.15);
  --job-ink: #2d6a4f;
}

:root[data-theme='parchment'] .calendar-band-color-3 {
  --job-line: #b45309;
  --job-fill: rgba(180, 83, 9, 0.15);
  --job-ink: #b45309;
}

:root[data-theme='parchment'] .calendar-band-color-4 {
  --job-line: #a81c51;
  --job-fill: rgba(168, 28, 81, 0.15);
  --job-ink: #a81c51;
}

:root[data-theme='parchment'] .calendar-band-color-5 {
  --job-line: #6a34cc;
  --job-fill: rgba(106, 52, 204, 0.15);
  --job-ink: #6a34cc;
}

/* ---- the range stepper --------------------------------------------------- */
/* Day and Week step in local state, so these are buttons where the month nav
   is links. Styled off .month-nav so the two are the same control. */
.sched-range-nav .month-nav-arrow,
.sched-range-nav .month-nav-today {
  border: 1px solid var(--line);
  background: rgba(var(--tint), 0.03);
  cursor: pointer;
  font: inherit;
}

.sched-range-nav .month-nav-label {
  white-space: nowrap;
}

/* ---- the timeline -------------------------------------------------------- */

.sched-tl {
  --tl-gutter: 3.5rem;
  display: grid;
  grid-template-columns: var(--tl-gutter) repeat(var(--tl-cols, 1), minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(var(--tint), 0.015);
  /* clip, not hidden. It clips to the rounded corners exactly as before, but
     it does NOT become a scroll container — which is the whole reason
     .sched-tl-head can now stick to the page. Nothing scrolls this box
     programmatically; the one scrollTop we set is on .sched-tl-scroll inside
     it. */
  overflow: clip;
}

/* The column count comes from the number of days rendered, not from a
   breakpoint: the component decides how many days fit and CSS follows it, so
   the two cannot disagree about what is on screen. */
.sched-tl[data-days='1'] {
  --tl-cols: 1;
}

.sched-tl[data-days='2'] {
  --tl-cols: 2;
}

.sched-tl[data-days='3'] {
  --tl-cols: 3;
}

.sched-tl[data-days='4'] {
  --tl-cols: 4;
}

.sched-tl[data-days='5'] {
  --tl-cols: 5;
}

.sched-tl[data-days='6'] {
  --tl-cols: 6;
}

.sched-tl[data-days='7'] {
  --tl-cols: 7;
}

/* ONE TEMPLATE, WRITTEN OUT, NOT subgrid.
   The body is not a child of .sched-tl — it sits inside .sched-tl-scroll, which
   is the actual grid item — so `grid-template-columns: subgrid` had no parent
   grid to inherit from and resolved to `none`. Every column then became a full
   width row: measured at 1920 the seven "columns" were 976px each and stacked,
   with every block collapsed to a few pixels tall inside them. The template is
   cheap to repeat and cannot come apart like that. */
.sched-tl-head,
.sched-tl-anytime,
.sched-tl-body {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: var(--tl-gutter) repeat(var(--tl-cols, 1), minmax(0, 1fr));
}

/**
 * STICKY AGAINST THE PAGE, WHICH IS THE ONLY THING THAT SCROLLS PAST IT.
 *
 * It used to say "not sticky, deliberately", and the reasoning held right up
 * until the hour rows were halved twice. The head is a sibling of the internal
 * scroll container, so it was already safe from THAT scroll — but the calendar
 * still sits on a long dashboard page, and scrolling the page took the column
 * names away while leaving a grid of unlabelled columns behind.
 *
 * The blocker named in the old comment was real: .sched-tl carried
 * overflow:hidden, which makes it a scroll container, and a sticky child sticks
 * to its nearest scrolling ancestor — so it stuck to a box that never scrolls
 * and did nothing. overflow:clip clips identically without establishing a
 * scrollport, which hands the head back to the page scroller. See .sched-tl.
 *
 * OPAQUE, and now for a reason: rows genuinely pass underneath it. The old
 * translucent 3% tint over the card would have let 8am read through the
 * weekday names.
 */
.sched-tl-head {
  position: sticky;
  top: 0;
  z-index: 4;
  border-bottom: 1px solid var(--line);
  background: var(--bg-3);
  /* SAYS ITS OWN INK, because it paints its own background. Inherited, the day
     numbers came out at 2.39:1 on the light theme's white sticky row — a colour
     picked for the panel behind it, on a surface that is no longer the panel. */
  color: var(--text);
}

.sched-tl-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 0.3rem;
  border-right: 1px solid var(--line);
  color: var(--mute-i60);
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/**
 * MON over 10 — not "MON 10" sharing a baseline.
 *
 * On one line at 0.66rem and 1rem the weekday and the date were close enough
 * in size to read as a single string, and the Closed pill, thrown to the far
 * end of the row by margin-left:auto, carried more colour than either of them.
 * The thing the header exists to answer — which day is this column? — was the
 * third thing the eye landed on.
 *
 * Stacked, the number wins on size alone and the badge drops to a third line
 * where it annotates the day rather than competing with it. justify-content
 * centres the stack so the columns with no badge still sit level with the ones
 * that have one.
 */
.sched-tl-day-head {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 0.1rem;
  min-height: 56px;
  padding: 0.4rem 0.6rem;
  border-right: 1px solid var(--line);
  min-width: 0;
}

.sched-tl-day-head:last-child {
  border-right: 0;
}

.sched-tl-day-head small {
  color: var(--mute-i60);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
}

/* Tabular figures, so 11 and 30 take the same width and a row of dates reads
   as a row rather than a ragged one. */
.sched-tl-day-head strong {
  font-size: 1.35rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

/**
 * TODAY IS A FILL AND A BAR, NOT A COLOUR SWAP.
 *
 * Orange text was the whole marker, which asks the reader to compare five
 * numbers and pick the odd one out — and asks a red-green colourblind reader
 * to tell an orange from a grey at 0.66rem. The inset bar is a second channel
 * that does not depend on hue, and it lands in the same place every time, so
 * it can be found without reading anything.
 */
.sched-tl-day-head.today {
  background: rgba(255, 122, 33, 0.09);
  box-shadow: inset 0 -3px 0 var(--accent);
}

.sched-tl-day-head.today small {
  color: var(--accent-ink);
}

/* --accent-ink, not --accent. The raw brand orange on the head's now-white
   background measured 2.39:1 at 22px, and 3:1 is the floor for text that size.
   The inset bar underneath is what actually marks today; the colour agrees with
   it rather than carrying it alone. */
.sched-tl-day-head.today strong {
  color: var(--accent-ink);
}

/* margin-left:auto pushed these to the right end of a ROW. In a column it
   would push them to the right edge instead, breaking the left alignment the
   stack is built on. */
.sched-tl-head-count {
  margin-left: 0;
  color: var(--mute-i60);
  font-size: 0.66rem;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}

/* Explicit, because the inherited 1.5 on a third line is 5px of the header's
   height spent on nothing — and the header height is the budget being kept. */
.sched-tl-head-flag {
  margin-left: 0;
  padding: 0.05rem 0.34rem;
  border-radius: 999px;
  font-size: 0.58rem;
  line-height: 1.25;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/**
 * The two flags that are news keep their pill. The one that is not loses it.
 *
 * A Sunday being closed is the schedule working correctly, and it was drawn
 * with the same filled pill as "this day is full" and "there is work on a day
 * you are closed" — so the routine state shouted as loudly as the two
 * exceptions, on more days. Flattening all three would have been the other
 * error; only the routine one comes down.
 */
/* 9px text needs the full 4.5:1, and the two orange inks measured 4.49 and
   4.48 on this wash — near enough to look fixed and not be. The amber ink is
   the same hue family, is what the rest of the schedule uses for "this needs
   your attention", and is dark enough in the light palette (#886016) to clear
   it outright. */
.sched-tl-head-flag.full {
  background: rgba(255, 138, 61, .18);
  color: var(--ink-amber-1);
}

.sched-tl-head-flag.blocked {
  padding: 0;
  background: none;
  color: var(--mute-i60);
}

/* ---- the "no start time" strip ------------------------------------------- */
.sched-tl-anytime {
  border-bottom: 1px solid var(--line);
  background: rgba(var(--tint), 0.02);
}

.sched-tl-anytime-label {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 0.35rem 0.45rem;
  border-right: 1px solid var(--line);
  color: var(--mute-i60);
  font-size: 0.6rem;
  text-align: right;
  line-height: 1.15;
}

.sched-tl-anytime-col {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.3rem 0.3rem;
  border-right: 1px solid var(--line);
  min-width: 0;
}

.sched-tl-anytime-col:last-child {
  border-right: 0;
}

.sched-tl-chip {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  min-width: 0;
  padding: 0.22rem 0.4rem;
  border: 1px solid var(--job-line, var(--line));
  border-left-width: 3px;
  border-radius: 6px;
  background: var(--job-fill, rgba(var(--tint), 0.04));
  color: var(--job-ink, var(--ink));
  font-size: 0.8rem;
  text-align: left;
  cursor: pointer;
  touch-action: none;
}

.sched-tl-chip-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 650;
}

.sched-tl-chip-untimed {
  align-items: flex-start;
  padding: 0.4rem 0.5rem;
}

.sched-tl-chip-lines {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
  flex: 1 1 auto;
}

.sched-tl-chip-scope,
.sched-tl-chip-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-tl-chip-scope {
  color: var(--text);
  font-size: 0.72rem;
}

.sched-tl-chip-meta {
  color: var(--mute-i60);
  font-size: 0.68rem;
}

.sched-tl-chip-note {
  margin-left: auto;
  flex: 0 0 auto;
  color: var(--mute-i60);
  /* "No time" is the whole reason this chip is above the axis instead of on
     it, so it was the wrong thing on the card to set in 9.6px. */
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.sched-tl-chip-planned {
  border-style: dashed;
  border-left-width: 1px;
  background: transparent;
  color: var(--mute-i60);
}

/* ---- the body ------------------------------------------------------------ */
/* NO SCROLLBAR INSIDE THE SCROLLBAR.
   This was capped at min(62vh, 720px) so the calendar could not push the
   unscheduled rail off the bottom of a laptop. The cap did its job and cost
   more than it saved: at 62px an hour it showed eleven and a half hours, so a
   working day of 7am to 7pm arrived with a second scrollbar down the inside of
   a page that already had one — and the hours you could not see were the
   evening, which is where the overruns are.

   The hour is 52px now (see HOUR_PX) and the box is exactly as tall as the
   hours it holds, so the axis always fits and this never scrolls. Thirteen
   hours at 52 is 676px — still under the old 720 cap, so the rail below has
   not lost anything either. `clip` keeps a block dragged past the last hour
   from drawing over the settings without creating another scroll surface. */
.sched-tl-scroll {
  grid-column: 1 / -1;
  max-height: calc(var(--tl-hours) * var(--tl-hour-h));
  overflow-y: clip;
}

.sched-tl-body {
  min-height: calc(var(--tl-hours) * var(--tl-hour-h));
}

.sched-tl-gutter {
  display: grid;
  grid-auto-rows: var(--tl-hour-h);
  border-right: 1px solid var(--line);
}

.sched-tl-hour {
  padding: 0.15rem 0.45rem 0 0;
  color: var(--mute-i60);
  font-size: 0.66rem;
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}

/* The blocks inside are positioned as a PERCENTAGE of the column, so the column
   has to have a height of its own. Stating it here rather than relying on the
   row stretching to the body's min-height means a block cannot collapse if the
   grid ever gains a second row. */
.sched-tl-col {
  position: relative;
  min-height: calc(var(--tl-hours) * var(--tl-hour-h));
  border-right: 1px solid var(--line);
  min-width: 0;
  /* ONE LINE PER HOUR.
     There was a second, fainter gradient on the half hour, so a day read as
     twenty-six bands rather than thirteen — and the gutter only labels the
     hour, which left every other line unnamed and the grid busier than the
     work drawn on it. The half hour is not a thing anyone books to on this
     view: a block's own top edge says when it starts, to the minute. */
  background-image:
    repeating-linear-gradient(to bottom, var(--line) 0 1px, transparent 1px var(--tl-hour-h));
}

.sched-tl-col:last-child {
  border-right: 0;
}

.sched-tl-col.today {
  background-color: rgba(255, 138, 61, .05);
}

.sched-tl-col.blocked {
  background-color: rgba(var(--tint), 0.05);
}

.sched-tl-col.drag-over {
  background-color: rgba(255, 138, 61, .16);
  box-shadow: inset 0 0 0 2px var(--accent);
}

.sched-tl-col.armable {
  cursor: copy;
}

.sched-tl-blocked-note {
  position: absolute;
  inset: 0.6rem 0.4rem auto;
  margin: 0;
  color: var(--mute-i60);
  font-size: 0.68rem;
  text-align: center;
  line-height: 1.35;
}

/* The current time. Deliberately not a job colour — it is the only line on the
   grid that means "now" and it has to be unmistakable at a glance. */
.sched-tl-now {
  position: absolute;
  left: 0;
  right: 0;
  height: 0;
  border-top: 2px solid var(--bad);
  z-index: 2;
  pointer-events: none;
}

.sched-tl-now::before {
  content: '';
  position: absolute;
  left: -1px;
  top: -4px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--bad);
}

/* ---- a job on the grid --------------------------------------------------- */
.sched-tl-job {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  overflow: hidden;
  /**
   * THE FLOOR UNDER A SHORT JOB.
   *
   * Heights are a percentage of the axis, so at a 22px hour a half-hour job is
   * 11px — less than one line of type plus its border, which means an
   * unreadable sliver with `overflow: hidden` quietly eating the customer's
   * name. 21px is one xs row exactly: 2px of border, 3.2px of padding-block,
   * and a 15.7px line.
   *
   * The cost is honest and worth naming: a very short block now overstates its
   * duration by a few pixels at the BOTTOM. The top edge is still exact, and
   * the top edge is what the eye reads a calendar by — a block whose height is
   * approximate beats a block nobody can read.
   */
  min-height: 21px;
  padding: 0.28rem 0.4rem;
  border: 1px solid var(--job-line, var(--line));
  border-left: 3px solid var(--job-line, var(--accent));
  border-radius: 7px;
  background: var(--job-fill, rgba(var(--tint), 0.06));
  color: var(--job-ink, var(--ink));
  text-align: left;
  cursor: pointer;
  /* The pointer drag handler needs the browser to stop scrolling for it. */
  touch-action: none;
  /* Blocks that share a column get a hairline between them so two abutting
     jobs never read as one. */
  box-shadow: 0 1px 0 rgba(var(--panel-rgb), 0.5), -1px 0 0 rgba(var(--panel-rgb), 0.5);
}

/* Side-by-side blocks are separated by the box-shadow above, not by shrinking
   them: the width is an inline percentage from the packer and a rule here would
   overwrite it. What they do get is tighter padding — a shared block in a week
   column is about 62px, and 0.4rem each side is a fifth of it. */
.sched-tl-job.shared {
  padding-inline: 0.24rem;
  border-left-width: 2px;
}

.sched-tl-job:hover {
  filter: brightness(1.12);
  z-index: 4;
}

.sched-tl-job:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  z-index: 4;
}

.sched-tl-job.dragging {
  opacity: 0.45;
}

/* THE TYPE FLOOR ON THIS CARD IS 12px.
   Everything here ran between 9.3px and 12.2px, which is caption size for what
   is not a caption — a customer's name, when they are coming, and whether the
   job is booked. The card can afford it now: the lane cap keeps blocks at 84px
   or wider and the container queries below drop whole lines rather than
   shrinking them, so nothing has to be small to fit. Where a line genuinely
   will not fit it is removed, which is legible; shrinking it to 9px is not. */
.sched-tl-job-time {
  color: inherit;
  opacity: 0.85;
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* THE END TIME ONLY WHERE THERE IS ROOM TO READ IT.
   "8:30 AM–3:30 PM" needs about 92px. A week column is 131px at 1440 and half
   that when two jobs overlap, so the range was being cut to "8:30 AM–3:3" —
   which is worse than not printing it, because the block's own height already
   says when the job ends. Day view has the whole width, so it gets the range. */
.sched-tl-job-time i {
  display: none;
  font-style: normal;
  opacity: 0.75;
}

.sched-tl[data-days='1'] .sched-tl-job-time i {
  display: inline;
}

.sched-tl-job-name {
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-tl-job-city,
.sched-tl-job-span {
  color: inherit;
  opacity: 0.78;
  font-size: 0.75rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* NOT margin-top:auto. Pinning the footer to the bottom of the block looked
   tidy on an hour-long job and put the crew and the status four hundred pixels
   under the name on an eight-hour one — two halves of the same job at opposite
   ends of the screen. It reads top-down with everything else. */
.sched-tl-job-foot {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  min-width: 0;
}

.sched-tl-job-crew {
  color: inherit;
  opacity: 0.8;
  font-size: 0.75rem;
  font-weight: 700;
  /* The tracking went with the 9.6px size. At 12px an uppercase label with
     0.05em on it is wider than the crew initials it is labelling. */
  letter-spacing: 0.02em;
  text-transform: uppercase;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Sits NEXT TO the crew, not pushed to the far edge. margin-left:auto is right
   in a 131px week column and absurd in Day view, where it threw the status a
   thousand pixels from the job it belongs to. */
.sched-tl-job-badge {
  flex: 0 0 auto;
  padding: 0.08rem 0.36rem;
  border-radius: 999px;
  background: rgba(var(--panel-rgb), 0.55);
  color: inherit;
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

/* HOW MUCH OF A JOB FITS IN THE HEIGHT IT ACTUALLY HAS.
   The size class is computed from the job's DURATION, not from measured
   pixels, so it survives the hour height changing per breakpoint. Everything
   hidden here stays in the DOM: a screen reader still reads the whole job, and
   the title attribute carries it for a mouse. */
.sched-tl-job[data-size='xs'] {
  flex-direction: row;
  align-items: baseline;
  gap: 0.3rem;
  padding-block: 0.1rem;
}

.sched-tl-job[data-size='xs'] .sched-tl-job-city,
.sched-tl-job[data-size='xs'] .sched-tl-job-foot,
.sched-tl-job[data-size='xs'] .sched-tl-job-span,
/* SM IS THREE LINES NOW, NOT FOUR. The foot used to survive here with the crew
   hidden inside it, which left the status badge on its own row — a fourth line
   on a card that has room for three since the hour came down to 44px. The
   status is not lost by dropping it: it is what the block's COLOUR encodes,
   and the legend above the grid names all four. */
.sched-tl-job[data-size='sm'] .sched-tl-job-foot,
.sched-tl-job[data-size='sm'] .sched-tl-job-span {
  display: none;
}

/* And the same for width. Three or more jobs sharing a column leaves each about
   47px on a tablet, which is not enough for a city, a crew, a status badge and
   a "Day 2/4" — they all ellipsised to a single character. Time and name only;
   the tooltip still carries the whole job. */
/* [data-narrow] was here. It keyed off a column count the lane cap made
   impossible, so it stopped matching anything the day capLanes shipped.
   Container queries on .sched-tl-job do the width half of the job now. */

/* ---- crew lanes ---------------------------------------------------------- */

/* ---- crew filters -------------------------------------------------------
   One row per person means a twelve-person crew draws twelve lanes whether or
   not there is work in them, so a Tuesday with four jobs is four lanes of work
   and eight of "Free all day". Neither control renders unless it would do
   something: a fully booked day has nothing to hide, a one-role roster has
   nothing to filter. */
.sched-crew-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.9rem;
  margin: 0 0 0.6rem;
}

.sched-crew-filter {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  /* The label is the target, not the 13px box inside it. */
  min-height: 44px;
  color: var(--mute-i62);
  font-size: 0.8rem;
  font-weight: 650;
  cursor: pointer;
}

.sched-crew-filter input[type='checkbox'] {
  width: 1.05rem;
  height: 1.05rem;
  accent-color: var(--accent);
  cursor: pointer;
}

.sched-crew-filter select {
  min-height: 44px;
  padding: 0 0.5rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(var(--tint), 0.03);
  color: var(--text);
  font: inherit;
  font-size: 0.8rem;
  cursor: pointer;
}

.sched-crew-filter input:focus-visible,
.sched-crew-filter select:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sched-crew-filter-note {
  margin: 0 0 0 auto;
  color: var(--mute-t50);
  font-size: 0.76rem;
}

.sched-crew {
  --crew-name: 9.5rem;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(var(--tint), 0.015);
  /* clip, NOT hidden. `overflow: hidden` establishes a scroll container, and a
     sticky child then sticks inside a box that never scrolls — which is the
     same as not being sticky at all. `overflow: clip` crops to the rounded
     corners without creating one, so the axis row above sticks to the viewport
     the way it is meant to. */
  overflow: clip;
}

/* STICKY, because a long roster scrolls the hour axis off the top and every
   lane below it becomes an unlabelled bar chart. It needs an opaque background
   to sit over the lanes, which the translucent one was not. */
.sched-crew-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: grid;
  grid-template-columns: var(--crew-name) minmax(0, 1fr);
  border-bottom: 1px solid var(--line);
  /* --bg-3, the same solid the WEEK timeline's sticky head uses (.sched-tl-head)
     — it is white in the light theme, where a literal navy fallback painted a
     dark bar across a white page. A sticky row has to be opaque, and the two
     sibling views should not disagree about which opaque. */
  background: var(--bg-3);
}

.sched-crew-head-name {
  padding: 0.5rem 0.7rem;
  border-right: 1px solid var(--line);
  font-size: 0.78rem;
  font-weight: 700;
}

.sched-crew-head-axis {
  display: grid;
  grid-template-columns: repeat(var(--crew-hours), minmax(0, 1fr));
}

.sched-crew-head-axis span {
  padding: 0.5rem 0 0.5rem 0.3rem;
  border-left: 1px solid var(--line);
  color: var(--mute-i60);
  font-size: 0.62rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
}

.sched-crew-head-axis span:first-child {
  border-left: 0;
}

.sched-crew-lanes {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sched-crew-lane {
  display: grid;
  grid-template-columns: var(--crew-name) minmax(0, 1fr);
  border-bottom: 1px solid var(--line);
  min-height: calc(var(--lane-stack, 1) * 2.6rem);
}

.sched-crew-lane:last-child {
  border-bottom: 0;
}

.sched-crew-lane.orphan {
  background: rgba(255, 138, 61, .05);
}

.sched-crew-who {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.05rem;
  padding: 0.4rem 0.7rem;
  border-right: 1px solid var(--line);
  min-width: 0;
}

.sched-crew-who strong {
  font-size: 0.8rem;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-crew-who small {
  color: var(--mute-i60);
  font-size: 0.65rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-crew-track {
  position: relative;
  min-width: 0;
  padding: 0.25rem 0;
  background-image: repeating-linear-gradient(to right,
      var(--line) 0 1px,
      transparent 1px calc(100% / var(--crew-hours)));
}

.sched-crew-free {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  padding-left: 0.6rem;
  color: var(--mute-i60);
  font-size: 0.68rem;
}

.sched-crew-job {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 0.35rem;
  overflow: hidden;
  min-width: 0;
  padding: 0.2rem 0.45rem;
  border: 1px solid var(--job-line, var(--line));
  border-left: 3px solid var(--job-line, var(--accent));
  border-radius: 6px;
  background: var(--job-fill, rgba(var(--tint), 0.06));
  color: var(--job-ink, var(--ink));
  font-size: 0.72rem;
  cursor: pointer;
  touch-action: none;
}

.sched-crew-job strong {
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sched-crew-job-time {
  flex: 0 0 auto;
  opacity: 0.8;
  font-size: 0.62rem;
  font-variant-numeric: tabular-nums;
}

.sched-crew-job:hover {
  filter: brightness(1.12);
  z-index: 2;
}

.sched-crew-job:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  z-index: 3;
}

.sched-crew-job.dragging {
  opacity: 0.45;
}

.sched-crew-job.clash {
  border-color: var(--bad);
}

.sched-crew-clash {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--bad);
  color: #fff;
  font-size: 0.62rem;
  font-weight: 800;
}

.sched-crew-note {
  margin: 0;
  padding: 0.55rem 0.8rem;
  border-top: 1px solid var(--line);
  color: var(--mute-i60);
  font-size: 0.74rem;
}

.sched-crew-note.warn {
  color: var(--bad);
}

/* ---- month, as capacity -------------------------------------------------- */

.sched-month {
  display: grid;
  gap: 0.4rem;
}

.sched-month .calendar-weekday {
  padding: 0 0.2rem 0.15rem;
  color: var(--mute-i60);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.sched-month-cell.empty {
  border: 0;
  background: none;
}

.sched-month-cell {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  min-height: 5.6rem;
  padding: 0.45rem 0.5rem 0.55rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(var(--tint), 0.02);
  color: var(--ink);
  text-align: left;
  font: inherit;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.sched-month-cell:hover {
  border-color: rgba(var(--tint), 0.3);
  background: rgba(var(--tint), 0.05);
}

.sched-month-cell:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.sched-month-cell.today {
  border-color: var(--accent);
}

.sched-month-cell.quiet {
  background: rgba(var(--tint), 0.01);
}

.sched-month-cell.blocked {
  background: repeating-linear-gradient(135deg, rgba(var(--tint), 0.04) 0 6px, transparent 6px 12px);
}

/* ---- HOW FULL THE DAY IS, AS A RAMP ------------------------------------- */
/* Every cell drew the same orange bar whatever was in it, so the question the
   month view exists to answer — where is there room in August — meant reading
   thirty-one cells one at a time and comparing two small numbers in each.
   Green is room, red is trouble, and a month of it reads without words.

   One attribute, [data-load], set from lib/schedule-capacity, drives the
   border, the bar and the tint together. The chips ("Full", "Over") and the
   button's own summary sentence still say it in WORDS: the ramp is five steps
   of hue, which is precisely the pattern red/green colour blindness flattens,
   so nothing here is the only place a fact is stated.

   Deliberately quiet at the safe end. `open` and `light` are days you are not
   being asked to do anything about, and a wall of saturated green shouting
   "fine" over three weeks would drown the two cells that are not. */
.sched-month-cell[data-load='open'] {
  --load-ink: var(--cap-open);
}

.sched-month-cell[data-load='light'] {
  --load-ink: var(--cap-light);
}

.sched-month-cell[data-load='busy'] {
  --load-ink: var(--cap-busy);
}

.sched-month-cell[data-load='full'] {
  --load-ink: var(--cap-full);
}

.sched-month-cell[data-load='over'] {
  --load-ink: var(--cap-over);
}

/* NOT A SIXTH STEP ON THE RAMP. Every other band is a claim about how full the
   day is; this one is the admission that the claim cannot be made, because
   something on the day has no stated length. A hue would file it between two
   levels of certainty it does not belong between — so it takes the neutral and
   the diagonal, and the cell carries a "?" and a "+" on the hours besides. */
.sched-month-cell[data-load='unknown'] {
  --load-ink: var(--cap-unknown);
  border-color: color-mix(in srgb, var(--load-ink) 40%, transparent);
  background-image: repeating-linear-gradient(135deg, color-mix(in srgb, var(--load-ink) 9%, transparent) 0 5px, transparent 5px 10px);
}

.sched-month-cell[data-load='busy'],
.sched-month-cell[data-load='full'] {
  border-color: color-mix(in srgb, var(--load-ink) 45%, transparent);
}

.sched-month-cell[data-load='over'] {
  border-color: var(--load-ink);
  background-color: color-mix(in srgb, var(--load-ink) 8%, transparent);
}

/* Today's ring outranks the band. Which day it is does not change all month;
   how full a day is changes every time something is booked, and the bar under
   it is already saying that. */
.sched-month-cell.today {
  border-color: var(--accent);
}

.sched-month-cell.drag-over {
  border-color: var(--accent);
  background: rgba(255, 138, 61, .16);
}

.sched-month-cell.armable {
  cursor: copy;
}

.sched-month-top {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.sched-month-day {
  font-size: 0.95rem;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
}

.sched-month-cell.today .sched-month-day {
  color: var(--accent);
}

.sched-month-flags {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.sched-month-flag {
  display: grid;
  place-items: center;
  width: 0.95rem;
  height: 0.95rem;
  border-radius: 50%;
  font-size: 0.6rem;
  font-style: normal;
  font-weight: 800;
  line-height: 1;
}

.sched-month-flag.clash {
  background: var(--bad);
  color: #fff;
}

.sched-month-flag.crewless {
  background: rgba(var(--tint), 0.12);
  color: var(--mute-i60);
}

.sched-month-flag.unknown {
  background: color-mix(in srgb, var(--cap-unknown) 30%, transparent);
  color: var(--ink);
}

.sched-month-state {
  padding: 0.05rem 0.32rem;
  border-radius: 999px;
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.sched-month-state.full {
  background: rgba(255, 138, 61, .2);
  color: var(--ink-orange-4);
}

.sched-month-state.over {
  background: rgba(168, 51, 31, .22);
  color: var(--bad);
}

.sched-month-state.off {
  background: rgba(var(--tint), 0.1);
  color: var(--mute-i60);
}

.sched-month-count {
  font-size: 0.74rem;
  font-weight: 650;
}

.sched-month-count i {
  font-style: normal;
  color: var(--mute-i60);
  font-weight: 500;
}

.sched-month-hours {
  color: var(--mute-i60);
  font-size: 0.68rem;
  font-variant-numeric: tabular-nums;
}

/* The one character that turns a total into a floor. Given its own weight and
   colour because at 0.68rem a "+" between two figures is otherwise read as
   punctuation rather than as "and more than this". */
.sched-month-atleast {
  color: var(--ink);
  font-weight: 800;
}

.sched-month-open {
  margin-top: auto;
  color: var(--mute-i60);
  font-size: 0.7rem;
}

.sched-month-bar {
  margin-top: auto;
  display: block;
  height: 5px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.1);
  overflow: hidden;
}

.sched-month-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  /* The band, not a fixed orange. The fallback is the old colour, for the one
     case [data-load] is absent — a blocked day, which has no capacity to be a
     fraction of. */
  background: var(--load-ink, var(--accent));
}

/* ---- the ramp, named ------------------------------------------------------ */
/* Five steps of hue with nothing saying what they are is the same mistake the
   old id-hashed block colours made (see CalendarLegend). Only in Month, where
   the ramp is; the status legend beside it is about the blocks in Day and
   Week, and stacking both on every view is two captions for one grid. */
.calendar-legend-dot[data-load] {
  background: var(--load-ink);
  border-color: transparent;
}

.calendar-legend-dot[data-load='open'] {
  --load-ink: var(--cap-open);
}

.calendar-legend-dot[data-load='light'] {
  --load-ink: var(--cap-light);
}

.calendar-legend-dot[data-load='busy'] {
  --load-ink: var(--cap-busy);
}

.calendar-legend-dot[data-load='full'] {
  --load-ink: var(--cap-full);
}

.calendar-legend-dot[data-load='over'] {
  --load-ink: var(--cap-over);
}

/* The dot wears the hatch too, so the key matches the cell rather than
   describing it. Only rendered when a day on screen actually has one. */
.calendar-legend-dot[data-load='unknown'] {
  --load-ink: var(--cap-unknown);
  background-image: repeating-linear-gradient(135deg, rgba(0, 0, 0, .34) 0 2px, transparent 2px 4px);
}

/* ---- widths -------------------------------------------------------------- */

/* Tablet: three columns, and the hour shrinks because the whole grid has less
   height to give. The gutter narrows with it — "10 AM" still fits. */
@media (max-width: 1279.98px) {

  /* 21, half of the 42 this was, tracking the desktop hour down from 44 to 22.
     Thirteen hours is 273px, well inside the 620 this used to cap at. Still
     exactly one pixel under the desktop hour: blockSize's thresholds are
     shared across breakpoints and are set against THIS number, because a
     threshold that clears its lines at 22px and not at 21 clips on every
     tablet. The max-height comes off entirely: the rule above already sizes
     the box to its own hours, and a viewport-relative cap here would put the
     scrollbar straight back on a short window. */
  .sched-tl {
    --tl-gutter: 3rem;
    --tl-hour-h: 21px !important;
  }

  .sched-crew {
    --crew-name: 8rem;
  }

  .sched-month-cell {
    min-height: 5rem;
  }
}

/* Below 640 the mobile agenda takes over entirely (see .calendar-desktop-views
   above) — no timeline columns and no drag, which is the point. These rules
   only cover the window between a phone and a tablet. */
@media (max-width: 900px) {
  .sched-tl {
    --tl-gutter: 2.7rem;
  }

  /* Seven columns inside 640px is ~85px each, which the stack fits: the
     wrapping row this used to need is what the column direction replaced. */
  .sched-tl-day-head {
    padding: 0.4rem 0.35rem;
  }

  .sched-tl-day-head strong {
    font-size: 1.15rem;
  }

  .sched-crew {
    --crew-name: 6.5rem;
  }

  .sched-crew-head-axis span:nth-child(even) {
    color: transparent;
  }
}

/* A phone that has somehow been handed the desktop tree — a very wide zoom, or
   a landscape 640px window — must still not scroll sideways. */
@media (max-width: 640px) {

  .sched-tl-job-city,
  .sched-tl-job-foot {
    display: none;
  }
}

/* ===========================================================================
   GETTING BACK, AND GETTING OUT OF THE WAY
   ===========================================================================
   Four small things the time views were missing once they existed. */

/* -- back to the month you came from --------------------------------------- */
/* Clicking a date in Month drops you into Day, and the only route back was the
   View dropdown — something you have to remember exists, and which returns you
   to the top of a month you had already scrolled through. This restores the
   month, the scroll position and the date. */
.sched-back-to-month {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 44px;
  margin-right: 0.4rem;
  padding: 0.3rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
  color: var(--mute-i60);
  font: inherit;
  font-size: 0.82rem;
  white-space: nowrap;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.sched-back-to-month:hover {
  border-color: rgba(var(--tint), 0.3);
  background: rgba(var(--tint), 0.07);
  color: var(--ink);
}

.sched-back-to-month:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* THE RAIL TOGGLE IS GONE, AND SO ARE ITS RULES.
   It sat in the calendar toolbar reading "Show jobs (10)" while the stat strip
   directly above it read "10 · Ready to book" and linked to the same rail — the
   same number and the same destination, twice, a row apart. The stat is the one
   that stays: it is already there, it is already a link to #unscheduled-jobs,
   and it says what the number means.

   The `body[data-sched-rail]` rules go with it. Nothing sets that attribute any
   more, so a stale "collapsed" left in someone's localStorage simply never
   matches and the rail comes back on its own — no migration needed, and no way
   to be stranded with a hidden queue and no button to bring it back. */

/* The queue's written drag instruction is gone; the handle's own title carries
   what is left of it, and that only appears where there is a pointer anyway. */


/* ===========================================================================
   THE TRADE DIRECTORY
   ===========================================================================
   /for listed forty-nine trades as one flat grid of cards in array order —
   about 7,200px of page on a phone, with no way to jump to your own. The page
   now has a search box, six category filters, a hand-picked shortlist, and an
   A–Z directory of one line per trade. Only the last of those is a layout
   change; the rest is new furniture, styled here.
   =========================================================================== */

/* A SKIP LINK FOR EVERY PAGE THE APP SHELL WRAPS.
   The flagship stylesheet has had one since it shipped. These pages did not,
   and they are the ones that need it most: the shell puts a rail of eighteen
   app links before the content, so a desktop keyboard user walked all of it
   before reaching a word of the page.

   It is rendered by the SHELL, not the page — the rail comes before {children}
   in the DOM, so a skip link written into a page sits after the rows it exists
   to skip. Measured on /for before this: the first tab stop was the rail's
   wordmark. */
.shell-skip-link {
  position: absolute;
  z-index: 60;
  top: 10px;
  left: 10px;
  padding: 11px 17px;
  border-radius: 10px;
  background: var(--accent);
  color: #160a02;
  font-size: 0.9rem;
  font-weight: 750;
  text-decoration: none;
  transform: translateY(-160%);
  transition: transform 0.18s ease;
}

.shell-skip-link:focus {
  transform: translateY(0);
}

/* The skip target itself must not draw a focus ring — it is a wrapper the user
   never sees focus, only lands in. */
#app-main:focus {
  outline: none;
}

/* -- a visible way out of the mobile drawer -------------------------------- */
.sidenav-close {
  position: absolute;
  top: 0.55rem;
  right: 0.55rem;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--bg-elevated);
  color: inherit;
  cursor: pointer;
}

.sidenav-close svg {
  width: 17px;
  height: 17px;
}

.sidenav-close:hover {
  border-color: var(--cedge-orange-9);
}

/* -- what picking a trade changes ------------------------------------------ */
.trade-tuning {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 0.9rem;
}

.trade-tuning article {
  padding: 1.05rem 1.15rem;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--bg-elevated);
}

.trade-tuning h3 {
  margin: 0 0 0.35rem;
  font-size: 0.98rem;
  font-weight: 750;
  letter-spacing: -0.01em;
}

.trade-tuning p {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.5;
  color: var(--muted);
}

/* -- search and category filters ------------------------------------------- */
.trade-finder {
  display: grid;
  gap: 0.85rem;
  margin-bottom: 1.5rem;
}

.trade-search label {
  display: block;
  margin-bottom: 0.4rem;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--mute-i62);
}

.trade-search-field {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  max-width: 460px;
  padding: 0 0.9rem;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--bg-elevated);
}

.trade-search-field:focus-within {
  border-color: var(--accent);
}

.trade-search-ic {
  display: flex;
  width: 17px;
  height: 17px;
  color: var(--mute-i62);
}

.trade-search-ic svg {
  width: 100%;
  height: 100%;
}

.trade-search-field input {
  flex: 1;
  min-height: 46px;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 0.95rem;
}

/* The field already shows focus on its own border; removing the ring from the
   input inside it would leave nothing, so the ring goes on the wrapper. */
.trade-search-field input:focus {
  outline: none;
}

.trade-search-field:focus-within {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.trade-cats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.trade-cats button {
  min-height: 38px;
  padding: 0 0.85rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg-elevated);
  color: var(--muted);
  font: inherit;
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease;
}

.trade-cats button:hover {
  border-color: var(--cedge-orange-9);
  color: inherit;
}

/* Selected state carries a fill AND a weight change, so it does not depend on
   colour alone to say which one is on. */
.trade-cats button[aria-pressed='true'] {
  border-color: transparent;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #160a02;
  font-weight: 800;
}

/* -- the shortlist --------------------------------------------------------- */
.trade-common {
  margin-bottom: 1.9rem;
}

.trade-common h3,
.trade-directory h3 {
  margin: 0 0 0.85rem;
  font-size: 0.82rem;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mute-i62);
}

.trade-common-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 0.9rem;
}

/* The shortlist cards are the old .trade-index-card, one heading level down —
   they sit under "Start here" now rather than under the section's own h2. */
.trade-index-card h4 {
  margin: 0 0 0.3rem;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* 0.78rem is 12.5px, which is caption size for what is actually the only
   description of the trade on the page. */
.trade-index-card p {
  font-size: 0.85rem;
}

/* -- the A-Z directory ----------------------------------------------------- */
.trade-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1px;
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  /* Shows through the grid gap as hairlines, so forty-nine rows need one
     border rather than forty-nine. */
  background: var(--line);
}

.trade-list a {
  display: block;
  height: 100%;
  padding: 0.7rem 0.9rem;
  background: var(--bg-elevated);
  text-decoration: none;
  transition: background 0.16s ease;
}

.trade-list a:hover {
  background: rgba(var(--tint), 0.05);
}

.trade-list b {
  display: block;
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.trade-list span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.78rem;
  line-height: 1.4;
  color: var(--mute-i62);
}

.trade-empty {
  margin: 0;
  font-size: 0.92rem;
  color: var(--muted);
}

.trade-empty a {
  color: var(--gold-ink);
  font-weight: 600;
}

@media (max-width: 560px) {
  .trade-search-field {
    max-width: none;
  }

  .trade-common-grid {
    grid-template-columns: 1fr 1fr;
  }

  .trade-list {
    grid-template-columns: 1fr;
  }

  /* Forty-nine two-line rows is 3,100px of directory on a phone. The name is
     what somebody scrolling a phone is scanning for; the services are on the
     shortlist card above and on the trade's own page. */
  .trade-list span {
    display: none;
  }

  .trade-list a {
    padding: 0.62rem 0.85rem;
  }
}

/* -- the public site, at the top of the marketing rail ---------------------- */
/* This rail stands in for the marketing header on /for, /pricing, /faq,
   /security and /resources. Styled a shade quieter than the app preview below
   it is the wrong way round — these are the pages a logged-out visitor can
   actually open, so they read as ordinary navigation and the locked rows below
   read as the preview they are. */
.sidenav-public {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  margin-top: 0.9rem;
}

.sidenav-public-link {
  display: block;
  padding: 0.5rem 0.6rem;
  border-radius: 9px;
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 650;
  text-decoration: none;
  transition: background 0.16s ease, color 0.16s ease;
}

.sidenav-public-link:hover {
  background: rgba(var(--tint), 0.06);
  color: inherit;
}

.sidenav-public-link.active {
  background: rgba(255, 122, 33, 0.14);
  color: var(--accent-ink);
  font-weight: 750;
}

/* ===========================================================================
   /pricing: THE COMPARISON, ANSWERED
   =========================================================================== */

/* -- the verdict under the calculator -------------------------------------- */
/* The calculator used to stop at "= $1,188/yr" and leave the reader to do the
   subtraction. At the default settings that subtraction comes out against us,
   and a pricing page hoping nobody does the arithmetic is worse than one that
   does it first. data-side carries which way it fell, so the border can agree
   with the sentence without the sentence having to be colour to be read. */
.calc-verdict {
  margin: 1rem 0 0;
  padding: 1rem 1.15rem;
  border: 1px solid var(--line);
  border-left-width: 3px;
  border-radius: 14px;
  background: rgba(var(--tint), 0.03);
}

.calc-verdict[data-side='lower'] {
  border-left-color: var(--accent);
}

.calc-verdict[data-side='higher'] {
  border-left-color: var(--gold-ink);
}

.calc-verdict-line {
  margin: 0;
  font-size: 1rem;
  line-height: 1.5;
}

.calc-verdict-line strong {
  font-variant-numeric: tabular-nums;
}

.calc-verdict-break {
  margin: 0.5rem 0 0;
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--muted);
}

.calc-verdict-break strong {
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.calc-stack {
  margin-top: 0.9rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--line);
}

.calc-stack-head {
  margin: 0 0 0.5rem;
  font-size: 0.76rem;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mute-i62);
}

.calc-stack ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.calc-stack li {
  padding: 0.28rem 0.62rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(var(--tint), 0.04);
  font-size: 0.8rem;
  font-weight: 600;
}

/* -- "swipe to compare" ---------------------------------------------------- */
/* Hidden at every width where the 720px table fits, so the page never promises
   a gesture that does nothing. */
.compare-swipe {
  display: none;
}

@media (max-width: 800px) {
  .compare-swipe {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin: 1.4rem 0 -0.6rem;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--mute-i62);
  }

  .compare-swipe-arrow {
    animation: comparePeek 2.4s ease-in-out infinite;
  }
}

@keyframes comparePeek {

  0%,
  100% {
    transform: translateX(0);
  }

  50% {
    transform: translateX(5px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .compare-swipe-arrow {
    animation: none;
  }
}

/* Keyboard users get the scroller as a focus stop (tabIndex on the region), so
   it needs to show that it has focus. */
.compare-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* -- the tier chart at phone widths ---------------------------------------- */
/* Two columns held all the way down to 320px, which put a rate, a range label
   and a bar into about 140px each. One column below 520px. */
@media (max-width: 520px) {
  .pricing-tiers {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .pricing-tier {
    flex-direction: row;
    align-items: center;
    gap: 0.75rem;
  }

  .pricing-tier-chart {
    height: auto;
    width: 84px;
    flex: none;
  }
}

/* -- something checkable beside the last ask ------------------------------- */
.cta-trust {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.35rem;
  max-width: 62ch;
  margin: 1.4rem auto 0;
  font-size: 0.85rem;
  line-height: 1.6;
  color: var(--mute-i62);
  text-align: center;
}

.cta-trust strong {
  color: var(--text);
  font-weight: 700;
}

.cta-trust a {
  color: var(--gold-ink);
  font-weight: 650;
}

/* ===========================================================================
   THE SCHEDULE, AFTER THE WEEK-VIEW AUDIT
   =========================================================================== */

/* -- colour that means something ------------------------------------------- */
/* Every block used to take its colour from a six-way hash of the job's id, so
   a day showed blue, yellow, purple and green encoding nothing. Status is what
   the calendar already knows and what changes what you do next. The tokens are
   the same three the id-hash classes set, so nothing downstream changes. */
.calendar-job-status-new_lead {
  --job-line: var(--rail-crew-3);
  --job-fill: rgba(255, 209, 102, .2);
  --job-ink: var(--ink-amber-5);
}

.calendar-job-status-in_progress {
  --job-line: var(--rail-crew-1);
  --job-fill: rgba(61, 184, 255, .2);
  --job-ink: var(--ink-sky-3);
}

.calendar-job-status-complete {
  --job-line: var(--rail-crew-2);
  --job-fill: rgba(120, 220, 150, .2);
  --job-ink: var(--ink-green-4);
}

.calendar-job-status-archived {
  --job-line: rgba(var(--tint), 0.35);
  --job-fill: rgba(var(--tint), 0.07);
  --job-ink: var(--mute-i62);
}

:root[data-theme='light'] .calendar-job-status-new_lead,
:root[data-theme='sunlight'] .calendar-job-status-new_lead {
  --job-fill: rgba(233, 178, 60, .16);
}

:root[data-theme='light'] .calendar-job-status-in_progress,
:root[data-theme='sunlight'] .calendar-job-status-in_progress {
  --job-fill: rgba(61, 184, 255, .14);
}

:root[data-theme='light'] .calendar-job-status-complete,
:root[data-theme='sunlight'] .calendar-job-status-complete {
  --job-fill: rgba(76, 190, 120, .14);
}

:root[data-theme='clarity'] .calendar-job-status-new_lead {
  --job-line: #f0e442;
  --job-fill: rgba(240, 228, 66, 0.20);
  --job-ink: #f0e442;
}

:root[data-theme='clarity'] .calendar-job-status-in_progress {
  --job-line: #56b4e9;
  --job-fill: rgba(86, 180, 233, 0.20);
  --job-ink: #56b4e9;
}

:root[data-theme='clarity'] .calendar-job-status-complete {
  --job-line: #8ecdf0;
  --job-fill: rgba(142, 205, 240, 0.20);
  --job-ink: #8ecdf0;
}

:root[data-theme='monochrome'] .calendar-job-status-new_lead {
  --job-line: #ffffff;
  --job-fill: rgba(255, 255, 255, 0.16);
  --job-ink: #ffffff;
}

:root[data-theme='monochrome'] .calendar-job-status-in_progress {
  --job-line: #e4e4e7;
  --job-fill: rgba(228, 228, 231, 0.24);
  --job-ink: #ffffff;
}

:root[data-theme='monochrome'] .calendar-job-status-complete {
  --job-line: #ffffff;
  --job-fill: rgba(255, 255, 255, 0.32);
  --job-ink: #ffffff;
}

:root[data-theme='parchment'] .calendar-job-status-new_lead {
  --job-line: #b45309;
  --job-fill: rgba(180, 83, 9, 0.15);
  --job-ink: #b45309;
}

:root[data-theme='parchment'] .calendar-job-status-in_progress {
  --job-line: #a84c00;
  --job-fill: rgba(168, 76, 0, 0.15);
  --job-ink: #a84c00;
}

:root[data-theme='parchment'] .calendar-job-status-complete {
  --job-line: #2d6a4f;
  --job-fill: rgba(45, 106, 79, 0.15);
  --job-ink: #2d6a4f;
}

/* ---- the Day view's own summary ------------------------------------------
   The one view about a single day was the only one that said nothing about it:
   Capacity colors every cell by how full it is and the phone prints "2h of 8h
   booked" over the day it shows, while this drew eleven hours of ruled lines
   and left the addition to you. Same strip as the phone (.sched-cap), because
   a day must not read as busy on one and open on the other. */
.sched-daysum {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.9rem;
  margin: 0 0 0.7rem;
}

/* The capacity strip carries the row; the rest sits beside it. */
.sched-daysum .sched-cap {
  flex: 1 1 18rem;
  min-width: 0;
}

.sched-daysum-crew,
.sched-daysum-empty {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  font-size: 0.8rem;
  color: var(--mute-i62);
}

.sched-daysum-crew strong {
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 800;
}

/* The forecast, on the day it is about. Amber for a day to watch, red for one
   nobody should plan on — and absent entirely on the days it would say
   "fine", which is most of them. */
.sched-daysum-weather {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem 0.45rem;
  margin: 0;
  padding: 0.4rem 0.7rem;
  border: 1px solid var(--cedge-orange-54);
  border-radius: 10px;
  background: rgba(255, 176, 32, 0.1);
  color: var(--ink-amber-1);
  font-size: 0.78rem;
}

.sched-daysum-weather svg {
  width: 1rem;
  height: 1rem;
  flex: none;
}

.sched-daysum-weather strong {
  font-weight: 800;
}

.sched-daysum-weather>span {
  color: inherit;
  opacity: 0.85;
}

/* Not a louder amber: a different signal. "Don't plan on it" is the one state
   where the answer is to move the work. */
.sched-daysum-weather[data-level='unworkable'] {
  border-color: rgba(255, 107, 107, 0.55);
  background: rgba(255, 107, 107, 0.12);
  color: var(--ink-red-1);
}

.sched-daysum-who {
  color: var(--mute-t50);
}

.sched-daysum-quiet {
  color: var(--mute-t45);
}

.sched-daysum-empty button {
  min-height: 44px;
  padding: 0 0.55rem;
  border: 0;
  background: none;
  color: var(--accent-ink);
  font: inherit;
  font-weight: 800;
  text-decoration: underline;
  cursor: pointer;
}

.sched-daysum-empty button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

/* THE VIEW YOU ASKED FOR IS NOT THE VIEW YOU GOT, AND HERE IS WHY.
   Capacity below 1280 is seven cells at ~80px sharing the row with the rail, so
   it stands down to the job list. That was happening in silence, which reads as
   a broken control rather than a narrow window — and left no way back. Quiet
   (it is an explanation, not an alarm) but it carries the override. */
.calendar-view-swapped {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.3rem;
  margin: 0 0 0.55rem;
  padding: 0.45rem 0.7rem;
  border: 1px dashed var(--edge-t16);
  border-radius: 10px;
  background: rgba(var(--tint), 0.03);
  color: var(--mute-i62);
  font-size: 0.76rem;
}

.calendar-view-swapped button {
  min-height: 44px;
  padding: 0 0.55rem;
  border: 0;
  background: none;
  color: var(--accent-ink);
  font: inherit;
  font-weight: 700;
  text-decoration: underline;
  cursor: pointer;
}

.calendar-view-swapped button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

.calendar-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.9rem;
  margin: 0 0 0.6rem;
  font-size: 0.74rem;
  color: var(--mute-i62);
}

.calendar-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

/* ---- status as a SHAPE, not only as a color ------------------------------
   Day, Week and the Job list print the status in words on the chip. Projects,
   Year and the Crew lanes carried it in the fill alone — unreadable in
   greyscale, on a projector, and to anyone who cannot separate the amber from
   the green. The mark takes its color from the chip it is on, so it reads as
   part of the same object rather than as an annotation stuck to it. */
.calendar-status-mark {
  flex: none;
  font-size: 0.72em;
  line-height: 1;
  opacity: 0.9;
}

.calendar-legend-mark {
  font-size: 0.8em;
  line-height: 1;
  opacity: 0.85;
}

.calendar-legend-dot {
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 3px;
  border: 1px solid var(--job-line, var(--line));
  border-left-width: 3px;
  background: var(--job-fill, transparent);
}

.calendar-legend-dot-planned {
  border: 1px dashed rgba(var(--tint), 0.5);
  background: transparent;
}

/* -- "+N overlapping" ------------------------------------------------------ */
/* The fixed rail the two lanes give up their width to. Wide enough for "+12"
   and for a thumb; the lanes take `calc((100% - var(--tl-overflow-w)) / 2)`
   each, which is why this is a length and not a percentage. */
.sched-tl-col {
  --tl-overflow-w: 0px;
}

.sched-tl-col:has(.sched-tl-overflow) {
  --tl-overflow-w: 46px;
}

.sched-tl-overflow {
  position: absolute;
  right: 0;
  width: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px dashed rgba(var(--tint), 0.42);
  border-radius: 7px;
  background: rgba(var(--tint), 0.07);
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  z-index: 3;
}

.sched-tl-overflow:hover {
  border-color: var(--accent);
  background: rgba(255, 122, 33, 0.12);
}

.sched-tl-overflow:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* On the day view there is nowhere for it to go — its destination is the view
   you are already in — so it is a count rather than a control, and it has to
   stop looking like one. The pointer and the hover lift are the whole of what
   said "press me". */
.sched-tl-overflow.is-static {
  cursor: default;
  color: var(--mute-i60);
}

.sched-tl-overflow.is-static:hover {
  border-color: rgba(var(--tint), 0.42);
  background: rgba(var(--tint), 0.07);
}

/* -- the card decides its own detail from its own width --------------------- */
/* data-size answers "is this block tall enough", which is only half the
   question — a three-way overlap in a week column is 47px wide and an
   eight-hour job in it is still "md". This asks the other half of the question
   in the only place that can answer it: the card itself. */
.sched-tl-job {
  container-type: inline-size;
}

@container (max-width: 132px) {

  .sched-tl-job .sched-tl-job-city,
  .sched-tl-job .sched-tl-job-span {
    display: none;
  }
}

@container (max-width: 96px) {
  .sched-tl-job .sched-tl-job-crew {
    display: none;
  }
}

@container (max-width: 68px) {
  .sched-tl-job .sched-tl-job-foot {
    display: none;
  }
}

/* A long customer name in a 60px card must ellipsise, never break to one
   character a line. */
.sched-tl-job-time,
.sched-tl-job-name,
.sched-tl-job-city,
.sched-tl-job-crew {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* -- Closed, and Closed with work on it ------------------------------------ */
/* "Off" named no subject — off what, the crew, the day, the column? "Closed"
   is the working-hours setting in the setting's own word. A closed day WITH
   jobs on it is the one state worth a warning: the work is real and it is
   outside configured hours, and nothing about showing it moves it. */
.sched-tl-head-flag.blocked[data-with-work] {
  /* .blocked drops the pill because a closed Sunday is routine. This state is
     not routine, so it takes the padding back and keeps its fill. */
  padding: 0.05rem 0.34rem;
  border-color: var(--cedge-orange-9);
  background: rgba(255, 122, 33, 0.16);
  color: var(--accent-ink);
  font-variant-numeric: tabular-nums;
}

/* -- the day head is a button now ------------------------------------------ */
.sched-tl-day-head {
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.sched-tl-day-head:hover {
  background: rgba(var(--tint), 0.06);
}

/* Hovering today must not make today stop looking like today — the plain hover
   fill would otherwise replace the accent wash for as long as the pointer is
   on it. The inset bar survives either way; this keeps the fill too. */
.sched-tl-day-head.today:hover {
  background: rgba(255, 122, 33, 0.15);
}

.sched-tl-day-head:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* -- the queue's first job, once you have asked for it ---------------------- */
.schedule-drag-handle[data-just-focused] {
  animation: queueJobPulse 1.3s ease-out 1;
}

@keyframes queueJobPulse {

  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(255, 122, 33, 0);
  }

  25% {
    box-shadow: 0 0 0 5px rgba(255, 122, 33, 0.45);
  }
}

@media (prefers-reduced-motion: reduce) {
  .schedule-drag-handle[data-just-focused] {
    animation: none;
    outline: 2px solid var(--accent);
  }
}

.month-nav-today:disabled,
.month-nav-today[aria-disabled='true'] {
  opacity: 0.45;
  cursor: default;
}

/* ===========================================================================
   THE PUBLIC PAGES GET THEIR WIDTH BACK
   ===========================================================================
   /for, /pricing, /faq, /security and /resources wore the app's left rail:
   244px of every desktop screen, permanently, showing a locked preview of
   software the reader has not bought. Eighteen padlocked rows competing with
   the pricing narrative, and the actual site navigation somewhere below them.

   Inverted. The public site is a top bar; the preview is a drawer behind one
   button that says what it is. Nothing was removed — same rail, same rows,
   same "free to unlock" note — it is one tap away instead of always there.

   The signed-in dashboard rail is a different branch and is untouched: that
   one is a tool somebody uses all day and it earns its width.
   =========================================================================== */

.chrome-shell-public {
  min-height: 100vh;
  /* The ambient glow is a 430px blur positioned off the right edge of a column
     that used to be 244px narrower. `clip` rather than `hidden` on purpose:
     hidden would make this a scroll container and the sticky bar above would
     stop sticking. */
  overflow-x: clip;
}

.public-topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: clamp(0.6rem, 1.6vw, 1.4rem);
  min-height: 4.4rem;
  padding: 0 clamp(1rem, 3vw, 2.2rem);
  border-bottom: 1px solid var(--line);
  background: var(--chrome-solid);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}

.public-topbar-brand {
  flex: none;
  text-decoration: none;
}

.public-topbar-nav {
  display: flex;
  align-items: center;
  gap: clamp(0.5rem, 1.4vw, 1.3rem);
}

.public-topbar-nav a {
  padding: 0.4rem 0.15rem;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 650;
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.16s ease;
}

.public-topbar-nav a:hover {
  color: var(--text);
}

.public-topbar-nav a.active {
  color: var(--accent-ink);
}

/* Pushed right, and the first of the three things on that side. */
.public-topbar-preview {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 40px;
  padding: 0 0.85rem;
  border: 1px dashed rgba(var(--tint), 0.3);
  border-radius: 999px;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: 0.85rem;
  font-weight: 650;
  white-space: nowrap;
  cursor: pointer;
  transition: border-color 0.16s ease, color 0.16s ease;
}

.public-topbar-preview:hover {
  border-color: var(--cedge-orange-9);
  color: var(--text);
}

.public-topbar-preview[aria-expanded='true'] {
  border-style: solid;
  border-color: var(--accent);
  color: var(--text);
}

.public-topbar-signin {
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 650;
  text-decoration: none;
  white-space: nowrap;
}

.public-topbar-signin:hover {
  color: var(--text);
}

.public-topbar-cta {
  flex: none;
  white-space: nowrap;
}

.public-topbar-toggle {
  display: none;
}

.app-main.app-main-public {
  /* No rail to clear. This is the whole point of the change. */
  padding: 1.4rem clamp(1rem, 3vw, 2.2rem) 0;
}

.app-main-public .page-shell,
.app-main-public .wide-shell {
  min-height: calc(100vh - 5.8rem);
}

/* -- the drawer ------------------------------------------------------------ */
/* The rail's own rules still describe it — width, padding, the group cards, the
   footer. These only change where it starts from and what it sits on. */
.sidenav-drawer {
  transform: translateX(-100%);
  transition: transform 0.24s ease;
  box-shadow: 0 22px 60px rgba(0, 0, 0, 0.55);
  /* Genuinely opaque, for the same reason the mobile drawer is: --chrome-solid
     is still 8% see-through, which is a texture against a page gutter and a
     legibility problem over a full page of copy. */
  background: rgb(var(--chrome-rgb));
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  z-index: 41;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.sidenav-drawer.open {
  transform: translateX(0);
}

/* The scrim is display:none above the old 900px drawer breakpoint; this drawer
   exists at every width, so it needs one at every width too. */
.chrome-shell-public .sidenav-scrim {
  display: block;
  position: fixed;
  inset: 0;
  z-index: 40;
  background: rgba(4, 9, 16, 0.6);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
}

@media (prefers-reduced-motion: reduce) {
  .sidenav-drawer {
    transition: none;
  }
}

/* 1080, the same width the marketing header and the dashboard rail switch at.
   Measured at 1024 before this: brand + five links + the preview button + Sign
   in + the CTA came to 1109px of content in a 1024px bar, and the CTA was the
   thing hanging off the end. */
@media (max-width: 1080px) {

  /* The five public links move inside the drawer, where they are already the
     first thing in it, and the bar keeps the brand, the promise and the way in
     for somebody who already has an account. */
  .public-topbar-nav,
  .public-topbar-preview {
    display: none;
  }

  .public-topbar-toggle {
    display: inline-flex;
    margin-left: auto;
  }

  .public-topbar {
    min-height: 3.9rem;
  }

  .app-main.app-main-public {
    padding-inline: 1rem;
  }
}

@media (max-width: 560px) {

  /* On the narrowest screens the bar is brand + Menu; the CTA is the fixed
     bottom bar's job on those pages that have one, and the hero's on the rest. */
  .public-topbar-signin,
  .public-topbar-cta {
    display: none;
  }
}

/* -- marketing headings get a measure, not a column ------------------------ */
/* There is a bare `h1 { max-width: 11ch }` in this file, and 11ch of display
   type is about two words a line. Measured on /for at 768px: the hero is 696px
   wide and the heading was capped at 297px of it, so "One tool, tuned to the
   way your trade works." wrapped to four lines with 400px of empty hero beside
   it. At 1280 it was 456px inside a 960px hero — the same four lines.

   Scoped to the marketing heroes rather than fixed on the global rule, because
   that rule reaches every h1 in the product and this is not the change to make
   to a dashboard page title. 22ch is roughly two lines for a headline of this
   length, which is what a hero headline wants. */
.marketing-shell .hero-copy h1,
.marketing-shell .section-heading h1 {
  max-width: 22ch;
}

/* ===== Every text we send — the outgoing message catalogue ==================
   A contractor's number sends thirty-odd different messages under their name,
   and until this section there was nowhere to read them: the only way to find
   out what an automation said was to switch it on and wait for it to reach a
   customer.

   THREE COLUMNS, AND WHY THEY ARE THESE THREE. What decides whether an owner is
   happy for a message to go out is when it fires, what it says, and whether
   they can stop it. Two of those are facts about the wiring and one is the
   message, so the message takes the room: 1fr / 1.6fr / 0.8fr.

   A GRID RATHER THAN A <table>. The row has to become a card on a phone, and a
   table that scrolls sideways would put the message — the thing you came to
   read — off the right edge. The roles are on the markup so it is still
   announced as a table to a screen reader. */
.sms-cat-table {
  display: grid;
  gap: 0.65rem;
  margin-top: 1.1rem;
}

.sms-cat-head,
.sms-cat-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr) minmax(0, 0.8fr);
  gap: 1.1rem;
  align-items: start;
}

.sms-cat-head {
  padding: 0 0.9rem 0.15rem;
  color: var(--mute-t45);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.sms-cat-row {
  padding: 0.95rem 0.9rem;
  border: 1px solid var(--edge-t08);
  border-radius: 14px;
  background: rgba(var(--tint), 0.02);
}

.sms-cat-row:hover {
  border-color: var(--edge-t14);
  background: rgba(var(--tint), 0.035);
}

.sms-cat-when {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.sms-cat-when strong {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.sms-cat-when>span {
  color: var(--mute-t55);
  font-size: 0.82rem;
  line-height: 1.45;
}

/* Who the phone belongs to. Colour carries the same fact as the word, never
   instead of it — "To: Crew" reads without the tint. */
.sms-cat-who {
  justify-self: start;
  margin-top: 0.15rem;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  background: rgba(var(--tint), 0.06);
  font-size: 0.68rem !important;
  font-weight: 800;
  letter-spacing: 0.03em;
}

.sms-cat-who.is-customer {
  background: rgba(58, 160, 255, 0.13);
  color: var(--ink-sky-1, #7cc4ff);
}

.sms-cat-who.is-lead {
  background: rgba(255, 122, 33, 0.13);
  color: var(--accent-ink);
}

.sms-cat-who.is-owner {
  background: rgba(150, 110, 255, 0.14);
  color: var(--ink-violet-1);
}

.sms-cat-who.is-crew {
  background: rgba(52, 199, 123, 0.13);
  color: var(--ink-green-7);
}

.sms-cat-msg {
  display: grid;
  gap: 0.4rem;
  min-width: 0;
}

/* The outbound bubble from the inbox, on purpose: this IS what the customer
   gets, so it should look like the messages beside it on the same page. */
.sms-cat-bubble {
  margin: 0;
  padding: 0.6rem 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 18px 18px 18px 6px;
  background: linear-gradient(246deg, #0061af, #1f3b4d);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.22);
  color: #ffffff;
  font-size: 0.88rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.sms-cat-authored {
  color: var(--mute-t45);
  font-size: 0.74rem;
  line-height: 1.4;
}

.sms-cat-control {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.sms-cat-control small {
  color: var(--mute-t45);
  font-size: 0.72rem;
  line-height: 1.4;
}

.sms-cat-switch {
  justify-self: start;
  padding: 0.18rem 0.5rem;
  border: 1px solid var(--cedge-orange-27);
  border-radius: 999px;
  background: rgba(255, 122, 33, 0.1);
  color: var(--accent-ink);
  font-size: 0.74rem;
  font-weight: 800;
}

a.sms-cat-switch:hover {
  background: rgba(255, 122, 33, 0.18);
}

a.sms-cat-switch:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Manual and always-on are not switches, so they are not dressed as one. */
.sms-cat-switch.is-manual,
.sms-cat-switch.is-always {
  border-color: var(--edge-t12);
  background: rgba(var(--tint), 0.04);
  color: var(--mute-i60);
}

.sms-cat-foot {
  margin: 1.1rem 0 0;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule-t08);
  color: var(--mute-t55);
  font-size: 0.82rem;
  line-height: 1.55;
  max-width: var(--read-note);
}

/* One column below the tablet breakpoint: three columns of this at 900px gives
   the message about 380px, which is narrower than the phone it is imitating. */
@media (max-width: 1080px) {
  .sms-cat-head {
    display: none;
  }

  .sms-cat-row {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.7rem;
  }

  .sms-cat-control {
    grid-auto-flow: column;
    justify-content: start;
    align-items: center;
    gap: 0.5rem;
  }
}

/* ============================================================================
   DASHBOARD HOME — the 2026-08 restructure
   ----------------------------------------------------------------------------
   The page answers three questions in order now: what needs me, what is
   happening next, how is the business doing. Four styles support that:

     .dash-waiting       the customer's move, quieter than Act now
     .dash-quicklinks    where "Visit your site" went, out of the money section
     .dash-automations   a whole section compressed to one summary line

   Appended as its own block rather than edited into the existing home rules
   around 6429-6509 and 24358-24446, which are interleaved with the rail's
   mobile bar with no section banner between them.
   ========================================================================== */

/* WAITING sits below ACT NOW and must not compete with it. Same card, no
   numbered index, and a muted left edge instead of the accent one — the
   difference in weight IS the information. */
.dash-waiting {
  border-color: var(--edge-t10);
}

.dash-waiting .priority-item {
  border-left-color: var(--edge-t12);
}

.dash-waiting .priority-cta {
  color: var(--mute-t62);
}

.dash-waiting .priority-cta:hover {
  color: var(--text);
}

/* "No numbered index" also means one fewer child. .priority-item is a three
   column grid — 34px badge, message, action — and with the badge gone the
   message lands in the 34px track and wraps to one word per line while the
   action sits on top of it. Two children, two columns. */
.dash-waiting .priority-item {
  grid-template-columns: minmax(0, 1fr) auto;
}

@media (max-width: 640px) {

  /* The phone layout stacks by moving both children into column 2, out from
     under the badge. There is no badge here, so they stack in column 1 —
     without this they would pile into the action track and squeeze again. */
  .dash-waiting .priority-item {
    grid-template-columns: minmax(0, 1fr);
  }

  .dash-waiting .priority-copy,
  .dash-waiting .priority-cta {
    grid-column: 1;
  }
}

/* Shortcuts, not metrics. Compact and unemphatic; the buttons carry themselves. */
.dash-quicklinks .actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.2rem;
}

/* The automations section, folded to a line.
   It is a <details> so the whole panel is the disclosure — no separate toggle
   to keep in sync with the panel's own state. Open by default only when every
   automation is off, which is the one case that is genuinely a problem. */
.dash-automations {
  padding: 0;
}

.dash-automations-summary {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.85rem 1rem;
  list-style: none;
  cursor: pointer;
  border-radius: inherit;
}

.dash-automations-summary::-webkit-details-marker {
  display: none;
}

.dash-automations-summary:hover {
  background: rgba(var(--tint), 0.03);
}

.dash-automations-summary:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--cedge-orange-51);
}

/* The caret is drawn by the summary rather than the flex line, so it stays
   pinned right whatever the line wraps to. */
.dash-automations-summary::after {
  content: '▾';
  margin-left: auto;
  flex: 0 0 auto;
  color: var(--mute-t50);
  font-size: 0.7rem;
  transition: transform 0.15s ease;
}

.dash-automations[open]>.dash-automations-summary::after {
  transform: rotate(180deg);
}

.dash-automations-line {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.3rem 0.7rem;
  min-width: 0;
}

.dash-automations-line strong {
  color: var(--text);
  font-size: 0.95rem;
  font-weight: 700;
}

/* Health reads as a state, so it gets the good colour and a dot — and the WORD
   carries the meaning, so it still reads without colour vision. */
.dash-automations-health {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--good);
  font-size: 0.82rem;
  font-weight: 650;
}

.dash-automations-health::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.dash-automations-health.is-off {
  color: var(--mute-t55);
}

.dash-automations>*:not(.dash-automations-summary) {
  margin-left: 1rem;
  margin-right: 1rem;
}

.dash-automations>*:last-child {
  margin-bottom: 1rem;
}

@media (max-width: 640px) {

  /* 44px, and the caret gets its own room so a wrapped line cannot push it
     under the text. */
  .dash-automations-summary {
    min-height: 44px;
    padding: 0.75rem 0.85rem;
  }

  .dash-automations>*:not(.dash-automations-summary) {
    margin-left: 0.85rem;
    margin-right: 0.85rem;
  }
}

/* ============================================================================
   REFUND POLICY — the customer's copy of it, and the contractor's warnings
   ----------------------------------------------------------------------------
   Appended as a self-contained block. Two places, one subject:

   .quick-stop-policy  the cancellation terms on the public /quick-stop/[id]
                       status page, now rendered from the account's real tiers
                       instead of a hardcoded paragraph quoting the defaults.
   .refund-warnings    what the contractor is told about the numbers they just
                       typed, under the five inputs in QuickStopConfigurator.

   The warnings have two severities, and the rule they obey is that the WORD in
   front of each one carries the meaning. Colour only agrees with it: printed in
   greyscale, or read by anyone who can't separate red from amber, the two
   levels still differ by bar weight, bar style and type weight.
   ========================================================================== */

.quick-stop-policy {
  margin-top: 1rem;
}

.quick-stop-policy .quick-stop-policy-title {
  margin: 0 0 0.35rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--mute-t62);
}

/* The terms are the small print, but they are terms — 0.75 opacity on the old
   paragraph put a payment condition below comfortable reading contrast, so this
   sets a real colour instead of fading the text out. */
.quick-stop-policy ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.3rem;
  color: var(--mute-t62);
}

.quick-stop-policy ul li {
  position: relative;
  padding-left: 0.85rem;
  line-height: 1.45;
}

.quick-stop-policy ul li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cedge-orange-51);
}

.refund-warnings {
  margin: 0.6rem 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.45rem;
}

.refund-warnings li {
  padding: 0.55rem 0.7rem;
  border-radius: 0 8px 8px 0;
  font-size: 0.84rem;
  line-height: 1.5;
  color: var(--muted);
  background: var(--ground-2);
}

.refund-warnings li strong {
  font-weight: 700;
  color: var(--text);
}

/* Severe: a solid, heavy bar and a bolder label. This is a term a customer
   would call a swindle, not a tidiness note. */
.refund-warnings li.is-severe {
  border-left: 4px solid var(--bad);
  background: color-mix(in srgb, var(--bad) 9%, var(--ground-2));
}

.refund-warnings li.is-severe strong {
  color: var(--bad);
  font-weight: 800;
  letter-spacing: 0.01em;
}

/* Mild: a thinner, dashed bar — different in outline as well as in colour, so
   the two levels never depend on hue alone to be told apart. */
.refund-warnings li.is-warn {
  border-left: 3px dashed var(--cedge-amber-19);
}

@media (max-width: 640px) {
  .refund-warnings li {
    padding: 0.5rem 0.6rem;
    font-size: 0.82rem;
  }
}

/* ============================================================================
   QUICK STOPS — the potential-earnings card, demoted
   ----------------------------------------------------------------------------
   The figure was mathematically disclosed as an illustration and visually drawn
   as a forecast: the largest number on the page, in a glowing card, with "not a
   forecast" underneath in small grey text. Typography beats footnotes. It is
   arithmetic now — a sentence at caption size, in the same voice as the copy
   around it, with no glow and no hero number to argue with the disclaimer.
   ========================================================================== */
.es-earnings.is-illustration {
  background: rgba(var(--tint), 0.03);
  border: 1px solid var(--edge-t09);
  box-shadow: none;
  padding: 0.9rem 1rem;
}

.es-earnings.is-illustration .es-earnings-label {
  color: var(--mute-t55);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.es-earnings.is-illustration .es-earnings-line {
  margin: 0.3rem 0 0;
  color: var(--text);
  /* Body size, not display size. The old total ran at ~2.5rem. */
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.45;
}

.es-earnings.is-illustration .es-earnings-line strong {
  font-weight: 800;
}

.es-earnings.is-illustration .es-earnings-note {
  margin: 0.4rem 0 0;
  color: var(--mute-t62);
  font-size: 0.8rem;
  line-height: 1.45;
}

/* ============================================================================
   QUICK STOPS — the three-tab shell
   ----------------------------------------------------------------------------
   Today / Settings / Insights. Modelled on .settings-tabnav, with a hint line
   under each label because these three are not obvious from one word: an owner
   looking for the refund tiers has to be able to tell that "Settings" is where
   prices live and "Insights" is not.
   ========================================================================== */
.qs-tabnav {
  display: flex;
  gap: 0.35rem;
  margin: 0 0 1rem;
  padding: 0.3rem;
  overflow-x: auto;
  border: 1px solid var(--edge-t09);
  border-radius: 14px;
  background: rgba(var(--tint), 0.025);
  /* Thin scrollbar on the horizontal overflow rather than a chunky one eating
     the row's height on a phone. */
  scrollbar-width: thin;
}

.qs-tab {
  display: grid;
  gap: 0.1rem;
  flex: 1 1 0;
  /* Never narrower than a readable label; the row scrolls instead. */
  min-width: 8.5rem;
  padding: 0.55rem 0.8rem;
  /* 44px, because these are the page's primary navigation and they were 37px
     tall — under the target size on the only device where the row is hard to
     hit in the first place. Grid, so align-content is what centres the label
     inside the taller box. */
  min-height: 44px;
  align-content: center;
  border: 1px solid transparent;
  border-radius: 11px;
  background: transparent;
  color: var(--mute-t62);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.qs-tab span {
  font-size: 0.94rem;
  font-weight: 700;
}

.qs-tab small {
  font-size: 0.72rem;
  font-weight: 500;
  opacity: 0.85;
}

.qs-tab:hover {
  color: var(--text);
  background: rgba(var(--tint), 0.04);
}

.qs-tab:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--cedge-orange-51);
}

.qs-tab.active {
  color: var(--text);
  border-color: var(--cedge-orange-51);
  background: rgba(255, 122, 33, 0.1);
}

/* The panel takes no styling of its own — the sections inside it are already
   .panel cards and a wrapper with padding would double every gap. */
.qs-tabpanel:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--cedge-orange-51);
  border-radius: 14px;
}

/* The deep links into this page all point at a section id, and the app header
   is fixed — so `#quick-stop-setup` scrolled the section's own "SETUP" heading
   up underneath it and landed on the first field instead. Same offset the
   settings tabs use, for the same reason. */
.qs-tabpanel [id] {
  scroll-margin-top: calc(var(--appbar-h) + 5.2rem);
}

@media (max-width: 640px) {

  /* THREE EQUAL THIRDS, NOT A ROW THAT SCROLLS.
     `min-width: 7.5rem` on three tabs plus the gaps and the rail's padding came
     to 381px inside a 309px content box at 390px — so the row scrolled
     sideways and only two of the three labels were ever on screen. The hint
     line is already hidden here, which leaves "Today", "Settings", "Insights":
     each of them fits a third of any phone. min-width: 0 is what lets
     `flex: 1 1 0` actually divide the row. */
  .qs-tabnav {
    overflow-x: visible;
  }

  .qs-tab {
    min-width: 0;
    padding: 0.5rem 0.4rem;
    text-align: center;
    justify-items: center;
  }

  .qs-tab small {
    display: none;
  }
}

/* ================================================================
   QUICK STOPS — settings drawers that report themselves, and a save
   bar that says whether there is anything to save
   ================================================================
   The five drawers carried a fixed blurb apiece describing what each
   was ABOUT, never what it held. An account could therefore be
   reported ready to go while drawer 2 accepted five-hour visits and
   drawer 5 held refund terms the app's own warnings call unfair — both
   visible only to somebody who opened the drawer and read. The value
   now replaces the blurb, and anything worth a second look wears a
   badge on the closed head. See lib/quick-stop-sections. */

.bset-section-state {
  flex: none;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* Two levels, and the WORD carries which — "Not set" against "Check
   this". Colour only agrees with it, so the badge still sorts itself in
   greyscale and for anyone who cannot separate amber from orange. */
.bset-section-state[data-state='todo'] {
  border-color: var(--cedge-orange-2);
  background: rgba(255, 122, 33, 0.12);
  color: var(--ink-orange-8);
}

.bset-section-state[data-state='warn'] {
  border-color: var(--cedge-amber-11);
  background: rgba(255, 209, 102, 0.1);
  color: var(--gold-ink);
}

.bset-section-issues {
  margin: 0 0 1rem;
  padding: 0.75rem 0.9rem 0.75rem 2rem;
  border-radius: 12px;
  border: 1px solid var(--edge-t09);
  background: rgba(var(--tint), 0.02);
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--muted);
}

.bset-section-issues li+li {
  margin-top: 0.4rem;
}

/* The save bar. It was a plain button under five collapsed drawers,
   always enabled — so the only way to know a save had landed was to
   scroll back to a button you had already pressed. Sticky, and present
   only once SaveButton's onlyWhenChanged says the form is dirty, which
   makes its presence the answer to "have I changed anything". */
.qs-savebar {
  position: sticky;
  bottom: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin: 1.25rem -0.35rem -0.35rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--edge-t14);
  border-radius: 14px;
  background: var(--bg-elevated);
  /* Prefixed for iOS Safari, as everywhere else in this file — --bg-elevated is
     translucent, so without the blur the settings scroll past legibly underneath
     the bar rather than behind it. */
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  box-shadow: 0 -8px 28px rgba(0, 0, 0, 0.22);
}

/* EMPTY WHEN CLEAN. Otherwise a sticky bar sits at the foot of the page
   saying "Unsaved changes" over a form nobody has touched.

   `button:not([hidden])`, and the [hidden] half is load-bearing:
   SaveButton stays MOUNTED and sets the hidden attribute (its effects
   reach the form through the button's own .form property, so a button
   that unmounts takes its listeners with it and never comes back). A
   bare :has(button) would therefore match forever.

   Nor can this test computed display: .btn sets display:inline-flex,
   and an author rule beats the UA stylesheet's [hidden]{display:none} —
   the same trap .bset-section-body[hidden] and .settings-tabpanel[hidden]
   are each written to dodge. The attribute is the honest signal.

   .form-actions a few hundred lines down does the same job with
   :not(:has(> *:not([hidden]))); that shape does not work here because
   this bar also holds a note, which is never hidden. */
.qs-savebar:not(:has(button:not([hidden]))) {
  display: none;
}

.qs-savebar-note {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.qs-savebar-note strong {
  color: var(--text);
  font-weight: 700;
}

@media (max-width: 560px) {
  .qs-savebar {
    flex-direction: column;
    align-items: stretch;
  }

  .qs-savebar .btn {
    width: 100%;
  }

  .bset-section-state {
    display: none;
  }
}

