  margin: 0.3rem 0 0.35rem;
  max-width: none;
  font-size: clamp(1.85rem, 3vw, 2.45rem);
}

.settings-shell>.settings-hero .workspace-lead {
  max-width: 68ch;
  font-size: 0.94rem;
  line-height: 1.55;
}

.settings-shell>.settings-hero .account-created-note {
  margin-top: 0.55rem;
}

