  background: linear-gradient(145deg, rgba(14, 30, 48, 0.96), rgba(7, 18, 30, 0.98));
  border: 1px solid rgba(56, 189, 248, 0.4);
  border-radius: 10px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3), 0 0 12px rgba(56, 189, 248, 0.12);
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

